class CourseError(Exception):
    pass


# =============================================================================
# the text course (SPEC.md 130.10.3)
# =============================================================================

_NAME = re.compile(r"^[A-Z0-9]{1,5}$")
_HEIGHT = re.compile(r"^-?\d+(\.(0|00|5|50|25|75))?$")     # SPEC.md 130.48: quarter units
_INT = re.compile(r"^-?\d+$")


def _tokens(line, where):
    """split a line on spaces, honouring one "quoted" string; '#' starts a
    comment outside quotes"""
    out = []
    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if c in " \t\r":
            i += 1
            continue
        if c == "#":
            break
        if c == '"':
            j = line.find('"', i + 1)
            if j < 0:
                raise CourseError("%s: an unterminated quoted string" % where)
            out.append(('"', line[i + 1:j]))
            i = j + 1
            continue
        j = i
        while j < n and line[j] not in " \t\r#\"":
            j += 1
        out.append(('w', line[i:j]))
        i = j
    return out


class Room:
    def __init__(self, style, tiles, height, line, exit=0, hidden=False):
        self.style = style          # 'floor' | 'wall' | 'goal' | None (a hole)
        self.tiles = tiles          # a frozenset of (wx, wy)
        self.height = height        # ('flat', h2) | ('ramp', axis, p0, p1, h0_2, r)
        self.line = line
        self.exit = exit            # wave 8b (SPEC.md 130.19.4): a goal's EXIT, 0 - 15
        self.hidden = hidden        # ...and a secret finish
        self.half = {}              # SPEC.md 130.24.4: {cell: (diag, half)} - the cells this room lays ONE half of


