def title_window(c):
    """the WIDER (the Hercules') window of a `view` course in picture px:
    (x0, y0, x1, y1), half-open"""
    v = c.model["grid"]["view"]
    top, c0 = 4 * (v & 255), v >> 8
    return 8 * (c0 - HERC_LEFT), top, 8 * (c0 + 40 + HERC_RIGHT), top + 200


def title_author(c, spec):
    """play a TITLE_AUTHOR script on the title course with the model.  ->
    (the parsed demo dict with its runs, Physics, [(step, verb)] marks)"""
    d = {"num": spec["num"], "ball": MAT_NAMES.index(spec["ball"]), "vel": tuple(spec.get("vel", (0, 0, 0))),
         "respawn": spec.get("respawn"), "runs": [],
         "expects": [(e[0], e[1] if len(e) > 1 else None) for e in spec.get("expects", ())]}
    gx, gy, gz = spec["at"]
    d["at"] = (int(round(16 * gx * 256)), int(round(16 * gy * 256)), int(round(gz * 256)))
    if "air" in spec:
        d["air"] = spec["air"]
    p = title_start(c, d)
    x0, y0, x1, y1 = title_window(c)
    keys, marks = [], []
    title_author.p, title_author.marks = p, marks       # (for a refused script's post-mortem)
    title_author.trace = []

    class Full(Exception):
        pass

    def step(k):
        if len(keys) >= TITLE_STEPS:
            raise Full()
        n0 = len(p.events)
        p.step(k)
        keys.append(k)
        ev = [e[0] for e in p.events[n0:]]
        title_author.trace.append((len(keys), (p.gx >> 12, p.gy >> 12), p.gz >> 8, ev))
        return ev

    def onglass():
        bx, by = p.bx >> 8, p.by >> 8
        return bx + 16 > x0 and bx < x1 and by + 16 > y0 and by < y1

    def point(t):
        cell = (int(t[0]), int(t[1]))
        if cell in c.tiles:         # (a fractional point: its cell's floor, moved within the cell -
            u, v = t[0] - cell[0] - 0.5, t[1] - cell[1] - 0.5   # an edge to run along)
            x, y = _way_point(c, cell)
            return (int(round(x + 16 * (u - v))), int(round(y + 8 * (u + v))))
        return (16 * (t[0] - t[1]) + c.x0 - 8, 8 * (t[0] + t[1]) - 5 + c.y0)    # (a void tile: height 0)

    def aim(cells):
        p.route = [point(t) for t in cells]
        p.wp = 0
    try:
        _title_verbs(spec, d, p, c, keys, marks, step, onglass, aim)
    except Full:
        if len(marks) != len(spec["script"]):
            raise CourseError("title demo %d: the script runs past BZ_TSTEPS %d in %r, not its last verb"
                              % (d["num"], TITLE_STEPS, marks[-1][1]))
    while len(keys) < TITLE_STEPS:
        step(0)
    runs = []
    for k in keys:
        if runs and runs[-1][0] == k and runs[-1][1] < 255:
            runs[-1][1] += 1
        else:
            runs.append([k, 1])
    d["runs"] = [tuple(r) for r in runs]
    return d, p, marks


def _title_verbs(spec, d, p, c, keys, marks, step, onglass, aim):
    """title_author's verbs (TITLE_AUTHOR's), stepping through `step`"""
    for act in spec["script"]:
        marks.append((len(keys), act, (p.gx >> 12, p.gy >> 12)))
        v = act[0]
        if v == "wait":
            for _ in range(act[1]):
                step(0)
        elif v == "keys":
            for _ in range(act[2]):
                step(act[1])
        elif v == "press":
            k = 0
            for ch in act[1]:
                k |= dict((ch_, b) for b, ch_ in KEY_LETTERS)[ch]
            while act[2] not in step(k):
                pass
        elif v in ("to", "go"):
            aim(act[1])
            last = p.route[-1]
            while True:
                step(p.auto())
                near = (p.wp == len(p.route) - 1 and abs(last[0] - (p.bx >> 8)) < AUTO_REACH
                        and abs(last[1] - (p.by >> 8)) < AUTO_REACH)
                if near and (v == "go" or (not p.air and abs(p.gvx) + abs(p.gvy) < 24)):
                    break
        elif v == "until":
            aim(act[2])
            while act[1] not in step(p.auto()):
                pass
        elif v == "off":
            aim(act[1])
            while onglass():
                step(p.auto())
        elif v == "hop":
            if len(act) > 1:
                aim(act[1])
            nh = p.nhop
            step(p.auto() | K_HOP)
            if p.nhop == nh:
                raise CourseError("title demo %d: `hop` at step %d did not Hop" % (d["num"], len(keys)))
        elif v == "boost":
            q = _clone(p)
            ahead = 0
            while True:
                n0 = len(q.events)
                q.step(q.auto())
                ahead += 1
                if any(e[0] in _CONTACTS for e in q.events[n0:]) or ahead > 400:
                    break
            if ahead < 3 or ahead > 400:
                raise CourseError("title demo %d: `boost` at step %d: no first contact 3 - 400 steps ahead (%d)"
                                  % (d["num"], len(keys), ahead))
            for _ in range(ahead - 3):
                step(p.auto())
            step(p.auto() | K_HOP)
            nb = p.nboost
            step(p.auto())
            step(p.auto())
            if p.nboost == nb:
                raise CourseError("title demo %d: `boost` at step %d did not boost" % (d["num"], len(keys)))
        else:
            raise CourseError("title demo %d: unknown verb %r" % (d["num"], v))


def bzt_text(d, note):
    """a demo dict -> its .bzt"""
    out = ["# " + ln for ln in note.split("\n")]
    gx, gy, gz = d["at"]
    out += ["tdemo   %d" % d["num"], "ball    %s" % MAT_NAMES[d["ball"]],
            "at      %s %s %s" % (_num(gx / 256.0), _num(gy / 256.0), _num(gz / 256.0)),
            "vel     %d %d %d" % d["vel"]]
    if "air" in d:
        out.append("air     %d" % d["air"])
    if d["respawn"] is not None:
        out.append("respawn %d %d" % tuple(d["respawn"]))
    out += ["expect  %s%s" % (ev, "" if n is None else " %d" % n) for ev, n in d["expects"]]
    out += ["run     %s %d" % (keys_text(k), n) for k, n in d["runs"]]
    return "\n".join(out) + "\n"


def _num(v):
    return ("%.4f" % v).rstrip("0").rstrip(".")


def main_tauthor(argv):
    """bbcourse.py tauthor [TITLE.bbc] [-n N]: play TITLE_AUTHOR's scripts on
    the title course with the model and write apps/bonanza/demos/title<N>.bzt
    (SPEC.md 130.23.3); -v prints each script's marks and the model's events"""
    ap = argparse.ArgumentParser(prog="bbcourse.py tauthor")
    ap.add_argument("course", nargs="?", default=os.path.join(COURSE_DIR, "title.bbc"))
    ap.add_argument("-n", type=int, action="append")
    ap.add_argument("-v", action="store_true")
    ap.add_argument("--dir")
    a = ap.parse_args(argv)
    c = compile_course(a.course)
    BZ_TITLE_K[0] = len(default_paths()) + 1        # (BZ_CRS_TITLE, after the pathway)
    for n in a.n or sorted(TITLE_AUTHOR):
        spec = dict(TITLE_AUTHOR[n], num=n)
        d, p, marks = title_author(c, spec)
        log, q = title_check(c, d, "title demo %d" % n)
        note = ("Bounce Bonanza's TITLE DEMO %d (SPEC.md 130.23.3), written by `python3 tools/bbcourse.py tauthor`\n"
                "from bbcourse.TITLE_AUTHOR[%d] and the model: %s.  %d falls, %d tube rides; the build\n"
                "replays it from its start and checks every `expect`.") % (
                    n, n, spec.get("what", ""), q.nfall, q.ntube)
        out = title_demo_path(n, a.dir)
        with open(out, "w", newline="\n") as f:
            f.write(bzt_text(d, note))
        print("bbcourse: %s: %d runs, %d steps" % (out, len(d["runs"]), TITLE_STEPS))
        if a.v:
            for st, act, at in marks:
                print("   %4d  %-8s %r" % (st, at, act))
            for e in q.events:
                if e[0] not in ("wall", "corner"):
                    print("         %4d %s" % (e[1], e[0]))
    return 0


# The PLAYGROUND (SPEC.md 130.16.8): where its elements are, so item 7 can sweep
# them on the course itself and assert their shapes.  play_geometry() checks
# these against the compiled course, so a course edit that moves an element
# fails at that check, naming it, rather than sweeping empty floor.
PLAY_RUNGS = ((1.5, (10, 11, 13, 14)), (1, (17, 11, 20, 14)), (0.5, (24, 11, 27, 14)), (2, (31, 11, 34, 14)))
PLAY_FRONT = 19               # the apron's front row: each rung is approached along -wy from it, at the cap
PLAY_GAPS = ((1, (10, 13)), (2, (13, 16)), (3, (16, 19)))   # the notches' wx; the near lip is the apron's front
PLAY_GAPROW = 14              # ...approached along +wy from the apron's back row, at the cap
PLAY_LANE, PLAY_STRIP = 28, (23, 26)   # the brake strip: its middle lane's wx, and its three tiles' wy
PLAY_MAT = (7, 15, 10, 18)    # the mat, at the apron's left end
_PLAY_DIRK = {(0, -1): K_R | K_U, (0, 1): K_L | K_D, (1, 0): K_R | K_D, (-1, 0): K_L | K_U}


def _rect(r):
    return {(x, y) for x in range(r[0], r[2]) for y in range(r[1], r[3])}


def play_geometry(c):
    """-> [what is not where PLAY_* say]: the apron level, each rung a level
    floor its height above it, the apron's front row in front of each, each
    notch `g` void tiles then the far floor at the apron's level, the strip"""
    t, bad = c.tiles, []
    ap = t.get((PLAY_LANE, PLAY_FRONT))
    if ap is None or ap.kind != KIND_FLOOR or ap.sx or ap.sy:
        return ["the apron's front row at (%d, %d)" % (PLAY_LANE, PLAY_FRONT)]
    h = ap.z0
    for H, r in PLAY_RUNGS:
        for k in _rect(r):
            u = t.get(k)
            if u is None or u.kind != KIND_FLOOR or u.sx or u.sy or u.z0 != h + int(2 * H):
                bad.append("the %g-unit rung's cell %s" % (H, k))
        for x in range(r[0], r[2]):
            for y in range(r[3], PLAY_FRONT + 1):
                u = t.get((x, y))
                if u is None or u.z0 != h or u.sx or u.sy:
                    bad.append("the %g-unit rung's run-up cell %s" % (H, (x, y)))
    for g, (x0, x1) in PLAY_GAPS:
        for x in range(x0, x1):
            if any((x, PLAY_FRONT + 1 + i) in t for i in range(g)):
                bad.append("the %d-tile notch at wx %d is not void" % (g, x))
            u = t.get((x, PLAY_FRONT + 1 + g))
            if u is None or u.z0 != h or u.kind != KIND_FLOOR:
                bad.append("the %d-tile notch's far floor at wx %d" % (g, x))
    for y in range(PLAY_STRIP[0], PLAY_STRIP[1]):
        u = t.get((PLAY_LANE, y))
        if u is None or u.z0 != h or u.surf != SURF_NORMAL:
            bad.append("the brake strip's cell %s" % ((PLAY_LANE, y),))
    if (PLAY_LANE, PLAY_STRIP[1]) in t:
        bad.append("the brake strip does not end at the void")
    if any(t.get(k) is None or t[k].surf != SURF_BOUNCE or t[k].z0 != h for k in _rect(PLAY_MAT)):
        bad.append("the mat")
    return bad


def rec_map(tiles):
    """SPEC.md 130.24.2: a course's RECORDS by key - (wx, wy) for a whole cell, (wx, wy, i) for piece i of a
    split one - each a Tile"""
    out = {}
    for k, t in tiles.items():
        if isinstance(t, Split):
            for i, r in enumerate(t.halves):
                if r is not None:
                    out[k + (i,)] = r
        else:
            out[k] = t
    return out


def rec_adj(tiles, key):
    """the records a ball can roll to from record `key` (SPEC.md 130.24.7.3): across each edge the key's record
    owns, the record that owns it on the other side; inside a split cell, the pieces across its lines"""
    cell = key[:2]
    t = tiles[cell]
    out = []
    edges = EDGE_D if len(key) == 2 else [e for e in EDGE_D if OWNER[t.diag][e] == key[2]]
    for e in edges:
        dx, dy = EDGE_D[e]
        n = (cell[0] + dx, cell[1] + dy)
        nt = tiles.get(n)
        if nt is None:
            continue
        if isinstance(nt, Split):
            i = OWNER[nt.diag][OPP[e]]
            if nt.halves[i] is not None:
                out.append(n + (i,))
        else:
            out.append(n)
    if len(key) == 3:
        for i, j, _p0, _p1, _k in INNER[t.diag]:
            o = j if key[2] == i else i if key[2] == j else None
            if o is not None and t.halves[o] is not None:
                out.append(cell + (o,))
    return out


def reach_closure(tiles, start, props=(), drop=()):
    """SPEC.md 130.11.4.4's reach RESTRICTED to what the start can get to (the
    PLAYGROUND's dead ends, 130.16.8): a launch (HOPMAX on a floor's rate), a
    BOOST launch from a firm level floor and a bounce only from a cell already
    reached, each bounce at ITS floor's best restitution (a mat's E_MAT, sand's
    half, else the best EF: the reach's own global EMAX would put a mat's
    bounce on every floor); a cell is reached when a flight there is at least
    its low corner less BZ_CLIMB, or it rolls on from a reached 4-neighbour
    (its low corner within BZ_CLIMB of that one's top).  An over-approximation
    still, as the reach is: a cell it leaves out is unreachable.
    SPEC.md 130.24 (story D2.5): per RECORD - rec_map's keys, a whole cell's
    (wx, wy) as before, a split cell's pieces (wx, wy, i); a flight over a cell
    reaches each of its records, a roll goes by rec_adj.  drop: record keys left
    out (posts, another exit's goals).  -> the set of record keys"""
    rm = rec_map(tiles)
    sol = {k: u for k, u in rm.items() if u.kind != KIND_WALL and k not in drop}
    bycell = {}
    for k in sol:
        bycell.setdefault(k[:2], []).append(k)
    hi = {k: 4 * max(u.corners()) for k, u in sol.items()}
    lo = {k: 4 * min(u.corners()) for k, u in sol.items()}
    obs = prop_cells(props)
    efmax = max(m["EF"] for m in MATERIALS)

    def ef(k):
        u = sol[k].surf
        return E_MAT if u == SURF_BOUNCE else efmax >> 1 if u == SURF_SAND else efmax

    def spread(sl):
        best = {}
        for (k, h, r) in sl:
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    for c_ in bycell.get((k[0] + dx, k[1] + dy), ()):
                        if c_ not in best or h > best[c_]:
                            best[c_] = h
        return best
    R = {start}
    while True:
        srcs = []
        for k in sorted(R):
            u = sol[k]
            U = (abs(u.sx) + abs(u.sy)) * VMAXG // 4 + HOPMAX
            srcs.append((k, hi[k] + UP(U), RADIUS(U)))
            if BOOSTMAX and u.kind in (KIND_FLOOR, KIND_GOAL) and not u.sx and not u.sy \
                    and u.surf in (SURF_NORMAL, SURF_ICE) and k[:2] not in obs:
                srcs.append((k, hi[k] + UP(BOOSTMAX - G), RADIUS(BOOSTMAX - G)))
        best = spread(srcs)
        while True:
            extra = []
            for k in sorted(R):
                E = max(best.get(k, hi[k]), hi[k])
                if E > hi[k]:
                    e = ef(k)
                    rh = min(e * IMP(E - hi[k]) >> 8, e * VZMAX >> 8)
                    rl = min(e * IMP(E - lo[k]) >> 8, e * VZMAX >> 8)
                    extra.append((k, hi[k] + UP(rh), RADIUS(rl)))
                    u = sol[k]                  # round 3b (SPEC.md 130.17.17): the boost ADDS to that bounce
                    if BOOSTMAX and BADDMAX and u.kind in (KIND_FLOOR, KIND_GOAL) and not u.sx and not u.sy \
                            and u.surf in (SURF_NORMAL, SURF_ICE) and k[:2] not in obs:
                        ub = min(VZMAX, max(BOOSTMAX, rh + BADDMAX))
                        ul = min(VZMAX, max(BOOSTMAX, rl + BADDMAX))
                        extra.append((k, hi[k] + UP(ub - G), RADIUS(ul - G)))
            nb = spread(srcs + extra)
            if nb == best:
                break
            best = nb
        R2 = set(R) | {k for k, h in best.items() if h >= lo[k] - CLIMB}
        todo = list(R2)
        while todo:
            k = todo.pop()
            for n in rec_adj(tiles, k):
                if n in sol and n not in R2 and lo[n] <= hi[k] + CLIMB:
                    R2.add(n)
                    todo.append(n)
        if R2 == R:
            return R
        R = R2


def reach_from(tiles, cells):
    """the heights a launch, a BOOST launch or a bounce ON the given cells alone
    puts over every solid cell (no rolling off them): -> {cell: px}"""
    sol = {k: u for k, u in tiles.items() if u.kind != KIND_WALL}
    best = {}
    for k in cells:
        u = sol[k]
        hk = 4 * max(u.corners())
        for h, r in ((hk + UP(HOPMAX), RADIUS(HOPMAX)), (hk + UP(BOOSTMAX - G), RADIUS(BOOSTMAX - G))):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    n = (k[0] + dx, k[1] + dy)
                    if n in sol and h > best.get(n, -9999):
                        best[n] = h
    return best


def _play_run(c, mat, start, d, target, at=None, space2=None, n=300, keys=None):
    """a ball poked at the cap at `start` along d with the chord held (or
    `keys`), Space's edges on steps `at` and `space2`: -> (True when it is
    grounded on, or makes a contact with, a target cell; the Physics)"""
    p = Physics(c, mat=mat).poke(start[0], start[1], VMAXG * d[0], VMAXG * d[1])
    p.lvl = [LVL_MAX] * 4
    k0 = _PLAY_DIRK[d] if keys is None else keys
    for i in range(n):
        n0 = len(p.events)
        p.step(k0 | (K_HOP if i == at or i == space2 else 0))
        if p.nfall:
            return False, p
        if (p.gx >> 12, p.gy >> 12) in target and (not p.air or any(
                e[0] in ("land", "bounce", "hopc", "boost") for e in p.events[n0:])):
            return True, p
    return False, p


def _play_contact(c, mat, start, d, at):
    """the step of the first contact of the Hop pressed on step `at`, or None"""
    p = Physics(c, mat=mat).poke(start[0], start[1], VMAXG * d[0], VMAXG * d[1])
    p.lvl = [LVL_MAX] * 4
    hopped = False
    for i in range(300):
        n0 = len(p.events)
        p.step(_PLAY_DIRK[d] | (K_HOP if i == at else 0))
        for e in p.events[n0:]:
            if e[0] == "hop":
                hopped = True
            elif hopped and e[0] in ("land", "bounce", "hopc", "boost", "stun", "shatter"):
                return i
        if p.nfall or (i > at and not hopped):
            return None
    return None


def play_sweep(c, start, d, target):
    """one of the PLAYGROUND's rungs or notches swept as item 7's ladders are
    (LAD_PTS take-off points at the cap; the boost's second press at every
    arm_positions() step): -> {mat: {'roll', 'hop', 'boost2', 'boost'}}"""
    out = {}

    def judge(p, n0):
        if p.nfall:
            return False
        if (p.gx >> 12, p.gy >> 12) in target and (not p.air or any(
                e[0] in ("land", "bounce", "hopc", "boost") for e in p.events[n0:])):
            return True
        return None
    for m in range(len(MATERIALS)):
        cell = {"roll": _play_run(c, m, start, d, target)[0], "boost2": [], "boost": [],
                "hop": [a for a in range(LAD_PTS) if _play_run(c, m, start, d, target, a)[0]]}
        if MATERIALS[m]["BOOST"]:
            def mk(m=m):
                p = Physics(c, mat=m).poke(start[0], start[1], VMAXG * d[0], VMAXG * d[1])
                p.lvl = [LVL_MAX] * 4
                return p
            for a in range(LAD_PTS):
                land = _play_contact(c, m, start, d, a)
                if land is None:
                    continue
                res = sweep_second(mk, lambda i: _PLAY_DIRK[d], a, arm_positions(a, land), judge, 300)
                good = [e for e, ok in res.items() if ok]
                if good:
                    cell["boost"].append(a)
                if land - 2 in good:
                    cell["boost2"].append(a)
        out[m] = cell
    return out


def play_fall(c, herc, keys=None, **kw):
    """the brake strip's overrun (SPEC.md 130.16.8): a ball from rest on the
    apron's back row in the strip's lane, the chord down it held, no Grip, into
    the pit - GLIDE (kw: Glide's `_nosafe`, `_nolatch`) a frame at a time:
    -> dict(kill: the frame the fall respawned it, or None; land: it touched a
    floor on the way; lost: the first airborne frame the footprint is not in
    the window, or None; rev: the row direction reversed while airborne;
    halt: wave 6b, the first airborne frame on which LATTICE's row pan
    STOPPED because the tracked point came back inside its lead placement
    (130.17.6.2 step 5) - the tracked point moving against the fall, the
    `nolatch` control's signature under LATTICE, whose pans cannot reverse
    inside the band - or None)"""
    p = Physics(c, play=True).poke(PLAY_LANE, PLAY_GAPROW + 1, 0, 0)
    g = Glide(p, herc, c.brows, c.cols, **kw)
    spf = (PIT_HZ / CARD_HZ[herc]) / STEP_PIT
    acc, nl, out, dirs = 0.0, p.nland, {"kill": None, "land": False, "lost": None, "rev": False, "halt": None}, set()
    g.camera()
    for fr in range(1, 1200):
        acc += spf
        n = int(acc)
        acc -= n
        for _ in range(n):
            p.step(_PLAY_DIRK[(0, 1)] if keys is None else keys)
            if p.nfall:
                out["kill"] = fr
                out["rev"] = len(dirs) > 1
                return out
        dr, _dc, _f = g.camera()
        if p.air:
            if p.nland != nl:
                out["land"] = True
            if dr:
                dirs.add(dr > 0)
            inf = g.ay.info if not (g._w6 or _f) else None
            if inf is not None and inf["stop"] and out["halt"] is None:
                out["halt"] = fr
            top = g.R0 << g.lsh
            if out["lost"] is None and not (top <= p.py and p.py + BALL_D <= top + WIN_LINES):
                out["lost"] = fr
        nl = p.nland
    out["rev"] = len(dirs) > 1
    return out


def play_grip(c, mat):
    """Grip held from the strip's first tile, the ball from rest on the apron's
    back row with the chord down the lane until then: -> (stopped on the strip,
    the tiles from the strip's first edge to where it rests)"""
    p = Physics(c, play=True, mat=mat).poke(PLAY_LANE, PLAY_GAPROW + 1, 0, 0)
    for _ in range(600):
        g = (p.gy >> 12) >= PLAY_STRIP[0]
        p.step(K_GRIP if g else _PLAY_DIRK[(0, 1)])
        if p.nfall:
            return False, None
        if g and not p.air and not p.gvx and not p.gvy:
            return True, (p.gy - (PLAY_STRIP[0] << 12)) / 4096.0
    return False, None


def _play_checks(c, res):
    """item 7 on the PLAYGROUND (SPEC.md 130.16.8): its elements where PLAY_*
    say; the 2-unit top outside the reachable set, every other top reached,
    and no top reaching another; the rungs' and the notches' sweeps on the
    course itself; the brake strip's Grip and its fall into the void, the
    camera's fallback case; no boost on the mat"""
    bad = play_geometry(c)
    res.append(("7 PLAY: its elements are where bbcourse.PLAY_* say (%s)" % ("; ".join(bad[:3]) if bad else
                                                                           "rungs, notches, strip, mat"), not bad))
    if bad:
        return
    src = c.src
    props = build_props(src, c.tiles, c.fname)
    R = reach_closure(c.tiles, src.start[0], props)
    tops = {H: _rect(r) for H, r in PLAY_RUNGS}
    seen = {H: len(cs & R) for H, cs in tops.items()}
    # round 3b (SPEC.md 130.17.17): the boost ADDED to a fall's bounce takes the reach to the 2-unit top (a
    # Hop off the 1.5-unit top, the boost on the apron below) - PRINTED, not asserted: the PLAYGROUND is a
    # test course (the owner, 2026-11-15), and the boost's fixed apex holds only on a level landing now
    print("    PLAY's 2-unit top in the reachable set with the Hop and the boost: %d of 9 cells (round 3b's added "
          "boost; wave 6's design had none)" % seen[2])
    res.append(("7 PLAY: the 1.5-, 1- and half-unit tops are reached (%d, %d, %d of 9)" % (
                    seen[1.5], seen[1], seen[0.5]), seen[1.5] == seen[1] == seen[0.5] == 9))
    cross = []
    for Ha, ca in tops.items():
        rf = reach_from(c.tiles, ca)
        for Hb, cb in tops.items():
            if Hb != Ha and any(rf.get(k, -9999) >= 4 * min(c.tiles[k].corners()) - CLIMB for k in cb):
                cross.append((Ha, Hb))
    res.append(("7 PLAY: every rung a dead end - no rung's top reaches another's by a launch, a boost or a bounce "
                "from it (%s)" % (", ".join("%g -> %g" % x for x in cross) or "none"), not cross))
    # the control: the 2-unit rung where the half-unit one stands, 5 tiles from the 1-unit top
    t2 = dict(c.tiles)
    r2, rh = dict(PLAY_RUNGS)[2], dict(PLAY_RUNGS)[0.5]
    h2 = t2[(r2[0], r2[1])].z0
    for k in _rect(r2):
        del t2[k]
    for k in _rect(rh):
        t2[k] = Tile(KIND_FLOOR, h2, 0, 0, 0)
    R2 = reach_closure(t2, src.start[0], props)
    res.append(("7 PLAY negative control `deadend` (the 2-unit rung moved to the half-unit one's place, 5 tiles from "
                "the 1-unit top): the reachable set takes its top (%d of 9 cells)" % len(_rect(rh) & R2),
                bool(_rect(rh) & R2)))
    st = {}
    for H, r in PLAY_RUNGS:
        st[H] = play_sweep(c, ((r[0] + r[2] - 1) // 2, PLAY_FRONT), (0, -1), _rect(r))
    gp = {}
    for g, (x0, x1) in PLAY_GAPS:
        gp[g] = play_sweep(c, ((x0 + x1 - 1) // 2, PLAY_GAPROW), (0, 1),
                           {(x, y) for x in range(x0, x1) for y in range(PLAY_FRONT + 1 + g, PLAY_FRONT + 5 + g)})
    R_, S, Gl = MAT_RUBBER, MAT_STEEL, MAT_GLASS
    print("    PLAY's own rungs and notches (take-off points of %d at the cap; rubber's boost Space 2 before / any "
          "second press): %s; %s" % (LAD_PTS, "; ".join(
              "%g unit%s: rubber %s %d/%d/%d, glass %s %d, steel %s %d" % (
                  H, "" if H == 1 else "s", "rolls" if st[H][R_]["roll"] else "-", len(st[H][R_]["hop"]),
                  len(st[H][R_]["boost2"]), len(st[H][R_]["boost"]), "rolls" if st[H][Gl]["roll"] else "-",
                  len(st[H][Gl]["hop"]), "rolls" if st[H][S]["roll"] else "-", len(st[H][S]["hop"]))
              for H, _r in PLAY_RUNGS), "; ".join(
              "gap %d: rubber %d/%d/%d, glass %d, steel %d" % (
                  g, len(gp[g][R_]["hop"]), len(gp[g][R_]["boost2"]), len(gp[g][R_]["boost"]),
                  len(gp[g][Gl]["hop"]), len(gp[g][S]["hop"])) for g, _x in PLAY_GAPS)))
    res.append(("7 PLAY's own rungs: half a unit rolls up for every ball; 1 unit rubber's and glass's Hop, never "
                "steel's; 1.5 units rubber's Hop and boost, no Hop alone; 2 units nobody's, no second-press position",
                all(st[0.5][m]["roll"] for m in range(3)) and st[1][R_]["hop"] and st[1][Gl]["hop"]
                and not st[1][S]["hop"] and st[1.5][R_]["boost2"] and not any(st[1.5][m]["hop"] for m in range(3))
                and not any(st[2][m]["roll"] or st[2][m]["hop"] or st[2][m]["boost"] for m in range(3))))
    res.append(("7 PLAY's own notches: every ball Hops 1 tile; rubber 2, steel never; nobody crosses 3, the boost "
                "included, at any second-press position",
                all(gp[1][m]["hop"] for m in range(3)) and gp[2][R_]["hop"] and not gp[2][S]["hop"]
                and not any(gp[3][m]["hop"] or gp[3][m]["boost"] for m in range(3))))
    grips = [play_grip(c, m) for m in range(3)]
    print("    PLAY's brake strip, Grip from its first tile at the speed the apron gives: %s" % ", ".join(
        "%s %s" % (MAT_NAMES[m], "stops %.1f tiles in" % g[1] if g[0] else "goes over") for m, g in enumerate(grips)))
    res.append(("7 PLAY's brake strip: Grip held from its first tile stops rubber and glass on it (%s)" % ", ".join(
        "%.1f" % g[1] for g in grips if g[0]), grips[R_][0] and grips[Gl][0]))
    nolatch = []
    for herc in (0, 1):
        on, off, nol = play_fall(c, herc), play_fall(c, herc, _nosafe=True), play_fall(c, herc, _nolatch=True)
        card = ("CGA", "Hercules")[herc]
        res.append(("7 PLAY's brake strip, %s: overrun at speed it falls into the VOID and respawns (frame %s, no "
                    "floor touched); with the camera's fallback the footprint stays in the window, and the rows "
                    "never reverse nor halt while it falls" % (card, on["kill"]),
                    on["kill"] and not on["land"] and on["lost"] is None and not on["rev"] and on["halt"] is None))
        res.append(("7 PLAY's brake strip, %s, control `nosafe` (the fallback left out): the footprint leaves the "
                    "window at frame %s, before the kill at %s - the depth the basin was chosen for" % (
                        card, off["lost"], off["kill"]), off["kill"] and off["lost"] and off["lost"] < off["kill"]))
        nolatch.append(nol["rev"] or nol["halt"])
    res.append(("7 PLAY's brake strip, control `nolatch` (the fallback not latched): the rows reverse or, under "
                "LATTICE (wave 6b), HALT while it falls (CGA %s, Hercules %s: the frame the rows stopped; the CGA's "
                "leg is the arm's)" % tuple(nolatch), bool(nolatch[0])))
    # the mat: a Hop from the apron whose first contact is ON it, Space 2 before that contact: a contact Hop
    # there, never a boost (the Hops whose first contact is on the apron boost there, as they should)
    mstart, md, mat_c = (PLAY_MAT[2] + 2, (PLAY_MAT[1] + PLAY_MAT[3]) // 2), (-1, 0), _rect(PLAY_MAT)
    on, boosted = 0, 0
    for a in range(LAD_PTS):
        land = _play_contact(c, MAT_RUBBER, mstart, md, a)
        if land is None or land - 2 <= a:
            continue
        p = Physics(c, mat=MAT_RUBBER).poke(mstart[0], mstart[1], VMAXG * md[0], VMAXG * md[1])
        p.lvl = [LVL_MAX] * 4
        for i in range(land + 1):
            p.step(_PLAY_DIRK[md] | (K_HOP if i in (a, land - 2) else 0))
        if (p.gx >> 12, p.gy >> 12) in mat_c:
            on += 1
            boosted += p.nboost
    res.append(("7 PLAY's mat: a Hop from the apron whose first contact is on the mat, Space 2 steps before it, "
                "never boosts (%d take-off points, %d boosts)" % (on, boosted), on > 0 and not boosted))


def _clone(p):
    """a copy of a Physics a script can step ahead without touching the real one"""
    import copy
    q = copy.copy(p)
    q.lvl, q.events, q.pkick, q.wol = list(p.lvl), list(p.events), list(p.pkick), list(p.wol)
    if p.fam:                                       # wave 9: the families' state
        q.fst, q.fsl = bytearray(p.fst), [bytearray(x) for x in p.fsl]
    return q


def _boost_rule(p, tok, hopw, C):
    """why the contact just stepped did not boost (SPEC.md 130.16.4.1's rules,
    rule 2 as wave 6b has it, 130.17.4.2): tok, hopw: the token and the window
    as the contact's step began; C: the centre's grid cell"""
    if not tok:
        return "rule 1: no Hop from the ground set the token (this is not its first contact)"
    if tok != 2 or p.mst == ST_STUN:
        return ("rule 2: the flight was not ARMED (the token 1: no second Space edge after the take-off, up to the "
                "contact's step; the late grace converts only a bounce) or the ball was stunned")
    if not p.m["BOOST"]:
        return "rule 3: %s has no BOOST" % MAT_NAMES[p.mat]
    if not p.firm_level(C, None) or p.onp:
        return "rule 4: the contact's grid cell %s is not a firm level floor" % ((p.gx >> 12, p.gy >> 12),)
    return "rule 5: the rebound was already at least BOOST"


def author_demo(c, K, script):
    """play an AUTHOR script on course c (number K) with the model: -> (the
    log's bytes, the Physics after it)"""
    p = Physics(c, play=True)
    keys = []
    route = list(p.route)

    def step(k):
        p.step(k)
        keys.append(k)
        if len(keys) > 2 * DEMO_STEPS:
            raise CourseError("%s: the authored demo runs past %d steps" % (c.name, 2 * DEMO_STEPS))

    def steer(pt):
        dx = pt[0] - (p.bx >> 8)
        dy = pt[1] - (p.by >> 8)
        k = 0
        ax = _clamp(8 * dx, AUTO_VMAX) - p.vx
        k |= K_R if ax > AUTO_ACC // 2 else K_L if ax < -(AUTO_ACC // 2) else 0
        ay = _clamp(8 * dy, AUTO_VMAX) - p.vy
        k |= K_D if ay > AUTO_ACC // 2 else K_U if ay < -(AUTO_ACC // 2) else 0
        return k
    for act in script:
        if act[0] == "auto":
            while p.wp < act[1] and not p.goal:
                step(p.auto())
        elif act[0] == "wp":
            p.route, p.wp = route, act[1]
        elif act[0] == "route":
            p.route = [_way_point(c, t) for t in act[1]]
            p.wp = 0
            while p.wp < len(p.route) - 1 and not p.goal:
                step(p.auto())
            last = p.route[-1]
            while abs(last[0] - (p.bx >> 8)) >= AUTO_REACH or abs(last[1] - (p.by >> 8)) >= AUTO_REACH:
                step(p.auto())
        elif act[0] == "steer":
            n0 = p.nfall
            pt = _way_point(c, act[1]) if act[1] in c.tiles else (
                16 * (act[1][0] - act[1][1]) + c.x0 - 8, 8 * (act[1][0] + act[1][1]) - 5 + c.y0
                + 8 * c.src.zbase)                  # (a void cell's point at height 0 AS WRITTEN: 130.48.1)
            while p.nfall == n0:
                step(steer(pt))
        elif act[0] == "ret":
            n0 = p.nret
            step(K_RET)
            if p.nret == n0:
                raise CourseError("%s: the authored RETURN did not respawn" % c.name)
        elif act[0] == "cup":
            while not p.goal:
                step(p.auto())
        elif act[0] == "hop":                   # wave 6 (SPEC.md 130.16.8)
            n0 = p.nstep
            while (p.gx >> 12, p.gy >> 12) != tuple(act[1]):
                step(p.auto())
                if p.nstep - n0 > DEMO_STEPS:
                    raise CourseError("%s: the authored `hop` never reaches %s" % (c.name, act[1]))
            nh = p.nhop
            step(p.auto() | K_HOP)
            if p.nhop == nh:
                raise CourseError("%s: the authored `hop` at %s did not Hop (step %d)" % (c.name, act[1], p.nstep))
        elif act[0] == "boost":
            if not p.air or not p.btok:
                raise CourseError("%s: the authored `boost` at step %d: no Hop from the ground in flight (rule 1)"
                                  % (c.name, p.nstep))
            q = _clone(p)
            ahead = 0
            while True:
                n0 = len(q.events)
                q.step(q.auto())
                ahead += 1
                if any(e[0] in _CONTACTS for e in q.events[n0:]) or q.nfall or q.nret or ahead > 400:
                    break
            if ahead > 400 or q.nfall or q.nret:
                raise CourseError("%s: the authored `boost` at step %d: the Hop has no first contact (it falls)"
                                  % (c.name, p.nstep))
            if ahead < 3:
                raise CourseError("%s: the authored `boost` at step %d: the first contact is %d step(s) away, too "
                                  "close for Space 2 steps before it" % (c.name, p.nstep, ahead))
            for _ in range(ahead - 3):
                step(p.auto())
            # wave 6b (SPEC.md 130.17.4.2): the press 2 steps before the contact ARMS the flight (its key-down
            # edge: the Hop's press was released, `hop` presses one step); the window it opens is not read
            if p.kprev & K_HOP:
                raise CourseError("%s: the authored `boost` at step %d: Space still held from the Hop, no edge to "
                                  "arm the flight" % (c.name, p.nstep))
            step(p.auto() | K_HOP)
            if p.btok != 2:
                raise CourseError("%s: the authored `boost`'s press at step %d did not arm the flight (token %d)"
                                  % (c.name, p.nstep, p.btok))
            step(p.auto())
            tok, hopw = p.btok, p.hopw
            nb = p.nboost
            step(p.auto())
            if p.nboost == nb:
                raise CourseError("%s: the authored `boost`'s contact at step %d did not boost: %s" % (
                    c.name, p.nstep, _boost_rule(p, tok, hopw, p.cell(p.gx >> 12, p.gy >> 12))))
        elif act[0] == "aim":
            p.route = [_way_point(c, t) for t in act[1]]
            p.wp = 0
        elif act[0] == "grip":
            n0 = p.nstep
            if len(act) > 1:
                while (p.gx >> 12, p.gy >> 12) != tuple(act[1]):
                    step(p.auto())
                    if p.nstep - n0 > DEMO_STEPS:
                        raise CourseError("%s: the authored `grip` never reaches %s" % (c.name, act[1]))
            while p.air or p.gvx or p.gvy:
                step(K_GRIP)
                if p.nstep - n0 > DEMO_STEPS:
                    raise CourseError("%s: the authored `grip` never brings the ball to rest" % c.name)
        else:
            raise CourseError("%s: unknown AUTHOR verb %r" % (c.name, act[0]))
    return encode_log(keys, K, c.ball, bool(p.goal), c.ident), p


def demo_file(c):
    """SPEC.md 130.14.7.4: a shipped demo's part file, named by its course's NAME (never by K)"""
    return "BZD%s.BIN" % c.name


def build_demos(courses, paths, demo_dir=None):
    """every course's demo but a test course's (SPEC.md 130.54): its .bzd when there is one, else a
    route demo; each checked by the model.  -> {K: {log kind where warn p}}, in course order (the demo
    rows' order, BZ_DEMO_CRS)"""
    idents = [c.ident for c in courses]
    out = {}
    for K, c in enumerate(courses):
        if c.test:
            continue
        dp = demo_path(paths[K], demo_dir)
        if os.path.exists(dp):
            rel = os.path.relpath(dp, ROOT) if dp.startswith(ROOT + os.sep) else dp
            with open(dp, "r", encoding="ascii") as f:
                d = parse_bzd(f.read(), rel)
            if d["name"] != c.name:
                raise CourseError("%s: the demo names course %s; this file is %s's" % (rel, d["name"], c.name))
            show = []
            if d["ident"] != c.ident and getattr(c, "fshow", None) is not None \
                    and any(isinstance(t, FieldTile) for t in c.tiles.values()):
                # SPEC.md 130.28.6: the SHOW rule (the toggle) moves the picture and never the physics, so a demo
                # authored on the default's course (its identity THAT one) ships under the rule with the BUILD's
                # identity re-stamped - the model's replay below still checks it, step for step
                c0 = compile_course(paths[K], _hack={"fshow": None})
                if d["ident"] == c0.ident:
                    show.append("%s: identity %04Xh re-stamped %04Xh by the build: the SHOW rule (SPEC.md 130.28.6) "
                                "moves the picture alone" % (rel, d["ident"], c.ident))
                    d["ident"] = c.ident
            log, warn, p = check_demo(c, K, bzd_log(d, K), idents, rel)
            warn = show + warn
            if c.name == "PLAY":                    # wave 6 (SPEC.md 130.16.8): the demo that boosts
                ok, why = play_demo_verdict(c, log)
                if not ok:
                    raise CourseError("%s: the PLAYGROUND's demo must boost and end at its goal: %s" % (rel, why))
            kind = "file"
        else:
            rel = "%s's route demo" % c.name
            if c.name in AUTHOR:                    # wave 6 (SPEC.md 130.16.8): never a quiet route demo
                raise CourseError("%s: an AUTHORED course with no demo file (%s): write it with `python3 "
                                  "tools/bbcourse.py author %s`" % (c.name, os.path.relpath(dp, ROOT),
                                                                    os.path.relpath(paths[K], ROOT)))
            if len(c.route) < 2:
                raise CourseError("%s: no demo file (%s) and no route to make one from" % (
                    c.name, os.path.relpath(dp, ROOT)))
            log, warn, p = check_demo(c, K, route_demo(c, K), idents, rel)
            kind = "route"
        out[K] = {"log": log, "kind": kind, "where": rel, "warn": warn, "p": p}
    return out


def report(c, k=None):
    head = "course %s%s (%s, \"%s\", ball %s)" % ("%d " % k if k is not None else "", c.name,
                                                  os.path.basename(c.fname), c.title, MAT_NAMES[c.ball])
    g = c.part["grid"]

    def most(d):
        return max(d.values()) if d else 0
    top = min(c.reach, key=lambda rc: foot_top(rc, rc.zhi))
    print("  %s: %d x %d px (COLS %d, BROWS %d), X0 %d, Y0 %d (set by cell (%d, %d) at %d px: %s), reach "
          "settled in %d rounds, EMAX %d" % (
              head, c.width, c.lines, c.cols, c.brows, c.x0, c.y0, top.wx, top.wy, top.zhi,
              "%s of cell %s" % (top.src[1], top.src[0]) if top.src else "its own floor", c.rounds, c.emax))
    pt = c.part
    print("    part %d bytes in RAM (BZC2, RECB %d): header %d, map %d, blocks %d x 16 = %d, OCCIDX %d, records "
          "%d x %d = %d, masks %d x 16 = %d%s, grid %d (%d rows x %d cells x 4 + %d header, ROWTAB %d, route %d)%s, "
          "directory %d x %d; stored %d bytes, %d of them zero holes%s" % (
              len(c.cga), REC, HDR, 2 * c.cols * c.brows, len(c.blocks), 16 * len(c.blocks), 2 * (c.brows + 1),
              len(c.model["recs"]), REC, REC * len(c.model["recs"]), len(c.masks), 16 * len(c.masks),
              ", MTAB %d" % (2 * len(c.masks)),
              (pt["propoff"] or pt["wdiroff"] or pt["diroff"]) - pt["gridoff"], g["nrows"], g["kw"], GHDR,
              2 * g["nrows"], 4 * len(c.route),
              ", props %d" % ((pt["wdiroff"] or pt["diroff"]) - pt["propoff"]) if pt["nprop"] else "",
              pt["nsec"], DIRENT, len(c.stored), sum(e["len"] - e["dlen"] for e in pt["dir"] if not e["part"]),
              "; LZ4 %d as RECB 4 (%s)" % (c.packed4, budget_note(c, c.packed4))
              if getattr(c, "packed4", None) else ""))
    if c.split:                                     # SPEC.md 130.30: the two parts
        print("    TWO PARTS (SPEC.md 130.30): the picture part %d bytes (%d under 65,024), the world part %d (%d "
              "under); stored %d and %d" % (len(c.cga), PARTMAX - len(c.cga), len(c.wcga), PARTMAX - len(c.wcga),
                                            len(c.stored), len(c.wstored)))
    if c.sstored:                                   # SPEC.md 130.30.12: the picture part in SHEETS
        print("    SHEETS (SPEC.md 130.30.12): %d of %d block rows each, from rows %s, every one %d bytes" % (
            c.plan["k"], c.plan["n"], ", ".join(str(x["m0"]) for x in c.plan["sheets"]), len(c.cga)))
    print("    records %d -> %d merged (masks %d -> %d, %d with the ghost dither; %d records laying nothing once "
          "dithered left out of the part); most in a block %d -> %d (bound "
          "%d), in a block row %d -> %d (bound %d); most laid at a position %d%s; %d OCC cells (%d OCCG) of %d "
          "reachable" % (
              len(c.raw), len(c.records), c.raw_masks, c.umasks, len(c.masks),
              len(c.records) - len(c.model["recs"]), most(c.raw_block), most(c.per_block),
              REC_BLOCK_MAX, most(c.raw_row), most(c.per_row), REC_ROW_MAX, c.worst[0],
              " (cell %s at %d px)" % (c.worst[1], c.worst[2]) if c.worst[1] else "",
              sum(1 for v in c.cells.values() if v[3] & FL_OCC), sum(1 for v in c.cells.values() if v[3] & FL_OCCG),
              len(c.reach)))
    if c.ftabs:                                     # SPEC.md 130.28.4: the tables each shape statement costs
        rows = field_tables_by_statement(c.tiles)
        print("    section F: %d tables of %d (%d bytes); by statement: %s" % (
            len(c.ftabs), FSHAPE_MAX, FTAB * len(c.ftabs), "; ".join(
                "line %d %s adds %d%s" % (ln, w, len(add), " and shares %d (%s)" % (
                    len(sh), ", ".join(str(i) for i in sh)) if sh else "") for ln, w, add, sh in rows)))


def pans(c, log, herc, **gkw):
    """the HOST'S PREDICTION of GLIDE's pans over a demo LOG on course C on a
    card (SPEC.md 130.16.13's --pans): the log through Physics at the card's
    nominal step rate, Glide (the heavy rule on; LATTICE, or gkw's: _w6 for
    wave 6's policy) once a frame -> (columns, rows, two-row frames, seconds
    of play)"""
    r = cam_demo(c, log, herc, **gkw)
    rows = [f for f in r.rows if not f["full"]]
    return (sum(abs(f["dc"]) for f in rows), sum(abs(f["dr"]) for f in rows),
            sum(1 for f in rows if abs(f["dr"]) >= 2), r.p.nstep * STEP_PIT / float(PIT_HZ))


# =============================================================================
# the camera's harness and its checks (SPEC.md 130.17.6.5, 130.17.6.6,
# 130.17.9): --camcheck, --pans, item 8
# =============================================================================

CAM_AUTO = (1800, 1500)       # an autopilot's frames, CGA / Hercules (about 30 s)
CAM_DEDUP = ("FIRST", "TRIAL", "MILL")   # autopilots the totals count once with their demos (130.17.6.6)
CAM_PRICE = ((7.5, 19.7), (13.7, 18.8))  # 130.9's strip prices, k clk: a row, a column (CGA, Hercules)
CAM_BUSY = 27.0               # a frame of this many k clk of strips or more is "costly" (130.17.6.6)
CAM_EXIT = 90                 # the frames after a tube exit guarantee 5 watches
CAM_HALF = ("TRIAL", "MILL", "MOON", "PEAK", "PLAY")    # the half-rate pass, the CGA (130.17.6.6)
CAM_TAPS = (8, 15, 25)        # the dither map's tap lengths, ASSERTED; CAM_TAPS_P PRINTED (130.17.6.5 item 4)
CAM_TAPS_P = (40, 60)
CAM_STALL = 6                 # a stall: this many frames with a pan outstanding and no step, then a step


class CamRun:
    """a Physics stepped at a card's nominal step rate (SLOW times it: the
    half-rate pass's 2), the camera once a frame, every frame recorded: the
    harness of --camcheck and --pans (SPEC.md 130.17.9).  gkw: Glide's."""

    def __init__(self, c, herc, p, slow=1.0, heavy=True, **gkw):
        self.c, self.herc, self.p = c, herc, p
        self.g = Glide(p, herc, c.brows, c.cols, heavy=Heavy(p) if heavy else None, **gkw)
        self.spf = slow * (PIT_HZ / CARD_HZ[herc]) / STEP_PIT
        self.acc, self.fr, self.rows = 0.0, 0, []
        self.g.camera()

    def frame(self, stepper):
        """one frame: stepper() steps once (False: the run is over) -> False when over"""
        self.acc += self.spf
        n = int(self.acc)
        self.acc -= n
        for _ in range(n):
            if stepper() is False:
                return False
        g, p = self.g, self.p
        self.fr += 1
        R0, c0, wr, wc = g.R0, g.c0, g.nwr, g.nwc
        dr, dc, full = g.camera()
        lat = not (full or g._w6 or g.scripted)
        self.rows.append({
            "fr": self.fr, "dr": dr, "dc": dc, "full": full, "cut": g.cut, "tube": bool(p.tube), "lvl": g.level,
            "px": p.px, "py": p.py, "air": p.air, "vx": p.vx, "vy": p.vy, "R0b": R0, "c0b": c0, "R0": g.R0,
            "c0": g.c0, "resp": p.nfall + p.nret, "wr": g.nwr - wr, "wc": g.nwc - wc, "oc": g.want_c,
            "or": g.want_r, "cy": p.py + 8 + _s16(p.gz >> 8) - g.cgz,
            "near": g.heavy.near if g.heavy is not None else 0,
            "x": dict(g.ax.info) if lat else None, "y": dict(g.ay.info) if lat else None})
        return True


def cam_demo(c, log, herc, slow=1.0, heavy=True, **gkw):
    """a demo LOG through the model (play) -> its CamRun, to the goal or the log's end"""
    _k, mat, kt, _fl = decode_log_t(log)
    p = Physics(c, play=True, mat=mat)
    r = CamRun(c, herc, p, slow, heavy, **gkw)
    it = iter(kt)

    def st():
        if p.goal:
            return False
        k = next(it, None)
        if k is None:
            return False
        p.step(k[0], k[1])
    while r.frame(st):
        pass
    return r


def cam_auto(c, herc, frames=None, slow=1.0, heavy=True, **gkw):
    """the course's autopilot (not a play: Physics(play=False) with the course's
    ball) for CAM_AUTO frames, or to the goal -> its CamRun"""
    p = Physics(c, play=False, mat=c.ball)
    r = CamRun(c, herc, p, slow, heavy, **gkw)
    frames = CAM_AUTO[herc] if frames is None else frames

    def st():
        if p.goal:
            return False
        p.step_auto()
    while r.fr < frames and r.frame(st):
        pass
    return r


def cam_runs(courses, demos, slow=1.0, which=None, cards=(0, 1), **gkw):
    """every demo and every autopilot (130.17.6.1's set) -> {(name, herc,
    'demo' | 'auto'): rows}; which: the course names to run, or every one"""
    out = {}
    for K, c in enumerate(courses):
        if which is not None and c.name not in which:
            continue
        for herc in cards:
            if K in demos:
                out[(c.name, herc, "demo")] = cam_demo(c, demos[K]["log"], herc, slow, **gkw).rows
            out[(c.name, herc, "auto")] = cam_auto(c, herc, slow=slow, **gkw).rows
    return out


def cam_episodes(rows, k, gap=4):
    """runs of steps of one sign on an axis (k: 'dr' or 'dc'), merged across
    gaps of up to GAP still frames; a full write ends one"""
    eps, cur = [], None
    for i, f in enumerate(rows):
        if f["full"]:
            if cur:
                eps.append(cur)
            cur = None
            continue
        m = f[k]
        if not m:
            continue
        sg = 1 if m > 0 else -1
        if cur and cur["s"] == sg and i - cur["end"] <= gap + 1:
            cur["end"], cur["amt"] = i, cur["amt"] + abs(m)
        else:
            if cur:
                eps.append(cur)
            cur = {"s": sg, "start": i, "end": i, "amt": abs(m)}
    if cur:
        eps.append(cur)
    return eps


def cam_reversals(rows, herc, ax):
    """REVERSALS (130.17.6.1's measure): a pan the other way on axis AX ('c'
    or 'r') starting within 2 s of one ending, no full write and no respawn
    between -> [(the first episode, the second)]"""
    within = int(2 * CARD_HZ[herc])
    eps = cam_episodes(rows, "dr" if ax == "r" else "dc")
    out = []
    for a, b in zip(eps, eps[1:]):
        if b["s"] != a["s"] and b["start"] - a["end"] <= within and \
                not any(rows[i]["full"] for i in range(a["end"], b["start"] + 1)) and \
                rows[a["start"]]["resp"] == rows[b["start"]]["resp"]:
            out.append((a, b))
    return out


def _cam_outstanding(rows, ax):
    """runs of frames with a pan outstanding on AX (a target not reached, a step or a withheld step)"""
    ko, km, kw = ("or", "dr", "wr") if ax == "r" else ("oc", "dc", "wc")
    runs, cur = [], None
    for i, f in enumerate(rows):
        if not f["full"] and (f[ko] or f[km] or f[kw]):
            cur = (cur or []) + [i]
        else:
            if cur:
                runs.append(cur)
            cur = None
    if cur:
        runs.append(cur)
    return runs


def cam_stalls(rows, ax):
    """STALLS: CAM_STALL or more frames with a pan outstanding and no step, then a step -> [(frame, length)]"""
    km = "dr" if ax == "r" else "dc"
    out = []
    for run in _cam_outstanding(rows, ax):
        z = 0
        for j, i in enumerate(run):
            if rows[i][km] == 0:
                z += 1
            else:
                if z >= CAM_STALL:
                    out.append((rows[run[j - z]]["fr"], z))
                z = 0
    return out


def cam_slowfast(rows, ax):
    """SLOW-THEN-FAST windows (the owner's "slows down, then quickly moves
    over"): inside one outstanding run, a window of 4 frames (rows) or 8
    (columns) that pans at most half of the best such window in the 40 frames
    after it -> [(frame, its steps, the best after)]"""
    km = "dr" if ax == "r" else "dc"
    W = 4 if ax == "r" else 8
    out = []
    for run in _cam_outstanding(rows, ax):
        if len(run) < W + 2:
            continue
        mv = [abs(rows[i][km]) for i in run]
        win = [sum(mv[j:j + W]) for j in range(len(mv) - W + 1)]
        j = 0
        while j < len(win):
            after = max(win[j + W:j + W + 40] or [0])
            if after >= W // 2 and win[j] * 2 <= after and after - win[j] >= 2:
                out.append((rows[run[j]]["fr"], win[j], after))
                j += W
            else:
                j += 1
    return out


def _cam_runs_of(flags):
    out, n = [], 0
    for v in list(flags) + [False]:
        if v:
            n += 1
        elif n:
            out.append(n)
            n = 0
    return out


def cam_summary(rows, herc):
    """one run's figures (130.17.6.6): pans, two-row frames, reversals,
    stalls, slow-then-fast windows, and outside tubes the priced work, the
    column runs and the costly runs"""
    rc, cc = CAM_PRICE[herc]
    lt = [f for f in rows if not f["full"]]
    out = [f for f in lt if not f["tube"]]
    d = {"frames": len(rows), "rows": sum(abs(f["dr"]) for f in lt), "cols": sum(abs(f["dc"]) for f in lt),
         "two": sum(1 for f in lt if abs(f["dr"]) >= 2), "two_out": sum(1 for f in out if abs(f["dr"]) >= 2),
         "c2r": sum(1 for f in lt if f["dc"] and abs(f["dr"]) >= 2),
         "kclk": sum(abs(f["dr"]) * rc + abs(f["dc"]) * cc for f in out),
         "colf": sum(1 for f in out if f["dc"])}
    d["rev"] = [(ax, rows[b["start"]]["fr"]) for ax in "cr" for a, b in cam_reversals(rows, herc, ax)]
    d["stall"] = [(ax,) + s for ax in "cr" for s in cam_stalls(rows, ax)]
    d["sf"] = [(ax,) + s for ax in "cr" for s in cam_slowfast(rows, ax)]
    nf = lambda f: not f["full"] and not f["tube"]
    cr = _cam_runs_of(nf(f) and bool(f["dc"]) for f in rows)
    br = _cam_runs_of(nf(f) and abs(f["dr"]) * rc + abs(f["dc"]) * cc >= CAM_BUSY for f in rows)
    d["colruns"] = [x for x in cr if x >= 2]
    d["busyruns"] = [x for x in br if x >= 2]
    d["l2cga"] = (sum(abs(f["dc"]) for f in out if f["lvl"] == 2), sum(abs(f["dr"]) for f in out if f["lvl"] == 2),
                  sum(1 for f in out if f["lvl"] == 2)) if not herc else (0, 0, 0)
    d["starts"] = sum(1 for f in lt if f["y"] and f["y"]["born"]), sum(1 for f in lt if f["x"] and f["x"]["born"])
    d["eps"] = len(cam_episodes(rows, "dr")), len(cam_episodes(rows, "dc"))    # either policy's (LATTICE's born: starts)
    return d


def cam_margins(rows, herc):
    """the ball's footprint (130.4's, from px & ~3, 20 x 16) against the window
    on every frame outside tubes -> (frames it is not wholly inside, the worst
    margin across px, the worst down lines)"""
    W, _H, rl, lsh = CARDS[herc]
    bad, mx, my = [], 9999, 9999
    for f in rows:
        if f["tube"]:
            continue
        top, xa = f["R0"] << lsh, 8 * f["c0"]
        fx = f["px"] & ~3
        a, b = fx - xa, xa + 8 * W - (fx + FOOT_W)
        u, v = f["py"] - top, top + WIN_LINES - (f["py"] + FOOT_H)
        if (f["px"] >> 3) < f["c0"] or (((f["px"] >> 2) + 4) >> 1) >= f["c0"] + W or \
                f["py"] < top or f["py"] > top + WIN_LINES - BALL_D:
            bad.append(f["fr"])
        mx, my = min(mx, a, b), min(my, u, v)
    return bad, mx, my


def cam_lookahead(rows, herc):
    """the room ahead of a moving ball, as a share of the window: across (|vx|
    >= 1 px a step) and down (grounded, |vy| >= half a line), outside tubes"""
    W, _H, rl, lsh = CARDS[herc]
    ax, ay = [], []
    for f in rows:
        if f["full"] or f["tube"]:
            continue
        ox = f["px"] + 8 - 8 * f["c0"]
        oy = f["cy"] - (f["R0"] << lsh)
        if abs(f["vx"]) >= 256:
            ax.append((8 * W - ox if f["vx"] > 0 else ox) / (8.0 * W))
        if abs(f["vy"]) >= 128 and not f["air"]:
            ay.append((WIN_LINES - oy if f["vy"] > 0 else oy) / float(WIN_LINES))
    return ax, ay


def _pct(a, q):
    return sorted(a)[int(q * (len(a) - 1))] if a else -1


def cam_guarantees(rows, herc, name):
    """130.17.6.5's guarantees 1 - 3 on one run of LATTICE -> [failures]"""
    bad = []
    lim = {1: LAT_H1, 2: LAT_H2}
    for f in rows:
        for ax in ("x", "y"):
            inf = f[ax]
            if inf is None:
                continue
            tag = "%s frame %d %s" % (name, f["fr"], "columns" if ax == "x" else "rows")
            # 1: a pan born only when the point left the band on its side
            if inf["born"] and inf["w"] != inf["s"] and inf["s"]:
                bad.append("%s: guarantee 1, a pan %+d born with the point inside the band" % (tag, inf["s"]))
            if inf["s0"] and inf["s"] and inf["s"] != inf["s0"] and not (inf["born"] and inf["w"] == inf["s"]):
                bad.append("%s: guarantee 1, the pan turned with the point inside the band" % tag)
            # 2 (a): the latch never clears inside a pan (checked against the frame before, below)
            # 2 (b): held within its cap
            if inf["held"] > LAT_H2 or (inf["wh"] and inf["held"] > lim[f["lvl"]]):
                bad.append("%s: guarantee 2 (b), %d steps withheld running at level %d" % (tag, inf["held"],
                                                                                      f["lvl"]))
            # 2 (c): never more than the pan's rate
            st = abs(inf["step"])
            if st > (1 if ax == "x" else 2 if inf["fast"] else 1):
                bad.append("%s: guarantee 2 (c), %d steps on a %s pan" % (tag, st, "fast" if inf["fast"] else
                                                                           "slow"))
    for ax in ("x", "y"):
        prev = None
        for f in rows:
            inf = f[ax]
            if inf is None:
                prev = None
                continue
            if prev is not None and inf["s0"] and not inf["born"] and inf["pid"] == prev["pid"] and \
                    prev["fast"] and not inf["fast"]:
                bad.append("%s frame %d %s: guarantee 2 (a), the pan's fast latch cleared" % (
                    name, f["fr"], "columns" if ax == "x" else "rows"))
            prev = inf
    out, _mx, _my = cam_margins(rows, herc)
    if out:
        bad.append("%s: guarantee 3, the ball's footprint outside the window on %d frames (first %d)" % (
            name, len(out), out[0]))
    return bad


def cam_two_rows(rows, name):
    """the TWO-ROW check (130.17.9): a frame takes two rows only on a pan whose
    fast the urgent edge or a tube set -> [failures]"""
    bad = []
    why = {}
    for f in rows:
        inf = f["y"]
        if inf is None:
            continue
        if inf["rise"]:
            why[inf["pid"]] = inf["rise"]
        if abs(f["dr"]) >= 2 and why.get(inf["pid"]) not in ("urgent", "tube"):
            bad.append("%s frame %d: two rows on a pan made fast by %s" % (name, f["fr"], why.get(inf["pid"])))
    return bad


def cam_exits(rows, name):
    """GUARANTEE 5 (the tube-exit check): at every tube exit, in the CAM_EXIT
    frames after it no pan is born fast and no pan's rate rises, and a pan
    still running at the exit takes its every step, none withheld, until it
    ends -> (exits, [failures])"""
    bad, n = [], 0
    for i, f in enumerate(rows):
        if not (i and rows[i - 1]["tube"] and not f["tube"]):
            continue
        n += 1
        live = {}
        for ax in ("x", "y"):
            inf = rows[i - 1][ax]
            if inf is not None and inf["s1"]:
                live[ax] = inf["pid"]
        for g in rows[i:i + CAM_EXIT]:
            if g["full"]:
                break
            for ax in ("x", "y"):
                inf = g[ax]
                if inf is None:
                    continue
                what = "%s exit at frame %d, %s frame %d" % (name, f["fr"], "columns" if ax == "x" else "rows",
                                                             g["fr"])
                if inf["born"] and inf["rise"]:
                    bad.append("%s: a pan born fast (%s)" % (what, inf["rise"]))
                elif inf["rise"]:
                    bad.append("%s: a pan's rate rose (%s)" % (what, inf["rise"]))
                if ax in live:
                    if inf["pid"] != live[ax] or not inf["s0"]:
                        live.pop(ax)
                        continue
                    if inf["wh"]:
                        bad.append("%s: the pre-aimed pan's step withheld" % what)
                    if not inf["s1"]:
                        live.pop(ax)
    return n, bad


def cam_exit_work(rows):
    """the camera's pan work left after the tube exits: the steps (rows and
    columns) taken in the CAM_EXIT frames after each exit, summed"""
    n = 0
    for i, f in enumerate(rows):
        if i and rows[i - 1]["tube"] and not f["tube"]:
            for g in rows[i:i + CAM_EXIT]:
                if g["full"]:
                    break
                n += sum(abs(g[ax]["step"]) for ax in ("x", "y") if g[ax] is not None)
    return n


def _cam_fork(base):
    """a CamRun's copy a branch can step without touching BASE (the course,
    its grid and props shared, never written)"""
    import copy
    p0 = base.p
    memo = {id(p0.grid): p0.grid, id(p0.props): p0.props, id(base.c): base.c}
    p, g = copy.deepcopy((p0, base.g), memo)
    r = CamRun.__new__(CamRun)
    r.c, r.herc, r.p, r.g, r.spf, r.acc, r.fr, r.rows = base.c, base.herc, p, g, base.spf, base.acc, base.fr, []
    return r


def _cam_play(r, pat):
    """step R through PAT, [(key byte, steps)] -> True when the branch stayed
    clean (no fall or RETURN, no goal, no frame in a tube)"""
    p = r.p
    seq = iter([k for k, n in pat for _ in range(n)])
    n0 = p.nfall + p.nret

    def st():
        k = next(seq, None)
        if k is None:
            return False
        p.step(k)
    while r.frame(st):
        pass
    return p.nfall + p.nret == n0 and not p.goal and not any(f["tube"] for f in r.rows)


def _cam_revs(rows, herc):
    return sum(len(cam_reversals(rows, herc, ax)) for ax in "cr")


def _dither_keys(gvx, gvy, sign):
    """the key chord that pushes along (sign = 1) or against (-1) the ball's ground velocity"""
    sx, sy = (gvx > 0) - (gvx < 0), (gvy > 0) - (gvy < 0)
    if abs(gvx) > 2 * abs(gvy):
        sy = 0
    elif abs(gvy) > 2 * abs(gvx):
        sx = 0
    return {(1, 1): K_D, (1, -1): K_R, (-1, 1): K_L, (-1, -1): K_U, (1, 0): K_R | K_D, (-1, 0): K_L | K_U,
            (0, 1): K_L | K_D, (0, -1): K_U | K_R}.get((sx * sign, sy * sign), 0)


def cam_dither(c, herc, log=None, taps=CAM_TAPS, every=0.5, secs=60, **gkw):
    """THE DITHER MAP (SPEC.md 130.17.6.1, 130.17.6.5 item 4): along the demo
    (or the autopilot), every EVERY seconds of the first SECS with the ball
    grounded and moving, a branch brakes 30 steps (Grip) and taps against its
    travel, releases, taps along it, releases, taps against it again (TAP
    steps each, 50 and 70 released), and a control branch brakes and
    releases.  A sample REVERSES when its taps make more reversals than the
    control.  -> {tap: [(frame, the tile, taps' reversals, the control's)]}"""
    if log is not None:
        _k, mat, kt, _fl = decode_log_t(log)
        p = Physics(c, play=True, mat=mat)
        it = iter(kt)

        def step():
            if p.goal:
                return False
            k = next(it, None)
            if k is None:
                return False
            p.step(k[0], k[1])
    else:
        p = Physics(c, play=False, mat=c.ball)

        def step():
            if p.goal:
                return False
            p.step_auto()
    r = CamRun(c, herc, p, **gkw)
    out = {t: [] for t in taps}
    nxt, hz = 0, CARD_HZ[herc]
    while r.fr < int(secs * hz) and r.frame(step):
        r.rows = r.rows[-1:]                    # (the base run's rows are not read)
        if r.fr < nxt or p.air or p.tube or abs(p.gvx) + abs(p.gvy) <= 24:
            continue
        nxt = r.fr + int(every * hz)
        back, fwd = _dither_keys(p.gvx, p.gvy, -1), _dither_keys(p.gvx, p.gvy, 1)
        ctl = _cam_fork(r)
        if not _cam_play(ctl, [(K_GRIP, 30), (0, 270)]):
            continue
        nc = _cam_revs(ctl.rows, herc)
        for t in taps:
            b = _cam_fork(r)
            if _cam_play(b, [(K_GRIP, 30), (back, t), (0, 50), (fwd, t), (0, 50), (back, t), (0, 70)]):
                out[t].append((r.fr, (p.gx >> 12, p.gy >> 12), _cam_revs(b.rows, herc), nc))
    return out


# MILL's ramp bottom (SPEC.md 130.17.6.1, 130.17.6.5 item 4): rubber poked at (15, 7), rolled down B's ramp
# (Down + Left) to the green (tile y 18), then each PATTERN, (key byte, steps)
RAMP_POKE, RAMP_GREEN = (15, 7), 18
_RDN, _RUP = K_D | K_L, K_U | K_R
RAMP_PATTERNS = (
    ("coast", [(0, 300)]),
    ("brake and ease 8", [(K_GRIP, 60), (0, 20)] + [(_RUP, 8), (0, 50), (_RDN, 8), (0, 50)] * 4),
    ("brake and ease 20", [(K_GRIP, 60), (0, 20)] + [(_RUP, 20), (0, 50), (_RDN, 20), (0, 50)] * 4),
    ("climb tries", [(K_GRIP, 60)] + [(_RUP, 80), (0, 60)] * 3),
    ("wiggles", [(K_GRIP, 60)] + [(K_L, 15), (0, 30), (K_R, 15), (0, 30)] * 4),
    ("back once", [(K_GRIP, 60), (0, 20), (_RUP, 10), (0, 120)]),
)


def ramp_bottom(c, herc, pat, **gkw):
    """one ramp-bottom pattern on MILL -> (the CamRun, the frame the pattern began)"""
    p = Physics(c, play=True).poke(*RAMP_POKE)
    r = CamRun(c, herc, p, **gkw)
    seq = iter([k for k, n in pat for _ in range(n)])
    st = {"start": None}

    def step():
        if st["start"] is None:
            if (p.gy >> 12) < RAMP_GREEN:
                p.step(_RDN)
                return
            st["start"] = r.fr
        k = next(seq, None)
        if k is None:
            return False
        p.step(k)
    while r.frame(step) and not p.nfall:
        pass
    return r, st["start"]


def ramp_reversals(c, herc, **gkw):
    """-> [(pattern, reversals from its start, rows, columns)] on the card"""
    out = []
    for name, pat in RAMP_PATTERNS:
        r, s = ramp_bottom(c, herc, pat, **gkw)
        s = s if s is not None else len(r.rows)
        n = sum(1 for ax in "cr" for a, b in cam_reversals(r.rows, herc, ax) if b["start"] >= s - 1)
        d = [f for f in r.rows[s:] if not f["full"]]
        out.append((name, n, sum(abs(f["dr"]) for f in d), sum(abs(f["dc"]) for f in d)))
    return out


# the SIDE check's CONSTRUCTED scenario (SPEC.md 130.17.6.3, 130.17.9): the shipped runs have no frame on
# which level 1's side decides, so this one is built for it - MILL's rubber ball poked at rest on (21, 17),
# Right held: the lift's slab near the window's BOTTOM while a column pan runs to the right, so a side-blind
# level 1 withholds columns the side-aware rule takes (found on 6b's model by a search of the tiles round
# the lift, every chord; bonanzaring's CAMERA leg replays it)
SIDE_SCEN = {"crs": "MILL", "at": (21, 17), "keys": K_R, "steps": 240}


def side_run(c, herc, **gkw):
    """SIDE_SCEN on course C (MILL) -> its CamRun"""
    p = Physics(c, play=True).poke(*SIDE_SCEN["at"])
    r = CamRun(c, herc, p, **gkw)
    left = [SIDE_SCEN["steps"]]

    def st():
        if not left[0]:
            return False
        left[0] -= 1
        p.step(SIDE_SCEN["keys"])
    while r.frame(st):
        pass
    return r


def side_check(rows, name):
    """the SIDE check: level 1 withholds a column only with the near-edge bit
    of the column pan's heading set, and cuts rows only with the row pan's ->
    (frames on which the side decided, [failures])"""
    bad, n = [], 0
    for f in rows:
        if f["lvl"] != 1:
            continue
        for ax, bits in (("x", (NEAR_L, NEAR_R)), ("y", (NEAR_T, NEAR_B))):
            inf = f[ax]
            if inf is None:
                continue
            n += inf["side"]
            if inf["wh"] and not f["near"] & bits[inf["s"] > 0]:
                bad.append("%s frame %d: level 1 withheld %s heading %s with that edge's bit clear (bz_pflag "
                           "%02Xh)" % (name, f["fr"], "a column" if ax == "x" else "a row",
                                       ("left", "right", "up", "down")[(ax == "y") * 2 + (inf["s"] > 0)], f["near"]))
    return n, bad


def _cam_rises(rows):
    """every rate rise: -> ['<axis><cause>@<frame>' ...] (a capital: born fast)"""
    out = []
    for f in rows:
        for ax in ("x", "y"):
            inf = f[ax]
            if inf is not None and inf["rise"]:
                w = {"urgent": "u", "ring": "r", "tube": "t"}[inf["rise"]]
                out.append("%s%s@%d" % ("c" if ax == "x" else "r", w.upper() if inf["born"] else w, f["fr"]))
    return out


def _cam_sf_cause(rows, sf):
    """a slow-then-fast window's cause: what made it slow, 'heavy' (steps
    withheld in it), and what made the pan fast after it, the rate rise in
    the 50 frames from the window's start (urgent edge, ring or tube) - both
    when both hold, so a heavy-slowed pan that a tube then turns fast says
    so; '?' when neither"""
    ax, fr = sf[0], sf[1]
    i = next((j for j, f in enumerate(rows) if f["fr"] == fr), 0)
    k, kw = ("x", "wc") if ax == "c" else ("y", "wr")
    W = 8 if ax == "c" else 4
    why = []
    if any(rows[j][kw] for j in range(i, min(len(rows), i + W))):
        why.append("heavy")
    for f in rows[i:i + 50]:
        inf = f[k]
        if inf is not None and inf["rise"]:
            why.append("%s rise at %d" % (inf["rise"], f["fr"]))
            break
    return ", then ".join(why) or "?"


def bench_dirs(bench, scripted, rates=range(96, 105), phases=range(10), **gkw):
    """item 8 (SPEC.md 130.17.6.7): BENCH's 1,200 frames at 0.96 - 1.04 x
    PHASES -> ({(herc, dir): the fewest frames that scrolled that way},
    scripted frames whose footprint left the window)"""
    mins, lost = {}, 0
    for herc in (0, 1):
        for r in rates:
            for ph in phases:
                bad = [0]

                def cb(p, g, dr, dc, bad=bad):
                    bad[0] += g.outwin()
                d, _gp = glide_run(bench, herc, r / 100.0, ph / 10.0, scripted=scripted, frame_cb=cb, **gkw)
                lost += bad[0]
                for k in DIRS:
                    mins[(herc, k)] = min(mins.get((herc, k), 1 << 30), d.get(k, 0))
    return mins, lost


def camcheck(courses, demos, res, controls=True):
    """--camcheck (SPEC.md 130.17.9), item 8 runs it whole: LATTICE over every
    demo and autopilot on both cards, 130.17.6.5's guarantees 1 - 3 and 5,
    the side check, the two-row check, MILL's ramp bottom and the dither map
    ASSERTED into RES; the rest REPORTED; and with CONTROLS each broken model
    going red at its own check"""
    t0 = time.time()
    by = {c.name: c for c in courses}
    R = cam_runs(courses, demos)
    S = {k: cam_summary(rows, k[1]) for k, rows in R.items()}
    g13, two, ex, nex = [], [], [], 0
    for k, rows in R.items():
        nm = "%s %s %s" % (k[0], ("CGA", "Hercules")[k[1]], k[2])
        g13 += cam_guarantees(rows, k[1], nm)
        two += cam_two_rows(rows, nm)
        n, b = cam_exits(rows, nm)
        nex += n
        ex += b
    nfr = sum(len(r) for r in R.values())
    res.append(("8 LATTICE (bbcourse.Glide, 130.17.6.2) over every demo and autopilot on both cards (%d runs, %d "
                "frames): guarantee 1 (a pan born, or turned, only with the point outside the band on its side), 2 "
                "(a pan's fast latch never clears; no axis withheld past H2 = %d, nor past H1 = %d on a level-1 "
                "frame; no frame steps more than its pan's rate) and 3 (the ball's footprint inside the window "
                "outside tubes)%s" % (len(R), nfr, LAT_H2, LAT_H1, "" if not g13 else ": %d failures, the first: %s"
                                      % (len(g13), g13[0])), not g13))
    res.append(("8 the TWO-ROW check: a frame takes two rows only on a pan the urgent edge or a tube made fast "
                "(%d two-row frames)%s" % (sum(s["two"] for s in S.values()), "" if not two else
                                           ": %d failures, the first: %s" % (len(two), two[0])), not two))
    res.append(("8 guarantee 5, every tube exit smooth: at each of the %d exits no pan is born fast and no pan's "
                "rate rises in the %d frames after it, and a pan running at the exit takes every step, none "
                "withheld, until it ends%s" % (nex, CAM_EXIT, "" if not ex else ": %d failures, the first: %s"
                                                % (len(ex), ex[0])), nex > 0 and not ex))
    # the side check, on its constructed scenario
    sd = []
    for herc in (0, 1):
        n, b = side_check(side_run(by[SIDE_SCEN["crs"]], herc).rows, "SIDE %s" % ("CGA", "Hercules")[herc])
        sd.append((n, b))
    res.append(("8 the SIDE check on its constructed scenario (%s's rubber ball poked at %s, %s held %d steps): "
                "level 1 withholds a column, or cuts rows, only with the edge bit of the pan's heading set "
                "(bz_pflag bits 4 - 7), and the side DECIDES on %d CGA frames and %d Hercules frames%s" % (
                    SIDE_SCEN["crs"], SIDE_SCEN["at"], keys_text(SIDE_SCEN["keys"]), SIDE_SCEN["steps"], sd[0][0],
                    sd[1][0], "" if not (sd[0][1] or sd[1][1]) else ": %s" % (sd[0][1] + sd[1][1])[0]),
                sd[0][0] > 0 and sd[1][0] > 0 and not sd[0][1] and not sd[1][1]))
    # MILL's ramp bottom
    rb = {herc: ramp_reversals(by["MILL"], herc) for herc in (0, 1)}
    res.append(("8 MILL's ramp bottom, rolled down B's ramp to the green: %s - no reversal on either card" % "; ".join(
        "%s %s" % (n, "/".join(str(x[1]) for x in (rb[0][i], rb[1][i]))) for i, (n, _p) in enumerate(RAMP_PATTERNS)),
        all(x[1] == 0 for herc in (0, 1) for x in rb[herc])))
    # the dither map
    dm = {}
    for K, c in enumerate(courses):
        for herc in (0, 1):
            d = cam_dither(c, herc, demos[K]["log"] if K in demos else None, taps=CAM_TAPS + CAM_TAPS_P)
            for tap, v in d.items():
                dm.setdefault(tap, []).extend((c.name, herc) + x for x in v)
    rev = {t: [x for x in v if x[4] > x[5]] for t, v in dm.items()}
    res.append(("8 the DITHER MAP (brake, then taps against, along and against the ball's travel): no sample "
                "reverses a pan at taps of %s steps (%s samples)" % (
                    ", ".join(str(t) for t in CAM_TAPS), ", ".join("%d of %d" % (len(rev[t]), len(dm[t]))
                                                                   for t in CAM_TAPS)),
                all(not rev[t] for t in CAM_TAPS) and all(dm[t] for t in CAM_TAPS)))
    # ---- REPORTED ----
    print("    LATTICE (130.17.6.6), each run at its card's nominal step rate, the heavy rule on: seconds, columns "
          "and rows a second, two-row frames, reversals | wave 6's policy (Glide _w6)")
    W6 = cam_runs(courses, demos, _w6=True)
    S6 = {k: cam_summary(rows, k[1]) for k, rows in W6.items()}
    for k in sorted(R, key=lambda k: ([c.name for c in courses].index(k[0]), k[2], k[1])):
        s, s6 = S[k], S6[k]
        sec = len(R[k]) / CARD_HZ[k[1]]
        print("      %-5s %-4s %-8s %6.2f s | %5.2f %6.2f %3d %2d | wave 6 %5.2f %6.2f %3d %2d" % (
            k[0], k[2], ("CGA", "Hercules")[k[1]], sec, s["cols"] / sec, s["rows"] / sec, s["two"], len(s["rev"]),
            s6["cols"] / sec, s6["rows"] / sec, s6["two"], len(s6["rev"])))
    for lab, SS in (("LATTICE", S), ("wave 6", S6)):
        t = _cam_total(SS)
        print("    %-7s over every demo and autopilot, both cards (the autopilots of %s counted once with their "
              "demos): rows %d, columns %d, two-row frames %d, reversals %d, stalls of %d frames or more %d "
              "(the longest %d), slow-then-fast windows %d; outside tubes the priced pan work CGA %.0fk, Hercules "
              "%.0fk; runs of 2+ column frames CGA %s, Hercules %s; runs of 2+ frames of %.0fk or more CGA %s, "
              "Hercules %s; row and column pans (runs of one sign, still gaps of up to 4 frames merged) %d, %d%s" % (
                  lab, ", ".join(CAM_DEDUP), t["rows"], t["cols"], t["two"], t["rev"], CAM_STALL, t["stall"],
                  t["stallmax"], t["sf"], t["kclk"][0], t["kclk"][1], _runs_text(t["colruns"][0]),
                  _runs_text(t["colruns"][1]), CAM_BUSY, _runs_text(t["busyruns"][0]), _runs_text(t["busyruns"][1]),
                  t["eps"][0], t["eps"][1], "" if SS is S6 else "; LATTICE's row and column pans born %d, %d" % (
                      t["starts"][0], t["starts"][1])))
    print("    LATTICE's reversals left: %s" % "; ".join("%s %s %s %s at %d" % (k[0], ("CGA", "Hercules")[k[1]], k[2],
                                                                           "columns" if ax == "c" else "rows", fr)
                                                    for k in R for ax, fr in S[k]["rev"]))
    print("    every rate rise (c/r: columns/rows; u urgent, r ring, t tube; a CAPITAL is a pan born fast):")
    for k, rows in R.items():
        ri = _cam_rises(rows)
        if ri:
            print("      %s %s %s (%d): %s" % (k[0], ("CGA", "Hercules")[k[1]], k[2], len(ri), " ".join(ri)))
    sfl = [(k, x, _cam_sf_cause(R[k], x)) for k in R for x in S[k]["sf"]]
    print("    the slow-then-fast windows (%d): %s" % (len(sfl), "; ".join("%s %s %s %s at %d (%s)" % (
        k[0], ("CGA", "Hercules")[k[1]], k[2], "columns" if x[0] == "c" else "rows", x[1], why) for k, x, why in sfl)))
    l2 = [sum(S[k]["l2cga"][i] for k in S if k[1] == 0 and not (k[0] in CAM_DEDUP and k[2] == "auto"))
          for i in range(3)]
    print("    steps the cap forced onto the CGA's level-2 frames outside tubes: %d columns and %d rows on %d "
          "level-2 frames (130.17.6.3)" % tuple(l2))
    for herc in (0, 1):
        la = {}
        for lab, RR in (("LATTICE", R), ("wave 6", W6)):
            ax_, ay_, mx, my = [], [], 9999, 9999
            for k, rows in RR.items():
                if k[1] != herc:
                    continue
                a, b = cam_lookahead(rows, herc)
                ax_ += a
                ay_ += b
                _o, x, y = cam_margins(rows, herc)
                mx, my = min(mx, x), min(my, y)
            la[lab] = (_pct(ax_, .1), _pct(ax_, .5), _pct(ay_, .1), _pct(ay_, .5), mx, my)
        print("    %s: the room ahead of a moving ball, 10th / 50th percentile, across %.2f / %.2f, down %.2f / %.2f "
              "of the window; the footprint's worst margin outside tubes %d px across, %d lines down (wave 6: "
              "%.2f / %.2f, %.2f / %.2f; %d px, %d lines)" % ((("CGA", "Hercules")[herc],) + la["LATTICE"] +
                                                              la["wave 6"]))
    print("    the dither map at the printed taps: %s" % "; ".join(
        "%d steps %d of %d (%s)" % (t, len(rev[t]), len(dm[t]), ", ".join("%s %s at %d" % (
            x[0], ("CGA", "Hercules")[x[1]], x[2]) for x in rev[t]) or "none") for t in CAM_TAPS_P))
    r6 = [ramp_reversals(by["MILL"], herc, _w6=True) for herc in (0, 1)]
    print("    MILL's ramp bottom under wave 6's policy (reversals CGA/Hercules): %s" % "; ".join(
        "%s %d/%d" % (n, r6[0][i][1], r6[1][i][1]) for i, (n, _p) in enumerate(RAMP_PATTERNS)))
    H = cam_runs(courses, demos, slow=2.0, which=CAM_HALF, cards=(0,))
    H6 = cam_runs(courses, demos, slow=2.0, which=CAM_HALF, cards=(0,), _w6=True)
    for lab, HH in (("LATTICE", H), ("wave 6", H6)):
        hs = {k: cam_summary(rows, 0) for k, rows in HH.items() if not (k[0] in CAM_DEDUP and k[2] == "auto")}
        mg = [cam_margins(rows, 0) for rows in HH.values()]
        print("    the HALF-RATE pass (each frame twice the steps; %s's demos and autopilots, the CGA, outside "
              "tubes), %s: two-row frames %d (%s), priced work %.0fk (%s), runs of 2+ column frames %s, "
              "slow-then-fast windows %d; the footprint out of the window on %d frames, its worst margin %d px "
              "across, %d lines down" % (
                  ", ".join(CAM_HALF), lab, sum(s["two_out"] for s in hs.values()),
                  ", ".join("%s %s %d" % (k[0], k[2], s["two_out"]) for k, s in hs.items()),
                  sum(s["kclk"] for s in hs.values()), ", ".join("%s %s %.0fk" % (k[0], k[2], s["kclk"])
                                                                for k, s in hs.items()),
                  _runs_text(sum((s["colruns"] for s in hs.values()), [])), sum(len(s["sf"]) for s in hs.values()),
                  sum(len(m[0]) for m in mg), min(m[1] for m in mg), min(m[2] for m in mg)))
    hrise = [(k, r) for k, rows in H.items() for r in _cam_rises(rows) if r[:2] == "ru"]
    print("    the half-rate pass's row pans whose rate ROSE at the urgent edge (LATTICE): %s" % (
        "; ".join("%s %s %s" % (k[0], k[2], r) for k, r in hrise) or "none"))
    if controls:
        _cam_controls(courses, demos, by, res)
    print("    --camcheck: %.0f s" % (time.time() - t0))


def _runs_text(rs):
    return "%d (%d frames, the longest %d)" % (len(rs), sum(rs), max(rs or [0]))


def _cam_total(S):
    t = {"rows": 0, "cols": 0, "two": 0, "rev": 0, "stall": 0, "stallmax": 0, "sf": 0, "kclk": [0.0, 0.0],
         "colruns": [[], []], "busyruns": [[], []], "starts": [0, 0], "eps": [0, 0]}
    for k, s in S.items():
        if k[0] in CAM_DEDUP and k[2] == "auto":
            continue
        for n in ("rows", "cols", "two"):
            t[n] += s[n]
        t["rev"] += len(s["rev"])
        t["stall"] += len(s["stall"])
        t["stallmax"] = max([t["stallmax"]] + [x[2] for x in s["stall"]])
        t["sf"] += len(s["sf"])
        t["kclk"][k[1]] += s["kclk"]
        t["colruns"][k[1]] += s["colruns"]
        t["busyruns"][k[1]] += s["busyruns"]
        t["starts"][0] += s["starts"][0]
        t["starts"][1] += s["starts"][1]
        t["eps"][0] += s["eps"][0]
        t["eps"][1] += s["eps"][1]
    return t


def _cam_controls(courses, demos, by, res):
    """130.17.10's host controls, each its broken model (a Glide flag) red at its own check"""
    mill = by["MILL"]
    # nohyst: the ramp bottom and the dither map (the CGA's)
    rb = [x for herc in (0, 1) for x in ramp_reversals(mill, herc, _nohyst=True) if x[1]]
    dn = {}                                     # tap -> ["COURSE card n", ...]; PLAY's tap 60 is the ring arm's scenario
    for herc in (0, 1):
        for K, c in enumerate(courses):
            d = cam_dither(c, herc, demos[K]["log"] if K in demos else None, taps=(CAM_TAPS_P[-1],), _nohyst=True)
            for t, v in d.items():
                n = sum(1 for x in v if x[2] > x[3])
                if n:
                    dn.setdefault(t, []).append("%s %s %d" % (c.name, ("CGA", "Herc")[herc], n))
    # (round 3b, SPEC.md 130.17.17: the larger reach moved MILL's occluders and so the heavy rule's frames, and
    # with Hr 0 no ramp-bottom pattern reverses any more - about 50 searched on both cards - so the ramp
    # bottom is PRINTED and the control is held red at the dither map.  Wave 9 (the pickups yard, glass tiles,
    # grounded faces) moved PLAY's demo again: taps of 8 - 25 reverse nowhere on the CGA now, so the control
    # reads the 60-step taps, on BOTH cards, and is red only when each card has a reversing sample)
    print("    control `nohyst` at the ramp bottom: %s" % (
        ", ".join("%s reverses %d" % (x[0], x[1]) for x in rb) or "no reversal (round 3b's tree)"))
    res.append(("8 control `nohyst` (Hr 0): red at the dither map on both cards (the reversing samples: %s)" % (
        "; ".join("%d steps %s" % (t, ", ".join(dn[t])) for t in sorted(dn)) or "none"),
        bool(dn) and all(any(" %s " % cd in x for x in dn[t]) for t in dn for cd in ("CGA", "Herc"))))

    def every(**kw):
        return [("%s %s %s" % (k[0], ("CGA", "Hercules")[k[1]], k[2]), k[1], rows)
                for k, rows in cam_runs(courses, demos, **kw).items()]
    # nocap: guarantee 2 (b)
    b = [x for nm, herc, rows in every(_nocap=True) for x in cam_guarantees(rows, herc, nm) if "2 (b)" in x]
    res.append(("8 control `nocap` (no cap on the heavy rule): red at guarantee 2 (b) (%d frames; the first: %s)" % (
        len(b), b[0] if b else "-"), bool(b)))
    # ringy: the two-row check
    b = [x for nm, _h, rows in every(_ringy=True) for x in cam_two_rows(rows, nm)]
    res.append(("8 control `ringy` (rows read the ring): red at the two-row check (%d two-row frames on a pan the "
                "ring made fast; the first: %s)" % (len(b), b[0] if b else "-"), bool(b)))
    # noprex: guarantee 5 (SPEC.md 130.25.3: a pan a tube made fast is never withheld - the rule guarantee 5
    # rests on since the Y0 search moved PEAK's heavy frames onto a tube exit)
    b = [x for nm, _h, rows in every(_noprex=True) for x in cam_exits(rows, nm)[1]]
    res.append(("8 control `noprex` (a pre-aimed pan withheld like any other): red at the tube-exit check (%d "
                "failures; the first: %s)" % (len(b), b[0] if b else "-"), bool(b)))
    # nopreaim: the pan left after an exit (130.17.6.2: the pre-aim runs the pan during the transit, so the exit
    # has little left to do; without it the window still pans to the exit's framing, AFTER the exit). Before
    # 130.25.3 this control went red at guarantee 5, through the heavy rule's withholding, which the exemption
    # now rules out whatever the pre-aim does
    w0 = sum(cam_exit_work(rows) for _nm, _h, rows in every())
    w1 = sum(cam_exit_work(rows) for _nm, _h, rows in every(_nopreaim=True))
    res.append(("8 control `nopreaim` (no tube pre-aim): red at the work left after the exits (%d steps in the %d "
                "frames after every exit, against the shipped camera's %d)" % (w1, CAM_EXIT, w0), w1 > w0))
    # side0: the side check
    b = []
    for herc in (0, 1):
        b += side_check(side_run(mill, herc, _side0=True).rows, "SIDE %s" % ("CGA", "Hercules")[herc])[1]
    res.append(("8 control `side0` (level 1 side-blind): red at the side check on its scenario (%d frames; the "
                "first: %s)" % (len(b), b[0] if b else "-"), bool(b)))
    # noscr: item 8's eight directions
    mins, _l = bench_dirs(by["BENCH"], True, rates=(100,), phases=(0,), _noscr=True)
    res.append(("8 control `noscr` (bz_camscr's model ignored: LATTICE runs): red at the eight directions (the "
                "fewest %d, under 5)" % min(mins.values()), min(mins.values()) < 5))

def main_pans(paths):
    """--pans (SPEC.md 130.16.13, 130.17.9): each course's demo (K 1 ..), both
    cards: the columns and rows the camera pans and their rates, two-row
    frames, reversals, stalls and runs of column frames, wave 6's policy
    (Glide _w6) and LATTICE side by side - the host's prediction the
    re-baseline compares bonanzaperf's MEASURED pans against"""
    courses, _files, _texts = compile_all(paths)
    print("The camera's pans over each demo, the host's prediction (SPEC.md 130.16.13, 130.17.6.6): the log through "
          "Physics at the card's step rate, Glide with the heavy rule once a frame (the respawn cut modelled); "
          "wave 6's policy | LATTICE")
    print("| demo | card | seconds | columns | a second | rows | a second | two-row frames | reversals | stalls | "
          "column runs | columns | a second | rows | a second | two-row frames | reversals | stalls | column runs |")
    print("|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|")
    for K, d in sorted(compile_all.demos.items()):
        for herc in (0, 1):
            cells = []
            for kw in ({"_w6": True}, {}):
                r = cam_demo(courses[K], d["log"], herc, **kw)
                s = cam_summary(r.rows, herc)
                secs = r.p.nstep * STEP_PIT / float(PIT_HZ)
                cells.append("%d | %.2f | %d | %.2f | %d | %d | %d | %d" % (
                    s["cols"], s["cols"] / secs if secs else 0, s["rows"], s["rows"] / secs if secs else 0, s["two"],
                    len(s["rev"]), len(s["stall"]), len(s["colruns"])))
            print("| %d %s | %s | %.2f | %s | %s |" % (K, courses[K].name, ("CGA", "Hercules")[herc], secs, cells[0],
                                                     cells[1]))
    return 0


def main_camcheck(paths):
    """--camcheck (SPEC.md 130.17.9): item 8's camera checks alone"""
    courses, _files, _texts = compile_all(paths)
    res = []
    camcheck(courses, compile_all.demos, res)
    for what, good in res:
        print("  %-4s %s" % ("ok" if good else "FAIL", what))
    ok = all(g for _w, g in res)
    print("bbcourse --camcheck: %s" % ("ok" if ok else "FAILED"))
    return 0 if ok else 1

def write_out(out, paths, path=None, title=None, dev=False):
    """compile every course IN MEMORY first: a refused course removes the
    stamp and writes nothing, so make cannot take a stale part for current.
    DEV: the BZDEV=1 build's (`--dev`) - without it a TEST course is refused,
    so none ships (SPEC.md 130.54)"""
    os.makedirs(out, exist_ok=True)
    st = os.path.join(out, ".bz-crs")
    try:
        tests = [n for n, _t, tst in _course_info(paths) if tst]   # (before the compile: it decides nothing)
        if path and _course_info([path])[0][2]:     # SPEC.md 130.54.6: a TEST MAP (`test` on the pathway)
            tests.append("the test map %s" % os.path.basename(path))
        if tests and not dev:
            raise CourseError("%s: a TEST course (`test`), the BZDEV=1 build's alone: this build is not `--dev`, so "
                              "it would ship (SPEC.md 130.54)" % ", ".join(tests))
        courses, files, texts = compile_all(paths, path=path, title=title)
    except CourseError:
        if os.path.exists(st):
            os.remove(st)
        raise
    # the stamp before the files: a run that dies writing leaves a stamp and a
    # missing file, which make's fallback turns back into a re-run
    with open(st, "w") as f:
        f.write(stamp(paths + ([path] if path else []) + ([title] if title else []) + [KIT_FILE]) + "\n")
    for name in sorted(files):
        with open(os.path.join(out, name), "wb") as f:
            f.write(files[name])
    for name in sorted(texts):
        with open(os.path.join(out, name), "w", newline="\n") as f:
            f.write(texts[name])
    for k, c in enumerate(courses):
        report(c, k)
    for k, c in enumerate(courses):         # the visibility audit, REPORT mode (SPEC.md 130.15.10.4)
        d = compile_all.demos.get(k)
        print("\n".join(visibility(c, k, d["log"] if d and d["kind"] == "file" else None)[0]))
    for K, d in sorted(compile_all.demos.items()):
        _K, mat, fl, pv, steps, N, ident = struct.unpack_from("<BBBBIHH", d["log"], 4)
        print("  demo %d %s (%s): %d bytes, %d runs, %d steps (%.2f s), %s, %s%s; the model's replay ends with %d "
              "falls, %d returns%s" % (K, courses[K].name, d["where"], len(d["log"]), N, steps,
                                       steps * STEP_PIT / float(PIT_HZ), MAT_NAMES[mat],
                                       "COMPLETE" if fl & RL_COMPLETE else "inputs only",
                                       " TILT" if fl & RL_TILT else "", d["p"].nfall, d["p"].nret,
                                       # (SPEC.md 130.14.7.4.1: a route demo that hops says so)
                                       ", %d Hops, %d boosts" % (d["p"].nhop, d["p"].nboost)
                                       if d["kind"] == "route" and d["p"].nhop else ""))
        for w in d["warn"]:
            print("bbcourse: warning: %s" % w, file=sys.stderr)
    return courses


def _title_checks(res):
    """SPEC.md 130.23.6, item 13: the title course compiles with its view, art
    and label as built, its four demos meet their expects and are BZ_TSTEPS
    steps; and the controls - a view off the picture, an art pixel off it, a
    demo a step short, an expect not met - are each REFUSED"""
    path = os.path.join(COURSE_DIR, "title.bbc")
    if not os.path.exists(path):
        return
    src = open(path).read()
    tc = compile_course(path)
    v = tc.model["grid"]["view"]
    lab = [L for L in tc.lanes if props_label(tc, L)]
    ok = (tc.gflags & GF_VIEW and v and len(lab) == 1 and len(lab[0]["poses"]) == 4
          and all(lab[0]["poses"][1 + i] == label_glyph(ch, lab[0]["rect"][0], lab[0]["rect"][1], 3)
                  for i, ch in enumerate("123")))
    res.append(("13 TITLE: the window FIXED (BZG1 +28 bit 2, +30/+31 %04Xh), one LABEL lane whose poses 1 - 3 are "
                "tallx.f8's 1 2 3, never an OBS cell" % v, bool(ok) and not any(
                    p.get("label") and p["at"] in tc.pcell for p in tc.props)))
    BZ_TITLE_K[0] = len(default_paths()) + 1
    try:
        demos = build_title_demos(tc)
        res.append(("13 TITLE: its %d demos replayed on the model from their starts, every one BZ_TSTEPS (%d) steps "
                    "and its expects met (BZTDEMO.BIN %d bytes)" % (TITLE_NDEMO, TITLE_STEPS, len(demos)), True))
    except CourseError as e:
        res.append(("13 TITLE: its demos: %s" % e, False))
    controls = []
    for what, text in (("a view off the picture", src.replace("view 56 124", "view 4000 124")),
                       ("an art pixel off the picture", src.replace("art title.bba 0 0", "art title.bba 700 0"))):
        try:
            compile_course(text, "<title, %s>" % what)
            controls.append((what, False))
        except CourseError:
            controls.append((what, True))
    with open(title_demo_path(1)) as f:
        d = parse_bzt(f.read())
    short = dict(d, runs=d["runs"][:-1] + ([(d["runs"][-1][0], d["runs"][-1][1] - 1)] if d["runs"][-1][1] > 1
                                            else []))
    for what, dd in (("a demo a step short", short), ("an expect not met", dict(d, expects=[("shatter", 1)]))):
        try:
            title_check(tc, dd, "<title demo 1, %s>" % what)
            controls.append((what, False))
        except CourseError:
            controls.append((what, True))
    res.append(("13 TITLE negative controls REFUSED: %s" % ", ".join("%s %s" % (w, "yes" if g else "NO")
                                                                     for w, g in controls),
                all(g for _w, g in controls)))


def props_label(c, L):
    """is lane L a LABEL's (SPEC.md 130.23.2)?"""
    return bool(c.props[L["prop"]].get("label"))


