def _group_rerender(text):
    """SPEC.md 130.32.9: a course's GROUP lanes against their members' own art -> a selfcheck row.  Each
    group lane's every pose, as its block indices name it, against the bare picture with every member laid
    in painter's order at the pose the lane's CLASS MAPS and MULTS (read back from the part) give"""
    c = compile_course(text, fname="<group lab>", occluders=False)
    recs = c.part["props"]
    gl = [r for r in recs if r["kind"] == PK_GROUP]
    byi = {r["i"]: c.props[c.order[r["i"]]] for r in recs}
    lane = {L["prop"]: L for L in c.lanes}
    comp = sorted({e["m"] for g in gl for e in g["ents"]}, key=lambda m: (sum(byi[m]["at"]), byi[m]["line"]))
    bad, n = [], 0
    for r in gl:
        L, G = r["lane"], lane[c.order[r["i"]]]
        for q in range(L["poses"]):
            qs = {e["m"]: e["cmap"].index((q // e["mult"]) % e["ncls"]) for e in r["ents"]}
            want = [bytearray(row) for row in G["bare"]]
            for m in comp:
                for (x, y), ink in byi[m]["gpix"][qs.get(m, 0)].items():
                    if 8 * L["col"] <= x < 8 * (L["col"] + L["w"]) and 8 * L["brow"] <= y < 8 * (L["brow"] + L["h"]):
                        want[y - 8 * L["brow"]][x - 8 * L["col"]] = ink
            for rr in range(L["h"]):
                for kk in range(L["w"]):
                    blk = b"".join(bytes(want[8 * rr + yy][8 * kk:8 * kk + 8]) for yy in range(8))
                    n += 1
                    if c.blocks[G["words"][q][rr * L["w"] + kk]] != blk:
                        bad.append((r["i"], q, rr, kk))
    ok = bool(gl) and not bad
    return ("9 group lanes (130.32.9): %d lanes, %d pose blocks re-rendered from the members' own art%s"
            % (len(gl), n, "" if ok else " -- differ at %s" % bad[:3]), ok)


def _w9_checks(res):
    """wave 9's selfcheck (SPEC.md 130.25.6, 130.25.7, 130.25.13 bonanzacourse)"""
    # EXPLORATORY (SPEC.md 130.25.18.1): a floating crack VANISHES over two lanes, the companion's record
    # naming the crack (+18) and sharing its byte; its control (_hack novanish) keeps the one holed lane
    vt = _W9B + "float rect 4 4 9 8\nuses glass\nprop crack 8 7\n"
    got = []
    for hk in ({}, {"novanish": True}):
        c = compile_course(vt, fname="<vanish>", occluders=False, _hack=hk)
        rs = [d for d in c.part["props"] if d["kind"] == FK_CRACK]
        got.append(sorted((d["comp"], d["partner"] is not None, d["fsb"], d["lane"]["h"] if not d["comp"] else
                           min(d["lane"]["h"], 2)) for d in rs))   # (the companion's 2 - 3 rows: the alignment)
    res.append(("2 a floating crack vanishes over two lanes, one byte (130.25.18.1): %s; its control %s"
                % (got[0], got[1]), got[0] == [(False, True, 0, 3), (True, True, 0, 2)]
                and got[1] == [(False, False, 0, 2)]))
    # ...and on a THIN bridge (`float ... thick`, 130.27.2.1) the tile and its faces fit ONE lane: no companion
    c = compile_course(_W9B + "float rect 9 5 12 6 thick 0.5\nuses glass\nprop crack 10 5\nprop crack 11 5\n",
                       fname="<bridge>", occluders=False)
    rs = [(d["comp"], d["partner"], d["lane"]["w"], d["lane"]["h"]) for d in c.part["props"] if d["kind"] == FK_CRACK]
    res.append(("2 two ADJACENT cracks on a thin bridge (thick 0.5) each vanish in their own 2 x 3 lane, no companion "
                "(130.27.2.1): %s" % rs, rs == [(False, None, 2, 3)] * 2))
    for what, text, want in _w9_cases():
        try:
            compile_course(text, fname="<%s>" % what, occluders=False)
            fired, msg = False, "compiled"
        except CourseError as e:
            fired, msg = want in str(e), str(e)
        res.append(("2 refused (wave 9): %s%s" % (what, "" if fired else " -- got: " + msg), fired))
    # GROUP LANES (SPEC.md 130.32.9): the cap's refusal (a control: the cap lowered under a pair's 12 poses),
    # and every group lane's every pose, read back out of the PART, equal to the overlay of its members' own
    # marks at the poses its class maps give - over the bare picture, in painter's order
    gt = _W4C + "uses glass\n" + "".join("prop crack %d 6 hole wide\n" % (6 + k) for k in range(3)) \
        + "prop glass 9 7\nprop glass 10 7\nprop glass 10 8\n"     # (a glass TURN: (9, 7) and (10, 8) touch at a corner)
    try:
        compile_course(gt, fname="<a group past its poses>", occluders=False, _hack={"grp_pmax": 11})
        fired, msg = False, "compiled"
    except CourseError as e:
        fired, msg = "a group lane of" in str(e), str(e)
    res.append(("2 refused (130.32): a group lane past its poses (the cap lowered to 11)%s"
                % ("" if fired else " -- got: " + msg), fired))
    res.append(_group_rerender(gt))
    # ...and what group lanes ALLOW (int5's merge of w9/crack2 and w9/grouplane): two `hole wide` cracks edge to
    # edge, and two thin-bridge cracks touching at a corner down the screen - each refused before 130.32 - group
    for what, t_ in (("two wide cracks edge to edge", _W9B + "uses glass\nprop crack 10 5 hole wide\n"
                      "prop crack 11 5 hole wide\n"),
                     ("two bridge cracks touching at a corner", _W9B + "float rect 4 4 9 8 thick 0.5\nuses glass\n"
                      "prop crack 5 5\nprop crack 6 6\n")):
        line, ok = _group_rerender(t_)
        res.append((line.replace("9 group lanes (130.32.9)", "9 group lanes (130.32.9), %s" % what), ok))
    with _famtest():                                # a fourth family (three test rows beside the probe)
        extra = []
        for k in range(3):
            r = dict(_famtest.ROW, name="t%d" % k, id=250 + k, kinds=())
            FAM_BY_NAME[r["name"]] = r
            extra.append(r["name"])
        try:
            compile_course(_W4C + "uses probe %s\n" % " ".join(extra), fname="<4 families>", occluders=False)
            fired, msg = False, "compiled"
        except CourseError as e:
            fired, msg = "4th family" in str(e), str(e)
        for n in extra:
            FAM_BY_NAME.pop(n)
        res.append(("2 refused (wave 9): a fourth FETCHED family (uses probe and three test rows)%s" % (
            "" if fired else " -- got: " + msg), fired))
    # SPEC.md 130.25.6.5: NO FAMILY LIMIT - a course of FIVE families (the shift's four, before) compiles, its
    # list in the part; the engine's slots and hook lists are the whole family table's (bonanza_phys's
    # `every family` fetches all of them under unicorn, its red fam4 the old limit); red: a built part whose
    # hook mask has a bit its FAMILIES row lacks - which BZ_FHENT does not count - is refused by fbundle's check
    t5 = (_W4C + "uses probe glass pickups magnet wind\nprop probe 6 8 reset respawn\nprop glass 9 8\n"
          "prop jump 8 5 for 3\nprop magnet 13 8 face -x range 4 strength 48\nprop blower 5 5 face +x region 6 5 9 7\n")
    try:
        c5 = compile_course(t5, fname="<5 families>", occluders=False)
        fo5 = struct.unpack_from("<H", c5.cga, 46)[0]
        ok = c5.cga[45] == 5 and [c5.cga[fo5 + 2 * j] for j in range(5)] == [
            FAM_BY_NAME[n]["id"] for n in ("probe", "glass", "pickups", "magnet", "wind")]
        msg = "its list %s" % [c5.cga[fo5 + 2 * j] for j in range(c5.cga[45])]
    except CourseError as e:
        ok, msg = False, str(e)
    ok = ok and fam_slots() == len(FAMILIES) and fam_hook_entries() == sum(
        sum(1 for b in range(len(HOOK_NAMES)) if f["hooks"] >> b & 1) for f in FAMILIES)
    pb = bytearray(FAM_HDR)
    pb[0:4] = b"BF" + bytes((1, famv(FAM_BY_NAME["probe"])))
    pb[8] = FAM_BY_NAME["probe"]["hooks"]
    try:
        fam_maskcheck(FAM_BY_NAME["probe"], pb)
        ctl = True
    except CourseError:
        ctl = False
    pb[8] |= H_PROP                                 # (the probe's row has no PROP hook)
    try:
        fam_maskcheck(FAM_BY_NAME["probe"], pb)
        red = False
    except CourseError as e:
        red = "lacks" in str(e)
    res.append(("2 no family limit (130.25.6.5): five families on one course compile (%s); BZ_FAMMAX %d slots, "
                "BZ_FHENT %d hook entries - the whole family table; red: a part with a hook its row lacks refused%s"
                % (msg, fam_slots(), fam_hook_entries(), "" if ctl and red else " -- control %s, red %s" % (ctl, red)),
                ok and ctl and red))
    # the list in the part and in the identity: a course naming the probe carries BZC2 +45 NFAM 1 and
    # +46 FAMOFF -> (ID 1, FAMV), NFST 1, the RESPAWN mask; a probe's FAMV moved moves the identity
    t = _W4C + "uses probe\nprop probe 6 6 reset respawn\nprop probe 8 6 reset attempt\n"
    c = compile_course(t, fname="<probe>", occluders=False)
    pt = c.cga
    nfam, fo = struct.unpack_from("<BH", pt, 45)
    ok = nfam == 1 and pt[fo:fo + 4] == bytes((1, famv(FAM_BY_NAME["probe"]), 1, 1))
    recs = [r for r in c.part["props"] if is_fam(r["kind"])]
    ok = ok and [(r["fsb"], r["cls"]) for r in recs] == [(0, CL_RESPAWN), (1, CL_ATTEMPT)]
    fam0 = FAM_BY_NAME["probe"]["rev"]
    FAM_BY_NAME["probe"]["rev"] = fam0 + 1
    try:
        c2 = compile_course(t, fname="<probe rev+1>", occluders=False)
    finally:
        FAM_BY_NAME["probe"]["rev"] = fam0
    b0 = compile_course(_W4C, fname="<no family>", occluders=False)
    res.append(("3 the family list (130.25.6.4): BZC2 +45 NFAM %d, +46 FAMOFF -> %s (ID, FAMV, NFST, the RESPAWN "
                "mask), the records' FSB and class %s; the probe's FAMV moved moves the identity (%04Xh -> %04Xh), "
                "and the same course with no family has +45 - +47 zero" % (
                    nfam, pt[fo:fo + 4].hex(), [(r["fsb"], r["cls"]) for r in recs], c.ident, c2.ident),
                ok and c.ident != c2.ident and b0.cga[45:48] == bytes(3)))
    # NO TRAP under the reset classes (130.25.7.3): the WALL probe on the bridge past the flag - RESPAWN,
    # cleared by the respawn, compiles; forced ATTEMPT, left WALL by an earlier pass, is refused (the red arm)
    with _famtest():
        ok_g, msg_g = True, "compiled"
        try:
            g = compile_course(_W9B + "uses wallprobe\nprop wallprobe 10 5 reset respawn\n", fname="<bridge>")
            msg_g = "compiled, %d flag run(s)" % len(g.trap)
        except CourseError as e:
            ok_g, msg_g = False, str(e)
        try:
            compile_course(_W9B + "uses wallprobe\nprop wallprobe 10 5 reset attempt\n", fname="<bridge attempt>")
            fired, msg = False, "compiled"
        except CourseError as e:
            fired, msg = "NO TRAP" in str(e) and "ATTEMPT family state" in str(e), str(e)
    res.append(("7 NO TRAP under the reset classes (130.25.7.3): a WALL-making element on the only bridge past a "
                "flag - RESPAWN (cleared at the respawn): %s; forced ATTEMPT: %s" % (msg_g, msg), ok_g and fired))
    # GLASS (130.25.18, 130.25.13): a CRACK PATH as that bridge - its own class RESPAWN compiles (the respawn
    # restores every crack); the class forced ATTEMPT with BROKEN among the states a pass can leave it in is
    # refused, naming the state (the red arm 130.25.13 names)
    cb = _W9B + "uses glass\nprop crack 9 5\nprop crack 10 5\nprop crack 11 5\n"
    ok_g, msg_g = True, "compiled"
    try:
        g = compile_course(cb, fname="<crack bridge>")
        msg_g = "compiled, %d flag run(s)" % len(g.trap)
    except CourseError as e:
        ok_g, msg_g = False, str(e)
    kr = FAM_BY_NAME["glass"]["kinds"][0]
    keep = (kr["cls"], kr["states"])
    kr["cls"], kr["states"] = CL_ATTEMPT, (CR_WHOLE, CR_BROKEN)
    try:
        compile_course(cb, fname="<crack bridge attempt>")
        fired, msg = False, "compiled"
    except CourseError as e:
        fired, msg = "NO TRAP" in str(e) and "ATTEMPT family state" in str(e), str(e)
    finally:
        kr["cls"], kr["states"] = keep
    res.append(("7 NO TRAP, GLASS's crack (130.25.18): a crack path as the only bridge past a flag - RESPAWN, its "
                "class: %s; forced ATTEMPT (whole or broken): %s" % (msg_g, msg), ok_g and fired))
    # the reach over the SUPERSET (130.25.7.3): each crack's cell takes its broken form's kill as its zlo -
    # the floor less 3 units - so the occluders and the bounds see a ball falling through it; _hack noforms
    # (the whole form alone) leaves it at the floor
    g = compile_course(cb, fname="<crack bridge>")
    g0 = compile_course(cb, fname="<crack bridge, no forms>", _hack={"noforms": True})
    lo = dict(((r.wx, r.wy), r.zlo) for r in g.reach)
    lo0 = dict(((r.wx, r.wy), r.zlo) for r in g0.reach)
    cr = [(9, 5), (10, 5), (11, 5)]
    want = [4 * (g.cells[c][0] - 6) for c in cr]
    res.append(("6 the reach over a crack's superset (130.25.7.3, 130.25.18): the cracks' zlo %s px (their broken "
                "kill, the floor less 3 units: %s), %s px with the whole form alone (_hack noforms); %d occluder "
                "records against %d" % ([lo[c] for c in cr], want, [lo0[c] for c in cr], len(g.records),
                                         len(g0.records)),
                [lo[c] for c in cr] == want and all(lo0[c] > lo[c] for c in cr)))
    _pickup_checks(res)


def _pickup_checks(res):
    """PICKUPS (SPEC.md 130.25.9, 130.25.19): the records, FAMV over the constants, and the reach with the
    raised values where a pickup is reachable - its red arm `nopickreach`, the pair taken together unless
    every one is marked `overwrite`, and a bound's refusal naming the pair"""
    t = _W4C + "uses pickups\nprop hourglass 5 5\nprop speed 6 6 for 2 overwrite\nprop jump 8 6\n"
    c = compile_course(t, fname="<pickups>", occluders=False)
    recs = sorted((r["kind"], r["cls"], r["dur"], r["ow"]) for r in c.part["props"] if is_fam(r["kind"]))
    want = [(K_HOURGLASS, CL_ATTEMPT, 0, 0), (K_SPEED, CL_RESPAWN, int(2 * SEC_STEPS / 4 + 0.5), PU_OVERWRITE),
            (K_JUMP, CL_RESPAWN, PU_DUR, 0)]
    j0 = globals()["PU_JHOP"]
    f0 = famv(FAM_BY_NAME["pickups"])
    globals()["PU_JHOP"] = j0 + 4
    f1 = famv(FAM_BY_NAME["pickups"])
    globals()["PU_JHOP"] = j0
    res.append(("3 PICKUPS' records (130.25.19): (kind, class, +18 duration, +19 flags) %s; FAMV %02Xh, %02Xh with "
                "PU_JHOP + 4 (the constants are in it)" % (recs, f0, f1), recs == want and f0 != f1))
    # the reach: the jump raises the reach where it is reachable; the arm without it raises nothing
    # (on SAND, where no boost launches: on a firm level floor rubber's boosted bounce chain already
    # reaches VZMAX's cap in the reach, so a jump there raises nothing - the owner's "bounded only by VZMAX")
    S = _W4C + ("surface sand rect 4 4 12 9\nsurface sand rect 13 4 14 9\nsurface sand rect 12 4 13 6\n"
                "surface sand rect 12 7 13 9\n")      # (every floor sand but the cup's own cell)
    base = compile_course(S, fname="<no pickup>", occluders=False)
    tj = S + "uses pickups\nprop jump 8 6\n"
    cj = compile_course(tj, fname="<jump>", occluders=False)
    cr = compile_course(tj, fname="<jump, nopickreach>", occluders=False, _hack={"nopickreach": True})
    zb = dict(((r.wx, r.wy), r.zhi) for r in base.reach)
    up = sorted((r.wx, r.wy) for r in cj.reach if r.zhi > zb.get((r.wx, r.wy), r.zhi))
    upr = [r for r in cr.reach if r.zhi > zb.get((r.wx, r.wy), r.zhi)]
    res.append(("6 PICKUPS' reach (130.25.19): a jump raises zhi on %d cells (its Hop %d and the boost stacked); "
                "the red arm nopickreach raises %d" % (len(up), PU_JHOP, len(upr)), len(up) > 0 and not upr))
    # the pair: held together unless every one is `overwrite` - and a bound's refusal says so
    both = S + "uses pickups\nprop speed 6 6\nprop jump 8 6%s\n"
    cp = compile_course(both % "", fname="<pair>", occluders=False)
    co = compile_course((both % " overwrite").replace("prop speed 6 6", "prop speed 6 6 overwrite"),
                        fname="<pair overwrite>", occluders=False)
    sp = {r.src[1] for r in cp.reach if r.src and r.src[1].startswith("pickup")}
    so = {r.src[1] for r in co.reach if r.src and r.src[1].startswith("pickup")}
    note = _pairnote(cp.reach)
    res.append(("6 PICKUPS' pair (130.25.9): unmarked, the reach's raised cells come from %s; every one "
                "`overwrite`, from %s; a bound's refusal on the pair names `overwrite`: %s" % (
                    sorted(sp), sorted(so), bool(note)),
                sp == {"pickup speed and jump"} and "pickup speed and jump" not in so and "overwrite" in note
                and not _pairnote(co.reach)))


def _w4_records(c, res):
    """item 3 (wave 4): the records of kinds 5 - 8 as the statements wrote them,
    the BZG1 flags and pad mask, and the reader's refusals"""
    if not any(p["kind"] >= PK_CHECKPOINT for p in c.props):
        return
    pt = c.part
    ok = True
    for r in pt["props"]:
        pr = c.props[c.order[r["i"]]]
        if r["kind"] != pr["kind"] or r["at"] != pr["at"]:
            ok = False
        if r["kind"] == PK_CHECKPOINT:
            ok = ok and r["num"] == pr["num"] and r["ball"] == pr["ball"] and r["lane"]["poses"] == 2
        elif r["kind"] == PK_PAD:
            ok = ok and r["mat"] == pr["mat"] and r["lane"] is None
        elif r["kind"] == PK_CUP:
            ok = ok and r["capture"] == pr["capture"] and r["hw"] == MOUTH_HW and r["lane"] is None
        elif r["kind"] == PK_SPRING:
            ok = ok and r["gvz"] == pr["gvz"] and r["lane"] is None
    kinds = [p["kind"] for p in c.props]
    wf = (GF_CKPT if PK_CHECKPOINT in kinds or PK_CUP in kinds else 0) | (GF_CUP if PK_CUP in kinds else 0)
    wm = 0
    for p in c.props:
        if p["kind"] == PK_PAD:
            wm |= 1 << p["mat"]
    ok = ok and pt["grid"]["padmask"] == wm
    lanes = [r for r in pt["props"] if r["lane"]]
    ok = ok and lanes == pt["props"][:len(lanes)] and len(lanes) <= PROP_MAX
    # (GF_SPLIT is the grid's, not a record's: set exactly when a cell is split - wave D5's MOON and PLAY)
    wf |= GF_SPLIT if any(isinstance(t_, Split) for t_ in c.tiles.values()) else 0
    wf |= GF_FIELD if any(isinstance(t_, FieldTile) for t_ in c.tiles.values()) else 0     # (SPEC.md 130.28.2)
    ok = ok and pt["grid"]["gflags"] & ~GF_ANA == wf          # (GF_ANA: item 15's, SPEC.md 130.29.4)
    res.append(("3 %s: every flag, pad, cup and spring record as its statement wrote it (a flag's ball at +17, a "
                "two-pose lane, first with the lanes), BZG1 +28 FLAGS %02Xh and +29 PAD MASK %02Xh the records'"
                % (c.name, pt["grid"]["gflags"], pt["grid"]["padmask"]), ok))
    # the reader's own refusals: a flag in a lane-less record; a pad mask the records do not give
    fr = next(r for r in pt["props"] if r["kind"] == PK_CHECKPOINT) if PK_CHECKPOINT in kinds else None
    if fr is not None:
        bb = bytearray(world_of(c))                 # (a two-part course's records are its world part's, 130.30)
        o = pt["propoff"] + PROPREC * fr["i"]
        bb[o + 1] &= ~PF_LANE
        bb[o + 8:o + 16] = bytes(8)
        restamp_world(c, bb)
        try:
            read_world(c, bb)
            caught = False
        except CourseError as e:
            caught = "without its LANE" in str(e) or "a lane after a record without one" in str(e) \
                or "pose maps" in str(e)
        res.append(("3 %s negative control: a flag's record without its LANE is refused by the reader" % c.name,
                    caught))
    bb = bytearray(world_of(c))
    bb[pt["gridoff"] + 29] ^= 4 if not wm & 4 else 1
    restamp_world(c, bb)
    try:
        read_world(c, bb)
        caught = False
    except CourseError as e:
        caught = "PAD MASK" in str(e)
    res.append(("3 %s negative control: a PAD MASK bit no pad gives is refused by the reader" % c.name, caught))


def spring_bounds(c):
    """item 6 (wave 4): every SPRING's flight - a launch at gvz from its cell's
    floor - inside the reach's zhi over its RADIUS and its apex footprint inside
    the picture.  -> [(spring, its apex px, the least zhi found, the footprint's
    top line)], and whether all hold"""
    out = []
    ok = True
    byc = {(rc.wx, rc.wy): rc for rc in c.reach}
    for p in c.props:
        if p["kind"] != PK_SPRING:
            continue
        top = 4 * c.tiles[p["at"]].z0 + UP(p["gvz"])
        rc = byc[p["at"]]
        line = foot_top(rc, top) + c.y0
        good = rc.zhi >= top and line >= 0
        out.append((p["at"], top, rc.zhi, line))
        ok = ok and good
    return out, ok


def _ones(c, mat, surf=SURF_NORMAL):
    """the one-arrow top on a surface: max |gvx|, |gvy| after holding one arrow
    (screen right) from rest for 400 steps on a flat floor"""
    f, dk, _b, _e = surf_entry(mat, surf)
    tab = ftg_table(f)
    vx = vy = rx = ry = 0
    for _ in range(FEEL_N):                         # (wave 6: the fractional drag, 130.16.3.1)
        vx, rx = _fdrag(vx + tab[LVL_MAX], dk, rx)
        vy, ry = _fdrag(vy - tab[LVL_MAX], dk, ry)
        vx, vy = _clamp(vx, VMAXG), _clamp(vy, VMAXG)
    return max(abs(vx), abs(vy))


def _w4_course_report(c, res):
    """items 7 and 8's printing for a course with wave 4's props: the cup's
    capture table, each spring's landings per ball, each branch's savings and
    landings (SPEC.md 130.14.4.1)"""
    cup = next((p for p in c.props if p["kind"] == PK_CUP), None)
    if cup is not None:
        surf = c.tiles[cup["at"]].surf
        green = sorted({surf} | {c.tiles[(cup["at"][0] + dx, cup["at"][1] + dy)].surf
                                 for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1))})
        print("    %s's cup at %s, capture %d: the one-arrow tops on its green (%s): %s" % (
            c.name, cup["at"], cup["capture"], "/".join(SURFACES[g] for g in green), ", ".join(
                "%s %d (%s)" % (MAT_NAMES[m], _ones(c, m, g), "holes out" if _ones(c, m, g) <= cup["capture"]
                                 else "lips out") for m in range(3) for g in green)))
    for sp in (p for p in c.props if p["kind"] == PK_SPRING):
        rows = []
        for m in range(3):
            got = {}
            for d in DIR_VEC:
                for v in (128, 192, 256, 320, 384):
                    p = Physics(c, play=True, mat=m).poke(sp["at"][0] - d[0], sp["at"][1] - d[1], v * d[0], v * d[1])
                    n0 = 0
                    out = None
                    for _ in range(160):
                        n0 = len(p.events)
                        p.step(0)
                        ev = [e for e in p.events[n0:] if e[0] in ("land", "bounce", "stun", "shatter", "respawn", "wall")]
                        if p.nspr and ev:
                            out = ev[0][0]
                            break
                    got[out] = got.get(out, 0) + 1
            rows.append("%s %s" % (MAT_NAMES[m], " ".join("%s %d" % (k, n) for k, n in sorted(got.items(),
                                                                                           key=str))))
        print("    %s's spring at %s (%d): the first contact after its launch over 20 approaches a ball (four "
              "sides, 128 - 384): %s" % (c.name, sp["at"], sp["gvz"], "; ".join(rows)))
    for name, ways in sorted(c.branches.items()):
        pts = [t for t, _ln in ways]
        main = [t for t, _ln in c.src.ways]
        near = lambda t: min(range(len(main)), key=lambda i: abs(main[i][0] - t[0]) + abs(main[i][1] - t[1]))
        i0, i1 = near(pts[0]), near(pts[-1])
        pm = Physics(c, play=True)
        at = {}
        while pm.nstep < DEMO_STEPS and not pm.goal and pm.wp <= max(i0, i1) + 1:
            w0 = pm.wp
            pm.step_auto()
            for k in range(w0, pm.wp):
                at.setdefault(k, pm.nstep)
        msteps = at.get(i1, 0) - at.get(i0, 0)
        land = []
        for m in range(3):
            p = Physics(c, play=True, mat=m).poke(*pts[0])
            p.nstep = at.get(i0, 0)
            p.route = [_way_point(c, t) for t in pts]
            p.wp = 1
            worst = 0
            while p.nstep < at.get(i0, 0) + DEMO_STEPS and not p.goal and p.wp < len(pts) - 1 and not p.nfall:
                n0 = len(p.events)
                p.step_auto()
                for e in p.events[n0:]:
                    if e[0] in ("land", "bounce", "stun", "shatter", "hopc"):
                        lv = e[2][1] if e[0] == "land" else e[2]
                        worst = max(worst, lv)
            land.append("%s %d steps, worst landing lvz %d%s" % (MAT_NAMES[p.mat if m == 0 else m],
                                                                p.nstep - at.get(i0, 0), worst,
                                                                ", fell" if p.nfall else ""))
        print("    %s's branch %s (%s): the main route between its waypoints %d and %d takes %d steps; the branch "
              "(each ball put at rest on its first point): %s" % (c.name, name, " ".join("(%d, %d)" % t for t in pts),
                                                                 i0, i1, msteps, "; ".join(land)))


def _w4_route(c, res):
    """item 8 (wave 4): the autopilot on the course's route reaches the goal or
    the cup without a fall within DEMO_STEPS; prints the airborne steps over OCC
    and what the route met"""
    p = Physics(c, play=True)
    air_occ = 0
    while p.nstep < DEMO_STEPS and not p.goal:
        p.step_auto()
        if p.air and not p.tube and p.cell(p.gx >> 12, p.gy >> 12)[4] & FL_OCC:
            air_occ += 1
    how = ""
    nfl = sum(1 for q in c.props if q["kind"] == PK_CHECKPOINT)
    if p.goal and p.nckpt < nfl and not _NOFLAG:
        # SPEC.md 130.14.7.4.4: the arrows reach the goal past a flag without touching it - the route is the
        # FLAG PASS's (route_plan: the route demo's), which steers through the flag's cell; the course is not
        # changed to suit the autopilot.  The item replays that plan's keys to the same tests
        plan = route_plan(c)
        p = Physics(c, play=True)
        air_occ = 0
        for k_ in (plan or ())[:DEMO_STEPS]:
            if p.goal:
                break
            p.step(k_)
            if p.air and not p.tube and p.cell(p.gx >> 12, p.gy >> 12)[4] & FL_OCC:
                air_occ += 1
        how = " (the arrows skip a flag: the FLAG PASS's route, 130.14.7.4.4, %s)" % (
            "%d steps" % len(plan) if plan else "NONE found")
    elif not p.goal and getattr(c, "traphop", None):
        # wave 11 (SPEC.md 130.14.4.1.1, 130.14.7.4.1): a course BUILT ON THE HOP (`trap hop`, LITTLE HOP) is
        # one the arrows alone cannot finish by design, and its route is the HOPPING autopilot's (route_plan:
        # the limit's and the route demo's).  So for such a course - and only such a course: one without
        # `trap hop` is still held to the arrows alone - the item replays that plan's keys and holds it to the
        # same goal, no fall and every flag, inside DEMO_STEPS
        plan = route_plan(c)
        p = Physics(c, play=True)
        air_occ = 0
        for k_ in (plan or ())[:DEMO_STEPS]:
            if p.goal:
                break
            p.step(k_)
            if p.air and not p.tube and p.cell(p.gx >> 12, p.gy >> 12)[4] & FL_OCC:
                air_occ += 1
        how = " (`trap hop`: the HOPPING autopilot's route, 130.14.7.4.1, %s)" % (
            "%d steps" % len(plan) if plan else "NONE found")
    kinds = {}
    for e in p.events:
        if e[0] in ("flag", "pad", "spring", "capture", "lip", "cup"):
            kinds[e[0]] = kinds.get(e[0], 0) + 1
    want = {"flag": sum(1 for q in c.props if q["kind"] == PK_CHECKPOINT)}
    res.append(("8 %s: the autopilot reaches the %s at step %s (%.1f s) with no fall in %d steps, touching every "
                "flag (%s of %d), over %d pad swaps, %d spring launches and %d tube captures; %d airborne steps over OCC "
                "cells (priced in the demo legs, 130.14.6)%s" % (
                    c.name, "cup" if c.gflags & GF_CUP else "goal", p.nstep if p.goal else "-",
                    p.nstep * STEP_PIT / float(PIT_HZ), DEMO_STEPS, kinds.get("flag", 0), want["flag"], p.npad,
                    p.nspr, kinds.get("capture", 0), air_occ, how),
                p.goal == 1 and p.nfall == 0 and kinds.get("flag", 0) == want["flag"]))
    return p


def _w4_physics(byname, res):
    """item 7 (wave 4): each prop's rule and RETURN by the model, on the shipped
    courses and on the fixture course (SPEC.md 130.14.4.3 - 130.14.4.7), and
    the tilt's cap (130.14.8.2)"""
    W = compile_course(_W4C + "uses spring\nspring 8 7 512\npad steel 6 7\ncheckpoint 9 5 ball glass\n", "<w4>")
    cup = next(r for r in W.part["props"] if r["kind"] == PK_CUP)
    # the cup: 128 holes out, 256 lips out and pops, rolls on
    a = Physics(W, play=True).poke(11, 6, 128, 0)
    while not a.goal and a.nstep < 60:
        a.step(0)
    b = Physics(W, play=True).poke(11, 6, 256, 0)
    pops = []
    for _ in range(40):
        n0 = len(b.events)
        b.step(0)
        pops += [e for e in b.events[n0:] if e[0] == "lip"]
        if b.nlip and b.gvz == LIPZ and b.air:
            pass
    res.append(("7 the CUP: a ball poked across its mouth at 128 holes out (step %d: bz_goal, bz_hid, every velocity 0) "
                "and at 256 LIPS OUT once with its pop (gvz %d) and rolls on (%d lip-out, goal %d)" % (
                    a.nstep, LIPZ, b.nlip, b.goal),
                a.goal == 1 and a.hid == 1 and a.gvx == a.gvy == a.gvz == 0 and b.nlip == 1 and not b.goal
                and len(pops) == 1))
    # a stunned steel ball in the mouth holes out after its stun; a shattering glass ball does not
    st = Physics(W, play=True, mat=MAT_STEEL).poke(12, 6)
    st.mst, st.mct = ST_STUN, 10
    while st.nstep < 30 and not st.goal:
        st.step(0)
    gl = Physics(W, play=True, mat=MAT_GLASS).poke(12, 6)
    gl.mst, gl.mct = ST_SHATTER, SHA_STEPS
    for _ in range(SHA_STEPS + 2):
        gl.step(0)
    res.append(("7 the CUP: a stunned steel ball in the mouth holes out on the first step after its stun (step %d); a "
                "shattering glass ball does not, and respawns at the start" % st.nstep,
                st.goal == 1 and st.nstep == 10 and not gl.goal and gl.nfall == 1))
    # the pad: a grounded step swaps the material, its record and its tables; once
    p = Physics(W, play=True).poke(5, 7, 160, 0)
    while p.npad == 0 and p.nstep < 60:
        p.step(K_R | K_D)
    sw = (p.mat, p.m is MATERIALS[MAT_STEEL], p.fta == fta_table(MATERIALS[MAT_STEEL]["ACC"]), p.npad)
    for _ in range(10):
        p.step(0)
    res.append(("7 a PAD: the steel pad swaps a rubber ball to steel, its record and its air table (step %d), and "
                "swaps it once" % p.nstep, sw == (MAT_STEEL, True, True, 1) and p.npad == 1))
    # the flag: touched, its ball; a fall respawns there as the flag's ball (glass), bz_nfall += 1
    f = Physics(W, play=True).poke(9, 6, 0, -200)
    while not f.nckpt and f.nstep < 40:
        f.step(0)
    touched = (f.ckpt, f.ckmat, f.cksn, f.nckpt)
    f.poke(13, 8, 0, 300)
    while not f.nfall and f.nstep < 200:
        f.step(K_L | K_D)
    res.append(("7 a FLAG: touched, the last flag (bz_ckpt %d) and its ball (bz_ckmat %s); a fall respawns ON it as "
                "its ball (%s, the flag's, not the ball it was touched with), bz_nfall 1" % (
                    touched[0], MAT_NAMES[touched[1]], MAT_NAMES[f.mat]),
                touched == (1, MAT_GLASS, 1, 1) and f.nfall == 1 and (f.gx >> 12, f.gy >> 12) == (9, 5)
                and f.mat == MAT_GLASS))
    # RETURN mid-roll: back to the flag, bz_nret 1, bz_nfall unchanged, nothing else that step
    r = Physics(W, play=True).poke(9, 6, 0, -200)
    while not r.nckpt:
        r.step(0)
    r.poke(7, 6, 200, 0)
    for _ in range(5):
        r.step(K_R)
    st0 = r.nstep
    r.step(K_RET | K_R)
    res.append(("7 RETURN (key byte bit 6): mid-roll, the ball back on the flag as its ball, bz_nret 1, bz_nfall 0, "
                "the arrows' levels zero (nothing else ran that step)",
                r.nret == 1 and r.nfall == 0 and (r.gx >> 12, r.gy >> 12) == (9, 5) and r.mat == MAT_GLASS
                and r.lvl == [0, 0, 0, 0] and r.nstep == st0 + 1))
    # the spring: a grounded ball leaves at its gvz; a rubber bounce leaves at the MAX, not the sum; glass
    # shattering on it is not launched
    s1 = Physics(W, play=True).poke(8, 7)
    s1.step(0)
    sp = next(r_ for r_ in W.part["props"] if r_["kind"] == PK_SPRING)
    s2 = Physics(W, play=True).poke(8, 7)
    s2.gz += 30 << 8
    s2.air, s2.gvz, s2.ztop = 1, -400, s2.gz >> 8
    while not s2.nspr and s2.nstep < 60:
        s2.step(0)
    s3 = Physics(W, play=True, mat=MAT_GLASS).poke(8, 7)
    s3.gz += 60 << 8
    s3.air, s3.gvz, s3.ztop = 1, -700, s3.gz >> 8
    while not s3.nshat and s3.nstep < 60:
        s3.step(0)
    rb = [e for e in s2.events if e[0] == "bounce"]
    res.append(("7 a SPRING: a ball grounded on it leaves at its %d; a rubber ball bouncing on it leaves at max(%d, "
                "its rebound %s) = %d, never the sum; a glass ball that shatters on it is not launched" % (
                    sp["gvz"], sp["gvz"], rb[0][3] if rb else "-", s2.gvz + 0),
                s1.air == 1 and s1.gvz == sp["gvz"] and s1.nspr == 1 and rb and s2.nspr == 1
                and s2.events[-1][2] == max(sp["gvz"], rb[0][3]) and s3.nshat == 1 and s3.nspr == 0))
    # the reachable set with springs: zhi over the spring takes its flight
    out, ok = spring_bounds(W)
    res.append(("7 the reachable set takes each SPRING's flight: %s" % ", ".join(
        "%s apex %d px, zhi %d" % (o[0], o[1], o[2]) for o in out), ok))
    # the tilt's cap: a cap dropped from 8 to 2 under a held arrow gives 8, 6, 4, 2
    t = Physics(W, play=True).poke(5, 6)
    for _ in range(9):
        t.step(K_R, 0x88)
    lv = [t.lvl[1]]
    for _ in range(4):
        t.step(K_R, 0x28)
        lv.append(t.lvl[1])
    res.append(("7 the TILT cap (130.14.8.2): a held arrow at cap 8 then cap 2 gives levels %s; a keyboard step's tilt "
                "byte 88h is wave 2's ramp" % lv, lv == [8, 6, 4, 2, 2]))
    tm = Physics(W, play=True, _tilt_min=True).poke(5, 6)
    for _ in range(9):
        tm.step(K_R, 0x88)
    tm.step(K_R, 0x28)
    res.append(("7 negative control (tiltcap): the min taken before the decay drops 8 to 2 at once (level %d)"
                % tm.lvl[1], tm.lvl[1] == 2))
    # the red arms' controls the rows pin (ckpt, ckmat, padftg, cupv, springsum), here on the model
    rc = Physics(W, play=True, _ckpt_safe=True).poke(9, 6, 0, -200)
    while not rc.nckpt:
        rc.step(0)
    rc.poke(13, 8, 0, 300)
    while not rc.nfall and rc.nstep < 200:
        rc.step(K_L | K_D)
    cv = Physics(W, play=True, _cup_nov=True).poke(11, 6, 256, 0)
    for _ in range(40):
        cv.step(0)
    ss = Physics(W, play=True, _spring_sum=True).poke(8, 7)
    ss.gz += 30 << 8
    ss.air, ss.gvz, ss.ztop = 1, -400, ss.gz >> 8
    while not ss.nspr and ss.nstep < 60:
        ss.step(0)
    res.append(("7 negative controls on the model: the respawn at bz_safe (ckpt) misses the flag, the capture "
                "without the speed test (cupv) holes out at 256, the spring that ADDS (springsum) leaves above "
                "the max", (rc.gx >> 12, rc.gy >> 12) != (9, 5) and cv.goal == 1 and ss.gvz > s2.gvz))
    # NO TRAP's own control: the trap course with the refusal removed compiles, and the check finds the trap
    T = compile_course(_W4T % "glass", "<trap>", _hack={"no_trap": True})
    found = trap_check(T)
    Tok = compile_course(_W4T % "rubber", "<no trap>")
    res.append(("7 NO TRAP: with the refusal removed (the trap control) the check finds the glass flag that cannot "
                "reach the cup (%s); the same flag naming rubber passes" % (found,),
                found is not None and found[3] == MAT_GLASS and Tok.trap and all(t_[3] for t_ in Tok.trap)))


def play_demo_verdict(c, log):
    """SPEC.md 130.16.8 item 9: a PLAYGROUND demo's model replay boosts at least
    once, rests on the 1.5-unit ledge (PLAY_RUNGS) at some step, and ends at its
    goal on its last step.  -> (ok, what it did)"""
    steps = struct.unpack_from("<I", log, 8)[0]
    _K, mat, kt, _fl = decode_log_t(log)
    p = Physics(c, play=True, mat=mat)
    ledge = _rect(dict(PLAY_RUNGS)[1.5])
    first = on = None
    for k, t in kt:
        p.step(k, t)
        if p.goal and first is None:
            first = p.nstep
        if on is None and not p.air and (p.gx >> 12, p.gy >> 12) in ledge:
            on = p.nstep
    ok = p.nboost >= 1 and on is not None and first == steps
    return ok, "its replay boosts %d time(s), %s the 1.5-unit ledge%s, %s" % (
        p.nboost, "reaches" if on else "never reaches", " at step %d" % on if on else "",
        "ends at the goal on its last step %d" % steps if first == steps else "goal at %s of %d steps" % (first, steps))


def no_boost_log(c, log):
    """the log with the Space press that made its first boost cleared (the key
    byte's Space bit, from that press's edge to its release): -> bytes, or None"""
    _K, mat, kt, fl = decode_log_t(log)
    p = Physics(c, play=True, mat=mat)
    at = None
    for i, (k, t) in enumerate(kt):
        p.step(k, t)
        if p.nboost:
            at = i
            break
    if at is None:
        return None
    e = at
    while e >= 0 and not kt[e][0] & K_HOP:
        e -= 1
    if e < 0:
        return None
    while e > 0 and kt[e - 1][0] & K_HOP:
        e -= 1
    keys = [k for k, _t in kt]
    while e < len(keys) and keys[e] & K_HOP:
        keys[e] &= ~K_HOP
        e += 1
    tilts = [t for _k, t in kt] if fl & RL_TILT else None
    return encode_log(keys, log[4], mat, bool(fl & RL_COMPLETE), log_ident(log), log[7], tilts)


def _w4_demos(courses, paths, res):
    """item 9 (SPEC.md 130.14.7.4, 130.14.17 item 5): every shipped demo"""
    demos = build_demos(courses, paths)
    idents = [c.ident for c in courses]
    for K, d in sorted(demos.items()):
        c = courses[K]
        log = d["log"]
        bad = check_log(log, len(courses), idents)
        steps = struct.unpack_from("<I", log, 8)[0]
        p, first = replay_log(c, log)
        ok = bad is None and log_ident(log) == c.ident and log[7] == PHYSV and log[4] == K and (
            first == steps if log[6] & RL_COMPLETE else True)
        res.append(("9 demo %d %s (%s): passes 130.14.7.2's checks 1 - 8 (identity %04Xh = the course's, physics "
                    "%02Xh = BZ_PHYSV), and the model replays its %d steps to %s" % (
                        K, c.name, d["where"], log_ident(log), log[7], steps,
                        "the goal on its last step" if log[6] & RL_COMPLETE else "its end"), ok))
    again = build_demos(courses, paths)
    res.append(("9 the route demos are deterministic (two builds byte-identical: %s)" % ", ".join(
        "%s %d bytes" % (courses[K].name, len(d["log"])) for K, d in sorted(again.items()) if d["kind"] == "route"),
        all(again[K]["log"] == demos[K]["log"] for K in demos)))
    # wave 6 (SPEC.md 130.16.9): a shipped demo under other PHYSICS is REFUSED by the build (it was re-stamped
    # or demoted, never failing: 130.14.18 item 9's assertion is replaced and its control flips), and so is
    # one that would be DEMOTED
    K = next(K for K, d in sorted(demos.items()) if d["log"][6] & RL_COMPLETE)
    c = courses[K]

    def refused(log, what):
        try:
            check_demo(c, K, bytes(log), idents, "<%s>" % what)
            return "accepted"
        except CourseError as e:
            return str(e)
    for what, pv in (("5b's physics A0h", 0xA0), ("BZ_PHYSV ^ 5Ah", PHYSV ^ 0x5A)):
        other = bytearray(demos[K]["log"])
        other[7] = pv
        why = refused(other, what)
        res.append(("9 a shipped demo with a stale `physics` line (%s) is REFUSED by the build, naming `bbcourse.py "
                    "author` (it was re-stamped)" % what, "bbcourse.py author" in why and "physics" in why))
    short = bytearray(demos[K]["log"])
    struct.pack_into("<I", short, 8, struct.unpack_from("<I", short, 8)[0] - short[RLOG_HDR + 1] + 1)
    short[RLOG_HDR + 1] = 1                       # the first run cut to one step: it no longer ends at the goal
    why = refused(short, "would be demoted")
    res.append(("9 a shipped demo that would be DEMOTED (it says COMPLETE and no longer ends at its goal) is REFUSED",
                "DEMOTED" in why))
    # `stalebzd` (SPEC.md 130.16.14): moon.bzd's own text with its `physics` line left at A0h, built as the
    # build builds it - refused at item 9
    mk = next((k for k, c_ in enumerate(courses) if c_.name == "MOON"), None)
    if mk is not None and os.path.exists(demo_path(paths[mk])):
        with open(demo_path(paths[mk]), encoding="ascii") as f:
            txt = f.read()
        stale = re.sub(r"(?m)^physics\s+\S+", "physics A0", txt)
        try:
            check_demo(courses[mk], mk, bzd_log(parse_bzd(stale, "<moon.bzd, physics A0>"), mk), idents,
                       "<moon.bzd, physics A0>")
            why = "accepted"
        except CourseError as e:
            why = str(e)
        res.append(("9 control `stalebzd`: moon.bzd with its `physics` line left at A0h is refused (%s)"
                    % why[:90], stale != txt and "bbcourse.py author" in why))
    # the demo's COURSE identity: another build's demo FAILS the build ...
    wrong = bytearray(demos[K]["log"])
    struct.pack_into("<H", wrong, 14, c.ident ^ 0x0101)
    try:
        check_demo(c, K, bytes(wrong), idents, "<another build>")
        failed = False
    except CourseError as e:
        failed = "earlier build" in str(e)
    res.append(("9 a demo of another build of its course FAILS the build, naming it", failed))
    # ... and the negative control: with that check removed the demo is accepted, and this item's own
    # check (the log's +14 against the course's identity) catches it
    acc = check_log(bytes(wrong), len(courses), [i if k != K else c.ident ^ 0x0101 for k, i in enumerate(idents)])
    res.append(("9 negative control: the identity check removed (the demo-identity control), the demo is accepted by "
                "the reader and this item's identity test fails it", acc is None and log_ident(wrong) != c.ident))
    # wave 6 (SPEC.md 130.16.8): the PLAYGROUND's authored demo is the only one that boosts - its model replay
    # boosts and ends at its goal; its control is the same log with the boost's Space press removed
    pk = next((k for k, c_ in enumerate(courses) if c_.name == "PLAY"), None)
    if pk is not None and pk in demos:
        ok, why = play_demo_verdict(courses[pk], demos[pk]["log"])
        res.append(("9 BZD%d (PLAY): %s" % (pk, why), ok))
        nb = no_boost_log(courses[pk], demos[pk]["log"])
        ok2, why2 = play_demo_verdict(courses[pk], nb) if nb is not None else (True, "no boost to remove")
        res.append(("9 control `noboostdemo`: BZD%d's log with its boost's Space press removed is refused (%s)"
                    % (pk, why2), nb is not None and not ok2))
    # wave 6 (SPEC.md 130.16.8): a course in AUTHOR whose .bzd is missing is REFUSED, never quietly given a
    # route demo - the demos' folder swapped for an empty one
    import tempfile
    with tempfile.TemporaryDirectory() as td:
        try:
            build_demos(courses, paths, td)
            why = "accepted"
        except CourseError as e:
            why = str(e)
    authored = [c.name for c in courses if c.name in AUTHOR]
    res.append(("9 a course in AUTHOR (%s) without its .bzd is REFUSED, never given a route demo (%s)" % (
        ", ".join(authored), why[:80]), "AUTHORED course with no demo file" in why))
    # the .bzd text round-trips
    rt = all(bzd_log(parse_bzd(demo_text(d["log"], courses[K].name), "<rt>"), K) == d["log"]
             for K, d in demos.items())
    res.append(("9 every demo's .bzd text (bbcourse.py demo's) parses back to its bytes", rt))


W2_COMMIT = "848ade16"          # wave 2's tree (SPEC.md 130.12.9)
W5_COMMIT = "503031d4"          # wave 5b's tree: wave 6 moved only the reach's inputs from it (SPEC.md 130.16.13)
W5_HOPMAX, W5_BOOST = 224, 0    # ...and those inputs as 5b had them


def wave2_parts(names, commit=W2_COMMIT, files=None, texts=None):
    """the parts of the named courses as a commit's own tool compiled them
    (848ade16, wave 2's; 573eec83, 3b's; ef59209a, the last BZC1 tree's), out
    of git in a temporary tree: -> ({NAME: bytes}, None) or (None, why it
    cannot be had).  files: the courses' file names, in BZ_COURSES's order
    (default each NAME's lower case); texts: THIS tree's course files (absolute
    paths) to compile with that commit's tool instead of its own (130.16.13)"""
    W2_COMMIT = commit
    import subprocess
    import tempfile
    import tarfile
    try:
        r = subprocess.run(["git", "cat-file", "-e", W2_COMMIT + "^{commit}"], cwd=ROOT, capture_output=True)
        if r.returncode:
            return None, "commit %s is not in this clone (a shallow one? `git fetch --unshallow`)" % W2_COMMIT
        with tempfile.TemporaryDirectory() as td:
            tar = os.path.join(td, "w.tar")
            dem = subprocess.run(["git", "cat-file", "-e", W2_COMMIT + ":apps/bonanza/demos"], cwd=ROOT,
                                 capture_output=True).returncode == 0
            lz = subprocess.run(["git", "cat-file", "-e", W2_COMMIT + ":tools/os88lz.py"], cwd=ROOT,
                                capture_output=True).returncode == 0
            r = subprocess.run(["git", "archive", "-o", tar, W2_COMMIT, "tools/bbcourse.py", "tools/bonanza_assets.py",
                                "apps/bonanza/courses"] + (["apps/bonanza/demos"] if dem else [])
                               + (["tools/os88lz.py"] if lz else []), cwd=ROOT, capture_output=True)
            if r.returncode:
                return None, "git archive of %s failed" % W2_COMMIT
            w = os.path.join(td, "w")
            with tarfile.open(tar) as tf:
                if hasattr(tarfile, "data_filter"):
                    tf.extractall(w, filter="data")
                else:
                    tf.extractall(w)
            paths = [os.path.join(w, "apps", "bonanza", "courses", f) for f in (files or [n.lower() + ".bbc"
                                                                                     for n in names])]
            if texts is not None:
                for src, dst in zip(texts, paths):
                    with open(src, "rb") as fi, open(dst, "wb") as fo:
                        fo.write(fi.read())
            r = subprocess.run([sys.executable, os.path.join(w, "tools", "bbcourse.py"), "-o",
                                os.path.join(td, "art")] + paths, cwd=w, capture_output=True)
            if r.returncode:
                return None, "%s's tool failed: %s" % (W2_COMMIT, r.stderr.decode(errors="replace")[-200:])
            return {n: open(os.path.join(td, "art", "BZ%d.BIN" % k), "rb").read() for k, n in enumerate(names)}, None
    except OSError as e:
        return None, "git is not to be had (%s)" % e


# =============================================================================
# wave 5b's items (SPEC.md 130.15.12.3): 10, the compact form; 12, the budget
# =============================================================================

def rec4_compare(sb, zm, br, s_, t_, SB, TB, wrap=False):
    """the guest's byte compare under RECB 4 (SPEC.md 130.15.5.1): the keys
    ks = clamp(s_b + SB - br) and kt = clamp(z_b + m - TB) to 0 - 255, laid
    iff ks < s' and kt < t' (unsigned).  wrap: the negative control's key that
    wraps mod 256 instead of clamping"""
    ks, kt = sb + SB - br, zm - TB
    if wrap:
        ks, kt = ks & 255, kt & 255
    else:
        ks, kt = min(max(ks, 0), 255), min(max(kt, 0), 255)
    return ks < s_ and kt < t_


def rec4_verdicts(c, sb_delta=0, wrap=False):
    """every record of the course under its D biases, at every query of its
    block (block_queries) and at poked keys either side of both clamps: the
    byte compare against the rule.  -> (verdicts compared, first mismatch or
    None).  sb_delta, wrap: the negative controls (SB one lower; a key that
    wraps)"""
    SB, TBS = rec_biases(c.model["recs"], c.name, c.model["brows"])
    n = 0
    for br, col, s, top, mi in c.model["recs"]:
        TB = TBS[br >> BAND_SH]                     # (SPEC.md 130.51: the record's band's)
        s_, t_ = s - br + SB, top - TB
        qs = set(c.queries.get((br, col), ()))
        ks = (-300, -129, -1, 0, 1, s_ - 1, s_, s_ + 1, 254, 255, 256, 300, 511, 600)
        kt = (-300, -129, -1, 0, 1, t_ - 1, t_, t_ + 1, 254, 255, 256, 300, 511, 600)
        qs |= {(k - SB + br, j + TB) for k in ks for j in kt}
        for sb, zm in qs:
            n += 1
            if rec4_compare(sb, zm, br, s_, t_, SB + sb_delta, TB, wrap) != (sb < s and zm < top):
                return n, (br, col, s, top, sb, zm)
    return n, None


def _w5_compact(courses, res):
    """item 10 (SPEC.md 130.15.12.3): the compact form, and its eight controls"""
    ctl = {"low_first": [], "sb": [], "wrap": [], "wdiff": [], "mtab": [], "irmove": [], "no_obs": []}
    for c in courses:
        if c.split:                                 # (a TWO-PART course, SPEC.md 130.30: _w5_compact2's checks;
            _w5_compact2(c, res)                    # the one-part form's controls run on the one-part courses)
            continue
        why = []
        try:
            if expand(c.stored, c.name, sim=True) != c.cga:
                why.append("expand(stored) != RAM")
            pt = read_part(c.cga, c.name)
        except CourseError as e:
            why.append(str(e))
        else:
            if [struct.unpack_from("<H", c.cga, pt["mtab"] + 2 * i)[0] for i in range(pt["nmask"])] \
                    != [pt["maskoff"] + 16 * i for i in range(pt["nmask"])]:
                why.append("MTAB")
        holes = sum(e["len"] - e["dlen"] for e in c.part["dir"])
        res.append(("10 %s: expand(stored) == RAM byte for byte (%d bytes), the IN-PLACE "
                    "simulation clean (every stored byte read before anything is written over it), the directory's "
                    "rules (%d entries, each in its header fields' place and size), the records' s' and t' bounds "
                    "and MTAB (%d words); %d bytes of holes%s" % (
                        c.name, len(c.cga), c.part["nsec"], len(c.masks), holes,
                        "" if not why else " -- " + "; ".join(why)), not why))
        n, bad = rec4_verdicts(c)
        SB, TB = rec_biases(c.model["recs"], c.name, c.model["brows"])
        TB = "%d - %d over %d bands" % (min(TB), max(TB), len(TB))
        res.append(("10 %s: the 4-byte records' byte compares (SB %d, TB %s) give the rule's verdict on all %d "
                    "(record, query) pairs - every query of the merge's set, and keys poked either side of both "
                    "clamps%s" % (c.name, SB, TB, n, "" if bad is None else " -- differs at %s" % (bad,)),
                    bad is None))
        if c.model["recs"]:
            ctl["sb"].append(rec4_verdicts(c, sb_delta=-1)[1] is not None)
            ctl["wrap"].append(rec4_verdicts(c, wrap=True)[1] is not None)
        # the identity, three ways (130.15.7)
        b8 = bytearray(identity_form(c))
        diroff = struct.unpack_from("<H", b8, 38)[0]
        b8[diroff + 1] ^= 5
        struct.pack_into("<H", b8, diroff + 6, struct.unpack_from("<H", b8, diroff + 6)[0] ^ 0x0101)
        moved = bytearray(identity_form(c))
        cell = struct.unpack_from("<H", moved, 26)[0] + GHDR
        moved[cell] ^= 1
        id3 = (ram_identity(bytes(b8)) == c.ident, ram_identity(bytes(moved)) != c.ident,
               ram_identity(c.cga) == ram_identity(identity_form(c)) == c.ident)
        res.append(("10 %s: the identity %04Xh three ways - a directory entry's form byte and stored length changed "
                    "leave it, one changed RAM byte moves it, and the RAM form and its 8-byte identity form give the same one%s"
                    % (c.name, c.ident, "" if all(id3) else " -- %s" % (id3,)), all(id3)))
        # CELLS (130.15.6): the exceptions, the cells whose stored difference from the rule is not 0, every
        # one a lift's shaft cell; and the control, the rule without SAFE's OBS clause (red arm cellsafe's)
        exc = cells_exceptions(c.cga)
        shaft = set(c.slabcells)
        nvoid = sum(1 for i in range(2, len(c.part["grid"]["cells_raw"]), 4)
                    if c.part["grid"]["cells_raw"][i] & 15 == KIND_VOID)
        res.append(("10 %s: CELLS - %d VOID cells' z0 and every cell's SAFE stored as their difference from the "
                    "rule, %d exception%s%s, every one a lift's shaft cell (%d shaft cell%s)" % (
                        c.name, nvoid, len(exc), "" if len(exc) == 1 else "s",
                        "" if not exc else " (%s)" % ", ".join("(%d, %d) %s" % e for e in exc),
                        len(shaft), "" if len(shaft) == 1 else "s"),
                    all((wx, wy) in shaft for wx, wy, _ in exc)))
        def _would_be_safe(cell):                   # a prop's cell SAFE but for its OBS (a clock's may not be)
            tl = c.tiles.get(cell)
            return (tl is not None and tl.kind == KIND_FLOOR and tl.sx == 0 and tl.sy == 0
                    and all((cell[0] + dx, cell[1] + dy) in c.tiles for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1))))
        if any(_would_be_safe(cell) for cell in c.pcell):
            ctl["no_obs"].append(any((wx, wy) not in shaft for wx, wy, _ in cells_exceptions(c.cga, _no_obs=True)))
        # the controls
        try:
            expand(stored_form(c.model, 4, c.cga, c.name, _hack={"low_first": True}), c.name, sim=True,
                   _hack={"low_first": True})
            ctl["low_first"].append(False)
        except CourseError as e:
            ctl["low_first"].append("section M" in str(e))
        if len(c.model["recs"]) > 1:
            ctl["wdiff"].append(expand(c.stored, c.name, _hack={"wdiff_short": True}) != c.cga)
        if c.masks:
            ctl["mtab"].append(expand(c.stored, c.name, _hack={"mtab_short": True}) != c.cga)
        bb = bytearray(c.cga)
        pt = c.part
        ji = next(j for j, e in enumerate(pt["dir"]) if e["tag"] == "I")
        jr = next(j for j, e in enumerate(pt["dir"]) if e["tag"] == "R") if any(
            e["tag"] == "R" for e in pt["dir"]) else None
        if jr == ji + 1:
            ei, er = pt["diroff"] + DIRENT * ji, pt["diroff"] + DIRENT * jr
            struct.pack_into("<H", bb, ei + 4, struct.unpack_from("<H", bb, ei + 4)[0] + 2)
            struct.pack_into("<HH", bb, er + 2, struct.unpack_from("<H", bb, er + 2)[0] + 2,
                             struct.unpack_from("<H", bb, er + 4)[0] - 2)
            try:
                read_part(bytes(bb), c.name)
                ctl["irmove"].append(False)
            except CourseError as e:
                ctl["irmove"].append("(I)" in str(e))
    for key, what in (("low_first", "ROWPLANES stored and read with the low bytes first fails the in-place "
                                    "simulation, naming the map (the last row's last quarter)"),
                      ("sb", "SB one lower in the guest's key fails the byte compares"),
                      ("wrap", "a key that wraps instead of clamping fails the byte compares"),
                      ("wdiff", "an expander off by one record (WDIFF one record short) fails expand == RAM"),
                      ("mtab", "MTAB one entry short fails expand == RAM"),
                      ("irmove", "the I and R entries' boundary moved by a word (still tiling the part) is refused "
                                 "by the place-and-size rule, naming I"),
                      ("no_obs", "the CELLS rule with SAFE's OBS clause taken out (the red arm cellsafe's) has "
                                 "exceptions outside the shafts (the courses with a prop's cell that is SAFE but for it)")):
        v = ctl[key]
        res.append(("10 negative control: %s, on every course (%d)" % (what, len(v)), bool(v) and all(v)))


def _w5_compact2(c, res):
    """item 10 for a TWO-PART course (SPEC.md 130.30.4): each part's stored form expands IN PLACE to its RAM form,
    read_parts takes both, the 4-byte records' compares, and the identity three ways over the pair; CELLS'
    exceptions as a one-part course's"""
    why = []
    try:
        if expand(c.stored, c.name, sim=True) != c.cga or expand(c.wstored, c.name, sim=True) != c.wcga:
            why.append("expand(stored) != RAM")
        read_parts(c.cga, c.wcga, c.name)
    except CourseError as e:
        why.append(str(e))
    res.append(("10 %s (TWO parts, SPEC.md 130.30): each part's expand(stored) == RAM byte for byte "
                "(%d + %d bytes), the IN-PLACE simulation clean per part, read_parts takes both%s" % (
                    c.name, len(c.cga), len(c.wcga), "" if not why else " -- " + "; ".join(why)), not why))
    n, bad = rec4_verdicts(c)
    res.append(("10 %s: the 4-byte records' byte compares give the rule's verdict on all %d (record, query) pairs%s"
                % (c.name, n, "" if bad is None else " -- differs at %s" % (bad,)), bad is None))
    moved = bytearray(c.wcga)
    moved[struct.unpack_from("<H", moved, 26)[0] + GHDR] ^= 1
    pic = bytearray(c.cga)
    pic[HDR] ^= 1
    id3 = (ram_identity2(c.cga, bytes(moved)) != c.ident, ram_identity2(bytes(pic), c.wcga) != c.ident,
           ram_identity2(c.cga, c.wcga) == c.ident)
    res.append(("10 %s: the identity %04Xh three ways - one changed world RAM byte moves it, one changed picture "
                "RAM byte moves it, and the two parts give the shipped one%s" % (
                    c.name, c.ident, "" if all(id3) else " -- %s" % (id3,)), all(id3)))
    exc = cells_exceptions(c.wcga)
    shaft = set(c.slabcells)
    res.append(("10 %s: CELLS - %d exception%s in the world part, every one a lift's shaft cell" % (
        c.name, len(exc), "" if len(exc) == 1 else "s"), all((wx, wy) in shaft for wx, wy, _ in exc)))


def _mask_pix(mask, br, bc):
    """the picture pixels a 16-byte mask of block (br, bc) LAYS: its pairs 0"""
    return frozenset((8 * bc + lx, 8 * br + ly) for ly in range(8) for lx in range(8)
                     if not (mask[2 * ly + (lx >> 2)] >> (6 - 2 * (lx & 3))) & 3)


def _w5_dither(courses, res, demos=None):
    """item 11 (SPEC.md 130.15.12.3, 130.15.10): the dither and the audit"""
    import bonanza_assets as _BA
    # every K mask holds the checker, in both RAM forms' bytes; deduplicated again after the dither
    bad, figs = [], []
    for c in courses:
        ms = (decode_parts(c.cga, c.wcga) if c.split else decode_part(c.cga))["masks"]
        if any(dither(mk) != mk for mk in ms) or len(set(ms)) != len(ms):
            bad.append(c.name)
        if any(r["kmask"] != dither(r["mask"]) for r in c.records) or len(c.masks) > c.umasks:
            bad.append(c.name)
        figs.append("%s %d -> %d" % (c.name, c.umasks, len(c.masks)))
    res.append(("11 every K mask has the checker set (mask OR CHK = mask, 3333h on an even line and CCCCh on an odd "
                "one: the kept lattice x + y odd, the shadow's dark pixels' complement) in the RAM form, each "
                "record's mask its merged mask ORed with it, and the masks deduplicated again (%s)%s" % (
                    ", ".join(figs), "" if not bad else " -- %s" % sorted(set(bad))), not bad))
    # no record in the part lays nothing: an all-keep kmask is left out with its record (S1), and every record
    # the rule holds and the part leaves out is exactly such a one
    dbad, dfig = [], []
    for c in courses:
        m = decode_parts(c.cga, c.wcga) if c.split else decode_part(c.cga)
        kept = [r for r in c.records if r["kmask"] != ALLKEEP]
        if ALLKEEP in m["masks"] or len(m["recs"]) != len(kept) or \
                [(r["brow"], r["col"], r["s"], r["top"]) for r in kept] != [q[:4] for q in m["recs"]]:
            dbad.append(c.name)
        dfig.append("%s %d" % (c.name, len(c.records) - len(kept)))
    res.append(("11 no K mask is all-keep and no record points at one: the records whose pixels all lie on the kept "
                "lattice are left out of the part and kept by the rule (%s)%s" % (
                    ", ".join(dfig), "" if not dbad else " -- %s" % dbad), not dbad))
    # what is not dithered: the balls' masks and the lift's slab, each its generator's bytes
    bbad = []
    for mat in range(len(MAT_NAMES)):
        part = _BA.build_ball2(mat)
        sil = _BA.material_frame(mat, 0, 0)
        for sh in range(_BA.SHIFTS):
            for r in range(_BA.D):
                slots = [None] * (_BA.RB * 4)
                for x, cc in enumerate(sil[r]):
                    if cc is not None and 0 <= x + sh < len(slots):
                        slots[x + sh] = cc
                want = _BA.cga_bytes([3 if cc is None or cc == _BA.SEE else 0 for cc in slots])
                o = _BA.B2_MASKOFF + (sh * _BA.D + r) * _BA.RB
                if part[o:o + _BA.RB] != want:
                    bbad.append(MAT_NAMES[mat])
    sbad, nslab = [], 0
    for c in courses:
        for p in c.props:
            if p["kind"] == PK_PLATFORM:
                nslab += 1
                form = c.wcga if c.split else c.cga
                po = struct.unpack_from("<H", form, 28)[0]
                so = p["spoff"] - struct.unpack_from("<H", world_of(c), 28)[0] + po
                if form[so:so + PL_SPR] != slab_bytes(slab_pixels()):
                    sbad.append(c.name)
    res.append(("11 not dithered: the three balls' masks are their silhouettes' at every shift (bonanza_assets' "
                "generator's bytes, no checker added), and the lift's slab sprite in every part with one (%d) is "
                "slab_bytes() of its pixels%s" % (
                    nslab, "" if not (bbad or sbad) else " -- %s" % sorted(set(bbad + sbad))),
                not bbad and not sbad and nslab))
    # the merge's exactness, re-run on the UNDITHERED masks: each merged record's mask the AND of its members',
    # its laid pixels those the mask clears, and the merged masks lay what the unmerged ones lay at every query
    mbad = []
    for c in courses:
        def from_masks(recs, key):
            out = []
            for r in recs:
                d = dict(r)
                d["pix"] = _mask_pix(r[key], r["brow"], r["col"])
                out.append(d)
            return out
        for r in c.records:
            andm = bytearray(b"\xff" * 16)
            for mb in r["members"]:
                for i in range(16):
                    andm[i] &= mb["mask"][i]
            if bytes(andm) != r["mask"] or _mask_pix(r["mask"], r["brow"], r["col"]) != r["pix"]:
                mbad.append(c.name)
                break
        tried, diff = merge_exact(from_masks(c.raw, "mask"), from_masks(c.records, "mask"), c.queries)
        if diff is not None:
            mbad.append(c.name)
    res.append(("11 the merge is exact on the UNDITHERED masks: every merged mask the AND of its members', laying "
                "exactly its pixels, and every query's laid set the unmerged masks' (%s)%s" % (
                    ", ".join(c.name for c in courses), "" if not mbad else " -- %s" % mbad), not mbad))
    # the CARD's composite (records less the checker) against the dithered masks laid as the guest lays them,
    # and laid_at's card count against the pixels those masks lay: reach centres, lowest and highest, both
    # air states, and every fourth step of the autopilot's route
    for c in courses:
        pos = []
        for rc in c.reach:
            if (rc.wx, rc.wy) in getattr(c, "noocc", ()):
                continue                            # (SPEC.md 130.53)
            gx, gy = (16 * rc.wx + 8) << 8, (16 * rc.wy + 8) << 8
            po_ = pose_of(c, rc, gx, gy)            # (130.49: a REAL pose there - its floor, its margin)
            zl_, f_ = po_ or (None, None)
            for z in (sorted({zl_, rc.zhi}) if po_ else ()):
                for air in ((1,) if f_ is None else (0, 1)):
                    pos.append((((gx - gy) >> 8) + c.x0 - 8, (((gx + gy) >> 1) >> 8) - z + c.y0 - 13, rc.s, z,
                                oair_at(air, z, f_), mcell(gx, gy)))
        ph = Physics(c, play=True)
        while ph.nstep < DEMO_STEPS and not ph.goal:
            ph.step(ph.auto())
            if not ph.nstep & 3 and not ph.tube and not ph.hid:
                pos.append((ph.px, ph.py, ph.sb, ph.zb, ph.oair, mcell(ph.gx, ph.gy)))
        diff = cnt = ghosts = 0
        for px, py, sb, z, air, cl_ in pos:         # (cl_: the ball's cell, SPEC.md 130.29's model there)
            lset = set()
            if composite(c, px, py, sb, z, air, ghost=True, cell=cl_) != card_composite(c, px, py, sb, z, air,
                                                                                        laid=lset, cell=cl_):
                diff += 1
            card = laid_at(c, px, py, sb, z, air, card=True, cell=cl_)
            if card != lset:
                cnt += 1
            ghosts += sum(1 for q in ball_pixels(px, py) if ghost(*q) and any(
                q in r["pix"] for r in laid_at(c, px, py, sb, z, air)))
        res.append(("11 %s: the card's composite (records less the checker) equals the dithered masks laid as the "
                    "guest lays them, and laid_at's card count their laid pixels (%d positions, %d differ, %d counts "
                    "differ; %d ball pixels kept as ghosts)" % (c.name, len(pos), diff, cnt, ghosts),
                    diff == 0 and cnt == 0))
        c._vis_pos = pos
    # the negative controls (130.15.10.3)
    mill = next((c for c in courses if c.name == "MILL"), None)
    if mill is not None:
        hit = next((q for q in mill._vis_pos if composite(mill, *q[:5], ghost=False, cell=q[5])
                    != card_composite(mill, *q[:5], cell=q[5])), None)
        res.append(("11 MILL negative control: the card's model with the checker NOT stripped disagrees with the "
                    "dithered composite%s" % (" (first at px %d, py %d)" % hit[:2] if hit else ""), hit is not None))
        if getattr(mill, "_raised", None) is None:
            mill._raised = _raised_tops(mill)
        keep = mill.by_block
        fed = {}
        for r in mill.records:
            d = dict(r)
            d["pix"] = _mask_pix(r["kmask"], r["brow"], r["col"])
            fed.setdefault((r["brow"], r["col"]), []).append(d)
        mill.by_block = fed
        try:
            hit = next((q for q in mill._vis_pos if composite(mill, *q[:5], via="records", cell=q[5])
                        != composite(mill, *q[:5], via="pixels", cell=q[5])), None)
        finally:
            mill.by_block = keep
        res.append(("11 MILL negative control: the rule's composite fed the DITHERED masks fails item 5's comparison "
                    "with the per-pixel buffer%s" % (" (first at px %d, py %d)" % hit[:2] if hit else ""),
                    hit is not None))
    # the audit, in REPORT mode, for every course
    sums = []
    for k, c in enumerate(courses):
        d = (demos or {}).get(k)
        lines, sm = visibility(c, k, d["log"] if d and d["kind"] == "file" else None)
        print("\n".join(lines))
        sums.append("%s %d/%d BELOW, %d stretches" % (c.name, sm["below"], sm["marks"], sm["stretches"]))
        c.vis = sm
    res.append(("11 the visibility audit printed for every course, REPORT mode (%s); BENCH exempt"
                % "; ".join(sums), all(c.vis["ghost"] for c in courses)))


# SPEC.md 130.27.6: the ground rule's course - a field at 0 and an island 6 units up across the void
GROUND_TEST = ('course GR "Ground"\nwidth 64\nfloor rect 4 4 10 10 flat 0\nfloor rect 12 4 15 7 flat 6\n'
               'start 5 5\n')


def _face_bottoms(c, ops):
    """SPEC.md 130.27.6: every whole cell's sw and se face over the VOID in `ops`, read off its spans:
    [(cell, which, the face's last line, the corners' heights (zp, zq) in px)] - the cells the picture draws
    (a glass tile's is not one, 130.25.18)"""
    gc = {p_["at"] for p_ in c.props if p_.get("art") == "glass"} | set(getattr(c, "rails", ()))
    drawn = {k: v for k, v in c.tiles.items() if k not in gc}       # (130.35: nor a guard rail's wall)
    out = []
    for _k, cell, _t, h, _s, _e, faces in _cell_faces(drawn):
        if h is not None or isinstance(_t, FieldTile):  # (a FIELD cell's faces follow its profile: 130.28.6)
            continue
        for fp, zp, fq, zq, nb, which in faces:
            if nb is not None:
                continue
            sp = _op_spans(ops, cell, which)
            if sp:
                out.append((cell, which, max(sp), (fp, zp), (fq, zq)))
    return out


def _face_verdict(c, ops, floats, ground):
    """-> (faces checked, faces whose last line DECIDES grounded from floating, [what is wrong]): each face's
    last line is the lower of its two bottom corners' - a FLOATING cell's 3 units under its top, any other's
    the ground plane's or 3 units, whichever is lower (SPEC.md 130.27.1)"""
    n = dec = 0
    bad = []
    for cell, which, last, (fp, zp), (fq, zq) in _face_bottoms(c, ops):
        n += 1
        flo = cell in floats
        fd = floats.get(cell, FACE8) if isinstance(floats, dict) else FACE8
        bp, bq = (zp - fd, zq - fd) if flo else (min(zp - FACE8, ground), min(zq - FACE8, ground))
        want = max(4 * (fp[0] + fp[1]) - bp, 4 * (fq[0] + fq[1]) - bq) - 1
        if min(zp, zq) - FACE8 > ground + 2:
            dec += 1
        if last != want:
            bad.append("%s %s face's last line %d, not %d (%s)" % (cell, which, last, want,
                                                                   "floating" if flo else "grounded"))
    return n, dec, bad


def _ground_checks(courses, res):
    """item 14 (SPEC.md 130.27.6): the grounded faces - the rule on a course made for it and its FLOATING twin,
    each with its negative control, and every course's faces over the void held to the rule"""
    try:
        cg = compile_course(GROUND_TEST, "<GROUND>", _hack={"no_finish": True})
        cf = compile_course(GROUND_TEST + "float rect 12 4 15 7\n", "<GROUND, floating>", _hack={"no_finish": True})
        cn = compile_course(GROUND_TEST, "<GROUND, the rule off>", _hack={"no_finish": True, "noground": True})
    except CourseError as e:
        res.append(("14 GROUND: the ground rule's course compiles (%s)" % e, False))
        return
    isl = [(cell, w, last) for cell, w, last, *_r in _face_bottoms(cg, cg.ops) if cell[0] >= 12]
    want = 8 * (13 + 6 + 2) - cg.ground - 1          # the island's sw face at (13, 6): corner B (28, 14), the ground
    got = dict(((cell, w), last) for cell, w, last in isl).get(((13, 6), "sw"))
    ff = dict(((cell, w), last) for cell, w, last, *_r in _face_bottoms(cf, cf.ops)).get(((13, 6), "sw"))
    fn = dict(((cell, w), last) for cell, w, last, *_r in _face_bottoms(cn, cn.ops)).get(((13, 6), "sw"))
    wantf = 8 * (13 + 6 + 2) - (48 - FACE8) - 1      # ... 3 units under its top, 6 units (48 px) up
    res.append(("14 GROUND: the island 6 units up hangs its face over the void to the ground plane (%d px, the "
                "field's 0 less 3 units): (13, 6)'s sw face ends on line %s, the ground's %d; FLOATING (`float rect "
                "12 4 15 7`) it ends on line %s, 3 units down (%d); negative control, the rule off: line %s" % (
                    cg.ground, got, want, ff, wantf, fn),
                cg.ground == -FACE8 and got == want and ff == wantf and fn == wantf and cf.floats
                and not cg.floats))
    for nm, cc, fl, gr, good in (("the course", cg, cg.floats, cg.ground, True),
                                 ("its floating twin", cf, cf.floats, cf.ground, True),
                                 ("negative control: the floating twin read as grounded", cf, frozenset(),
                                  cf.ground, False),
                                 ("negative control: the course with the rule off read as grounded", cn,
                                  frozenset(), cg.ground, False)):
        n, dec, bad = _face_verdict(cc, cc.ops, fl, gr)
        res.append(("14 GROUND: %s - %d faces over the void, %d of them deciding: %s" % (
            nm, n, dec, "every one on its line" if not bad else "%d off (%s)" % (len(bad), "; ".join(bad[:3]))),
            (not bad) == good and dec > 0))
    for c in courses:
        n, dec, bad = _face_verdict(c, c.ops, c.floats, c.ground)
        res.append(("14 GROUND %s: the ground plane %d px (%s units); %d faces over the void, %d deciding, %d "
                    "FLOATING cells: %s" % (c.name, c.ground, c.ground / 8.0, n, dec, len(c.floats),
                                            "every one on its line" if not bad else
                                            "%d off: %s" % (len(bad), "; ".join(bad[:4]))), not bad))
    play = next((c for c in courses if c.name == "PLAY"), None)
    if play is not None:
        res.append(("14 GROUND: PLAYGROUND uses `float` (%d floating cells), so the statement ships exercised"
                    % len(play.floats), bool(play.floats)))


def _w5_budget(courses, res):
    """item 12 (SPEC.md 130.15.12.3): the `target` statement and the budget"""
    import copy
    peak = next((c for c in courses if c.name == "PEAK"), None)
    if peak is not None and peak.src.target:
        cc = copy.copy(peak)
        cc.src = copy.copy(peak.src)
        cc.target, cc.src.target = 30, (30, peak.src.target[1])
        # (SPEC.md 130.27.5: the 1.5x line is REPORTED, never refused - PEAK as a 30 s course, over it, is
        # accepted and its note says OVER; the red arm, the refusal put back, fails this)
        try:
            n_ = check_budget(cc, 1)
            got, ok_ = budget_note(cc, n_), n_ is not None and "OVER 1.5x" in budget_note(cc, n_)
        except CourseError as e:
            got, ok_ = "refused: %s" % e, False
        res.append(("12 reported, not refused (130.27.5): PEAK as a 30 s course (its %d LZ4 bytes over the 1.5x "
                    "line of %d) - %s" % (packed_len(peak.stored), budget_cap(30), got), ok_))
    first = _first_text()
    for what, text, want in (("target 45", _swap(first, "target 30", "target 45"), "target takes 30, 60 or 90"),
                             ("target given twice", first + "target 60\n", "target given twice")):
        try:
            compile_course(text, "<FIRST, %s>" % what)
            got, fired = "compiled", False
        except CourseError as e:
            got, fired = str(e), want in str(e)
        res.append(("12 refused: %s%s" % (what, "" if fired else " -- got: " + got), fired))
    try:
        check_budget(compile_course(_swap(first, "target 30", ""), "<FIRST, no target>"), 1)
        got, fired = "accepted", False
    except CourseError as e:
        got, fired = str(e), "no `target`" in str(e)
    res.append(("12 refused: a course (not the benchmark's) with no target%s" % ("" if fired else " -- got: " + got), fired))
    for k, c in enumerate(courses):
        if c.target is None:
            res.append(("12 %s (course %d): no target, a test course's: no budget" % (c.name, k),
                        c.test))
            continue
        n, z = packed_len(c.stored, "lz4"), packed_len(c.stored, "lzb")
        bg = budget(c.target)
        res.append(("12 %s: target %d s, budget %d, 1.5x %d (REPORTED, 130.27.5): RECB 4's stored form LZ4 %d (%s), "
                    "LZB %d (%s); RAM %d of %d" % (
                        c.name, c.target, bg, budget_cap(c.target), n, "over" if n > bg else "under", z,
                        "over" if z > bg else "under", len(c.cga), PARTMAX), len(c.cga) <= PARTMAX))


