def _field_cases():
    """SPEC.md 130.28.3's refusals, each a line written to trip it: (what, text, a substring of the refusal)"""
    S = _FCHUTE
    return [
        ("a leg off the axis", S + "chute 1 round depth 4 way 8 29 2 way 12 30\n", "not along one axis"),
        ("an inner way that goes straight on", S + "chute 1 round depth 4 way 8 29 2 way 10 29 way 14 29\n",
         "goes straight on"),
        ("an inner way that doubles back", S + "chute 1 round depth 4 way 8 29 2 way 12 29 way 10 29\n",
         "doubles back"),
        ("a 2-wide leg too short", S + "chute 2 round depth 4 way 8 30 2 way 9 30\n", "too short"),
        ("a slope not a whole number of half units a tile", S.replace("way 16 31 4", "way 16 31 3.5"),
         "not a whole number"),
        ("a depth past the slope bound", S.replace("depth 10", "depth 16"), "the bound |sx| + |sy|"),
        ("a pit's radius 5", S + "pit 22 28 2 radius 5 depth 8\n", "radius is 2 - 4"),
        ("a pit's hole not under its radius", S + "pit 22 28 2 radius 2 depth 8 hole 2\n", "under its radius"),
        ("two chutes on one cell", S + "chute 1 round depth 4 way 9 10 2 way 9 16\n", "is laid by this chute"),
        ("the start on a FIELD cell", S.replace("start 7 7", "start 14 12"), "which is a FIELD cell"),
        ("a pad on a FIELD cell", S + "pad steel 14 12\n", "which is a FIELD cell"),
        ("a spring on a FIELD cell", S + "spring 14 12 400\n", "which is a FIELD cell"),
        ("a split cell in a FIELD cell's 3 x 3", S + "floor half left tile 15 10 flat 3\n", "is in the 3 x 3"),
        ("a first way with no height", S + "chute 1 round depth 4 way 8 29 way 12 29\n", "gives the lip's height"),
    ]


# SPEC.md 130.28.6's JOIN rule: SHAPE's `bank` chute alone - a plate-level corner at (20, 5), a corner RAISED
# a unit over the plate at (26, 5)
_FRAISE = """course RAISE "Raised"
width 128
origin 480
floor rect 4 3 31 24 flat 2
chute 2 bank depth 8 way 20 9 2 way 20 5 way 26 5 4 way 26 9 2
start 5 4
goal tile 30 23 flat 2
"""


def _field_join_checks(res):
    """SPEC.md 130.28.6, the JOIN rule: a raised FIELD corner over a lower plate draws no floor ink at its
    lip; a plate-level one still does (both by the facets _field_ops inks); red: every lip-level triangle
    joined, the rule before it, inks the raised one's"""
    c = compile_course(_FRAISE, "<RAISE>", _hack={"no_finish": True})
    tiles = c.tiles
    plate = _floor_h4(tiles[(5, 4)], 0, 0)          # the plate's height, quarter px

    def inked(joined):
        """lip-level triangles drawn in the floor's ink: (raised, at the plate's height)"""
        up = flat = 0
        for (wx, wy), t in tiles.items():
            if not isinstance(t, FieldTile):
                continue
            for op in _field_ops(tiles, t, wx, wy, 0, 0, None, joined):
                if op[1] == "facet" and op[4].tone in (WHT, CYN):
                    G = [(gx - 16 * wx, gy - 16 * wy) for gx, gy in op[4].G]
                    hs = [t.h[v][u] for u, v in G]
                    if min(hs) > plate:
                        up += 1
                    elif max(hs) == plate:
                        flat += 1
        return up, flat
    up, flat = inked(field_joined(tiles))
    rup, rflat = inked(field_joined(tiles, _seed_all=True))
    res.append(("2 the JOIN rule (130.28.6): a FIELD corner raised over a lower plate draws no floor ink at its "
                "lip (%d triangles) and a plate-level corner still does (%d); red: every lip-level triangle "
                "joined inks %d of the raised corner's" % (up, flat, rup),
                up == 0 and flat > 0 and rup > 0 and rflat >= flat))


def _auto_run(c, **kw):
    """the autopilot on course C's route until the goal or 8,000 steps -> (Physics, steps)"""
    p = Physics(c, play=True, **kw)
    n = 0
    while n < 8000 and not p.goal:
        p.step(p.auto())
        n += 1
    return p, n


def _field_auto_checks(res):
    """SPEC.md 130.28.10: the autopilot through shapes - SHAPE's route (all three chutes) and PITS's (both
    chutes, the dish, the deep pit crossed) reach the goal with no fall; a FIELD way is marked and at ground
    height in the RAM form, and expand(stored) writes it so; red: 130.6's plane law on the FIELD ways
    (_auto_plane) sticks in SHAPE's first chute"""
    for f in ("shapes.bbc", "pits.bbc"):
        path = os.path.join(COURSE_DIR, f)
        c = compile_course(open(path).read(), path)
        nf = sum(1 for t, _ln in c.src.ways if isinstance(c.tiles[t], FieldTile))
        mark = all(((x ^ c.x0) & 1) == isinstance(c.tiles[t], FieldTile)
                   for (x, _y), (t, _ln) in zip(Physics(c).route, c.src.ways))
        p, n = _auto_run(c)
        res.append(("7 %s (SPEC.md 130.28.10): the autopilot drives its route through its shapes (%d of %d ways "
                    "FIELD, each marked) to the goal in %d steps, %d falls" % (c.name, nf, len(c.src.ways), n,
                                                                             p.nfall),
                    nf > 0 and mark and p.goal and p.nfall == 0 and expand(c.stored, c.name) == bytes(c.cga)))
        if f == "shapes.bbc":
            q, m = _auto_run(c, _auto_plane=True)
            res.append(("7 %s red (130.28.10): 130.6's plane law on its FIELD ways stops at way %d of %d, %s"
                        % (c.name, q.wp, len(c.src.ways), "the goal" if q.goal else "no goal in %d steps" % m),
                        not q.goal))


def _chute_lay(text, fname):
    """a course's chutes alone, by the compiler's own steps (chute_cells, field_tile, the SEAM rule,
    build_fields) and nothing else of it -> (FIELD tiles, tables); refusals as compile_course's"""
    src = _parse_text(text, fname)
    tiles = {}
    for fd in src.fields:
        where = "%s:%d" % (fname, fd["line"])
        for cell, (piece, fn) in sorted(chute_cells(fd, where).items()):
            if cell in tiles:
                raise CourseError("%s: cell (%d, %d) is laid twice" % (where, cell[0], cell[1]))
            tiles[cell] = field_tile(cell, piece, fn, fd["line"], where)
    field_seams(tiles, fname)
    return tiles, build_fields(tiles)


def _chute3_cases():
    """SPEC.md 130.28.4's 3-wide leg-length rule: (what, the chute, a substring of the refusal or None for the
    shortest leg that is accepted)"""
    return [
        ("an end-to-corner leg of 1 cell", "way 8 6 2 way 8 7 way 12 7", "from end to corner takes at least 2"),
        ("...of 2 cells", "way 8 6 2 way 8 8 way 12 8", None),
        ("a corner-to-end leg of 1 cell", "way 8 6 2 way 8 10 way 9 10", "from corner to end takes at least 2"),
        ("...of 2 cells", "way 8 6 2 way 8 10 way 10 10", None),
        ("a corner-to-corner leg of 2 cells", "way 8 6 2 way 8 10 way 10 10 way 10 14",
         "from corner to corner takes at least 3"),
        ("...of 3 cells", "way 8 6 2 way 8 10 way 11 10 way 11 14", None),
        ("an end-to-end leg of 1 cell", "way 8 6 2 way 8 7", None),
    ]


def _chute3_checks(c3, res):
    """SPEC.md 130.28.4's 3-wide chute (on trial): the leg-length rule's refusals and the shortest legs it
    accepts; CHUT3's 10 tables over all eight corner orientations; the deepest depths every orientation
    takes (15 px `round`, 13 px `bank`) and the next px refused by the slope bound; red arms - a corner's
    radial centre at 16 (the 2-wide's) and a taper's run laid a row in - each broken by the SEAM rule"""
    head = ("course LEG3 \"Legs\"\nwidth 128\norigin 400\nfloor rect 4 4 20 20 flat 2\nstart 5 18\n"
            "goal tile 18 18 flat 2\n")
    for what, ways, want in _chute3_cases():
        try:
            _chute_lay(head + "chute 3 round depth 8 %s\n" % ways, "<%s>" % what)
            ok, msg = want is None, "laid"
        except CourseError as e:
            ok, msg = want is not None and want in str(e), str(e)
        res.append(("2 %s (130.28.4, 3-wide): %s%s" % ("refused" if want else "accepted", what,
                                                       "" if ok else " -- got: " + msg), ok))
    pieces = {}
    for t in c3.tiles.values():
        if isinstance(t, FieldTile):
            pieces[t.piece] = pieces.get(t.piece, 0) + 1
    res.append(("2 CHUT3 (130.28.4, 3-wide): two `round` 8 px chutes, all eight corner orientations (%s cells), "
                "share 10 tables (%d)" % (", ".join("%s %d" % kv for kv in sorted(pieces.items())), len(c3.ftabs)),
                len(c3.ftabs) == 10 and pieces.get("corner") == 72))
    ring = []
    for prof, deep in (("round", 15), ("bank", 13)):
        got = []
        for dep in (deep, deep + 1):
            try:
                _chute_lay(_FCHUTE3.replace("round depth 8", "%s depth %d" % (prof, dep)), "<CHUT3 %d>" % dep)
                got.append(True)
            except CourseError as e:
                got.append(False if "the bound |sx| + |sy|" in str(e) else str(e))
        ring.append((prof, deep, got))
    res.append(("2 CHUT3's deepest (130.28.4): every corner orientation takes %s; one more px is refused by the "
                "slope bound" % ", ".join("%s %d px" % (p_, d_) for p_, d_, _g in ring),
                all(g == [True, False] for _p, _d, g in ring)))
    global _C3RED
    for arm, what in (("r0", "a corner's radial centre at 16, the 2-wide's"), ("taper", "a taper's run laid a "
                                                                                       "row in")):
        was, _C3RED = _C3RED, arm
        try:
            _chute_lay(_FCHUTE3, "<CHUT3 red %s>" % arm)
            fired, msg = False, "laid"
        except CourseError as e:
            fired, msg = "SEAM rule" in str(e), str(e)
        finally:
            _C3RED = was
        res.append(("2 CHUT3 red (130.28.4, 3-wide): %s is refused by the SEAM rule%s" % (
            what, "" if fired else " -- got: " + msg), fired))


def _field_checks(res):
    """SPEC.md 130.28's `bonanzacourse` items (stories C1 - C2): the refusals; the tables against every FIELD
    cell's world heights through the grid (and a symmetry flipped, red); the slope bound and the SEAM rule (a
    seam broken, red); the reader's refusals; the stored form; the model's scripted runs and their red arms"""
    for what, text, want in _field_cases():
        try:
            compile_course(text, fname="<%s>" % what, _hack={"no_finish": True})
            fired, msg = False, "compiled"
        except CourseError as e:
            fired, msg = want in str(e), str(e)
        res.append(("2 refused (130.28.3): %s%s" % (what, "" if fired else " -- got: " + msg), fired))
    cs = {k: compile_course(t, "<%s>" % k, _hack={"no_finish": True})
          for k, t in (("CHUTE", _FCHUTE), ("PIT", _FPIT), ("BRIDGE", _FBRIDGE), ("MANY", _FMANY),
                       ("CHUT3", _FCHUTE3))}
    for k, c in cs.items():
        g = Grid(c.cga)
        ft = {cell: t for cell, t in c.tiles.items() if isinstance(t, FieldTile)}
        same = all(g.cell(*cell)[6] == t.h for cell, t in ft.items())
        flip = sum(1 for cell, t in ft.items() if g.fworld(t.z0, fsl(t.shape, t.sym ^ FSYM_MU)) != t.h)
        smax = max(abs(a) + abs(b) for t in ft.values() for v in range(16) for u in range(16)
                   for a, b in (fslopes(t.h, u, v),))
        pieces = {}
        for t in ft.values():
            pieces[t.piece] = pieces.get(t.piece, 0) + 1
        print("    %s (SPEC.md 130.28): %d FIELD cells (%s), %d tables (F %d bytes), part %d, %d blocks, %d records"
              % (k, len(ft), ", ".join("%s %d" % kv for kv in sorted(pieces.items())), len(c.ftabs),
                 FTAB * len(c.ftabs), len(c.cga), len(c.blocks), len(c.records)))
        res.append(("2 %s: every FIELD cell's heights read back through the grid (its table, its symmetry); red: "
                    "MU flipped changes %d of %d" % (k, flip, len(ft)), same and flip > 0))
        res.append(("2 %s: the slope bound holds, |sx| + |sy| at most %d (bound %d)" % (k, smax, FSLOPE_MAX),
                    smax <= FSLOPE_MAX))
        res.append(("10 %s: expand(stored) == RAM with section F" % k, expand(c.stored, k) == bytes(c.cga)))
    # SPEC.md 130.28.2: 32 tables - MANY's 17th (shape 16) is named by cells whose +1 has bit 7, read back
    # through the grid above; red: the fifth bit dropped reads table 0 for them
    c = cs["MANY"]
    g = Grid(c.cga)
    hi = [(cell, t) for cell, t in sorted(c.tiles.items()) if isinstance(t, FieldTile) and t.shape >= 16]
    drop = sum(1 for cell, t in hi if g.fworld(t.z0, fsl(t.shape, t.sym) & 0x7F) != t.h)
    res.append(("2 MANY: %d tables, the %d cells of shape 16 - 31 carry the +1's bit 7 and read back their own "
                "tables (SPEC.md 130.28.2: up to %d); red: the fifth bit dropped misreads %d of them" % (
                    len(c.ftabs), len(hi), FSHAPE_MAX, drop),
                len(c.ftabs) > 16 and hi and all(c.cells[cl][1] & 0x80 for cl, _t in hi) and drop == len(hi)))
    _chute3_checks(cs["CHUT3"], res)
    _field_occ_checks(cs, res)
    _field_join_checks(res)
    _field_auto_checks(res)
    # the SEAM rule's red arm, and the reader's
    c = cs["CHUTE"]
    tl = dict(c.tiles)
    cell = next(cl for cl, t in sorted(tl.items()) if isinstance(t, FieldTile) and isinstance(
        tl.get((cl[0] + 1, cl[1])), FieldTile))
    bad = FieldTile([r[:] for r in tl[cell].h], tl[cell].line, tl[cell].piece, tl[cell].lip)
    bad.h[8][16] += 1
    tl[cell] = bad
    try:
        field_seams(tl, "<seam>")
        fired = False
    except CourseError as e:
        fired = "SEAM rule" in str(e)
    res.append(("2 red: a FIELD cell one quarter px off its neighbour at a shared edge is refused (the SEAM rule)",
                fired))
    p = bytearray(c.cga)
    foff = c.part["grid"]["foff"]
    p[foff + 8] ^= 0x40                             # a table byte made a cliff
    try:
        read_part(bytes(restamp(p)))
        fired, msg = False, "read"
    except CourseError as e:
        fired, msg = "F" in str(e), str(e)
    res.append(("10 red: read_part refuses a table with a cliff in it (the slope bound or the SEAM rule)%s" % (
        "" if fired else " -- got: " + msg), fired))
    # the model (story C2): the scripted runs, and the red arms that break them
    for what, k, mat, at, keys, ok, arm in _field_runs():
        p_ = Physics(cs[k], play=True, mat=mat)
        p_.tsec = 0
        _field_poke(p_, *at)
        for kk in keys(p_) if callable(keys) else keys:
            p_.step(kk)
        good = ok(p_)
        res.append(("7 FIELD run (130.28.5): %s" % what, good))
        if arm:
            q = Physics(cs[k], play=True, mat=mat, **{arm: True})
            q.tsec = 0
            _field_poke(q, *at)
            for kk in keys(q) if callable(keys) else keys:
                q.step(kk)
            res.append(("7 FIELD red `%s` breaks it: %s" % (arm.strip("_"), what), not ok(q)))


def _field_real_poses(c, rc, step=7, lift=0):
    """SPEC.md 130.28.6: a SAMPLE of a FIELD reach cell's real poses for --selfcheck - the centre at every
    integer point with (u + 3 v) % step == 0, each corner of its fraction, at its floor (grounded and in the
    air) and one and two px above it, with and without a height fraction -> [(px, py, s, z, air)].  lift:
    LIFT px higher, airborne (the SHOW rule's poses: lift BZ_CLIMB)"""
    t = c.tiles[(rc.wx, rc.wy)]
    out = []
    for v in range(16):
        for u in range(16):
            if (u + 3 * v) % step:
                continue
            for fu, fv in ((0, 0), (255, 255), (255, 0), (0, 255)):
                gx, gy = ((16 * rc.wx + u) << 8) + fu, ((16 * rc.wy + v) << 8) + fv
                zf = field_zlo(c.tiles, rc, gx, gy) + lift
                for z in range(zf, min(zf + 2, rc.zhi) + 1):
                    for f in (0, 200):
                        gz = (z << 8) + f
                        px = ((gx - gy) >> 8) + c.x0 - 8
                        py = ((((gx + gy) >> 1) - gz) >> 8) + c.y0 - 13
                        for air in ((0, 1) if z == zf and f == 0 and not lift else (1,)):
                            out.append((px, py, rc.s, z, air))
    return out


def _poses_hidden(c, poses, show=0, cells=None):
    """-> (poses where the records leave MORE than `show` lit ball pixels the per-pixel rule hides unlaid,
    poses where the rule hides any, poses it leaves 1 - `show` unlaid): records' pixels by a pixel -> record
    map, the rule by sbuf and tbuf (no record's top raised: a pixel no record holds is exactly what a
    too-thin cut leaves out).  show: SPEC.md 130.28.6's SHOW rule's bound (0: every hidden pixel laid)"""
    rec = {}
    for r in c.records:
        for p_ in r["pix"]:
            rec[p_] = r
    bad = hid = shown = 0
    for i_, (px, py, sb, z, air) in enumerate(poses):
        m = 0 if air else CLIMB
        any_ = False
        n = 0
        mod = amodel_pix(c, cells[i_], z, air, px, py) if cells else set()
        for (x, y) in ball_pixels(px, py):
            rule = c.sbuf[y][x] > sb and c.tbuf[y][x] > z + m
            r = rec.get((x, y))
            laid = (r is not None and r["s"] > sb and r["top"] > z + m) or (x, y) in mod
            any_ |= rule
            if rule and not laid:
                n += 1
        bad += n > show
        shown += 0 < n <= show
        hid += any_
    return bad, hid, shown


def _field_occ_checks(cs, res):
    """SPEC.md 130.28.6's real-pose cut: (1) the records against the whole-cell cut (fewer); (2) a sample of
    every FIELD cell's real poses, and the pit's hole at every height a ball falls through it, laid by the
    records wherever the per-pixel rule hides a lit ball pixel without the SHOW rule (the default) - red arm:
    the cut's floor 3 px too high misses some - and with it (the TOGGLE, compiled on through _hack fshow),
    at the airborne poses from BZ_CLIMB over the floor, all but at most FSHOW a pose - red arm: the rule from
    the floor, unbounded, leaves poses over FSHOW; (3) the model never puts a ball's centre in a FIELD cell
    under its floor there (what the cut stands on) - red arm: that floor read 1 px higher is broken by a
    grounded ball; (4) without the SHOW rule every GROUNDED step of the model on a FIELD cell where a record
    hides a lit ball pixel is on an OCCG cell (130.11.4.3, the guest's gate) - red arm: OCCG over FLOOR,
    GOAL and split floors alone (the gap play found, 2026-11-17) leaves such steps ungated - and with the
    SHOW rule no FIELD cell carries OCCG"""
    cbs, cgs = {}, {}
    for k, text in (("CHUTE", _FCHUTE), ("PIT", _FPIT)):
        c = cs[k]
        cn = c                                          # (the default: no SHOW rule)
        cb = cbs[k] = compile_course(text, "<%s, SHOW>" % k, _hack={"no_finish": True, "fshow": FSHOW})
        cgs[k] = compile_course(text, "<%s, no FIELD OCCG>" % k, _hack={"no_finish": True, "noccgf": True})
        cw = compile_course(text, "<%s>" % k, _hack={"no_finish": True, "focc": 16})
        fr = [rc for rc in c.reach if rc.kind == KIND_FIELD]
        poses = [q for rc in fr for q in _field_real_poses(c, rc)]
        hole = [rc for rc in c.reach if rc.kind == KIND_VOID and any(
            isinstance(c.tiles.get((rc.wx + dx, rc.wy + dy)), FieldTile) for dx in (-1, 0, 1) for dy in (-1, 0, 1))
            and all(isinstance(c.tiles.get((rc.wx + dx, rc.wy + dy)), FieldTile) or (dx, dy) == (0, 0)
                    or c.tiles.get((rc.wx + dx, rc.wy + dy)) is None for dx in (-1, 0, 1) for dy in (-1, 0, 1))]
        hp, hcell = [], []
        for rc in hole:
            for u, v in ((8, 8), (2, 2), (14, 14), (2, 14), (14, 2)):
                gx, gy = ((16 * rc.wx + u) << 8), ((16 * rc.wy + v) << 8)
                for z in range(rc.zlo, rc.zhi + 1, 2):
                    hp.append((((gx - gy) >> 8) + c.x0 - 8, (((gx + gy) >> 1) >> 8) - z + c.y0 - 13, rc.s, z, 1))
                    hcell.append((rc.wx, rc.wy))
        # the SHOW rule's poses: airborne from BZ_CLIMB over the floor (lower, the ball is drawn whole)
        hi = [q for rc in fr for q in _field_real_poses(c, rc, lift=CLIMB)]
        bad, hid, shown = _poses_hidden(cb, hi, FSHOW)
        hbad, hhid, _hs = _poses_hidden(cb, hp, FSHOW, hcell)
        nbad, nhid, _ns = _poses_hidden(cn, poses)
        nhbad, _nhh, _nhs = _poses_hidden(cn, hp, cells=hcell)
        cr = compile_course(text, "<%s, floor + 3>" % k, _hack={"no_finish": True, "fraise": 3, "fshow": None})
        rbad, _rh, _rs = _poses_hidden(cr, poses)
        ca = compile_course(text, "<%s, SHOW from the floor>" % k, _hack={"no_finish": True, "fshow": 1 << 20,
                                                                           "flift": 0})
        abad, _ah, _as = _poses_hidden(ca, poses, FSHOW)
        print("    %s (SPEC.md 130.28.6): %d records cut at the FIELD cells' real poses with the SHOW rule (%d px), %d "
              "without it, %d at their whole cells (masks %d, %d, %d; blocks %d); %d sampled real poses on the "
              "surface, %d of them with lit pixels the rule hides; %d airborne from BZ_CLIMB up, %d hidden, %d "
              "showing 1 - %d px; the hole: %d poses, %d hidden" % (
                  k, len(cb.records), FSHOW, len(cn.records), len(cw.records), len(cb.masks), len(cn.masks),
                  len(cw.masks), len(c.blocks), len(poses), nhid, len(hi), hid, shown, FSHOW, len(hp), hhid))
        res.append(("5 %s: the FIELD cells' records are cut at their REAL poses (130.28.6): %d records against %d "
                    "cut at the whole cell, and %d with the SHOW rule (the toggle)" % (
                        k, len(c.records), len(cw.records), len(cb.records)),
                    len(c.records) < len(cw.records) and c.cga != cw.cga and len(cb.records) < len(cn.records)))
        res.append(("5 %s: without the SHOW rule, at %d sampled real poses on FIELD cells (%d hidden in part) and %d in "
                    "%s, every lit ball pixel the per-pixel rule hides is laid by a record (%d, %d differ); red: the "
                    "cut's floor 3 px high leaves %d poses short" % (
                        k, len(poses), nhid, len(hp), "the pit's hole" if hole else "no hole", nbad, nhbad, rbad),
                    nbad == 0 and nhbad == 0 and nhid > 0 and rbad > 0 and (k != "PIT" or hhid > 0)))
        res.append(("5 %s: the SHOW rule (130.28.6): at %d sampled airborne poses BZ_CLIMB or more over a FIELD floor "
                    "(%d hidden in part) and the %d in %s, every lit ball pixel the per-pixel rule hides is laid but "
                    "at most %d a pose (%d, %d over; %d poses show some); red: the rule taken from the floor, "
                    "unbounded, leaves %d of the surface's poses over %d" % (
                        k, len(hi), hid, len(hp), "the pit's hole" if hole else "no hole", FSHOW, bad, hbad, shown,
                        abad, FSHOW),
                    bad == 0 and hbad == 0 and abad > 0))
    # (3) the model: the centre in a FIELD cell is never under the floor at its integer point - the scripted
    # runs, and 60 seeded runs from random poses on and beside FIELD cells, random keys
    worst = {0: 0, 1: 0}
    n = 0
    fr = {k: {(r.wx, r.wy): r for r in c.reach if r.kind == KIND_FIELD} for k, c in cs.items()}
    import random
    rnd = random.Random(1117)
    runs = [(k, mat, at, keys) for _w, k, mat, at, keys, _ok, _arm in _field_runs()]
    for i in range(60):
        k = ("CHUTE", "PIT", "MANY")[i % 3]
        wx, wy = rnd.choice(sorted(fr[k]))
        v = VMAXG
        ks = []
        while len(ks) < 120:
            ks += [rnd.choice((0, K_U, K_D, K_L, K_R, K_U | K_L, K_D | K_R, K_HOP))] * rnd.randrange(1, 20)
        runs.append((k, rnd.choice((MAT_RUBBER, MAT_STEEL)), (wx, wy, rnd.randrange(4096), rnd.randrange(4096),
                                                              rnd.randrange(-v, v + 1), rnd.randrange(-v, v + 1)),
                     ks[:120]))
    gnd = {"steps": 0, "hid": 0, "ungated": 0, "red": 0, "cells": set()}
    for k, mat, at, keys in runs:
        p_ = Physics(cs[k], play=True, mat=mat)
        p_.tsec = 0
        _field_poke(p_, *at)
        for kk in keys(p_) if callable(keys) else keys:
            p_.step(kk)
            rc_ = fr[k].get((p_.gx >> 12, p_.gy >> 12))
            if rc_ is None or p_.hid or p_.tube:
                continue
            n += 1
            for rz in (0, 1):
                if (p_.gz >> 8) < field_zlo(cs[k].tiles, rc_, p_.gx, p_.gy, rz):
                    worst[rz] += 1
            if k in cgs and not p_.air:             # (4): a grounded ball on a FIELD cell, the guest's gate
                gnd["steps"] += 1
                if composite(cs[k], p_.px, p_.py, p_.sb, p_.zb, 0) != \
                        composite(cs[k], p_.px, p_.py, p_.sb, p_.zb, 0, "none"):
                    gnd["hid"] += 1
                    gnd["cells"].add((k, rc_.wx, rc_.wy))
                    gnd["ungated"] += not cs[k].cells[(rc_.wx, rc_.wy)][3] & FL_OCCG
                    gnd["red"] += not cgs[k].cells[(rc_.wx, rc_.wy)][3] & FL_OCCG
    res.append(("7 FIELD runs (130.28.5.1, the cut's floor): over %d steps whose centre is a FIELD cell the ball "
                "is never under the floor at its integer point (%d under); red: that floor 1 px high, %d steps "
                "under it" % (n, worst[0], worst[1]), n > 0 and worst[0] == 0 and worst[1] > 0))
    nocc = {k: sum(1 for r in c.reach if r.kind == KIND_FIELD and c.cells[(r.wx, r.wy)][3] & FL_OCCG)
            for k, c in cbs.items()}
    # the toggle's two switches (130.28.6): a course's `fshow`, and the run's --fshow (FSHOW_ALL), each compile
    # exactly the SHOW arm's part; without them the default's
    global FSHOW_ALL
    cst = compile_course(_FCHUTE + "\nfshow\n", "<CHUTE, fshow>", _hack={"no_finish": True})
    was, FSHOW_ALL = FSHOW_ALL, True
    try:
        cal = compile_course(_FCHUTE, "<CHUTE>", _hack={"no_finish": True})
    finally:
        FSHOW_ALL = was
    try:
        compile_course(_FCHUTE + "\nfshow\nfshow\n", "<CHUTE, fshow twice>", _hack={"no_finish": True})
        twice = False
    except CourseError as e:
        twice = "fshow takes nothing" in str(e)
    res.append(("2 the SHOW rule's toggle (130.28.6): a course's `fshow` and the run's --fshow each give the SHOW "
                "arm's part (%s, %s), off the default's (%d records against %d); `fshow` twice is refused" % (
                    cst.cga == cbs["CHUTE"].cga, cal.cga == cbs["CHUTE"].cga, len(cst.records),
                    len(cs["CHUTE"].records)),
                cst.cga == cbs["CHUTE"].cga and cal.cga == cbs["CHUTE"].cga and cs["CHUTE"].cga != cst.cga
                and cst.fshow == FSHOW and cs["CHUTE"].fshow is None and twice))
    occg = {k: (sum(1 for r in cs[k].reach if r.kind == KIND_FIELD and cs[k].cells[(r.wx, r.wy)][3] & FL_OCCG),
                sum(1 for r in cs[k].reach if r.kind == KIND_FIELD)) for k in cbs}
    print("    FIELD OCCG (130.11.4.3, 130.28.6): CHUTE %d of %d FIELD cells, PIT %d of %d; %d grounded steps on FIELD "
          "cells, %d with a lit pixel a record hides (on %d cells)" % (
              occg["CHUTE"] + occg["PIT"] + (gnd["steps"], gnd["hid"], len(gnd["cells"]))))
    res.append(("7 FIELD OCCG (130.11.4.3, 130.28.6): at %d grounded steps on FIELD cells, the %d where a record "
                "hides a lit ball pixel are all on OCCG cells (%d not), so the guest runs the pass for them; red: "
                "OCCG over FLOOR, GOAL and split floors alone leaves %d ungated; with the SHOW rule (the toggle) "
                "no FIELD cell has OCCG (%s)" % (gnd["steps"], gnd["hid"], gnd["ungated"], gnd["red"],
                                                ", ".join("%s %d" % kv for kv in sorted(nocc.items()))),
                gnd["hid"] > 0 and gnd["ungated"] == 0 and gnd["red"] > 0 and not any(nocc.values())))


def _field_poke(p, wx, wy, pu, pv, gvx, gvy):
    p.poke(wx, wy, gvx, gvy)
    p.gx, p.gy = (16 * wx << 8) + pu, (16 * wy << 8) + pv
    p.gz = Physics.h4(p.prec(wx, wy), pu >> 8, pv >> 8) << 6
    p._fill(wx, wy)
    p._ps()
    p._derive(True)


def _field_steer(turn_x, before, after, n):
    def keys(p):
        for _ in range(n):
            yield after if (p.gx >> 8) >= turn_x else before
    return keys


def _field_steer_y(turn_y, before, after, n):
    def keys(p):
        for _ in range(n):
            yield after if (p.gy >> 8) >= turn_y else before
    return keys


def _field_runs():
    """SPEC.md 130.28.5's scripted runs (story C2.3): (what, course, material, poke, keys, the outcome, a red
    arm that must break it or None)"""
    rub, stl = MAT_RUBBER, MAT_STEEL
    U, D, L, Rt = K_U, K_D, K_L, K_R

    def noev(*names):
        return lambda p: not any(e[0] in names for e in p.events)
    return [
        ("a 2-wide corner carried round at 250, the turn held", "CHUTE", rub, (17, 12, 8 << 8, 0, 250, 0),
         _field_steer(288, 0, D | L, 160), lambda p: p.gy >> 8 > 230 and 304 <= p.gx >> 8 < 336, None),
        ("...and at 384, steel", "CHUTE", stl, (17, 12, 8 << 8, 0, 384, 0), _field_steer(288, 0, D | L, 160),
         lambda p: p.gy >> 8 > 230, None),
        ("a 1-wide corner left over its lip at 384, the arrows on", "CHUTE", rub, (14, 26, 0, 8 << 8, 384, 0),
         [Rt | D] * 120, lambda p: p.cell(p.gx >> 12, p.gy >> 12)[3] != KIND_FIELD, None),
        ("a ball rests at a chute's bottom, no dither", "CHUTE", rub, (12, 11, 8 << 8, 3 << 8, 0, 160), [0] * 400,
         lambda p: p.gvx == 0 and p.gvy == 0, None),
        ("the pit ridden round and out over the far lip at speed", "PIT", rub, (12, 21, 8 << 8, 8 << 8, 384, 0),
         [Rt | D] * 140, lambda p: p.nfall == 0 and p.gx >> 8 > 300, None),
        ("the pit fallen through when slow", "PIT", rub, (12, 19, 8 << 8, 15 << 8, 250, 0), [0] * 140,
         lambda p: p.nfall == 1, None),
        ("the lift: a floor above the lip is a wall", "CHUTE", rub, (13, 11, 8 << 8, 6 << 8, 0, -300),
         [U | Rt] * 60, lambda p: any(e[0] == "wall" for e in p.events), None),
        ("the lift: a floor at the lip's height is a lip", "CHUTE", rub, (17, 11, 8 << 8, 12 << 8, 0, -330),
         [U | Rt] * 40, lambda p: p.gy >> 8 < 176, "_nolift"),
        ("field to field: across the pit's bank, no wall", "PIT", rub, (14, 18, 1216, 1502, -137, -151), [Rt] * 20,
         noev("wall", "corner", "undo"), "_ffblock"),
        ("a chute on a bridge left over its lip into the void", "BRIDGE", rub, (16, 15, 8 << 8, 8 << 8, 0, -384),
         [U | Rt] * 80, lambda p: p.nfall == 1, None),
        ("a 3-wide corner carried round at 250, the turn held", "CHUT3", rub, (8, 12, 8 << 8, 8 << 8, 0, 250),
         _field_steer_y(240, 0, Rt | D, 160),
         lambda p: p.nfall == 0 and p.gx >> 8 >= 176 and 240 <= p.gy >> 8 < 288 and p.gvx > 0, None),
        ("...and at 384, steel", "CHUT3", stl, (8, 12, 8 << 8, 8 << 8, 0, 384), _field_steer_y(240, 0, Rt | D, 160),
         lambda p: p.nfall == 0 and p.gx >> 8 >= 176 and 240 <= p.gy >> 8 < 288 and p.gvx > 0, None),
        ("a ball rests at a 3-wide chute's bottom, no dither, from a cross speed of 300", "CHUT3", rub,
         (8, 11, 3 << 8, 8 << 8, 300, 0), [0] * 400,
         lambda p: p.gvx == 0 and p.gvy == 0 and abs((p.gx >> 8) - 136) <= 7, None),
    ]


def _split_checks(res, t):
    """SPEC.md 130.24.11's `bonanzacourse` items on THE SPLIT COURSE (stories D1.1 - D1.4): the refusals, the
    normalisation, items 3 - 6 on halves, the reader's refusals of a bad pair, the stored form with D, the
    down half's key, and the shipped courses untouched"""
    for what, text, want in _split_cases():
        try:
            compile_course(text, fname="<%s>" % what, _hack={"no_finish": True})
            fired, msg = False, "compiled"
        except CourseError as e:
            fired, msg = want in str(e), str(e)
        res.append(("2 refused (130.24.4): %s%s" % (what, "" if fired else " -- got: " + msg), fired))
    c = compile_course(_SPLIT, "<SPLIT>", _hack={"no_finish": True})
    nsp = sum(1 for v in c.tiles.values() if isinstance(v, Split))
    nq = sum(1 for v in c.tiles.values() if isinstance(v, Split) and v.diag == KIND_Q)
    dbytes = sum(4 * len(v.halves) for v in c.tiles.values() if isinstance(v, Split))
    kinds = {}
    for v in c.tiles.values():
        if isinstance(v, Split):
            key = "+".join("VOID" if h is None else {KIND_FLOOR: "floor", KIND_WALL: "wall", KIND_GOAL: "goal"}[
                h.kind] for h in v.halves)
            kinds[key] = kinds.get(key, 0) + 1
    print("    SPLIT (SPEC.md 130.24.11): %d split cells, %d of them quartered (%s), %d whole; part %d bytes (D %d), "
          "identity %04Xh" % (nsp, nq, ", ".join("%s %d" % kv for kv in sorted(kinds.items())), len(c.tiles) - nsp,
                               len(c.cga), dbytes, c.ident))
    res.append(("2 the SPLIT course compiles: %d split cells of both diagonals and %d QUARTERED (R4: a box's "
                "corners), GF_SPLIT set, section D %d bytes (8 a halved cell, 16 a quartered one) after C, PLAIN"
                % (nsp - nq, nq, dbytes),
                nsp == len(c.pairs) > 0 and c.gflags & GF_SPLIT and {v.diag for v in c.tiles.values()
                                                                    if isinstance(v, Split)} == set(SPLIT_KINDS)
                and any(e["tag"] == "D" and e["form"] == F_PLAIN and e["len"] == dbytes for e in c.part["dir"])))
    # the normalisation: a half equal to its partner is stored WHOLE - the same part, byte for byte
    cn = compile_course(_SPLIT + "floor half left tile 12 12 flat 0\nfloor half up tile 9 9 flat 0.5\n"
                        "goal half up tile 9 9 flat 0.5\ngoal half down tile 9 9 flat 0.5\n",
                        "<SPLIT, equal halves>", _hack={"no_finish": True})
    res.append(("2 two equal halves are stored WHOLE (cell (12, 12) laid again as its left half; (9, 9)'s up half a "
                "floor, then a goal again, then its down half a goal again): the part is the SPLIT course's byte "
                "for byte", not isinstance(cn.tiles[(12, 12)], Split) and not isinstance(cn.tiles[(9, 9)], Split)
                and cn.cga == c.cga))
    _course_items(c, -1, res, t)
    # `box ... chamfer [N]` (SPEC.md 130.24.4): no clause, today's square corners; N cuts each corner along a
    # line of cell edges - chamfer 1 on a box whose corners' a and s differ in parity drops exactly its four
    # corner QUARTERS (panel 3 of diag-q3), on one whose corners do not the two HALVES at each corner; no piece of
    # a chamfered box is a quarter, and what is dropped is exactly the four corner triangles' cells
    chok, chwhy = True, []
    for (a0, a1, s0, s1) in ((-3, 3, 22, 30), (-4, 4, 22, 30), (-5, 5, 26, 36), (8, 18, 26, 38)):
        sq, sh = box_cells(a0, a1, s0, s1, "<chamfer>")
        for n in (1, 2):
            cc, ch = box_chamfer(a0, a1, s0, s1, n, sq, sh, "<chamfer>")
            gone = sq - cc
            want = {x for x in sq if x[0] < (a0 + s0) // 2 + n or x[1] < (s0 - a1) // 2 + n
                    or x[1] >= -((a0 - s1) // 2) - n or x[0] >= -((-a1 - s1) // 2) - n}
            if gone != want or any(v[0] == KIND_Q for v in ch.values()):
                chok = False
                chwhy.append("box %d %d %d %d chamfer %d" % (a0, a1, s0, s1, n))
            if n == 1:
                kinds = sorted({sh[x][0] for x in gone if x in sh})
                odd = (a0 + s0) & 1
                if len(gone) != (4 if odd else 8) or kinds != ([KIND_Q] if odd else [KIND_TB, KIND_LR]):
                    chok = False
                    chwhy.append("box %d %d %d %d chamfer 1 drops %d (%s)" % (a0, a1, s0, s1, len(gone), kinds))
    t0 = compile_course(_split_mockups()["chamfer0"], "<chamfer0>", _hack={"no_finish": True})
    plain = 'course CHAM0 "Square corners"\nwidth 128\n' + _CHAMFER.replace("%s", "")
    t1 = compile_course(plain, "<chamfer0, plain>", _hack={"no_finish": True})
    t2 = compile_course(_split_mockups()["chamfer1"], "<chamfer1>", _hack={"no_finish": True})
    res.append(("2 `box ... chamfer [N]` (SPEC.md 130.24.4): no clause is today's square box (the same part); "
                "chamfer 1 drops exactly the four corner quarters (corners of mixed parity) or the corner halves (same "
                "parity, two a corner); chamfer 1 and 2 drop exactly the cells beyond four cuts along cell edges and leave no "
                "quarter; the chamfered scene compiles (%d cells against %d)%s" % (
                    len(t2.tiles), len(t0.tiles), "" if chok else " -- " + "; ".join(chwhy)),
                chok and t0.cga == t1.cga and len(t2.tiles) < len(t0.tiles)
                and not any(isinstance(v, Split) and v.diag == KIND_Q for v in t2.tiles.values())))
    # the reader: every bad pair refused (D1.3)
    g = c.part["grid"]
    co, po, dl = g["celloff"], g["pairoff"], len(g["pairs"])
    idx = [i for i in range(0, po - co, 4) if c.cga[co + i + 2] & 15 in SPLIT_KINDS]
    i0, i1 = idx[0], idx[1]

    def _vv(b):
        o = struct.unpack_from("<H", b, co + i0)[0]
        b[o:o + PAIR] = bytes([0x80, 0, 0, 0, 0x81, 0, 0, 0])
    bads = (("a dangling offset", lambda b: struct.pack_into("<H", b, co + i0, po + dl), "inside D"),
            ("records named twice", lambda b: struct.pack_into("<H", b, co + i1, struct.unpack_from("<H", b, co + i0)[0]),
             "are cell"),
            ("a split VOID-VOID", _vv, "all VOID"),
            ("a SAFE split cell", lambda b: b.__setitem__(co + i0 + 3, b[co + i0 + 3] | FL_SAFE), "flags"),
            ("a kind 7 (FIELD) cell with no section F (SPEC.md 130.28.2)",
             lambda b: b.__setitem__(co + i0 + 2, (b[co + i0 + 2] & 0xF0) | 7), "FIELD cell's shape"),
            ("GF_SPLIT clear", lambda b: b.__setitem__(c.part["gridoff"] + 28, b[c.part["gridoff"] + 28] & ~GF_SPLIT),
             "GF_SPLIT"))
    for what, f_, want in bads:
        b = bytearray(c.cga)
        f_(b)
        restamp(b)
        try:
            read_part(bytes(b))
            fired, msg = False, "accepted"
        except CourseError as e:
            fired, msg = want in str(e), str(e)
        res.append(("10 SPLIT: read_part refuses %s%s" % (what, "" if fired else " -- got: " + msg), fired))
    # the stored form (item 10): CELLS reads the halves through D, PLAIN and in place before C expands
    sim = expand(c.stored, "<SPLIT>", sim=True) == c.cga
    exc = cells_exceptions(c.cga)
    try:
        wrong = stored_form(c.model, 4, c.cga, "<SPLIT>", _hack={"no_halves": True})
        red = expand(wrong, "<SPLIT>") != c.cga
    except (CourseError, struct.error, IndexError):
        red = True
    res.append(("10 SPLIT: the stored form expands IN PLACE to its RAM form with section D (the in-place "
                "simulation: every byte read before it is written), and the CELLS rule BY HALVES reproduces every "
                "cell (%d exceptions); negative control: the rule without halves (a split cell's offset read as a "
                "z0) gives another grid" % len(exc), sim and not exc and red))
    # the down half's key (130.24.6.3): a ball in the up half behind a raised down half is laid under it
    s0 = 13 + 9
    gx, gy = (16 * 13 + 6) << 8, (16 * 9 + 3) << 8
    px = ((gx - gy) >> 8) + c.x0 - 8
    py = (((gx + gy) >> 1) >> 8) + c.y0 - 13

    def hid(cc):
        return sum(len(r["pix"] & set(ball_pixels(px, py))) for r in laid_at(cc, px, py, s0, 0, 0)
                   if r["s"] == s0 + 1)
    c0 = compile_course(_SPLIT, "<SPLIT, down half keyed s>", _hack={"no_finish": True, "down_s0": True})
    keyed = {c.sbuf[y][x] for y in range(c.lines) for x in range(c.width) if c.sbuf[y][x] == s0 + 1}
    res.append(("5 SPLIT: an LR split's raised DOWN half is keyed s + 1 (%d ball pixels hidden for a ball on the up "
                "half behind it); negative control: keyed s, it hides %d" % (hid(c), hid(c0)),
                bool(keyed) and hid(c) > 0 and hid(c0) == 0))
    # D2's verify: `surface` on a box's piece of a WHOLE cell reaches that piece alone (it once reached the N
    # quarter too: _put kept the whole tile itself as N), and a quartered cell's S or E top draws no outline
    # along its inner line when the quarter behind it is the same record (a box corner's 16 px stub)
    cw_ = compile_course('course SURF "Surf"\nwidth 128\nfloor rect 5 5 18 18 flat 0\n'
                         'wall tile 9 10 flat 1.5\nwall tile 10 10 flat 1.5\nwall tile 9 11 flat 1.5\n'
                         'wall tile 10 11 flat 1.5\nsurface bounce box -2 0 20 22\nstart 7 14\n',
                         "<SURF>", _hack={"no_finish": True})
    got = {k_: (v.diag, tuple(h.surf for h in v.halves)) for k_, v in cw_.tiles.items() if isinstance(v, Split)}
    want = {(9, 10): (KIND_LR, (SURF_NORMAL, SURF_BOUNCE)), (10, 10): (KIND_TB, (SURF_BOUNCE, SURF_NORMAL)),
            (9, 11): (KIND_TB, (SURF_NORMAL, SURF_BOUNCE)), (10, 11): (KIND_LR, (SURF_BOUNCE, SURF_NORMAL))}
    res.append(("2 `surface bounce box` on whole wall cells reaches each cell's piece inside the box alone - two "
                "TB and two LR halves, none quartered (%s)" % sorted(got.items()), got == want))
    cq_ = compile_course('course QS "Qs"\nwidth 128\nfloor rect 8 8 12 12 flat 0\nfloor quarter s tile 10 10 flat 1\n'
                         'start 9 9\n', "<QS>", _hack={"no_finish": True})
    eq = cq_.tiles[(10, 10)].halves[Q_E]
    ops_ = draw_ops(cq_.tiles, cq_.x0)
    esp = next(o[0] for o in ops_ if o[1] == "top" and o[5] is eq)
    y_ = min(esp)

    def stub(ops):
        pic = render(cq_.tiles, ops, cq_.x0, cq_.y0, cq_.width, cq_.lines).rows
        return sum(1 for a_, b_ in esp[y_] for x_ in range(a_ + 1, b_ - 1) if pic[y_ + cq_.y0][x_] == BLK)
    sg, sr = stub(ops_), stub([o if o[5] is not eq else o[:4] + (False,) + o[5:] for o in ops_])
    res.append(("3 a quartered cell's E top under an EQUAL N quarter draws no outline along c - R (%d black px of "
                "its first row); negative control, outlined as before: %d" % (sg, sr), sg == 0 and sr > 4))
    return c


def _course_items(c, k, res, t):
    """--selfcheck items 3 - 6 on ONE compiled course (each shipped course; SPEC.md 130.24.11's split
    course, the same items on halves)"""
    tag = "%s" % c.name
    # 3. the picture, the CGA's and the Hercules's through htab()
    try:
        dc = _decode(c.cga)
        ok = all(bytes(dc[y]) == bytes(c.pic[y]) for y in range(c.lines))
    except CourseError as e:
        print("    " + str(e))
        ok = False
    pt = c.part

    def herc_ok(hpart):
        for y in range(c.lines):
            for bx in range(c.cols):
                off = pt["map"][(y >> 3) * c.cols + bx]
                w = hpart[off + 2 * (y & 7):off + 2 * (y & 7) + 2]
                if bytes(w) != herc_bytes(c.pic[y][bx * 8:bx * 8 + 8], line=y, col0=bx * 8):
                    return False
        return True
    res.append(("3 %s: the map and the CGA blocks decode to the picture; the Hercules picture is the CGA blocks "
                "through htab() (bz_hgen's algorithm), equal to herc_bytes of it; every map word a block offset "
                "inside the part; block 0 black; ROWB = 2 COLS" % tag,
                ok and herc_ok(c.herc) and pt["rowb"] == 2 * pt["cols"]
                and c.cga[pt["blkoff"]:pt["blkoff"] + 16] == bytes(16)))
    bad = bytearray(c.cga)
    w0 = struct.unpack_from("<H", bad, HDR + 2 * 37)[0]
    sh = sheets_of(c.cga)                       # (a SHEETED course: the word moved inside sheet 0's own map, and
    nmap = c.plan["n"] * c.cols if sh else len(pt["map"])      # the decode of every sheet, 130.30.12)
    alt = next(HDR + 2 * i for i, w in enumerate(pt["map"][:nmap]) if w != w0)
    struct.pack_into("<H", bad, HDR + 2 * 37, struct.unpack_from("<H", bad, alt)[0])
    try:
        dd = _decode(SheetBytes([bad] + list(sh[1:]), c.plan) if sh else bytes(bad))
        caught = any(bytes(dd[y]) != bytes(c.pic[y]) for y in range(c.lines))
    except CourseError:
        caught = True
    res.append(("3 %s negative control: one map word moved fails the decode" % tag, caught))
    if k == 0:
        tb = bytearray(t)
        blk = c.cga[pt["blkoff"] + 16:pt["blkoff"] + 32]
        tb[256 * 0 + blk[0]] ^= 0x03
        import bonanza_assets as _BA
        old = _BA.htab
        _BA.htab = lambda: bytes(tb)
        try:
            caught = not herc_ok(herc_translate_course(c.cga))
        finally:
            _BA.htab = old
        res.append(("3 %s negative control: one htab() entry flipped fails the Hercules picture" % tag, caught))
    # 4. the grid against the geometry
    g = Grid(c.cga, c.wcga)
    okp = okk = okv = oks = oksf = True
    nsplit = 0
    for (wx, wy), ent in c.tiles.items():
        cl = g.cell(wx, wy)
        if isinstance(ent, Split):                  # SPEC.md 130.24.11: the pick and each half's h4 at all 256
            nsplit += 1                             # integer points; a VOID half's kill by NEAR
            pr = g.pair(wx, wy)
            if cl[3] != ent.diag or cl[4] & (FL_SAFE | FL_OBS):
                okk = False
            for h, tl in enumerate(ent.halves):
                if tl is None:
                    if pr[h][3] != KIND_VOID or pr[h][0] != zq(_near_low(c.tiles, wx, wy)) - 12:
                        okv = False
                elif pr[h][3] != tl.kind or pr[h][5] != tl.surf:
                    okk = False
            for u in range(16):
                for v in range(16):
                    hh = pick(ent.diag, u << 8, v << 8)
                    want_h = (1 if (u >= v if ent.diag == KIND_TB else u + v >= 16) else 0) if ent.diag != KIND_Q \
                        else {(1, 0): Q_N, (1, 1): Q_E, (0, 1): Q_S, (0, 0): Q_W}[(int(u >= v), int(u + v >= 16))]
                    tl = ent.halves[hh]
                    if hh != want_h or g.rec(wx, wy, u << 8, v << 8) != pr[hh]:
                        okp = False
                    if tl is not None:
                        zt, zr, zb, zl = (4 * w_ for w_ in tl.corners())
                        if 4 * (16 * zt + (zr - zt) * u + (zl - zt) * v) != 16 * Physics.h4(pr[hh], u, v):
                            okp = False
            continue
        tl = ent
        if isinstance(tl, FieldTile):               # SPEC.md 130.28.2: its heights, all 17 x 17, the tile's
            if cl[3] != KIND_FIELD or cl[6] != tl.h or cl[4] & FL_SAFE:
                okp = False
            continue
        zt, zr, zb, zl = (4 * v for v in tl.corners())
        if zb != zr + zl - zt:
            okp = False
        for u in range(16):
            for v in range(16):
                if 4 * (16 * zt + (zr - zt) * u + (zl - zt) * v) != 16 * Physics.h4(cl, u, v):
                    okp = False
        if cl[3] != tl.kind:
            okk = False
        safe = (tl.kind == KIND_FLOOR and tl.sx == 0 and tl.sy == 0 and (wx, wy) not in c.pcell
                and all(edge_rec(c.tiles.get((wx + dx, wy + dy)), OPP[e]) is not None for e, (dx, dy) in EDGE_D.items()))
        if bool(cl[4] & FL_SAFE) != safe:
            oks = False
    # the surfaces as the statements set them, read back independently
    want_s = {}
    for surf, shape, _ln, *_ in c.src.surfaces:
        for tt in shape:
            if tt in c.tiles:
                want_s[tt] = surf
    for wd in getattr(c.src, "waters", ()):         # SPEC.md 130.36: a `water` cell is a SAND floor, laid after
        for tt in wd["cells"]:                      # every other statement (its surface whatever they said)
            want_s[tt] = SURF_SAND
    for tt in c.tiles:
        if isinstance(c.tiles[tt], Split):          # (a split cell's surface: its floor halves', 130.24.4)
            if g.cell(*tt)[5] != max([h.surf for h in c.tiles[tt].halves if h is not None and h.kind != KIND_WALL]
                                     + [0]):
                oksf = False
        elif g.cell(*tt)[5] != want_s.get(tt, SURF_NORMAL):
            oksf = False
    for r in range(g.nrows):
        sR = g.smin + r
        for kk in range(-2, g.kw + 2):
            aC = g.amin + 2 * kk + (sR & 1)
            wx, wy = (sR + aC) >> 1, (sR - aC) >> 1
            if (wx, wy) in c.tiles:
                continue
            cl = g.cell(wx, wy)
            near = [r_ for tt in _cheb(c.tiles, wx, wy, 2) for r_ in tile_recs(tt)]
            want = (zq(min(min(tt.corners()) for tt in near)) - 12) if near else Z_OPEN    # (quarter units,
            if (wx, wy) in c.slabcells:                                                  # SPEC.md 130.48)
                want = 2 * (c.slabcells[(wx, wy)][0] >> 2) - 12
            if cl[3] != KIND_VOID or cl[0] != want or cl[4] & FL_SAFE or cl[5]:
                okv = False
    res.append(("4 %s: at all 256 integer points of every solid cell h4 is the plane the renderer drew%s" % (
        tag, "; on each of the %d SPLIT cells the pick names the half 130.24.7.1 says and h4 is that half's "
        "plane (SPEC.md 130.24.11)" % nsplit if nsplit else ""), okp))
    res.append(("4 %s: kinds are the rooms' styles; VOID is NEAR with the kill height or OPEN exactly where no "
                "solid cell is within two tiles; SAFE exactly where 130.10.4.3 says; every surface nibble as the "
                "statements set it (%d tiles not normal)" % (tag, sum(1 for v in want_s.values() if v)),
                okk and okv and oks and oksf))
    # OCCG: never without OCC; and sound - a grounded ball anywhere in a cell that lays a record has it
    occg_ok = all(not (v[3] & FL_OCCG) or v[3] & FL_OCC for v in c.cells.values())
    tried = missed = 0
    for (wx, wy), cl in c.cells.items():
        if not cl[3] & FL_OCC or (cl[2] & 15) not in (KIND_FLOOR, KIND_GOAL) + SPLIT_KINDS:
            continue
        for u in range(0, 16, 2):
            for v in range(0, 16, 2):
                for fr in (0, 128):
                    gx, gy = ((16 * wx + u) << 8) + fr, ((16 * wy + v) << 8) + fr
                    rc_ = g.rec(wx, wy, (u << 8) + fr, (v << 8) + fr)   # (a split cell: the half there)
                    if rc_[3] not in (KIND_FLOOR, KIND_GOAL):
                        continue
                    gz = Physics.h4(rc_, u, v) << 6
                    px = ((gx - gy) >> 8) + c.x0 - 8
                    py = ((((gx + gy) >> 1) - gz) >> 8) + c.y0 - 13
                    tried += 1
                    if laid_at(c, px, py, wx + wy, gz >> 8, 0) and not cl[3] & FL_OCCG:
                        missed += 1
    res.append(("4 %s: OCCG (%d cells) never without OCC, and set wherever a grounded ball at its floor lays a "
                "record (%d grounded positions of OCC cells tried, %d missed)" % (
                    tag, sum(1 for v in c.cells.values() if v[3] & FL_OCCG), tried, missed),
                occg_ok and missed == 0))
    # 5. the occluders, on the MERGED records
    recs = c.records
    srt = all((x["brow"], x["col"], x["s"]) <= (y["brow"], y["col"], y["s"]) for x, y in zip(recs, recs[1:]))
    seen = set()
    dup = False
    for r in recs:
        if seen & r["pix"]:
            dup = True
        seen |= r["pix"]
    span = 0
    for r in c.raw:
        tops = [c.tbuf[y][x] for (x, y) in r["pix"]]
        span = max(span, max(tops) - min(tops))
        if r["top"] != max(tops) or any(c.sbuf[y][x] != r["s"] for (x, y) in r["pix"]):
            dup = True
    masks_unique = len(c.masks) == len(set(c.masks))
    res.append(("5 %s: OCCIDX non-decreasing to the records' end, records sorted, no pixel in two records, no "
                "unmerged record's tops spanning over %d px (most %d), masks deduplicated (%d for %d records)"
                % (tag, BAND, span, len(c.masks), len(recs)), srt and not dup and span <= BAND and masks_unique))
    tried, diff = merge_exact(c.raw, c.records, c.queries)
    res.append(("5 %s: the merge is exact - for every block and every (s_b, z_b + m) of its query set the %d "
                "merged records lay exactly the pixels the %d unmerged ones lay (%d queries%s)" % (
                    tag, len(c.records), len(c.raw), tried, "" if diff is None else ", differs at %s" % (diff,)),
                diff is None))
    if k == 0:
        key = next(kk for kk, v in sorted(c.raw_block.items()) if v >= 2)
        rr = [r for r in c.raw if (r["brow"], r["col"]) == key]
        Q = sorted(c.queries.get(key, ()))
        pair = next(((i, j) for i in range(len(rr)) for j in range(i + 1, len(rr))
                     if _verdict(rr[i], Q) != _verdict(rr[j], Q) and any(_verdict(rr[i], Q))
                     and any(_verdict(rr[j], Q))), None)
        if pair:
            forced = merge_records(c.raw, c.queries, _force=(key, pair[0], pair[1]))
            res.append(("5 %s negative control: two records of block %s with different verdicts merged by force "
                        "fail the merge's check" % (tag, key), merge_exact(c.raw, forced, c.queries)[1] is not None))
    c._raised = _raised_tops(c)
    mism = 0
    tried = 0
    first_laid = None
    ag5 = AGrid(world_of(c))                  # (SPEC.md 130.29: the control's record is one the model does not cover)
    for rc in c.reach:
        if (rc.wx, rc.wy) in getattr(c, "noocc", ()):
            continue                            # (SPEC.md 130.53)
        gx, gy = (16 * rc.wx + 8) << 8, (16 * rc.wy + 8) << 8
        po_ = pose_of(c, rc, gx, gy)                # (130.49: a REAL pose there - its floor, its margin)
        zl_, f_ = po_ or (None, None)
        for z in (sorted({zl_, rc.zhi}) if po_ else ()):
            for air in ((1,) if f_ is None else (0, 1)):
                air = oair_at(air, z, f_)
                px = ((gx - gy) >> 8) + c.x0 - 8
                py = (((gx + gy) >> 1) >> 8) - z + c.y0 - 13
                tried += 1
                A = composite(c, px, py, rc.s, z, air, "records", cell=mcell(gx, gy))
                Bp = composite(c, px, py, rc.s, z, air, "pixels", cell=mcell(gx, gy), cut=c.occpix)
                if A != Bp:
                    # (wave 11, ROLL's chute: a merged record keeps its FIRST member's s and top (merge_records),
                    # so a member with a higher s and a lower top - ROLL's block (74, 21): (66, 96) merged into
                    # (65, 105) - has its tops raised here while its s is not lowered, and the raised buffer
                    # then hides a pixel at s_b 65, z_b + m 96 - 104 that NEITHER the member nor the merged
                    # record lays: the reference's artefact, not the guest's.  So a pixel of A differs only when
                    # it is neither the raised buffer's nor the plain per-pixel rule's - the unmerged tops)
                    rz, c._raised = c._raised, {}
                    try:
                        Bq = composite(c, px, py, rc.s, z, air, "pixels", cell=mcell(gx, gy), cut=c.occpix)
                    finally:
                        c._raised = rz
                    if any(v != Bp.get(p) and v != Bq.get(p) for p, v in A.items()):
                        mism += 1
                if first_laid is None and not ag5.runs(*mcell(gx, gy)):
                    for r in laid_at(c, px, py, rc.s, z, air):
                        if any(p in r["pix"] and Bp[p] != v for p, v in ball_pixels(px, py).items() if p in Bp):
                            first_laid = (r, px, py, rc.s, z, air, mcell(gx, gy))
                            break
    res.append(("5 %s: the ball composited through the MERGED RECORDS equals the per-pixel buffer's over the cut's "
                "pixels (tops raised to the unmerged records'), at the centre of every reachable cell, lowest and highest, both air "
                "states (%d positions, %d differ)" % (tag, tried, mism), mism == 0))
    fmism = fgate = ftried = 0
    fneg = None
    for rc in c.reach:
        if (rc.wx, rc.wy) in getattr(c, "noocc", ()):
            continue                            # (SPEC.md 130.53)
        if rc.zhi <= rc.zlo:
            continue
        po_ = pose_of(c, rc, (16 * rc.wx) << 8, (16 * rc.wy) << 8)  # (130.49: a REAL pose)
        zl_, f_ = po_ or (None, None)
        for z in (sorted({zl_, rc.zhi - 1}) if po_ else ()):
            gx, gy, gz = (16 * rc.wx) << 8, (16 * rc.wy) << 8, (z << 8) + 128
            px = ((gx - gy) >> 8) + c.x0 - 8
            py = (((gx + gy) >> 1) - gz >> 8) + c.y0 - 13
            for air in ((1,) if f_ is None else (0, 1)):
                air = oair_at(air, z, f_)
                ftried += 1
                if composite(c, px, py, rc.s, z, air, "records", cell=mcell(gx, gy)) != composite(
                        c, px, py, rc.s, z, air, "pixels", cell=mcell(gx, gy)):
                    fmism += 1
                if laid_at(c, px, py, rc.s, z, air):
                    if not c.cells[(rc.wx, rc.wy)][3] & FL_OCC:
                        fgate += 1
                    elif fneg is None:
                        fneg = (rc, px, py, z, air)
    res.append(("5 %s: at the fractional-height line the records composite as the pixels and every position that "
                "lays one is in an OCC cell (%d positions, %d differ, %d ungated)" % (tag, ftried, fmism, fgate),
                fmism == 0 and fgate == 0))
    if fneg is not None:
        rc, px, py, z, air = fneg
        cl = c.cells[(rc.wx, rc.wy)]
        cl[3] &= ~FL_OCC
        try:
            caught = bool(laid_at(c, px, py, rc.s, z, air)) and not cl[3] & FL_OCC
        finally:
            cl[3] |= FL_OCC
        res.append(("5 %s negative control: cell (%d, %d)'s OCC cleared is caught at its fractional-height line"
                    % (tag, rc.wx, rc.wy), caught))
    occ_ok = all(bool(v[3] & FL_OCC) == bool(c.laid.get(k_, 0)) for k_, v in c.cells.items()
                 if v[2] & 15 != KIND_WALL)
    res.append(("5 %s: OCC set exactly on the cells some position of which lays a record" % tag, occ_ok))
    if first_laid is not None:
        r, px, py, sb, z, air, cl_ = first_laid
        old = r["s"]
        r["s"] = sb
        try:
            caught = composite(c, px, py, sb, z, air, "records", cell=cl_) != composite(c, px, py, sb, z, air,
                                                                                        "pixels", cell=cl_)
        finally:
            r["s"] = old
        res.append(("5 %s negative control: one record's s_C lowered to the ball's row fails the composite" % tag,
                    caught))
    # 6. the bounds
    inside = True
    for rc in c.reach:
        xl, xh = foot_x(rc, c.x0)
        if xl < 0 or xh >= c.width or foot_top(rc, rc.zhi) + c.y0 < 0 or foot_top(rc, rc.zlo) + c.y0 + 30 >= c.lines:
            inside = False
    least = min(c.gtop, c.ftop) + c.y0
    top_rc = min(c.reach, key=lambda rc: foot_top(rc, rc.zhi))
    floors = [rc for rc in c.reach if rc.kind != KIND_VOID]
    fall = max(floors, key=lambda rc: rc.zhi - rc.zlo)
    void = max(c.reach, key=lambda rc: rc.zhi - rc.zlo)
    print("    %s: Y0 %d - the least reachable footprint top is line %d, cell (%d, %d) at %d px, set by %s; %d "
          "rounds to settle; the geometry's top is line %d.  Longest reachable fall onto a floor %d px (cell "
          "(%d, %d)), into a kill %d px (cell (%d, %d)); mean zhi - zlo %.1f px" % (
              tag, c.y0, c.ftop + c.y0, top_rc.wx, top_rc.wy, top_rc.zhi,
              ("a %s of cell %s" % (top_rc.src[1], top_rc.src[0])) if top_rc.src else "its own floor", c.rounds,
              c.gtop + c.y0, fall.zhi - fall.zlo, fall.wx, fall.wy, void.zhi - void.zlo, void.wx, void.wy,
              sum(rc.zhi - rc.zlo for rc in c.reach) / float(len(c.reach))))
    res.append(("6 %s: every reachable footprint inside the picture; Y0 the least that does it plus the "
                "alignment the search chose (line %d, +%d); the reach settled in %d rounds (at most %d)"
                % (tag, least, c.y0add, c.rounds, REACH_ROUNDS),
                inside and least == c.y0add and c.rounds <= REACH_ROUNDS))
    if c.y0counts is not None:                  # SPEC.md 130.25.3: the eight alignments
        ok = [k for k, n in enumerate(c.y0counts) if n and n[1] <= REC_BLOCK_MAX and n[2] <= REC_ROW_MAX]
        print("    %s: Y0's alignments, records (most a block) at +0 - +7: %s; +%d chosen" % (
            tag, ", ".join("refused" if n is None else "%d (%d)" % (n[0], n[1]) for n in c.y0counts),
            c.y0add))
        best = y0_order(c.y0counts)[0]
        res.append(("6 %s: the Y0 search kept +%d (%d records, %s) of the %d alignments that meet the "
                    "bounds, and its compile has the records its probe counted" % (
                        tag, c.y0add, len(c.records), "the fewest" if c.y0add == best else
                        "+%d, the fewest, refused by a later rule" % best, len(ok)),
                    c.y0add in ok and len(c.rule_records) == c.y0counts[c.y0add][0]))
    if c.props:
        _props_course_checks(c, res, tag)
    _w4_records(c, res)
    sb, sok = spring_bounds(c)
    if sb:
        res.append(("6 %s: every SPRING's flight in the reach - %s - and its apex footprint inside the picture"
                    % (tag, ", ".join("%s apex %d px, zhi %d, footprint line %d" % o for o in sb)), sok))


def _sc_seeds(X, res):
    """--selfcheck's section `seeds` (selfcheck(): a fork of its state after the compile)"""
    byname = X.byname
    if "MILL" in byname:                    # the negative control: two windmills' seeds exchanged
        src = open(byname["MILL"].fname if os.path.isabs(byname["MILL"].fname)
                   else os.path.join(ROOT, byname["MILL"].fname)).read()
        swp = src.replace("prop windmill 9 9  seed 16", "prop windmill 9 9  seed 36").replace(
            "prop windmill 7 9\n", "prop windmill 7 9  seed 16\n")
        try:
            cs = [compile_course(t, "<MILL, %s>" % n, occluders=False) for t, n in ((src, "as is"), (swp, "seeds swapped"))]
            def _plain(c):
                b = bytearray(c.cga)
                b[c.part["gridoff"] + 18:c.part["gridoff"] + 20] = b"\0\0"
                return sum(struct.unpack_from("<%dH" % (len(b) // 2), b, 0)) & 0xFFFF
            sums = [_plain(c) for c in cs]
            res.append(("1 negative control: MILL with its two windmills' seeds exchanged has another identity "
                        "(%04Xh against %04Xh; a plain sum of the words would %s)" % (
                            cs[1].ident, cs[0].ident, "not" if sums[0] == sums[1] else "too"),
                        swp != src and cs[0].ident != cs[1].ident))
        except CourseError as e:
            res.append(("1 negative control: MILL with its seeds exchanged compiles (%s)" % e, False))


def _sc_crosscommit(X, res):
    """--selfcheck's section `crosscommit` (selfcheck(): a fork of its state after the compile)"""
    courses = X.courses
    # wave 6 (SPEC.md 130.16.13): item 1's cross-commit check RE-ANCHORED on 503031d4.  That commit's tool,
    # run from git in a temporary tree on THIS tree's course texts (the PLAYGROUND, which that tree lacks,
    # excluded by name), and this tool with the reach's wave 5b inputs (HOPMAX 224, no BOOST launch) give the
    # same stored parts byte for byte: so the proof is that only the reach's inputs moved.  (5b's own check,
    # against ef59209a's BZC1 parts, and wave 4's before it, are carried by this chain.)  A SKIP is a FAILURE.
    # (wave 7, SPEC.md 130.18: the texts with the statements that commit's grammar lacks - `clock`, `limit`
    # and `music` - left out, for both tools: a clock's lanes are new parts' bytes, the rest are not in a part)
    # (wave D5, SPEC.md 130.24: a course with a SPLIT cell - MOON's coast - is written in `box`, which that
    # commit's grammar lacks, and its part holds halves no tool of that tree lays: excluded by its geometry,
    # as the PLAYGROUND is by name; the rest still carry the chain)
    # (wave 11: FIRST ROLL and LITTLE HOP, the real courses, are written in geometry that commit's grammar
    # cannot say at all - ROLL's `chute`, HOP's quarter heights - and like the PLAYGROUND neither is in that
    # tree: the chain is the courses whose FILE is in 503031d4's tree, which it compiled then.  It still has
    # to cover the five it was written for - BENCH, FIRST, TRIAL, MILL and PEAK (summit.bbc) - or the item fails)
    import subprocess

    def _in_w5(c):
        return subprocess.run(["git", "cat-file", "-e", "%s:apps/bonanza/courses/%s" % (
            W5_COMMIT, os.path.basename(c.fname))], cwd=ROOT, capture_output=True).returncode == 0
    w5 = [c for c in courses if c.name != "PLAY" and not any(isinstance(t_, Split) for t_ in c.tiles.values())
          and _in_w5(c)]
    W5_CHAIN = ("BENCH", "FIRST", "TRIAL", "MILL", "PEAK")
    if [c.name for c in w5] != [n for n in (c.name for c in courses) if n in W5_CHAIN]:
        res.append(("1 the cross-commit chain covers %s's courses %s (it covers %s)" % (
            W5_COMMIT, ", ".join(W5_CHAIN), ", ".join(c.name for c in w5) or "none"), False))
    # (that commit's tool exempts course 0 from `target` - BENCH was course 0 there, and is a test course
    # after the shipped ones here since SPEC.md 130.54: it is handed BENCH first, in its own order)
    w5.sort(key=lambda c: c.name != "BENCH")
    import tempfile
    w5dir = tempfile.mkdtemp(prefix="bbw5")
    w5txt = []
    for c in w5:
        src_path = c.fname if os.path.isabs(c.fname) else os.path.join(ROOT, c.fname)
        with open(src_path) as fh:
            kept = [ln for ln in fh.read().split("\n") if ln.split()[:1] not in (["clock"], ["limit"], ["music"],
                                                                                 ["uses"], ["float"], ["test"])]
            # (story 9.8, SPEC.md 130.25.20: `uses` left out too - that grammar lacks it, and a family list is
            # not in that commit's parts; this tool compiles the text with the family rule off, "famuses";
            # and 130.27.2's `float`, which that grammar lacks too)
            # (wave 8b, 130.19.4: a goal's or a cup's `exit E` and `hidden` left out too - the grammar's new
            # clauses, and every exit 0 then, so the cells and the cup records are that commit's)
            kept = [re.sub(r"\s+exit\s+\d+|\s+hidden\b", "", ln.split("#")[0]) if ln.split()[:1] in (["goal"], ["cup"])
                    else ln for ln in kept]
        dst = os.path.join(w5dir, os.path.basename(src_path))
        with open(dst, "w") as fh:
            fh.write("\n".join(kept))
        w5txt.append(dst)
    old, why = wave2_parts([c.name for c in w5], W5_COMMIT, [os.path.basename(c.fname) for c in w5], texts=w5txt)
    if old is None:
        res.append(("1 the courses against %s's parts: %s (a SKIP of this item is a failure, 130.16.13)"
                    % (W5_COMMIT, why), False))
    else:
        diff = []
        for c, txt in zip(w5, w5txt):
            _CHECKS_OFF.add("famuses")
            try:
                # (that tool had no Y0 search; and SPEC.md 130.27's ground plane is a picture rule that tool lacks:
                # with it off - every face over the void 3 units, as `float` everywhere - the parts are that tool's)
                c5 = compile_course(txt, _hack={"hopmax": W5_HOPMAX, "boost": W5_BOOST, "y0add": 0, "noground": True, "nokit": True,
                                                "occ": "off", "nolook": True, "halfz": True,
                                                "realcut": False, "noavsplit": True, "onetb": True})
                # (and SPEC.md 130.29's AV off: today's records; and 130.47's look off: that tool's ink; and
                # 130.48's quarter units off: that tool's half-unit bytes, no rebase, the CELLS rule's 79h; and
                # 130.49's real-pose cut off: the whole cells that tool cut)
            finally:
                _CHECKS_OFF.discard("famuses")
            if c5.stored != old[c.name]:
                diff.append(c.name)
        res.append(("1 every course compiled with the reach's wave 5b inputs (HOPMAX %d, no BOOST launch) is %s's "
                    "stored part byte for byte, that commit's tool run from git on this tree's course texts (%s): "
                    "wave 6 moved the reach's inputs and nothing else in a part (130.27's ground rule off)%s" % (
                        W5_HOPMAX, W5_COMMIT, ", ".join(c.name for c in w5), "" if not diff else
                        " -- DIFFER: %s" % diff), not diff))


def _sc_grammar(X, res, part=(0, 1)):
    """--selfcheck's section `grammar` (selfcheck(): a fork of its state after the compile).  PART (k, n):
    the k-th of n contiguous slices of its cases, in their order (SC_SPLIT: the parallel run's spread)"""
    total = len(_grammar_cases()) + len(_wave3_cases()) + 2 + len(_w4_cases()) + 1
    lo, hi, n_ = total * part[0] // part[1], total * (part[0] + 1) // part[1], [-1]

    def mine():
        n_[0] += 1
        return lo <= n_[0] < hi
    # 2. the grammar and the bounds
    for case in _grammar_cases():
        if not mine():
            continue
        what, text, want = case[:3]
        try:
            compile_course(text, fname="<%s>" % what, _hack=case[3] if len(case) > 3 else None)
            fired, msg = False, "compiled"
        except CourseError as e:
            fired, msg = want in str(e), str(e)
        res.append(("2 refused: %s%s" % (what, "" if fired else " -- got: " + msg), fired))
    for case in _wave3_cases():
        if not mine():
            continue
        what, text, want = case[:3]
        try:
            compile_course(text, fname="<%s>" % what, _hack=case[3] if len(case) > 3 else None)
            fired, msg = False, "compiled"
        except CourseError as e:
            fired, msg = want in str(e), str(e)
        res.append(("2 refused (wave 3): %s%s" % (what, "" if fired else " -- got: " + msg), fired))
    # wave 8 (SPEC.md 130.19.10): SLOW lanes are unbounded a window, and a course has more than 16 lanes -
    # each case COMPILES (the controls above are the same posts counted FAST, refused)
    big_ = _W3F % (60, 20, 20)
    for what, text in (("seven posts (SLOW lanes) meeting one window",
                        big_ + _posts([_sa(36, a) for a in (-8, -4, 0, 4, 8)] + [_sa(42, a) for a in (-6, 6)])),
                       ("seventeen lanes in a course",
                        big_ + _posts([_sa(s_, a) for s_ in (30, 36, 42, 48) for a in (-6, -2, 2, 6)]
                                      + [_sa(54, 0)]))):
        if not mine():
            continue
        try:
            cx = compile_course(text, fname="<%s>" % what, _hack={"no_finish": True})
            ok_, msg = True, "%d lanes" % sum(1 for r in cx.part["props"] if r["lane"])
        except CourseError as e:
            ok_, msg = False, str(e)
        res.append(("2 accepted (130.19.10): %s (%s)" % (what, msg), ok_))
    for what, text, want in _w4_cases():
        if not mine():
            continue
        try:
            compile_course(text, fname="<%s>" % what)
            fired, msg = False, "compiled"
        except CourseError as e:
            fired, msg = want in str(e), str(e)
        res.append(("2 refused (wave 4): %s%s" % (what, "" if fired else " -- got: " + msg), fired))
    if mine():                                      # SPEC.md 130.14.4.1: a SPRING may stand at a pit's edge
        try:                                        # (VOID west of (4, 6)); _sc_flags: a flag, a pad, the cup
            compile_course(_W4C.replace("origin 224\n", "origin 224\nuses spring\n") + "spring 4 6 300\n",
                           fname="<a spring at a pit's edge>")
            ok_, msg = True, "compiled"
        except CourseError as e:
            ok_, msg = False, str(e)
        res.append(("2 accepted (130.14.4.1): a spring at a pit's edge%s" % ("" if ok_ else " -- got: " + msg), ok_))


def _sc_w9(X, res):
    """--selfcheck's section `w9` (selfcheck(): a fork of its state after the compile)"""
    _w9_checks(res)


def _wind_cases():
    """WIND (SPEC.md 130.34.2): the blower statement's refusals, (what, text, the refusal's substring)"""
    C = _W4C + "uses wind\n"
    B = "prop blower 6 6 face +x region 6 5 9 7"
    return [
        ("a blower with a clause of no meaning", C + B + " gale\n", "unknown or repeated clause 'gale'"),
        ("a blower with a clause twice", C + B + " strength 4 strength 5\n", "unknown or repeated clause 'strength'"),
        ("a blower facing north", C + "prop blower 6 6 face north region 6 5 9 7\n", "faces +x, -x, +y, -y or up"),
        ("a blower with no region", C + "prop blower 6 6 face +x\n", "needs its `face` and its `region`"),
        ("a blower's region inverted", C + "prop blower 6 6 face +x region 9 5 6 7\n", "is not X0 <= X1"),
        ("a blower's region past 252", C + "prop blower 6 6 face +x region 6 5 253 7\n", "is not X0 <= X1"),
        ("a region cut short", C + "prop blower 6 6 face +x region 6 5 9\n", "takes 4 values"),
        ("a strength of 0", C + B + " strength 0\n", "outside 1 - 127"),
        ("a strength of 128", C + B + " strength 128\n", "outside 1 - 127"),
        ("a gust of 10 in 30", C + B + " gust 10 20\n", "a power of two"),
        ("a gust of 0 on", C + B + " gust 0 32\n", "each at least 1"),
        ("a gust of 2048", C + B + " gust 1024 1024\n", "a power of two"),
        ("a seed on a steady blower", C + B + " seed 3\n", "a steady blower takes none"),
        ("a seed past the gust's period", C + B + " gust 16 16 seed 32\n", "not under its period"),
        ("a top on a horizontal blower", C + B + " top 3\n", "`top` is an updraft's"),
        ("an updraft with no top", C + "prop blower 6 6 face up region 6 5 8 7\n", "needs its `top`"),
        ("an updraft's top of 25 units", C + "prop blower 6 6 face up region 6 5 8 7 top 25\n", "outside 1 - 24"),
        ("a blower given a reset class", C + B + " reset attempt\n", "takes no `reset`"),
        ("a blower far from its region", C + "prop blower 6 6 face +x region 9 5 11 7\n", "not on or beside its region"),
        ("an eighth blower", C + "".join("prop blower %d %d face +x region 5 5 12 8\n" % (x, y) for x, y in (
            (5, 5), (6, 5), (7, 5), (8, 5), (9, 5), (10, 5), (11, 5), (5, 7))), "past the 7 wind elements"),
        ("a blower on a ramp", C + "prop blower 14 6 face +x region 13 5 15 7\n", "not a FLAT FLOOR"),
        ("a blower, its family not named", _W4C + B + "\n", "does not name"),
        ("lift on a horizontal blower", C + B + " lift\n", "`lift` is an updraft's"),
        ("a wisp written", C + "prop wisp 6 6\n", "a wisp is the tool's"),
        ("a flag twice", C + B + " flag flag\n", "unknown or repeated clause 'flag'"),
    ]


def _wind_checks(res):
    """WIND's selfcheck (SPEC.md 130.34.8): the refusals (item 2), the records and FAMV (item 3), the pennant's
    poses downwind (item 3) and the UPDRAFT's reach with its red arm `nowindreach` (item 6)"""
    for what, text, want in _wind_cases():
        try:
            compile_course(text, fname="<%s>" % what, occluders=False)
            fired, msg = False, "compiled"
        except CourseError as e:
            fired, msg = want in str(e), str(e)
        res.append(("2 refused (WIND, 130.34.2): %s%s" % (what, "" if fired else " -- got: " + msg), fired))
    t = _W4C + ("uses wind\nprop blower 6 6 face -y region 6 5 11 7 strength 9 gust 20 44 seed 5\n"
                "prop blower 10 6 face up region 9 5 11 7 strength 16 top 3 lift flag\n")
    c = compile_course(t, fname="<wind>", occluders=False)
    recs = sorted((r["at"], r["wdir"], r["wflags"], r["wstr"], r["wreg"], r["won"], r["wmask"], r["wseed"], r["wtop"],
                   r["cls"], r["fsb"] & 7, r["lane"]["poses"]) for r in c.part["props"] if r["kind"] == WD_K)
    want = [((6, 6), 3, 0, 9, (6, 5, 11, 7), 20, 63, 5, 0, CL_ATTEMPT, 0, WD_FANP),
            ((10, 6), WD_UP, WD_FLIFT | WD_FFLAG, 16, (9, 5, 11, 7), 0, 0, 0, 4 * c.cells[(10, 6)][0] + 24,
             CL_ATTEMPT, 0, 2)]
    by = dict((r["i"], r) for r in c.part["props"])
    wisps = [(r["at"], by[r["wblower"]]["at"], r["lane"]["poses"]) for r in c.part["props"] if r["kind"] == WD_K2]
    f0 = famv(FAM_BY_NAME["wind"])
    k0 = FAM_BY_NAME["wind"]["consts"]
    FAM_BY_NAME["wind"]["consts"] = k0[:3] + (k0[3] + 1,)
    f1 = famv(FAM_BY_NAME["wind"])
    FAM_BY_NAME["wind"]["consts"] = k0
    res.append(("3 WIND's records (130.34.3, 130.34.11): (cell, face, flags, S, region, ON, MASK, SEED, TOP px, "
                "class, FSB & 7, poses) %s; the gusting blower's WISP (cell, its blower's, poses) %s; FAMV %02Xh, "
                "%02Xh with WD_SPIN + 1 (the constants are in it)" % (recs, wisps, f0, f1),
                recs == want and wisps == [((8, 6), (6, 6), 2)] and f0 != f1))
    # two gusting blowers' lanes in one window turning on the same step are refused; seeded apart they are not
    two = _W4C + ("uses wind\nprop blower 5 5 face +x region 5 5 9 5 gust 32 32 flag\n"
                  "prop blower 5 8 face +x region 5 8 9 8 gust 32 32 flag%s\n")
    try:
        compile_course(two % "", fname="<two gusts>")
        fired, msg = False, "compiled"
    except CourseError as e:
        fired, msg = "turn on the same step" in str(e), str(e)
    try:
        compile_course(two % " seed 7", fname="<two gusts, seeded>")
        ok2, msg2 = True, "compiled"
    except CourseError as e:
        ok2, msg2 = False, str(e)
    res.append(("2 WIND (130.34.11): two gusting blowers' lanes in one window turning on the same step - %s; one "
                "seeded 7 steps on - %s" % (msg[:140], msg2[:140]), fired and ok2))
    # the pennant flies DOWNWIND: east of the pole for +x and -y, west for -x and +y, up off its top for an updraft
    seen, ok = [], True
    for face in WD_DIRS:
        p = {"kind": WD_K, "art": "wind", "at": (6, 6), "z4": 32, "wdir": WD_DIRS.index(face)}
        furl, fly = _pennants(p, 224)
        cx, ytop = 224, 8 * 12 + 8 - 32 - WD_POLE - 1
        xs, ys = [x for x, _ in fly], [y for _, y in fly]
        side = "up" if max(ys) < ytop else "east" if min(xs) > cx else "west" if max(xs) < cx - 1 else "?"
        seen.append("%s %s" % (face, side))
        ok = ok and side == {"+x": "east", "-y": "east", "-x": "west", "+y": "west", "up": "up"}[face] and bool(furl)
    res.append(("3 WIND's pennant flies downwind (130.34.6): %s" % ", ".join(seen), ok))
    # ...and its lane fits LANE_WMAX x LANE_HMAX blocks at every alignment (a floor's height in half units, the
    # origin's x by 4): the tool can never refuse a blower for its own flag's size
    worst = (0, 0)
    for face in WD_DIRS:
        for z4 in range(0, 64, 4):
            for x0_ in (224, 228):
                fu, fy = _pennants({"kind": WD_K, "art": "wind", "at": (6, 6), "z4": z4, "wdir": WD_DIRS.index(face)},
                                   x0_)
                xs, ys = [x for x, _ in list(fu) + list(fy)], [y + 300 for _, y in list(fu) + list(fy)]
                worst = (max(worst[0], (max(xs) >> 3) - (min(xs) >> 3) + 1),
                         max(worst[1], (max(ys) >> 3) - (min(ys) >> 3) + 1))
    res.append(("3 WIND's pennant's lane at every alignment: at most %d x %d blocks (the limit %d x %d)"
                % (worst + (LANE_WMAX, LANE_HMAX)), worst[0] <= LANE_WMAX and worst[1] <= LANE_HMAX))
    # the updraft's reach (130.34.5): the cells round the column take its top's height; the arm without it does not
    base = _W4C + "floor rect 4 10 8 12 flat 4\nuses wind\n"
    up = base + "prop blower 6 10 face up region 5 10 7 11 strength 16 top 6\n"
    flat = base + "prop blower 6 10 face +x region 5 10 7 11 strength 16\n"
    zu = dict(((r.wx, r.wy), r.zhi) for r in compile_course(up, fname="<updraft>", occluders=False).reach)
    zf = dict(((r.wx, r.wy), r.zhi) for r in compile_course(flat, fname="<no updraft>", occluders=False).reach)
    _CHECKS_OFF.add("windreach")
    try:
        zr = dict(((r.wx, r.wy), r.zhi) for r in compile_course(up, fname="<updraft, nowindreach>",
                                                                  occluders=False).reach)
    finally:
        _CHECKS_OFF.discard("windreach")
    raised = sorted(k for k in zu if zu[k] > zf.get(k, zu[k]))
    top = 4 * 8 + 8 * 6
    # PIT WIND (130.34.11): on the model, a ball at rest on a `lift` updraft's fan - glass LAUNCHED (airborne and
    # rising) with no Hop, rubber (16 under G 24) and steel left on the ground; the red arm, the same course
    # without `lift`, leaves glass grounded
    lt = _W4C + "uses wind\nprop blower 6 6 face up region 5 5 7 7 strength 16 top 4%s\n"
    seen = []
    for arm in (" lift", ""):
        cl = compile_course(lt % arm, fname="<lift%s>" % arm, occluders=False)
        for mat in range(len(MATERIALS)):
            q = Physics(cl, mat=mat).poke(6, 6)
            for _ in range(40):
                q.step(0)
            seen.append((arm.strip() or "no lift", MAT_NAMES[mat], q.air, q.gz >> 8))
    want = [("lift", "rubber", 0, 32), ("lift", "steel", 0, 32), ("no lift", "glass", 0, 32)]
    lifted = [x for x in seen if x[0] == "lift" and x[1] == "glass"]
    res.append(("6 WIND's PIT WIND (130.34.11): 40 steps at rest on a `lift` updraft's fan (material, airborne, "
                "z px) %s; the red arm without `lift` leaves glass on the ground" % seen,
                all(x in seen for x in want) and lifted and lifted[0][2] == 1 and lifted[0][3] > 32))
    # the FANS are FAST lanes, each a pose change a step (130.34.11): seven steady fans in one window are refused;
    # the red arm `fanfast` (counted as event lanes) lets them through
    seven = _W4C + "uses wind\n" + "".join("prop blower %d %d face +x region %d %d %d %d\n" % (x, y, x, y, x, y)
                                           for x, y in ((5, 5), (7, 5), (9, 5), (11, 5), (5, 7), (7, 7), (9, 7)))
    try:
        compile_course(seven, fname="<seven fans>")
        fired, msg = False, "compiled"
    except CourseError as e:
        fired, msg = "FAST lanes" in str(e) or "pose changes" in str(e), str(e)
    _CHECKS_OFF.add("fanfast")
    try:
        compile_course(seven, fname="<seven fans, fanfast>")
        red, msg2 = True, "compiled"
    except CourseError as e:
        red, msg2 = False, str(e)
    finally:
        _CHECKS_OFF.discard("fanfast")
    res.append(("2 WIND's fans in one window (130.34.11): seven spinning fans - %s; the red arm `fanfast` - %s"
                % (msg[:140], msg2[:100]), fired and red))
    res.append(("6 WIND's updraft reach (130.34.5): %d cells raised over the same course with a horizontal blower, the "
                "column's zhi %d px (its top %d px and the hover's overshoot); the red arm `nowindreach` raises %d"
                % (len(raised), zu[(6, 10)], top, sum(1 for k in zr if zr[k] > zf.get(k, zr[k]))),
                len(raised) > 6 and zu[(6, 10)] > top and not any(zr[k] > zf.get(k, zr[k]) for k in zr)))


def _sc_wind(X, res):
    """--selfcheck's section `wind` (SPEC.md 130.34.8)"""
    _wind_checks(res)


# SPEC.md 130.36: WATER's refusals, each a string case - a walkway at 3 units over a yard at 0, the water cell
# (6, 6) on its front row, its arch +y onto the yard
_WAT = ('course W "w"\nwidth 64\norigin 224\nuses water\nfloor rect 4 4 10 7 flat 3\nfloor rect 4 7 10 10 flat 0\n'
        'start 5 5\n')


def _water_cases():
    """(what, text, the refusal's words): SPEC.md 130.36's refusals"""
    return (("a bed within a climb of the top", _WAT + "water tile 6 6 top 3 bed 2.5\narch 6 6 +y\n",
             "not more than a climb"),
            ("a column open on its +y face (no arch: steel would roll out at the bed)", _WAT + "water tile 6 6 top 3 "
             "bed 0\n", "not SEALED"),
            ("a column beside VOID", _WAT + "water tile 9 5 top 3 bed 0\n", "is VOID"),
            ("an arch on an `open` water (130.36.11)", _WAT + "water tile 6 6 top 3 bed 0 open\narch 6 6 +y\n",
             "an `open` water has no arch"),
            ("a column beside a floor too low", _WAT + "floor rect 7 5 8 6 flat 0.5\nwater tile 6 5 top 3 bed 0\n",
             "a floor too low"),
            ("an arch on a cell that is not water", _WAT + "water tile 6 6 top 3 bed 0\narch 6 6 +y\narch 5 6 +y\n",
             "not a water cell"),
            ("an arch in a back face", _WAT + "water tile 6 6 top 3 bed 0\narch 6 6 -x\n", "BACK face"),
            ("an arch whose exit is not at the bed", _WAT + "water tile 6 6 top 3 bed 0.5\narch 6 6 +y\n",
             "FLAT FLOOR at the bed"),
            ("an arch twice in one face", _WAT + "water tile 6 6 top 3 bed 0\narch 6 6 +y\narch 6 6 +y\n",
             "a second arch"),
            ("a ripple on a cell that is not the statement's", _WAT + "water tile 6 6 top 3 bed 0 ripple 5 6\n"
             "arch 6 6 +y\n", "not one of its cells"),
            ("a cell both ripple and always", _WAT + "water tile 6 6 top 3 bed 0 ripple 6 6 always 6 6\narch 6 6 +y\n",
             "named twice"),
            ("seven ALWAYS ripples in one window (FAST lanes, 6 at most)", _WAT.replace("4 4 10 7", "3 4 20 7")
             .replace("4 7 10 10", "3 7 20 10") + "water rect 5 6 19 7 top 3 bed 0 always 5 6 7 6 9 6 11 6 13 6 15 6 "
             "17 6\n" + "".join("arch %d 6 +y\n" % x for x in range(5, 19)), "FAST lanes"),
            ("water with no `uses water`", _WAT.replace("uses water\n", "") + "water tile 6 6 top 3 bed 0\n"
             "arch 6 6 +y\n", "does not name"),
            ("a guarded arch whose exit is a prop's cell (130.35.10)", _WAT + "water tile 6 6 top 3 bed 0\n"
             "arch 6 6 +y guard\npad steel 6 7\n", "is a prop's cell"),
            ("a guarded arch's rail 1 unit high (130.35.10)", _WAT + "water tile 6 6 top 3 bed 0\n"
             "arch 6 6 +y guard height 1\n", "a guard rail is 1.5 - 3.0 units"),
            ("an arch with a clause that is not `guard`", _WAT + "water tile 6 6 top 3 bed 0\narch 6 6 +y rail\n",
             "arch takes"))


def _water_checks(res):
    """SPEC.md 130.36's selfcheck: the refusals; the cells, records and reach of the WATER test course; the DEPTH
    KEY (its water cells' pixels keyed s + 1, an arch's opening s; steel at the bed under the records that ghost
    it, and in the opening drawn whole) and its red arm (_WATER_S0: keyed s, the records gone); the BED form
    (the water cells' zlo the bed, the top with `noforms`)"""
    global _WATER_S0
    for what, text, want in _water_cases():
        try:
            compile_course(text, fname="<%s>" % what, occluders=False)
            fired, msg = False, "compiled"
        except CourseError as e:
            fired, msg = want in str(e), str(e)
        res.append(("2 refused (water, 130.36): %s%s" % (what, "" if fired else " -- got: " + msg), fired))
    # SPEC.md 130.36.11: an `open` pool needs no seal - the column beside VOID compiles with `open`; red arm, the
    # same text without it is refused (the case above)
    try:
        compile_course(_WAT + "water tile 9 5 top 3 bed 0 open\n", fname="<an open pool>", occluders=False)
        oko, msg = True, "compiled"
    except CourseError as e:
        oko, msg = False, str(e)
    res.append(("2 an `open` pool (130.36.11): a column beside VOID with `open` %s; without it refused (above)"
                % ("compiles" if oko else "is refused -- " + msg[:120]), oko))
    wbbc = os.path.join(COURSE_DIR, "water.bbc")
    c = compile_course(wbbc)
    wat = [r for r in c.part["props"] if r["kind"] == FK_WATER]
    g = Grid(c.cga)
    cok = len(wat) == 6 and all(r["bed"] == 0 and g.cell(*r["at"])[:4] == (r["top"], 0, 0, KIND_FLOOR)
                                  and g.cell(*r["at"])[4] & (FL_OBS | FL_SAFE | FL_OCCG) == FL_OBS | FL_OCCG
                                  and g.cell(*r["at"])[5] == SURF_SAND for r in wat)
    lanes = [(r["at"], r["rip"]) for r in wat if r["lane"]]
    cok = cok and lanes == [((4, 8), WR_RIPPLE | WR_ALWAYS), ((8, 8), WR_RIPPLE), ((12, 8), WR_RIPPLE)] \
        and all(r["lane"]["poses"] == 2 for r in wat if r["lane"])
    res.append(("3 water (130.36): WATER's six water cells are sand FLAT FLOORs at the top with OBS, OCCG (a "
                "grounded ball at the BED is behind the glass: _occg from the bed) and not SAFE, three with a "
                "ripple LANE of 2 poses (%s; +20 1 while a ball is in it, 3 always), "
                "their records +18 the bed and +19 the top (%s)" % (lanes, ", ".join("(%d, %d)" % r["at"]
                                                                             for r in wat)),
                cok))
    by = dict(((q.wx, q.wy), q) for q in c.reach)
    c0 = compile_course(open(wbbc).read(), fname=wbbc + " (noforms)", _hack={"noforms": True})
    by0 = dict(((q.wx, q.wy), q) for q in c0.reach)
    res.append(("6 water (130.36): the reach takes the BED form - the water cells' zlo the bed (%s px), and their "
                "top (%s px) with `noforms`" % (sorted({by[r["at"]].zlo for r in wat}), sorted({by0[r["at"]].zlo
                                                                                            for r in wat})),
                all(by[r["at"]].zlo == 0 and by0[r["at"]].zlo == 2 * r["top"] for r in wat)))

    def steel_at(cc, gx, gy, mat=MAT_STEEL, z=0):  # (the footprint's pixels the card lays over a ball there)
        p = Physics(cc, mat=mat)
        p.gx, p.gy, p.gz, p.air = gx, gy, z << 8, 0
        p._derive(True)
        return laid_at(cc, p.px, p.py, p.sb, p.zb, p.oair, card=True, cell=mcell(gx, gy))
    deep = steel_at(c, (16 * 8 + 8) << 8, (16 * 8 + 8) << 8)     # the sketch's column, at its bed
    door = steel_at(c, (16 * 8 + 8) << 8, (16 * 8 + 15) << 8)    # ...rolling out through its arch
    _WATER_S0 = True
    try:
        cr = compile_course(open(wbbc).read(), fname=wbbc + " (water keyed s)")
    finally:
        _WATER_S0 = False
    deep0 = steel_at(cr, (16 * 8 + 8) << 8, (16 * 8 + 8) << 8)
    res.append(("10 water (130.36): the DEPTH KEY - steel at the bed of (8, 8): %d footprint pixels laid over it (its "
                "own column's glass keyed s + 1 among them, the rest the walkway's), %d in its arch; the red arm "
                "(the water keyed s, _WATER_S0): %d - the column's own art drawn under the ball" % (
                    len(deep), len(door), len(deep0)), len(deep) > len(deep0)))
    # the FLOAT LINE: rubber at rest on the water, a half unit under its top, laid under the top's own pixels
    # (their tops WATER_FLOAT px up) - in it, not on it; the red arm WATER_FLOAT 0: drawn whole on the top
    global WATER_FLOAT
    fl = steel_at(c, (16 * 8 + 8) << 8, (16 * 8 + 8) << 8, MAT_RUBBER, 20)
    wf = WATER_FLOAT
    WATER_FLOAT = 0
    try:
        cf = compile_course(open(wbbc).read(), fname=wbbc + " (no float tops)")
    finally:
        WATER_FLOAT = wf
    fl0 = steel_at(cf, (16 * 8 + 8) << 8, (16 * 8 + 8) << 8, MAT_RUBBER, 20)
    res.append(("10 water (130.36): the FLOAT LINE - rubber at rest in the sketch's column, 4 px under its top: %d "
                "footprint pixels of it laid under the water (the top's tops WATER_FLOAT %d px up); the red arm "
                "(WATER_FLOAT 0): %d" % (len(fl), wf, len(fl0)), len(fl) > len(fl0)))


def _water_bob_checks(res):
    """SPEC.md 130.36.10: the surface bob's period is in water's FAMV (a retune moves the identity of every course
    that names water), and it fits the part's code (a byte's shift)"""
    global WA_FBSH
    was = WA_FBSH
    try:
        f0 = famv(FAM_BY_NAME["water"])
        WA_FBSH = was + 1
        f1 = famv(FAM_BY_NAME["water"])
    finally:
        WA_FBSH = was
    res.append(("3 water (130.36.10): the surface bob's half period 2^%d steps folds into water's FAMV (%02Xh; "
                "%02Xh at 2^%d)" % (was, f0, f1, was + 1), f0 != f1 and 0 <= was <= 7))


