def _sc_hopplan(X, res):
    """--selfcheck's section `hopplan` (SPEC.md 130.14.7.4.1): the HOPPING autopilot finishes HOP (course 2,
    built on the Hop) with no fall and no RETURN, its route is the limit's and the route demo's, and its red
    arm (the arrows alone, route_plan's nohop) does not finish; a course the arrows finish is not searched"""
    hp = os.path.join(COURSE_DIR, "hop.bbc")
    c = compile_course(hp)
    plain = Physics(c, play=True)
    plain.tsec = 0
    for _i in range(PLAN_STEPS):
        if plain.goal:
            break
        plain.step(plain.auto())
    plan, red = route_plan(c), route_plan(c, nohop=True, nohold=True)
    q, first = Physics(c, play=True), None
    q.tsec = 0
    for i, k in enumerate(plan or ()):
        q.step(k)
        if q.goal and first is None:
            first = i + 1
    hops = sum(1 for i, k in enumerate(plan or ()) if k & K_HOP and not (i and plan[i - 1] & K_HOP))
    log = route_demo(c, 2)
    fl, steps = log[6], struct.unpack_from("<I", log, 8)[0]
    ok = plan is not None and first == len(plan) and not q.nfall and not q.nret and q.nhop and red is None \
        and not plain.goal and c.lroute == len(plan) and fl & RL_COMPLETE and steps == len(plan) \
        and bytes(log[RLOG_HDR:]) == bytes(encode_log(plan, 2, c.ball, True, c.ident)[RLOG_HDR:])
    res.append(("4 the hopping autopilot (130.14.7.4.1): HOP's route found with Space (%s steps, %.1f s, %d presses, "
                "%d Hops, %d boosts), its replay at the goal on its last step with %d falls and %d returns, the "
                "limit's route (%s) and the route demo's (%d steps, %s); RED ARM: the arrows alone (route_plan's "
                "nohop, and 130.6's autopilot for %d steps) do not finish (%s)" % (
                    len(plan) if plan else "NO", len(plan or ()) / float(SEC_STEPS), hops, q.nhop, q.nboost, q.nfall,
                    q.nret, c.lroute, steps, "COMPLETE" if fl & RL_COMPLETE else "inputs only", PLAN_STEPS,
                    "none" if red is None else "FINISHED in %d" % len(red)), bool(ok)))
    # SPEC.md 130.14.7.4.2: the HOLD - a thin ramp with an open side, curving at its foot, finished with no fall
    c = compile_course(_THINRAMP, "<a thin ramp, railed on one side, into a chute>")
    plain = Physics(c, play=True)
    for _i in range(PLAN_STEPS):
        if plain.goal or plain.nfall:
            break
        plain.step(plain.auto())
    plan, red = route_plan(c), route_plan(c, nohold=True)
    q = Physics(c, play=True)
    q.tsec = 0
    for k in plan or ():
        q.step(k)
    ok = plan is not None and q.goal and not q.nfall and not q.nret and not q.nhop and red is None \
        and plain.nfall and not plain.goal
    res.append(("4 the HOLD (130.14.7.4.2): a one-tile ramp railed on one side only, into a chute turning toward "
                "its open side - 130.6's arrows %s; the search with its holds finds a route (%s steps), its replay "
                "at the goal with %d falls, %d returns and %d Hops; RED ARM: the search without the holds "
                "(route_plan's nohold) finds %s" % (
                    "FALL off the open side" if plain.nfall else "do not fall (the case is gone)",
                    len(plan) if plan else "NO", q.nfall, q.nret, q.nhop,
                    "none" if red is None else "one in %d" % len(red)), bool(ok)))
    # SPEC.md 130.14.7.4.3: the WAIT - a lift ridden UP, the arrows alone rolling into its empty shaft
    global _NOWAIT
    c = compile_course(_LIFTUP, "<a lift ridden up from its low dock>")
    plain = Physics(c, play=True)
    for _i in range(PLAN_STEPS):
        if plain.goal or plain.nfall:
            break
        plain.step(plain.auto())
    plan = route_plan(c)
    _NOWAIT = True
    try:
        c.__dict__.pop("_hplan", None)
        red = route_plan(c)
    finally:
        _NOWAIT = False
        c.__dict__.pop("_hplan", None)
    q = Physics(c, play=True)
    q.tsec = 0
    for k in plan or ():
        q.step(k)
    ok = plan is not None and q.goal and not q.nfall and not q.nret and red is None \
        and plain.nfall and not plain.goal
    res.append(("5 the WAIT (130.14.7.4.3): a steel ball ridden UP a lift from its low dock - 130.6's arrows %s; "
                "the search with its waits finds a route (%s steps), its replay at the goal with %d "
                "falls and %d returns; RED ARM: the search without the waits finds %s" % (
                    "ROLL INTO THE EMPTY SHAFT" if plain.nfall else "do not fall (the case is gone)",
                    len(plan) if plan else "NO", q.nfall, q.nret,
                    "none" if red is None else "one in %d" % len(red)), bool(ok)))
    # SPEC.md 130.14.7.4.4: the AIM - the arrows reach the goal past a flag without touching it
    global _NOFLAG
    c = compile_course(_FLAGSIDE, "<a flag two cells off the arrows' line>")
    plain = Physics(c, play=True)
    for _i in range(DEMO_STEPS):
        if plain.goal or plain.nfall:
            break
        plain.step(plain.auto())
    q, first = replay_log(c, bytes(route_demo(c, 1)))
    _NOFLAG = True
    try:
        c.__dict__.pop("_hplan", None)
        r, _rf = replay_log(c, bytes(route_demo(c, 1)))
    finally:
        _NOFLAG = False
        c.__dict__.pop("_hplan", None)
    ok = plain.goal and not plain.nckpt and q.goal and first is not None and not q.nfall and not q.nret \
        and q.nckpt == 1 and r.goal and not r.nckpt
    res.append(("6 the AIM (130.14.7.4.4): a flag two cells off the arrows' straight line - 130.6's arrows %s; the "
                "route demo (the flag pass) reaches the goal at step %s touching %d of 1 flags with %d falls and %d "
                "returns; RED ARM: the flag pass off (_NOFLAG), the route demo touches %d of 1" % (
                    "reach the goal touching %d of 1 flags" % plain.nckpt if plain.goal else "do not finish",
                    first, q.nckpt, q.nfall, q.nret, r.nckpt), bool(ok)))
    # every compiled course the arrows alone finish touching every flag: its route demo is the plain
    # autopilot's, key for key
    same, n = True, 0
    for k, cc in enumerate(X.courses):
        if not k or len(cc.route) < 2 or not cc.lroute:
            continue
        p = Physics(cc, play=True)
        keys = []
        while len(keys) < DEMO_STEPS and not p.goal and not p.tout:
            keys.append(p.auto())
            p.step(keys[-1])
        if p.goal and p.nckpt == sum(1 for q_ in cc.props if q_["kind"] == PK_CHECKPOINT):
            n += 1
            same = same and bytes(route_demo(cc, k)) == bytes(encode_log(keys, k, cc.ball, True, cc.ident))
    res.append(("4 a course the arrows alone finish touching every flag is never searched (130.14.7.4.1, "
                "130.14.7.4.4): %d courses' route demos are 130.6's autopilot's keys exactly" % n, same and n > 0))


def _sc_inc(X, res):
    """--selfcheck's section `inc` (selfcheck(): a fork of its state after the compile)"""
    a, courses, byname = X.a, X.courses, X.byname
    # the tables bzcourse.inc carries (130.14.4.2, 130.14.7.2): BZ_CRS_PARS, BZ_CRS_IDS, BZ_PHYSV - the
    # physics identity recomputed with the standard library's own CRC-CCITT (binascii.crc_hqx)
    import binascii
    crc = binascii.crc_hqx(mattab() + b"".join(struct.pack("<H", v) for v in PHYS_CONSTS) + phys_tables(),
                           0xFFFF)
    inc = a[2]["bzcourse.inc"]
    res.append(("4 bzcourse.inc's BZ_CRS_LIMS (%s; wave 7, 130.18.3), BZ_CRS_IDS and BZ_PHYSV (%02Xh: CRC-16/CCITT "
                "of BZ_MATTAB, PHYS_CONSTS, BZ_SURFTAB, the corner and OCTANT tables, folded; binascii.crc_hqx "
                "agrees) are the courses' and the model's, and every identity is non-zero" % (
                    ", ".join(str(c.limit) for c in courses), PHYSV),
                "    dw " + ", ".join(str(c.limit) for c in courses) in inc
                and "    dw " + ", ".join("%05Xh" % c.ident for c in courses) in inc
                and PHYSV == (crc >> 8) ^ (crc & 0xFF) and "BZ_PHYSV        equ %03Xh" % PHYSV in inc
                and all(c.ident for c in courses)))
    # wave 7 (SPEC.md 130.18.3): each course's limit by the rule (or explicit and over its floor), printed
    # with its 55-step seconds against real time; `par` refused; a limit under the floor refused
    lrows, lbad = [], []
    for c in courses:
        if c.name == "BENCH":
            lbad += [c.name] if c.limit else []
            continue
        want = limit_rule(c.lroute) if c.lroute else None
        expl = c.src.limit is not None
        lrows.append("%s %d s%s (route %s steps, %.1f s; %d steps = %.1f s real)" % (
            c.name, c.limit, " explicit" if expl else "", c.lroute, (c.lroute or 0) / float(SEC_STEPS),
            c.limit * SEC_STEPS, c.limit * SEC_STEPS * STEP_PIT / float(PIT_HZ)))
        if not c.limit or (not expl and c.limit != want) or (c.lroute and c.limit * SEC_STEPS < c.lroute * LIMIT_FLOOR):
            lbad.append(c.name)
    print("    the time limits (SPEC.md 130.18.3; a second of %d steps is %.4f s): %s" % (
        SEC_STEPS, SEC_STEPS * STEP_PIT / float(PIT_HZ), "; ".join(lrows)))
    res.append(("4 every course but BENCH has a time limit, the tool's rule's or an explicit one over its route's "
                "floor; BENCH none (%s)" % (", ".join(lbad) or "all"), not lbad))
    for what, txt in (("par", 'course PAR "p"\nwidth 128\norigin 352\nfloor rect 3 10 9 14 flat 4\n'
                               'goal rect 9 10 12 14 flat 4\nstart 5 12\nway 10 12\npar 10\n'),
                      ("a limit under the floor", 'course LIM "l"\nwidth 128\norigin 352\n'
                       'floor rect 3 10 30 14 flat 4\ngoal rect 30 10 33 14 flat 4\nstart 5 12\nway 18 12\n'
                       'way 31 12\nlimit 5\n')):
        try:
            compile_course(txt, "<%s>" % what, occluders=False)
            why = "accepted"
        except CourseError as e:
            why = str(e)
        res.append(("4 wave 7's refusal: %s is refused (%s)" % (what, why[:120]),
                    why != "accepted" and ("par is refused" in why if what == "par" else "under the route" in why)))
    # wave 7 (SPEC.md 130.18.6): `music NAME` names the song; the title and an unknown name are refused
    base = 'course MUS "m"\nwidth 128\norigin 352\nfloor rect 3 10 9 14 flat 4\ngoal rect 9 10 12 14 flat 4\nstart 5 12\n'
    mc = compile_course(base + "music trial\n", "<music>", occluders=False)
    sn = song_names()
    rule = [course_song(c, k) for k, c in enumerate(courses)]
    mr = []
    for bad in ("music title\n", "music nosuch\n", "music victory\n"):   # (8R.6: the fanfare is no course's)
        try:
            compile_course(base + bad, "<music refused>", occluders=False)
            mr.append("accepted")
        except CourseError as e:
            mr.append("refused" if "music takes" in str(e) else str(e))
    # SPEC.md 130.50.3: EVERY course names its song - no song by position (130.20.6's rule is gone), so a
    # course with no `music` line is refused at the build, and moving a course never changes its music
    try:
        course_song(compile_course(base, "<music none>", occluders=False))
        nomus = "accepted"
    except CourseError as e:
        nomus = "refused" if "no `music` line" in str(e) else str(e)
    res.append(("4 `music trial` gives song %d (%s); `music title` (no such song since 130.26.5), an unknown name and "
                "the fanfare %s; a course with no `music` %s; the courses' songs %s, each its own `music` line"
                % (course_song(mc), sn[course_song(mc)], " and ".join(mr), nomus, rule),
                course_song(mc) == sn.index("trial") and mr == ["refused", "refused", "refused"]
                and "title" not in sn and nomus == "refused"
                and rule == [c.src.music[0] for c in courses]
                and "    db " + ", ".join(str(x) for x in rule) in inc))
    # item 4's controls: each table the step reads moves BZ_PHYSV (a user's .BZR saved under other
    # physics is refused, not replayed down another path)
    tb = phys_tables()
    moved = [phys_ident(_tabs=tb[:i] + bytes([tb[i] ^ 1]) + tb[i + 1:]) != PHYSV
             for i in (0, len(surftab()), len(surftab()) + 3 * len(CORNER))]
    res.append(("4 negative controls: one bit of BZ_SURFTAB, of the corner table and of OCTANT each moves BZ_PHYSV",
                all(moved)))
    try:                                      # item 5's negative control: a blade in front of the doorway
        compile_course(open(byname["MILL"].fname if os.path.isabs(byname["MILL"].fname)
                            else os.path.join(ROOT, byname["MILL"].fname)).read(), "<MILL, rotor in front>",
                       _hack={"rotor_front": True})
        caught = False
    except CourseError as e:
        caught = "depend on its pose" in str(e)
    except KeyError:
        caught = None
    if caught is not None:
        res.append(("5 MILL negative control: a rotor whose blades are drawn IN FRONT of the doorway (a moving part "
                    "before the ball in one pose and not another) is REFUSED by the pose check", caught))
    # wave 5b (SPEC.md 130.15.12.3): item 10, the compact form; item 12, the budget


