class _Slot:
    """a section's place in --selfcheck's items: filled at the end, in the sequential order"""
    def __init__(self, name, post):
        self.name, self.post, self.kid, self.val, self.items = name, post, None, None, None


class _Sections:
    """--selfcheck's SECTIONS (2026-11-16, docs/TESTING.md *BONANZA's host checks*): each a block of items
    that reads the compiled courses and appends to the items.  JOBS 1: each runs here, in order, as the
    sequential selfcheck always did.  More: each is a forked child of this process taken once the courses
    are compiled (so each sees exactly that state, whatever ran before it), started longest first
    (SC_COST), a core each; its items and its output come back and are spliced in at its place, so the
    report is the sequential one, line for line.  ONLY: the section names to run (--only), the rest left
    out and said so"""
    def __init__(self, res, jobs, only):
        import io
        self.res, self.only, self.left, self.times = res, only, [], {}
        self.par = jobs > 1 and hasattr(os, "fork")
        self.pool = _Pool(jobs) if self.par else None
        self.todo, self.segs, self.slots = [], [], []
        self.real = sys.stdout
        if self.par:
            self.buf = io.StringIO()
            sys.stdout = self.buf

    def want(self, name):
        if self.only is None or name in self.only:
            return True
        if name not in self.left:
            self.left.append(name)
        return False

    def _slot(self, name, post):
        s = _Slot(name, post)
        self.res.append(s)
        self.slots.append(s)
        if self.par:
            self.segs += [self.buf.getvalue(), s]
            self.buf.seek(0)
            self.buf.truncate()
        return s

    def _child(self, fn, a, post):
        n0, t0 = len(self.res), time.time()
        v = fn(*a)
        return (v if post else self.res[n0:]), time.time() - t0

    def add(self, name, fn, *a, post=None, now=False):
        """the section NAME: fn(*a) appends its items to the list it is handed (or, with POST, returns a
        value that post(value) turns into items, at the end).  NOW: started at once (in a child when
        parallel), not with the rest"""
        if not self.want(name):
            return
        if not self.par:
            t0 = time.time()
            if post:
                s = self._slot(name, post)
                s.val = fn(*a)
            else:
                fn(*a)
            self.times[name] = time.time() - t0
            return
        s = self._slot(name, post)
        if now:
            s.kid = self.pool.start(self._child, fn, a, post)
        else:
            self.todo.append((s, fn, a))

    def finish(self):
        """every section run and its items in place (res, in order); its output printed in order"""
        if self.par:
            sys.stdout = self.real
            self.segs.append(self.buf.getvalue())
            for s, fn, a in sorted(self.todo, key=lambda t_: -SC_COST.get(t_[0].name, 30)):
                s.kid = self.pool.start(self._child, fn, a, s.post)
            self.todo = []
            err = None
            for seg in self.segs:
                if isinstance(seg, str):
                    sys.stdout.write(seg)
                    continue
                val, text, exc = self.pool.wait(seg.kid)
                sys.stdout.write(text)
                if exc is not None:
                    err = err or exc
                    seg.items = []
                    continue
                seg.val, self.times[seg.name] = val
            if err is not None:
                raise err
        for s in self.slots:
            if s.items is None:
                s.items = s.post(s.val) if s.post else s.val
        self.res[:] = [r for x in self.res for r in (x.items if isinstance(x, _Slot) else [x])]

    def close(self):
        """on the way out of a failure: this process's output back, no child left running"""
        if self.par and sys.stdout is self.buf:
            sys.stdout = self.real
            sys.stdout.write("".join(x for x in self.segs if isinstance(x, str)) + self.buf.getvalue())
        if self.pool is not None:
            self.pool.kill()


# --selfcheck's sections' seconds (BB_TIMES=1), measured 2026-11-16 on four cores: only the order the
# parallel run starts them in, longest first - a section missing here is started as if 30 s
SC_COST = {"determinism": 59, "camcheck": 54, "crosscommit": 48, "physics": 34, "play": 34, "clockrule": 18,
           "split": 17, "grammar": 16, "w9": 16, "inc": 14, "y0moon": 12, "courses": 10, "budget": 9, "dither": 9,
           "flags": 7, "palette": 7, "routes": 7, "gaps": 6, "w4": 6, "path": 4, "splitphys": 4, "cache": 3,
           "compact": 2, "hud": 2, "props": 2, "clockvis": 1, "demos4": 1, "gap3": 1, "launch": 1, "millroute": 1,
           "seeds": 1, "tables": 1, "title": 1, "av": 40, "wind": 4, "guard": 30, "water": 20, "kit": 12, "arch": 30,
           "spike": 20, "boost": 12, "hump": 30, "gate": 30, "tilt": 20, "turn": 20, "clockocc": 10, "hopplan": 30,
           "lift2": 10, "width": 8, "sheets": 120}


def _av_floats_want(c):
    """SPEC.md 130.29.4: the cells FL_FLOAT is set on - every FLOOR or WALL whole cell a `float` names that the
    picture draws (a glass tile's is not drawn, nor a membrane's: 130.38.5, the glass tile's rule), on a GF_ANA
    part; and every floating SPLIT cell the picture draws (SPEC.md 130.49.1, AV_SPLIT)"""
    if not c.av:
        return set()
    gc = {p_["at"] for p_ in c.props if p_.get("art") == "glass" or p_["kind"] == SP_KM}
    return {k for k in c.floats if k in c.tiles and k not in gc and (
        c.tiles[k].kind in (KIND_FLOOR, KIND_WALL) if not isinstance(c.tiles[k], Split) else AV_SPLIT)} \
        | set(getattr(c, "rails", ()))


def _av_checks(c, res, tag, off=None, flags_only=False):
    """item 15 (SPEC.md 130.29.7) on one course: the flags, completeness, the model against the tiles,
    WRONG-HIDE, and the gate and the picture against --occ off's compile (OFF)"""
    g = AGrid(world_of(c))
    fgoal = any(k in c.tiles and not isinstance(c.tiles[k], Split) and c.tiles[k].kind == KIND_GOAL for k in c.floats)
    want_f = _av_floats_want(c)
    got_f = {k for k in c.cells if g.raw(*k) is not None and g.raw(*k)[3] & FL_FLOAT}
    path = getattr(c, "pth", None) is not None          # (SPEC.md 130.31: the pathway cuts no occluder, so no model)
    flags_ok = c.av == (not fgoal and not path) and bool(g.gflags & GF_ANA) == c.av and got_f == want_f
    res.append(("15 %s: GF_ANA %s%s; FL_FLOAT on exactly the %d floating FLOOR, WALL and split cells the picture "
                "draws (SPEC.md 130.29.4, 130.49.1)" % (tag, "set" if g.gflags & GF_ANA else "clear",
                                        " (a floating GOAL cell keeps it off)" if fgoal else
                                        " (the pathway: no occluders, 130.31)" if path else "", len(want_f)),
                flags_ok))
    if not c.av or flags_only:
        return
    rcs = [q for q in av_positions(c.reach, g, c.slabcells)
           if (q.wx, q.wy) not in getattr(c, "noocc", ())]      # (SPEC.md 130.53: the proofs pass them over)
    tried, miss = av_proof(c, g, rcs)
    res.append(("15 %s: COMPLETENESS - at %d VOID positions' every height, %d (pixel, cell) cases the rule lays are "
                "each hidden by the model read from the PART or laid by a shipped record%s" % (
                    tag, len(rcs), tried, "" if not miss else " -- MISSED %s" % miss), tried > 0 and not miss))
    n, bad = av_tile_edges(c, g)
    res.append(("15 %s: the model's edges and heights read from the part are the tiles' (the top polygons' first "
                "lines, %d columns, the end columns apart)%s" % (tag, n, "" if not bad else " -- %s" % bad[:3]),
                n > 0 and not bad))
    nb, nw, worst, npos = av_wrong(c, g)
    share = nw / float(nb) if nb else 0.0
    res.append(("15 %s: WRONG-HIDE %.4f%% of the ball's lit pixels over %d VOID positions (%d of %d), at most "
                "%.2f%%; the worst position %s" % (
                    tag, 100 * share, npos, nw, nb, 100 * OCC_WRONG_MAX,
                    "%.1f%% of the ball (cell %s at %d px, top-left %d, %d)" % (100 * worst[0], worst[1], worst[2],
                                                                                worst[3], worst[4])
                    if worst else "none"), share <= OCC_WRONG_MAX))
    c.av_figs = (len(rcs), tried, share, worst)
    if off is not None:
        same_g = all((c.cells[k][3] & ~FL_FLOAT) == off.cells[k][3] and c.cells[k][:3] == off.cells[k][:3]
                     for k in c.cells) and set(c.cells) == set(off.cells)
        same_p = c.map == off.map and c.blocks == off.blocks and c.y0 == off.y0 and c.x0 == off.x0
        res.append(("15 %s: against --occ off: every grid byte but FL_FLOAT the same (OCC, OCCG, SAFE, OBS: the "
                    "gate opens on today's frames), the picture, map and blocks the same; records %d -> %d, RAM "
                    "%d -> %d" % (tag, len(off.model["recs"]), len(c.model["recs"]), len(off.cga), len(c.cga)),
                    same_g and same_p))


# =============================================================================
# SPEC.md 130.35: the see-through GUARD RAIL - --selfcheck's section `guard` (item 16)
# =============================================================================

_GBASE = 'course G "g"\nwidth 64\nfloor rect 4 8 14 11 flat 4\nstart 6 9\n'
# the check's course: a walkway W (wy 8 - 10) at 4 units, its BACK edge guarded (wy 7) and its FRONT edge (wy 11);
# behind the back rail the gap (wy 6) and a lower path L at 0 units (wy 5): low enough to stand behind the rail on screen
_GCRS = _GBASE + 'guard rect 4 7 14 8\nguard rect 4 11 14 12\nfloor rect 4 5 14 6 flat 0\n'


def _guard_cases():
    """SPEC.md 130.35.1's refusals, each a string here"""
    G = _GBASE
    return [
        ("a guard on a solid cell", G + "guard rect 4 10 14 11\n", "stands on a solid cell"),
        ("a guard that guards nothing", G + "guard tile 20 20\n", "shares no edge with a floor"),
        ("a guard beside a ramp", G + "floor rect 4 5 14 7 ramp y 5 7 2 4\nguard rect 4 7 14 8\n",
         "not a whole FLAT floor"),
        ("a floor at a guard's corner with no rail through it", G + "floor tile 15 7 flat 4\nguard tile 14 8\n",
         "at a corner with no rail"),
        ("a guard rail 1 unit high (under rubber's boost)", G + "guard rect 4 7 14 8 height 1\n",
         "a guard rail is 1.5 - 3.0 units"),
        ("a guard with a side clause", G + "guard rect 4 7 14 8 side +y\n", "guard takes a shape and [height"),
        ("a guard laid twice", G + "guard rect 4 7 14 8\nguard tile 5 7\n", "laid twice"),
    ]


def _guard_ball(c, wx, wy, z, air):
    """a ball's top-left with its contact at the centre of tile (wx, wy), z px (SPEC.md 130.10.2)"""
    gx, gy = 16 * wx + 8, 16 * wy + 8
    return gx - gy + c.x0 - 8, (gx + gy) // 2 - z + c.y0 - 13


def guard_seen(c, wx, wy, z, air, cell=None):
    """a ball at the centre of (wx, wy), z px, composited as the guest does (the records, and SPEC.md 130.29's
    model when CELL is its VOID centre cell): -> (its lit pixels, those laid over, those laid over that are no
    GUARD RAIL's pixel)"""
    px, py = _guard_ball(c, wx, wy, z, air)
    sb = wx + wy
    ball = ball_pixels(px, py)
    out = composite(c, px, py, sb, z, air, via="records", cell=cell)
    rail = set()
    for (gx_, gy_), t in guard_cells(c.tiles).items():
        rail |= {(x, y + c.y0) for (x, y) in guard_pix(t, gx_, gy_, c.x0)}
    hid = {p for p, k in ball.items() if out[p] != k}
    return len(ball), hid, {p for p in hid if p not in rail}


def guard_flights(c, at, keys, rail_row, mat=MAT_RUBBER, hop=None, n=110, firsts=range(0, 24, 2), gaps=range(2, 34)):
    """every Hop (Space at step i) and, after it, a second press j steps later (a boost at its contact, or a
    contact Hop) by a ball poked at the centre of AT and driven by KEYS into a guard rail along cell row
    RAIL_ROW (wy): -> (the highest contact point over AT's floor, px, over every run; the runs that reached the
    rail's row or past it, or fell; the runs with a boost)"""
    top, crossed, boosts = 0, 0, 0
    z0 = None
    sgn = 1 if rail_row > at[1] else -1
    for i in firsts:
        for d in gaps:
            p = Physics(c, mat=mat).poke(*at)
            if hop is not None:
                p.hop = hop
            if z0 is None:
                z0 = p.gz >> 8
            bad = False
            for k in range(n):
                p.step(keys | (K_HOP if k in (i, i + d) else 0))
                top = max(top, (p.gz >> 8) - z0)
                if sgn * ((p.gy >> 12) - rail_row) >= 0 or p.nfall:
                    bad = True
            crossed += bad
            boosts += bool(p.nboost)
    return top, crossed, boosts


def _guard_checks(res, _hack=None):
    """item 16 (SPEC.md 130.35.6): the grammar's refusals are item 2's; here the picture, the occluders, AV and the
    physics on _GCRS, and their red arms"""
    hk = dict(_hack or {}, no_finish=True)
    floor_arm = hk.pop("guardfloor", False)
    c = compile_course(_GCRS, fname="<guard rails>", _hack=hk)
    if floor_arm:                                   # (a red arm: the physics reads each guard cell as a FLOOR at its
        g = Grid(c.cga)                             # top - the part's grid patched, the picture's untouched)
        g.p = bytearray(c.cga)
        for (wx, wy) in guard_cells(c.tiles):
            o = g.rowtab[wx + wy - g.smin] + 4 * ((wx - wy - g.amin) >> 1)
            g.p[o + 2] = (g.p[o + 2] & 0xF0) | KIND_FLOOR
        c._grid = g
    H = 8 * GUARD_H2 // 2                           # the rail's height, px (16)
    gc = guard_cells(c.tiles)
    flo = all(c.cells[k][3] & FL_FLOAT for k in gc) and c.av
    res.append(("16 guard: %d GUARD RAIL cells, each a WALL %d px over the walkway with FL_FLOAT set (AV passes "
                "over it, SPEC.md 130.35.4)" % (len(gc), H), len(gc) == 20 and flo and all(
                    c.cells[k][2] & 15 == KIND_WALL and 4 * (t.z0 - t.guard[1]) == H for k, t in gc.items())))
    # the picture: no pixel of the guard cells but the rail's (its neighbours' faces hang into the open cell)
    rail = {}
    for (wx, wy), t in gc.items():
        rail.update({(x, y + c.y0): k for (x, y), k in guard_pix(t, wx, wy, c.x0).items()})
    own = sum(1 for y in range(c.lines) for x in range(c.width)
              if c.sbuf[y][x] in {wx + wy for (wx, wy) in gc} and c.tbuf[y][x] == 48 and (x, y) not in rail)
    drawn = all(c.pic[y][x] == k for (x, y), k in rail.items())
    res.append(("16 guard: the picture holds every rail pixel (%d) and no other pixel at the rail's key and top - "
                "posts and bars, the rest of the cell the open edge" % len(rail), drawn and not own))
    # the occluders: a ball BEHIND each rail is laid over by the rail's own pixels ONLY and shows through the
    # gaps; a ball in FRONT of the back rail is laid over by nothing
    rows = []
    for what, wx, wy, z, air, cell in (("on L, behind the back rail", 8, 5, 0, False, None),
                                       ("on the walkway, behind the front rail", 8, 10, 32, False, None),
                                       ("over the gap, behind the back rail (the AV model)", 8, 6,
                                        min(12, max(r.zhi for r in c.reach if (r.wx, r.wy) == (8, 6))), True, (8, 6))):
        n, hid, other = guard_seen(c, wx, wy, z, air, cell)
        rows.append((what, len(hid), n, len(other)))
    ok_b = all(h > 0 and not o and n - h >= n // 2 for _w, h, n, o in rows)
    res.append(("16 guard: a ball behind a rail is laid over by the rail's pixels alone and is SEEN through its "
                "gaps - %s" % "; ".join("%s: %d of %d lit px laid, %d not the rail's" % r for r in rows), ok_b))
    n, hid, _o = guard_seen(c, 8, 8, 32, False)
    n2, hid2, _o2 = guard_seen(c, 8, 8, 44, True)
    res.append(("16 guard: a ball IN FRONT of the back rail (on the walkway's back row, grounded and in the air at "
                "44 px) is laid over by nothing (%d and %d of %d px)" % (len(hid), len(hid2), n), not hid and not hid2))
    # the physics: no Hop, contact Hop or boost carries a ball into a rail's row; rubber's highest flight from the
    # walkway stays under the drawn top bar; the jump pickup's Hop (PU_JHOP) and the jump with the boost are
    # reported against it (a WALL is a column at every height: they cannot cross either)
    fl = []
    for nm, mat, hop in (("rubber", MAT_RUBBER, None), ("steel", MAT_STEEL, None), ("glass", MAT_GLASS, None),
                         ("the jump pickup (rubber)", MAT_RUBBER, PU_JHOP)):
        for side, keys, row in (("back", K_U | K_R, 7), ("front", K_D | K_L, 11)):
            top, crossed, nb = guard_flights(c, (8, 9), keys, row, mat, hop)
            fl.append((nm, side, top, crossed, nb))
    rub = [f for f in fl if f[0] == "rubber"]
    res.append(("16 guard: no ball crosses a rail, any Hop and second press (a boost at its contact) - %s; rubber's "
                "highest flight %d px, under the %d px bar%s" % (
                    "; ".join("%s %s: apex %d px, %d runs boosted" % (f[0], f[1], f[2], f[4]) for f in fl),
                    max(f[2] for f in rub), H,
                    "" if not any(f[3] for f in fl) else " -- CROSSED: %s" % [f[:2] for f in fl if f[3]]),
                not any(f[3] for f in fl) and max(f[2] for f in rub) < H and all(f[4] for f in rub)))
    return c


# SPEC.md 130.35.9 - 130.35.10: TWO HEIGHTS and the WATER SEAL - a walkway W (x 4 - 12, wy 8 - 10) at 4 units, the
# lower ground L (1 unit) in front of it and round the water; a strip of two-height guards along W's front (wy 11:
# W behind, L in front), its last cell (12, 11) round a CORNER (W behind, L in front and to its right); a water
# column (13, 8 - 10, top 4, bed 1) beside W, its arch +y onto (13, 11) GUARDED; one-height guards behind W and
# the water, and down the water's right side (14, 8 - 9), its last cell (14, 10) round a corner onto L
_G2CRS = ('course G "g"\nwidth 64\norigin 288\nuses water\nfloor rect 4 8 13 11 flat 4\n'
          'floor rect 4 12 13 14 flat 1\nfloor rect 13 11 17 15 flat 1\nwater rect 13 8 14 11 top 4 bed 1\n'
          'arch 13 10 +y guard\nguard rect 4 7 14 8\nguard rect 14 8 15 11\nguard rect 4 11 13 12\nstart 5 9\n')


def _guard2_checks(res):
    """SPEC.md 130.35.9 - 130.35.10's items on _G2CRS (each red under its arm, _sc_guard)"""
    c = compile_course(_G2CRS, fname="<guard rails: two heights>", _hack={"no_finish": True})
    gc = guard_cells(c.tiles)
    two = {k: t for k, t in gc.items() if len(set(t.guard[2])) > 1}
    want = dict([((x, 11), (("N", "S"), (8, 2))) for x in range(4, 12)]
                + [((12, 11), (("N", "E", "S"), (8, 2, 2))), ((14, 10), (("W", "S"), (8, 2)))])
    ok = sorted(two) == sorted(want) and all(two[k].guard[0] == e and two[k].guard[2] == b and two[k].z0 == 12
                                              and two[k].guard[1] == 8 and c.cells[k][2] & 15 == KIND_WALL
                                              and c.cells[k][3] & FL_FLOAT for k, (e, b) in want.items())
    res.append(("16 guard (130.35.9): TWO HEIGHTS - %d guard cells beside a floor at 4 units and one at 1, along one "
                "side (wy 11) and round two corners ((12, 11), (14, 10)): each a WALL 2 units over the HIGHER floor, "
                "its rail edges every edge it shares with a floor, each from that floor" % len(two), ok))
    # the picture: every rail pixel drawn, and a lower edge's rail reaching down to the lower floor's line
    rail = {}
    for (wx, wy), t in gc.items():
        rail.update({(x, y + c.y0): k for (x, y), k in guard_pix(t, wx, wy, c.x0).items()})
    drawn = all(c.pic[y][x] == k for (x, y), k in rail.items())
    t6 = gc[(6, 11)]
    ys = [y for (x, y) in guard_pix(t6, 6, 11, c.x0)]
    span = max(ys) - min(ys) + 1
    tall = 4 * (t6.z0 - 2) - 1                      # (the S edge's posts: from the lower floor's line up the rail)
    res.append(("16 guard (130.35.9): the picture holds every rail pixel (%d); a two-height cell's rail spans %d "
                "lines - its lower edge's posts and bars down to the lower floor's line (at least %d)"
                % (len(rail), span, tall), drawn and span >= tall))
    # the physics: no ball crosses the two-height strip from the walkway
    fl = []
    for nm, mat, hop in (("rubber", MAT_RUBBER, None), ("glass", MAT_GLASS, None), ("steel", MAT_STEEL, None),
                         ("the jump pickup (rubber)", MAT_RUBBER, PU_JHOP)):
        top, crossed, nb = guard_flights(c, (8, 9), K_D | K_L, 11, mat, hop, firsts=range(0, 24, 4),
                                         gaps=range(2, 34, 2))
        fl.append((nm, top, crossed, nb))
    res.append(("16 guard (130.35.9): no ball crosses the two-height strip from the walkway, any Hop and second "
                "press - %s" % "; ".join("%s: apex %d px, %d crossed" % (f[0], f[1], f[2]) for f in fl),
                not any(f[2] for f in fl)))
    # THE WATER SEAL: the record, the rail's picture, and rubber and glass held on the water while steel sinks
    # under the rail and rolls out of the arch onto L
    wr = [r for r in c.part["props"] if r["kind"] == FK_WATER]
    rec = {r["at"]: r.get("wg", 0) for r in wr}
    res.append(("16 guard (130.35.10): the guarded arch's water record carries +20 WR_GUARDY (%s) and no other "
                "column a guard bit" % sorted(rec.items()),
                rec == {(13, 8): 0, (13, 9): 0, (13, 10): WR_GUARDY}))
    t = c.tiles[(13, 10)]
    ap = guard_pix(arch_guard_tile(t, (13, 10), 2, GUARD_H2), 13, 11, c.x0)
    ok_p = all(c.pic[y + c.y0][x] == k and c.sbuf[y + c.y0][x] == 24 for (x, y), k in ap.items()
               if (x, y + c.y0) not in rail)            # (a corner column a guard cell's rail draws is that rail's)
    res.append(("16 guard (130.35.10): the picture holds the rail along the column's front top (%d px), keyed the "
                "exit's s (24, the water's art's s + 1)" % len(ap), ok_p and len(ap) > 40))
    held = []
    for nm, mat in (("rubber", MAT_RUBBER), ("glass", MAT_GLASS)):
        for kn, keys in (("+y", K_D), ("+y, -x", K_D | K_L), ("+y, +x", K_D | K_R)):
            top, crossed, nb = guard_flights(c, (13, 10), keys, 11, mat, firsts=range(0, 24, 4),
                                             gaps=range(2, 34, 4))
            held.append((nm, kn, crossed))
    out = []
    for nm, mat in (("steel", MAT_STEEL),):
        p = Physics(c, mat=mat).poke(13, 9)
        n = 0
        for n in range(400):
            p.step(K_D)
            if p.nfall or (p.gy >> 12) >= 12:
                break
        out.append((nm, (p.gx >> 12, p.gy >> 12), p.nfall, n))
    sok = all(cl == (13, 12) or cl[1] >= 12 for _n, cl, nf, _k in out) and not any(nf for _n, _c, nf, _k in out)
    res.append(("16 guard (130.35.10): THE WATER SEAL - rubber and glass on the water, driven at the guarded face "
                "with every Hop and second press, never reach the exit (%s); steel sinks under the rail and rolls "
                "out of the arch onto L (%s)" % ("; ".join("%s %s: %d crossed" % h for h in held),
                                                  "; ".join("%s at %s, %d falls, step %d" % o for o in out)),
                not any(h[2] for h in held) and sok))
    return c


def _sc_guard(X, res):
    """--selfcheck's section `guard`: item 16 (SPEC.md 130.35.6), the GUARD RAIL, and its red arms; 130.35.9 -
    130.35.10's TWO HEIGHTS and the WATER SEAL, and theirs"""
    global _GUARD_ONEZ, _GUARD_FLAT, _WG_NOWALL, _WG_ALLMAT
    _guard2_checks(res)
    for what, sw, want in (("a guard beside two heights refused again (one height)", "_GUARD_ONEZ", "compile"),
                           ("the lower edges drawn from the higher floor", "_GUARD_FLAT", "down to the lower floor"),
                           ("the guarded arch's exit left OPEN (no wall for a ball on the water)", "_WG_NOWALL",
                            "THE WATER SEAL"),
                           ("the guarded arch walled for STEEL too", "_WG_ALLMAT", "THE WATER SEAL")):
        r_ = []
        globals()[sw] = True
        try:
            _guard2_checks(r_)
        except CourseError as e:
            r_.append(("compile: %s" % e, False))
        finally:
            _GUARD_ONEZ = _GUARD_FLAT = _WG_NOWALL = _WG_ALLMAT = False
        caught = [w for w, g in r_ if not g]
        res.append(("16 guard negative control (130.35.9 - 130.35.10): %s - caught (%s)" % (
            what, "; ".join(w[:70] for w in caught) or "NOT CAUGHT"), any(want in w for w in caught)))
    _guard_checks(res)
    for what, hack, want in (
            ("the guard drawn as the solid wall it is", {"guardsolid": True}, "SEEN through its gaps"),
            ("the rail keyed a row nearer (in front of the ball before it)", {"guardfront": True}, "IN FRONT"),
            ("FL_FLOAT not set on the guard cells (AV hides the gaps)", {"noguardfloat": True}, "SEEN through"),
            ("the guard a FLOOR in the grid, not a WALL (the jump climbs onto it)", {"guardfloor": True}, "CROSSED")):
        r_ = []
        try:
            _guard_checks(r_, _hack=hack)
        except CourseError as e:
            r_.append(("compile: %s" % e, False))
        caught = [w for w, g in r_ if not g]
        res.append(("16 guard negative control: %s - caught (%s)" % (what, "; ".join(w[:60] for w in caught)
                                                                     or "NOT CAUGHT"),
                    any(want in w for w in caught)))


def _sc_av(X, res):
    """--selfcheck's section `av`: item 15 (SPEC.md 130.29.7) - AV on every course, the pathway and the title,
    and its negative controls"""
    global _AV_FLAT, _AV_NODITHER
    courses = X.courses
    every = list(courses)
    try:
        every.append(compile_course(os.path.join(COURSE_DIR, "path.bbc"), crsinfo=[(c.name, c.title)
                                                                                   for c in courses]))
        every[-1].name = every[-1].name or "PATH"
        every.append(compile_course(os.path.join(COURSE_DIR, "title.bbc")))
    except CourseError as e:
        res.append(("15 the pathway and the title compile (%s)" % e, False))
    for c in every:                             # (sheetmax: a SHEETED course's picture under --occ off is
        off = compile_course(c.fname if os.path.isabs(c.fname) else os.path.join(ROOT, c.fname),   # larger
                             _hack={"occ": "off", "sheetmax": len(MAGIC_SHEETS)},   # still - TTALL's 94,592
                             crsinfo=[(q.name, q.title) for q in courses]       # bytes, past 2 sheets: 130.30.12)
                             if c.pth is not None else None)
        _av_checks(c, res, c.name, off)
    byname = {c.name: c for c in courses}
    # the negative controls, each red where item 15 says
    first = byname.get("FIRST")
    if first is not None:
        nr = compile_course(os.path.join(ROOT, first.fname) if not os.path.isabs(first.fname) else first.fname,
                            _hack={"noresidual": True})
        _t, miss = av_proof(nr)
        res.append(("15 FIRST negative control: the residual dropped (today's records outside the VOID cells "
                    "alone) is caught by COMPLETENESS (%s)" % (miss[:1] if miss else "not caught"), bool(miss)))
    bench = byname.get("BENCH")
    if bench is not None:
        g = AGrid(world_of(bench))
        rcs = av_positions(bench.reach, g, bench.slabcells)
        front = g.front
        g.front = lambda wx, wy, depth=None: front(wx, wy, 3)
        try:
            _t, miss = av_proof(bench, g, rcs)
        finally:
            g.front = front
        res.append(("15 BENCH negative control: the guest's model at depth 3 against the residual cut for depth 4 "
                    "is caught by COMPLETENESS (%s)" % (miss[:1] if miss else "not caught"), bool(miss)))
    trial = byname.get("TRIAL")
    if trial is not None:
        _AV_FLAT = True
        try:
            _n, bad = av_tile_edges(trial)
        finally:
            _AV_FLAT = False
        res.append(("15 TRIAL negative control: the model reading every cell as flat is caught by the comparison "
                    "with the tiles on its ramp (%s)" % (bad[:1] if bad else "not caught"), bool(bad)))
    play = byname.get("PLAY")
    if play is not None:                        # (counting the floating cells instead moves 0 - 4 ball pixels of
        nf = compile_course(os.path.join(ROOT, play.fname) if not os.path.isabs(play.fname) else play.fname,
                            _hack={"nofloatflag": True})            # today's lattices: the flag is the check)
        r_ = []
        _av_checks(nf, r_, "PLAY (no FL_FLOAT)", flags_only=True)
        res.append(("15 PLAY negative control: the compile with FL_FLOAT never set is caught by the flags' check "
                    "(its platform's %d floating cells)" % len(_av_floats_want(play)), not r_[0][1]))
    mill = byname.get("MILL")
    if mill is not None:
        pos = [q for q in getattr(mill, "_vis_pos", ()) if AGrid(world_of(mill)).runs(*q[5])]
        if not pos:
            for rc in av_positions(mill.reach, AGrid(world_of(mill)), mill.slabcells):
                gx, gy = (16 * rc.wx + 8) << 8, (16 * rc.wy + 8) << 8
                for z in sorted({rc.zlo, rc.zhi, (rc.zlo + rc.zhi) // 2}):
                    pos.append((((gx - gy) >> 8) + mill.x0 - 8, (((gx + gy) >> 1) >> 8) - z + mill.y0 - 13, rc.s,
                                z, 1, (rc.wx, rc.wy)))
        _AV_NODITHER = True
        try:
            hit = next((q for q in pos if composite(mill, *q[:5], ghost=True, cell=q[5])
                        != card_composite(mill, *q[:5], cell=q[5])), None)
        finally:
            _AV_NODITHER = False
        res.append(("15 MILL negative control: the model's masks laid WITHOUT the checker disagree with the dithered "
                    "composite at a VOID position (item 11's comparison)%s" % (
                        " (px %d, py %d)" % hit[:2] if hit else " -- not caught"), hit is not None))

def _kit_canon(c):
    """SPEC.md 130.37.7: a course's RAM form with every piece NAMED BY ITS BYTES instead of its place - the
    map's words, the lanes' pose maps, the records' masks and the FIELD cells' tables - so two compiles that
    differ in piece order alone canonicalise the same"""
    m = c.model
    blk = [m["blocks"][i:i + 16] for i in range(0, len(m["blocks"]), 16)]
    tab = [m["ftabs"][i:i + FTAB] for i in range(0, len(m["ftabs"]), FTAB)]
    cells = bytearray(m["cells"])
    ftab = []
    for i in range(0, len(cells), 4):
        if cells[i + 2] & 15 == KIND_FIELD:
            ftab.append(tab[fshape(cells[i + 1])])
            cells[i + 1] &= 0x70                    # (the symmetry stays)
    props = None
    if m["props"]:
        pb = bytearray(m["props"]["blob"])
        pw = {}
        for o in m["props"]["blk"]:
            pw[o] = blk[struct.unpack_from("<H", pb, o)[0] // 16]
            pb[o:o + 2] = b"\0\0"
        props = (bytes(pb), sorted(pw.items()), sorted(m["props"]["self"]))
    rest = dict((k, v) for k, v in m.items() if k not in ("idx", "blocks", "recs", "masks", "cells", "ftabs",
                                                           "props", "kit", "ways"))
    return (tuple(blk[i] for i in m["idx"]), sorted(blk),
            tuple((br, col, s, top, m["masks"][mi]) for br, col, s, top, mi in m["recs"]), sorted(m["masks"]),
            bytes(cells), tuple(ftab), sorted(tab), props, repr(sorted(rest.items())),
            len(c.cga), len(c.wcga) if c.split else 0)


def _sc_kit(X, res):
    """--selfcheck's section `kit` (selfcheck(): a fork of its state after the compile): item 17, SPEC.md
    130.37.7 - THE STANDARD KIT"""
    kit = kit_load()
    part = kit_part(kit)
    # the part: its header names each class's pieces where they are, and the build ships it
    hdr_ok = part[:4] == b"BZK1" and struct.unpack_from("<H", part, 4)[0] == len(KIT_TAGS)
    off = KIT_HDR
    for j, t in enumerate(KIT_TAGS):
        tg, z, sz, n, o = struct.unpack_from("<BBHHH", part, 6 + 8 * j)
        hdr_ok = hdr_ok and (chr(tg), z, sz, n, o) == (t, 0, KIT_SIZE[t], len(kit[t]), off) \
            and part[o:o + sz * n] == b"".join(kit[t])
        off += sz * n
    res.append(("16 the kit's part BZK1 (%d bytes: %s) names each class's pieces where they lie, block 0 black, "
                "and the build ships it, the replay log's zero tail after it (130.11.12.1), as BZKIT.BIN" % (
                    len(part), ", ".join("%d %s" % (len(kit[t]), t) for t in KIT_TAGS)),
                hdr_ok and off == len(part) and X.a[1].get("BZKIT.BIN") == kit_file(kit)
                and (not kit["B"] or kit["B"][0] == bytes(16))))
    play = [c for c in X.courses if c.kit_use is not None]
    # every play course at the ONE alignment, and its kit pieces at its sections' heads (read_part's rules)
    res.append(("16 every play course's Y0 is %d (mod 8), the kit's alignment (%s)" % (KIT_Y0, ", ".join(
        "%s %d" % (c.name, c.y0) for c in play)), all(c.y0 % 8 == KIT_Y0 for c in play)))
    # the RAM form is the kit-less compile's, the pieces in another order and nothing else moved
    same, notes = [], []
    for c in play:
        src = c.fname if os.path.isabs(c.fname) else os.path.join(ROOT, c.fname)
        try:
            c0 = compile_course(src, _hack={"nokit": True})
            if c.model.get("song"):                 # (SPEC.md 130.50.3: the same song, as the build attached)
                attach_song(c0, c.model["song"])
        except CourseError as e:
            same.append(False)
            notes.append("%s: %s" % (c.name, e))
            continue
        ok = _kit_canon(c) == _kit_canon(c0) and c0.model["kit"] == {}
        same.append(ok)
        if not ok:
            notes.append(c.name)
    res.append(("16 every play course's RAM form is its kit-less compile's with each class's pieces in kit order "
                "and nothing else moved: the map, the lanes' pose maps, the records' masks and the FIELD cells' "
                "tables name the same bytes (%s)%s" % (", ".join(c.name for c in play),
                                                       " -- DIFFER: %s" % notes if notes else ""), all(same)))
    # the stored form: KITREF expands, in place, to the RAM form; the guest's order (bitmap to scratch first)
    # is the one that does
    exp, used = True, []
    for c in play:
        for st, ram in ((c.stored, c.cga), (c.wstored, c.wcga)):
            if st is None:
                continue
            exp = exp and expand(st, c.name, sim=True) == ram
        used.append("%s B %d K %d F %d" % (c.name, len(c.kit_use["B"]), len(c.kit_use["K"]), len(c.kit_use["F"])))
    res.append(("16 every play course's stored form expands IN PLACE to its RAM form with the kit's pieces copied "
                "in (the simulation: nothing written before it is read; kit pieces named: %s)" % "; ".join(used),
                exp))
    # THE RED ARMS: a bit of a bitmap off, the kit a piece short, a piece changed, the bitmap read in place
    red = {"bit": [], "short": [], "changed": [], "inplace": []}
    for c in play:
        for st, ram in ((c.stored, c.cga), (c.wstored, c.wcga)):
            if st is None:
                continue
            do_, ns = struct.unpack_from("<HH", st, 38)
            for j in range(ns):
                tag, form, so, ln, dl = struct.unpack_from("<BBHHH", st, do_ + DIRENT * j)
                t = chr(tag)
                if form != F_KITREF:
                    continue
                at = so + ln - dl                   # the bitmap
                bm = bytearray(st[at:at + kit_bmlen(len(kit[t]))])
                i = next(i for i in range(8 * len(bm)) if bm[i >> 3] >> (i & 7) & 1)
                b2 = bytearray(st)
                b2[at + (i >> 3)] &= ~(1 << (i & 7)) & 255
                try:
                    red["bit"].append(expand(bytes(b2), c.name) != ram)
                except CourseError:
                    red["bit"].append(True)
                last = max(i for i in range(8 * len(bm)) if bm[i >> 3] >> (i & 7) & 1)
                short = dict(kit, **{t: kit[t][:last]})
                try:
                    red["short"].append(expand(st, c.name, kit=short) != ram)
                except CourseError:
                    red["short"].append(True)
                chg = dict(kit, **{t: kit[t][:i] + [bytes(x ^ 0xFF for x in kit[t][i])] + kit[t][i + 1:]})
                saved = _KITS.get(KIT_FILE)
                _KITS[KIT_FILE] = chg
                try:
                    read_parts(c.cga, c.wcga, c.name) if c.split else read_part(c.cga, c.name)
                    red["changed"].append(False)
                except CourseError as e:
                    red["changed"].append("not in the kit" in str(e))
                finally:
                    _KITS[KIT_FILE] = saved
                try:
                    expand(st, c.name, sim=True, _hack={"kit_inplace": True})
                    red["inplace"].append(False)
                except CourseError:
                    red["inplace"].append(True)
    res.append(("16 negative controls on every KITREF section (%d): a bitmap bit cleared expands to another RAM "
                "form, a kit one piece short of the last one named and a kit with a named piece changed are "
                "refused, and the bitmap read IN PLACE (not copied out first) writes over a byte it has not read "
                "on %d of them" % (len(red["bit"]), sum(red["inplace"])),
                red["bit"] and all(red["bit"]) and all(red["short"]) and all(red["changed"]) and any(red["inplace"])))
    # the kit's source is the generator's (REPORTED: the kit may lag the courses; `bbcourse.py kit` re-cuts it)
    print("    kit: %s - %d blocks, %d masks, %d tables; BZKIT.BIN %d bytes (regenerate with `python3 "
          "tools/bbcourse.py kit` after a course's art changes, SPEC.md 130.37.2)" % (
              os.path.relpath(KIT_FILE, ROOT), len(kit["B"]), len(kit["K"]), len(kit["F"]), len(part)))


def _sc_cache(X, res):
    """--selfcheck's section `cache`: the compile cache's key (cache_key) names every input, so a hit is the
    compile it stands for - each input moved by itself moves the key, and an entry comes back as the
    compile it was"""
    import copy
    import tempfile
    p = os.path.join(COURSE_DIR, "first.bbc")
    mode, _CACHE["mode"] = _CACHE["mode"], "rw"     # (on, whatever BB_CACHE says: this is the key's proof)
    try:
        k0 = cache_key(p, None, True, None, None)
        moved = {}
        with tempfile.TemporaryDirectory() as td:
            q = os.path.join(td, "first.bbc")
            with open(p, "rb") as f:
                txt = f.read()
            with open(q, "wb") as f:
                f.write(txt)
            kq = cache_key(q, None, True, None, None)
            with open(q, "wb") as f:                # one byte of the course
                f.write(txt.replace(b"course ", b"course  ", 1))
            moved["the course's text (one byte)"] = cache_key(q, None, True, None, None) != kq
        moved["the course's name"] = kq != k0
        moved["the tools' source (TOOL_HASH)"] = cache_key(p, None, True, None, None,
                                                           _tool="0" * 20) != k0
        moved["a file under courses/ or demos/, the font or the Makefile"] = cache_key(
            p, None, True, None, None, _inputs="0") != k0
        moved["occluders"] = cache_key(p, None, False, None, None) != k0
        moved["a _hack"] = cache_key(p, None, True, {"y0add": 0}, None) != k0
        moved["crsinfo"] = cache_key(p, None, True, None, [("X", "x")]) != k0
        moved["the course as text, not a file"] = cache_key(open(p).read(), "first", True, None, None) != k0
        _CHECKS_OFF.add("flat")
        try:
            moved["a refusal switched off (_CHECKS_OFF)"] = cache_key(p, None, True, None, None) != k0
        finally:
            _CHECKS_OFF.discard("flat")
        keep = copy.deepcopy(MATERIALS[MAT_RUBBER])
        MATERIALS[MAT_RUBBER]["HOP"] += 1
        try:
            moved["a material's field (MATERIALS, as --tune)"] = cache_key(p, None, True, None, None) != k0
        finally:
            MATERIALS[MAT_RUBBER].update(keep)
        back = cache_key(p, None, True, None, None) == k0
        with _famtest():                            # (last: its class attribute stays set, a later key's miss)
            moved["a family row registered (FAM_BY_NAME)"] = cache_key(p, None, True, None, None) != k0
        imp = {"bbcourse", "bonanza_assets", "os88lz", "os88font", "bbmusic"} <= set(TOOL_MODULES)
        res.append(("1 the compile cache's key moves with each input by itself (%s), comes back when they do, and "
                    "TOOL_HASH covers %s" % ("; ".join("%s %s" % (w, "moves" if v else "DOES NOT MOVE")
                                                       for w, v in moved.items()), ", ".join(TOOL_MODULES)),
                    all(moved.values()) and back and imp))
        # an entry is the compile it was: FIRST compiled fresh, written, read back - the same part, picture
        # and records - and a FALSE entry under another key is never what a lookup returns
        global CACHE_DIR
        keepdir = CACHE_DIR
        with tempfile.TemporaryDirectory() as td:
            CACHE_DIR = td
            try:
                c = _compile_y0(p, None, True, None, None)
                cache_put(k0, c)
                h = cache_get(k0)
                same = h is not None and (h.cga, h.stored, h.ident, h.pic, [r["mask"] for r in h.records]) == (
                    c.cga, c.stored, c.ident, c.pic, [r["mask"] for r in c.records])
                cache_put((k0[0], "f" * 64), X.courses[0])
                other = cache_get((k0[0], "e" * 64)) is None and cache_get(k0).cga == c.cga
                ops = all(callable(o[3]) for o in h.ops if len(o) > 3 and o[3] is not None)
            finally:
                CACHE_DIR = keepdir
        res.append(("1 a cache entry is its compile: FIRST written and read back has the same RAM and stored "
                    "parts, identity, picture and records (its closures restored), and a lookup under another "
                    "key misses", same and other and ops))
    finally:
        _CACHE["mode"] = mode


MG_TEST = os.path.join(ROOT, "apps", "bonanza", "courses", "magnets.bbc")   # the BZMAGNET=1 knob's course
# MAGNETS' scenes on it (SPEC.md 130.33.10): (name, material, the poke: tile and ground velocity, steps), the
# same as tests/bonanza_phys.py's MG_SCENES (which holds the guest to the model on each)
MG_SC = (("hover-steel", MAT_STEEL, (15, 22, 300, 0), 120), ("hover-rubber", MAT_RUBBER, (15, 22, 300, 0), 120),
         ("pull-steel", MAT_STEEL, (11, 12, 0, 160), 140), ("pull-fast", MAT_STEEL, (11, 12, 0, 384), 60),
         ("pull-rubber", MAT_RUBBER, (11, 12, 0, 160), 140), ("rail-steel", MAT_STEEL, (20, 10, 0, 200), 150),
         ("rail-rubber", MAT_RUBBER, (20, 10, 0, 200), 150))


def _mg_cases():
    """(what, text, the refusal's substring): 130.33.7's refusals"""
    C = _W4C + "uses magnet\n"
    return [
        ("a magnet with no face", C + "prop magnet 6 6\n", "takes <wx> <wy> face"),
        ("a magnet facing up", C + "prop magnet 6 6 face up\n", "face is +x, -x, +y or -y"),
        ("a hanging magnet with no arm", C + "prop magnet 6 6 face down\n", "names its arm's way"),
        ("a range of 9", C + "prop magnet 6 6 face +x range 9\n", "range is 1 - 8"),
        ("a strength of 0", C + "prop magnet 6 6 face +x strength 0\n", "strength is 1 - 127"),
        ("a strength of 128", C + "prop magnet 6 6 face +x strength 128\n", "strength is 1 - 127"),
        ("a magnet with a reset class", C + "prop magnet 6 6 face +x reset attempt\n", "takes no `reset`"),
        ("a magnet with a word of no meaning", C + "prop magnet 6 6 face +x fast\n", "not 'fast'"),
        ("a magnet on a ramp", C + "prop magnet 14 6 face +x\n", "not a FLAT FLOOR"),
        ("two fields meeting", C + "prop magnet 6 6 face +x range 3\nprop magnet 10 6 face -x range 3\n",
         "one field a cell"),
        ("a field over another magnet's post", C + "prop magnet 6 6 face +x range 3\nprop magnet 8 6 face +y\n",
         "holds the magnet on line"),
        ("a field off the grid", C + "prop magnet 4 6 face -x range 5\n", "off the grid"),
        ("a hanging magnet of range 2", C + "prop magnet 6 6 face down +x range 2\n", "ONE head over one cell"),
    ]


class _MgArm(MagnetFamily):
    """MAGNETS' red arms ON THE MODEL (--selfcheck `magnet`): ARM "nolift" (a hanging magnet lifts nothing),
    "anyball" (rubber pulled too), "sign" (a side magnet pushes away from its post)"""
    arm = None

    def step(self, p, slot):
        if self.arm == "anyball" and p.mat != MAT_STEEL:
            m = p.mat
            p.mat = MAT_STEEL
            try:
                return MagnetFamily.step(self, p, slot)
            finally:
                p.mat = m
        return MagnetFamily.step(self, p, slot)

    @staticmethod
    def mg_force(k1, mg):
        fx, fy, lift, ceil = MagnetFamily.mg_force(k1, mg)
        if _MgArm.arm == "nolift":
            lift = 0
        if _MgArm.arm == "sign":
            fx, fy = -fx, -fy
        return fx, fy, lift, ceil


def mg_scenes(c, arm=None):
    """each of MG_SC on course C's model (ARM: _MgArm's) -> {name: (fell at a step or None, the end's cell,
    the steps a magnet wiggled, its poses seen, the hover's (steps over the gap, lowest z px))}"""
    out = {}
    old = FAM_MODEL["magnet"]
    if arm:
        _MgArm.arm = arm
        FAM_MODEL["magnet"] = _MgArm()
    try:
        for name, mat, (wx, wy, gvx, gvy), n in MG_SC:
            p = Physics(c, play=True, mat=mat).poke(wx, wy, gvx, gvy)
            mgp = [pr for pr in p.props if pr["kind"] == K_MAGNET]
            fell, wig, poses, over, chg = None, 0, set(), [], 0
            q0 = [p.fpose(pr) for pr in mgp]
            for i in range(n):
                p.step()
                q1 = [p.fpose(pr) for pr in mgp]
                chg = max(chg, sum(a != b for a, b in zip(q0, q1)))
                q0 = q1
                if p.respawned:
                    fell = i
                    break
                wig += p.fsl[0][7] != 0
                poses |= set(q1)
                if p.air and 18 <= p.gx >> 12 <= 20:
                    over.append(p.gz)
            out[name] = (fell, (p.gx >> 12, p.gy >> 12), wig, poses,
                         (len(over), min(over or [0]) >> 8, max(over or [0]) - min(over or [0])), chg)
    finally:
        FAM_MODEL["magnet"] = old
        _MgArm.arm = None
    return out


def mg_ok(s):
    """the scenes show what they are for (SPEC.md 130.33.10)"""
    return (s["hover-steel"][0] is None and s["hover-steel"][1][0] >= 21 and s["hover-steel"][4][0] > 20
            and s["hover-steel"][4][1] >= 15 and s["hover-rubber"][0] is not None
            and s["pull-steel"][0] is not None and s["pull-fast"][0] is None and s["pull-rubber"][0] is None
            and s["rail-steel"][0] is None and s["rail-steel"][1][1] >= 15 and s["rail-steel"][3] == {0, 1, 2}
            and s["rail-rubber"][0] is not None
            and s["hover-steel"][4][2] >= 256 and max(v[5] for v in s.values()) <= 1)


def _sc_magnet(X, res):
    """--selfcheck's section `magnet` (SPEC.md 130.33.10): the refusals, the test course's records and lanes,
    the scenes on the model, and the model's red arms"""
    for what, text, want in _mg_cases():
        try:
            compile_course(text, fname="<%s>" % what, occluders=False)
            fired, msg = False, "compiled"
        except CourseError as e:
            fired, msg = want in str(e), str(e)
        res.append(("2 refused (magnets, 130.33.7): %s%s" % (what, "" if fired else " -- got: " + msg), fired))
    c = compile_course(MG_TEST)
    src = parse(open(MG_TEST).read(), MG_TEST)
    want = sorted((sp["at"], sp["mg"]) for sp in src.props if "mg" in sp)
    recs = [r for r in c.part["props"] if r["kind"] == K_MAGNET]
    got = sorted((r["at"], r["mg"][:4]) for r in recs)
    g = Physics(c).grid
    ceil = all(r["mg"][4] == (2 * g.cell(*r["at"])[0] + MG_CEIL if r["mg"][1] & MG_DOWN else 0) for r in recs)
    res.append(("3 MAGNETS' records (130.33.2): %d magnets, +18 - +21 the source's (way, DOWN, range, strength), "
                "a hanging one's +22 its ceiling, each a lane of 3 poses (the wiggle)" % len(recs),
                got == want and ceil and all(r["lane"] and r["lane"]["poses"] == 3 for r in recs)))
    s = mg_scenes(c)
    res.append(("6 MAGNETS' scenes on the model (130.33.10): %s" % "; ".join(
        "%s %s" % (k, "fell at %d" % v[0] if v[0] is not None else "ended on %s" % (v[1],)) for k, v in s.items())
        + "; the hover %d steps over the gap, z >= %d px, its bobble %.2f px from top to bottom; the rail's poses "
        "%s; at most %d magnet pose change a step" % (
            s["hover-steel"][4][0], s["hover-steel"][4][1], s["hover-steel"][4][2] / 256.0,
            sorted(s["rail-steel"][3]), max(v[5] for v in s.values())), mg_ok(s)))
    for arm in ("nolift", "anyball", "sign"):
        res.append(("6 MAGNETS' red arm %s on the model: the scenes no longer show what they are for" % arm,
                    not mg_ok(mg_scenes(c, arm))))


BP_TEST = os.path.join(ROOT, "apps", "bonanza", "courses", "boost.bbc")    # the BZBOOST=1 knob's course
# BOOST PADS' scenes on it (SPEC.md 130.40.8): (name, the poke: tile and ground velocity, steps), each ball - the
# same scenes tests/bonanza_phys.py's bp_host holds the guest to (its keys the same functions of the ball)
BP_SC = (("ramp", (14, 6, 0, 0), 120), ("gap", (10, 16, 0, 200), 130), ("chain", (12, 10, 120, 0), 160))


def _bp_keys(name, p):
    if name == "ramp":                              # (-x up the ramp; on the ledge, the brake)
        return K_L | K_U if p.gx >> 12 > 10 else K_GRIP
    if name == "gap":                               # (south into the pocket, then +x; over the low plate the brake)
        if p.gx >> 12 >= 14:
            return K_GRIP
        return K_R | K_D if (p.gy >> 12) >= 17 or p.gx >> 12 > 10 else K_D | K_L
    return K_GRIP if p.gy >> 12 >= 12 else 0        # (the chain: nothing held until the goal plate)


def _bp_cases():
    """(what, text, the refusal's substring): 130.40.7's refusals"""
    C = _W4C + "uses boost\n"
    return [
        ("a pad with no face", C + "prop boost 6 6\n", "takes <wx> <wy> face"),
        ("a pad facing up", C + "prop boost 6 6 face up\n", "faces +x, -x, +y or -y"),
        ("a strength of 0", C + "prop boost 6 6 face +x strength 0\n", "strength is 1 - 127"),
        ("a strength of 128", C + "prop boost 6 6 face +x strength 128\n", "strength is 1 - 127"),
        ("a strength twice", C + "prop boost 6 6 face +x strength 8 strength 9\n", "not 'strength'"),
        ("flat twice", C + "prop boost 6 6 face +x flat flat\n", "not 'flat'"),
        ("a pad with a reset class", C + "prop boost 6 6 face +x reset attempt\n", "takes no `reset`"),
        ("a pad with a word of no meaning", C + "prop boost 6 6 face +x fast\n", "not 'fast'"),
        ("a pad on a ramp", C + "prop boost 14 6 face +x\n", "not a FLAT FLOOR"),
        ("a pad on the cup's cell", C + "prop boost 12 6 face +x\n", "cup"),
        ("a pad with no `uses boost`", _W4C + "prop boost 6 6 face +x\n", "does not name"),
        ("`uses boost` and no pad", C, "no element of it is placed"),
        ("a pad hidden behind a wall in front of it", C + "wall rect 7 7 8 8 flat 9\nprop boost 6 6 face +x\n",
         "is HIDDEN"),
    ]


class _BpArm(BoostFamily):
    """BOOST PADS' red arms ON THE MODEL (--selfcheck `boost`): ARM "nopush" (a pad pushes nothing), "sign"
    (every pad pushes the other way), "air" (an airborne ball pushed too), "twolit" (a pad lit while another
    is: two pose changes on one step)"""
    arm = None

    def contact(self, p, slot, i):
        if self.arm == "air" and p.air:
            a = p.air
            p.air = 0
            try:
                return self.contact(p, slot, i)
            finally:
                p.air = a
        if self.arm == "twolit" and not p.air:
            p.fsl[slot][0] = 0
        g = (p.gvx, p.gvy)
        BoostFamily.contact(self, p, slot, i)
        if self.arm == "nopush":
            p.gvx, p.gvy = g
        elif self.arm == "sign":
            p.gvx, p.gvy = 2 * g[0] - p.gvx, 2 * g[1] - p.gvy


def bp_scenes(c, arm=None, drop=False):
    """each of BP_SC for each ball on course C's model (ARM: _BpArm's; DROP: on C less its pads, the controls)
    -> {(name, mat): (fell at a step or None, the end's (wx, wy, z px), met the gap's low plate at a step or None,
    the steps a pad was lit, the most pad pose changes on one step)}"""
    out = {}
    old = FAM_MODEL["boost"]
    if arm:
        _BpArm.arm = arm
        FAM_MODEL["boost"] = _BpArm()
    try:
        for name, (wx, wy, gvx, gvy), n in BP_SC:
            for mat in (MAT_RUBBER, MAT_STEEL, MAT_GLASS):
                p = Physics(c, play=True, mat=mat).poke(wx, wy, gvx, gvy)
                pads = [pr for pr in p.props if pr["kind"] == BP_K]
                fell, met, lit, chg = None, None, 0, 0
                q0 = [p.fpose(pr) for pr in pads]
                for i in range(n):
                    p.step(_bp_keys(name, p))
                    q1 = [p.fpose(pr) for pr in pads]
                    chg = max(chg, sum(a != b for a, b in zip(q0, q1)))
                    q0 = q1
                    if p.respawned and fell is None:
                        fell = i
                    if fell is None and met is None and name == "gap" and p.gx >> 12 >= 14 and (
                            not p.air or p.events[-1][1] == p.nstep and p.events[-1][0] in ("land", "bounce")):
                        met = i
                    lit += bool(pads) and p.fsl[0][0] != 0
                out[(name, mat)] = (fell, (p.gx >> 12, p.gy >> 12, p.gz >> 8), met, lit, chg)
    finally:
        FAM_MODEL["boost"] = old
        _BpArm.arm = None
    return out


def bp_ok(s, s0):
    """the scenes show what they are for (SPEC.md 130.40.8), S with the pads and S0 the course less them"""
    ok = True
    for mat in (MAT_RUBBER, MAT_STEEL, MAT_GLASS):
        r, r0 = s[("ramp", mat)], s0[("ramp", mat)]
        ok = ok and r[0] is None and r[1][0] <= 11 and r[1][2] == 32 and (r0[1][0] <= 11) == (mat == MAT_GLASS)
        g, g0 = s[("gap", mat)], s0[("gap", mat)]
        ok = ok and g[2] is not None and g0[2] is None and g0[0] is not None
        h, h0 = s[("chain", mat)], s0[("chain", mat)]
        ok = ok and h[0] is None and h[1][1] >= 12 and h0[1][1] < 12
    return ok and all(v[4] <= 1 for v in s.values()) and all(v[3] > 0 for v in s.values())


