def ga_frames_check(c, early=False, still=False):
    """SPEC.md 130.41.12 A5, A6 on the model: GATE's CRUMBLE (channel ring, 0) opened on step n0, then STEP and CELL
    each step - -> (ok, the steps its frame stepped on, the step its cell opened).  Its frame steps on n AND 7 =
    0 only, one at a time, to 3 within 17 - 24 steps; its cell a WALL while the frame is under 3 and the FLOOR from
    the step it is 3; its lanes' POSE the frame"""
    global _GA_EARLY, _GA_STILL
    _GA_EARLY, _GA_STILL = early, still
    try:
        fam = GateFamily()
        props = c.part["props"]
        art = next(r for r in props if r["kind"] == GT_KG and r.get("gart") and r["gch"] == 0)
        lanes = [r for r in props if r["kind"] == GT_KA and props[r["gap"]] is art]
        res = []
        for n0 in (1, 5):
            class P:
                pass
            p = P()
            p.props, p.fsl, p.nstep, p.fref, p.wcell, p.gz = props, [[0] * FSLOT], n0, 0, art["at"], 0
            p.fsl[0][0] = 1                         # (CONTACT on the ring plate, on step n0)
            steps, opened, ok = [], None, True
            for k in range(40):
                f0 = p.fsl[0][2]
                fam.step(p, 0)
                if p.fsl[0][2] != f0:
                    steps.append(p.nstep)
                    ok = ok and p.fsl[0][2] == f0 + 1 and p.nstep & 7 == 0
                win = {(art["at"][0] + dx, art["at"][1] + dy): [4, 0, 0, KIND_FLOOR, 0, 0] for dx in (-1, 0, 1)
                       for dy in (-1, 0, 1)}
                fam.cell(p, 0, win)
                wall = win[art["at"]][3] == KIND_WALL
                ok = ok and wall == (p.fsl[0][2] < GT_AFR - 1) and all(fam.pose(p, 0, r["i"]) == p.fsl[0][2]
                                                                     for r in lanes)
                if not wall and opened is None:
                    opened = p.nstep - n0
                p.nstep += 1
            ok = ok and len(steps) == GT_AFR - 1 and opened is not None and 17 <= opened + 1 <= 24
            res.append((ok, steps, opened))
        return all(r[0] for r in res), res
    finally:
        _GA_EARLY = _GA_STILL = False


class _GtArm(GateFamily):
    """the model's red arms (--selfcheck `gate`): ARM "noopen" (nothing opens a channel), "nowall" (a shut gate not
    walled), "lift" (a bridge coming down lifts a ball under its deck onto it)"""
    arm = None

    def contact(self, p, slot, i):
        global _GT_NOOPEN
        _GT_NOOPEN = self.arm == "noopen"
        try:
            GateFamily.contact(self, p, slot, i)
        finally:
            _GT_NOOPEN = False

    def cell(self, p, slot, win):
        global _GT_NOWALL, _GT_LIFT
        _GT_NOWALL, _GT_LIFT = self.arm == "nowall", self.arm == "lift"
        try:
            GateFamily.cell(self, p, slot, win)
        finally:
            _GT_NOWALL = _GT_LIFT = False


GT_WANT = {"ring": "through the ring gates (x 19 on), no fall", "ringshut": "stopped at the shut gates (x 17 or less)",
           "key": "through the plus gates (y 20 on), no fall", "keyshut": "stopped at the shut gates (y 18 or less)",
           "box": "across the box bridge (x 6 or less), no fall", "boxup": "falls where the bridge is up",
           "timed": "across the timed bridge (x 19 on), no fall", "late": "falls: it goes up under the ball",
           "under": "rubber and glass fall into it while up and keep falling when it comes down",
           "art": "held at the CRUMBLE while it falls (frame 3), then through it (y 4 or less), no fall"}


def gt_verdict(name, mat, r):
    """is scene NAME's result R (gt_play's) for ball MAT what it is for (SPEC.md 130.41.8)?"""
    fell, (x, y, _z), ch = r[1], r[2], r[3]
    return {"ring": fell is None and x >= 19 and ch == 1, "ringshut": fell is None and x <= 17 and ch == 0,
            "key": fell is None and y >= 20 and ch == 2, "keyshut": fell is None and y <= 18 and ch == 0,
            "box": fell is None and x <= 6 and ch == 4, "boxup": fell is not None and ch == 0,
            "timed": fell is None and x >= 19, "late": fell is not None,
            "under": fell is not None or mat == MAT_STEEL,
            "art": fell is None and y <= 4 and ch & 1}[name]


def gt_scenes(c, arm=None, names=None):
    """every GT_SC scene for every ball on C's model (ARM: _GtArm's) -> {(name, mat): gt_play's result}"""
    fm = None
    if arm:
        fm = _GtArm()
        fm.arm = arm
    return dict(((name, mat), gt_play(c, name, mat, fm)) for name in (names or GT_SC)
                for mat in (MAT_RUBBER, MAT_STEEL, MAT_GLASS))


def _sc_gate(X, res):
    """--selfcheck's section `gate` (SPEC.md 130.41.8): the refusals, the test course's records and lanes, the art's
    pairing, the scenes on the model, and the model's red arms"""
    global GT_ADIR
    import shutil
    import tempfile
    adir, keep = tempfile.mkdtemp(), GT_ADIR
    for nm in os.listdir(keep):
        shutil.copy(os.path.join(keep, nm), adir)
    for nm, text in GA_BAD.items():
        with open(os.path.join(adir, nm + ".bba"), "w") as f_:
            f_.write(text)
    GT_ADIR = adir
    _GA_CACHE.clear()
    try:
        for what, text, want in _gt_cases():
            try:
                compile_course(text, fname="<%s>" % what, occluders=False)
                fired, msg = False, "compiled"
            except CourseError as e:
                fired, msg = want in str(e), str(e)
            res.append(("2 refused (switches, keys, gates, bridges, 130.41.7, 130.41.12.3): %s%s" % (
                what, "" if fired else " -- got: " + msg), fired))
    finally:
        GT_ADIR = keep
        _GA_CACHE.clear()
        shutil.rmtree(adir, ignore_errors=True)
    c = compile_course(GT_TEST)
    src = parse(open(GT_TEST).read(), GT_TEST)
    want = sorted((sp["at"], sp["kind"], GT_TIMED if sp["gch"] is None else sp["gch"], sp["galong"])
                  for sp in src.props if sp["kind"] in GT_KINDS)
    recs = [r for r in c.part["props"] if r["kind"] in GT_KINDS]
    got = sorted((r["at"], r["kind"], r["gch"], r["galong"]) for r in recs)
    tm = [r for r in recs if r["kind"] == GT_KB and r["gch"] == GT_TIMED]
    row = FAM_BY_NAME["gate"]
    fv = famv(row)
    moved = all(famv(dict(row, consts=tuple(v ^ (j == k) for j, v in enumerate(row["consts"])))) != fv
                for k in range(len(row["consts"])))
    res.append(("3 GATES' records (130.41.3): %d elements, +18 the channel (FFh the %d timed bridge cells, each its "
                "seed a step after the last), +19 a gate's way and a bridge's deck, +20 its grid byte; each a lane of "
                "2 poses, no state bit, class ATTEMPT; FAMV %02Xh moves with each of its consts" % (
                    len(recs), len(tm), fv),
                got == want and len(recs) == 20 and moved and len(tm) == 6
                and sorted(r["sseed"] for r in tm) == list(range(6))
                and all((not r["lane"] if r.get("gart") else r["lane"] and r["lane"]["poses"] == 2)
                        and r["fsb"] == 0 and r["cls"] == CL_ATTEMPT
                        and (r["kind"] != GT_KB or (r["deck"] == 8 and r["gkd"] == KIND_FLOOR)) for r in recs)))   # (2 units,
                                                                                  # quarter units: SPEC.md 130.48.4)
    gl = [frozenset(xy for xy, ink in gt_plaque(0, 0, ch).items() if ink == BLK) for ch in range(GT_NCH)]
    res.append(("5 GATES' pairing (130.41.5): the %d channels' glyphs, black on a white plaque, pairwise distinct "
                "(each element of a channel carries its plaque)" % GT_NCH,
                len(set(gl)) == GT_NCH and all(set(gt_plaque(0, 0, ch).values()) == {BLK, WHT} for ch in range(GT_NCH))))
    # SPEC.md 130.41.11: the STYLES - pairwise distinct bars and decks, every bar style carrying the plaque whole and
    # black-and-white structure (both inks, so the 1bpp cards see it), in the grille's span; GATE's elements as
    # written; and the course with every `style` taken out exactly the course with `gatestyle grille`
    bars = [gt_bars_pix(0, 0, 0, 0, k) for k in range(len(GT_STYLES))]
    decks = [frozenset(gt_deck_pix(0, 0, k).items()) for k in range(len(GT_STYLES))]
    pq = gt_plaque(0, -(GT_BARH // 2), 0)
    sok = len(set(frozenset(b_.items()) for b_ in bars)) == len(bars) and len(set(decks)) == len(decks) \
        and all(all(b_.get(xy) == v for xy, v in pq.items()) and {BLK, WHT} <= set(b_.values())
                and max(abs(x) for x, _y in b_) <= GT_BARW for b_ in bars)
    gst = sorted(set((GT_STYLES[p_["gstyle"]], PK_NAMES[p_["kind"]]) for p_ in c.props if p_["kind"] in (GT_KG, GT_KB)
                 and p_.get("gart") is None))       # (130.41.12: an ART element takes no style)
    plain = open(GT_TEST).read()
    for nm in GT_STYLES:
        plain = plain.replace(" style %s" % nm, "")
    c0, c1 = compile_course(plain, fname=GT_TEST + " (no style)"), \
        compile_course(plain.replace("uses gate", "gatestyle grille\nuses gate"), fname=GT_TEST + " (grille)")
    res.append(("5 GATES' styles (130.41.11): %s - bars and decks pairwise distinct, the plaque whole on every one, "
                "black and white in each, inside the grille's %d px; GATE's elements %s; GATE with no `style` is "
                "GATE with `gatestyle grille` (%d bytes)" % (", ".join(GT_STYLES), 2 * GT_BARW + 1, gst, len(c0.cga)),
                sok and c0.cga == c1.cga and c0.cga != c.cga and len(gst) == 4))
    # SPEC.md 130.41.12: the designer's ART - GATE's three, their lanes (kind GT_KA, 4 poses, at most GT_ALANES an
    # art, +18 its gate, +19 its channel), its frames stepped and its cell opened at frame 3, and two red arms
    arts = [r for r in c.part["props"] if r.get("gart")]
    gal = [r for r in c.part["props"] if r["kind"] == GT_KA]
    per = {}
    for r in gal:
        per[r["gap"]] = per.get(r["gap"], 0) + 1
    names = sorted(p_["gart"]["name"] for p_ in c.props if p_.get("gart") is not None and p_.get("gacell") == 0)
    res.append(("7 GATE ART (130.41.12): %s on GATE, %d art cells (the portcullis two), %d lanes (%s an art), each 4 "
                "poses naming its gate and channel; the visibility rule %s" % (
                    ", ".join(names), len(arts), len(gal), "/".join(str(v) for v in per.values()),
                    ["%s %d" % (v[1], v[4]) for v in c.ga_vis]),
                names == ["crumble", "door", "portcullis"] and len(arts) == 4 and 3 <= len(per)
                and all(1 <= v <= GT_ALANES for v in per.values())
                and all(r["lane"]["poses"] == GT_AFR and c.part["props"][r["gap"]]["gch"] == r["gch"] for r in gal)))
    ok_, fr_ = ga_frames_check(c)
    res.append(("7 GATE ART's frames on the model (130.41.12 A5, A6): the crumble's channel opened on steps 1 and 5, "
                "its frame stepped on %s (n AND 7 = 0), its cell a WALL until frame 3 and the FLOOR from it (%s steps "
                "after the opening), its lanes' POSE the frame" % (
                    " and ".join("/".join(map(str, r[1])) for r in fr_), " and ".join(str(r[2]) for r in fr_)), ok_))
    for arm, kw in (("early (the cell opened at frame 0)", {"early": True}),
                    ("still (the frame never stepped)", {"still": True})):
        red = not ga_frames_check(c, **kw)[0]
        res.append(("7 GATE ART's red arm %s on the model: %s" % (arm, "red" if red else "STAYED GREEN"), red))
    s = gt_scenes(c)
    bad = ["%s %s" % (n_, MAT_NAMES[m_]) for (n_, m_), v in sorted(s.items()) if not gt_verdict(n_, m_, v)]
    res.append(("6 GATES' scenes on the model (130.41.8), every ball: %s%s" % (
        "; ".join("%s: %s" % (n_, GT_WANT[n_]) for n_ in GT_SC), " -- NOT: " + ", ".join(bad) if bad else ""),
        not bad))
    for arm, names in (("noopen", ("ring", "key", "box")), ("nowall", ("ringshut", "keyshut")), ("lift", ("under",))):
        sa = gt_scenes(c, arm, names)
        red = any(not gt_verdict(n_, m_, sa[(n_, m_)]) for n_ in names for m_ in (MAT_RUBBER, MAT_STEEL, MAT_GLASS))
        res.append(("6 GATES' red arm %s on the model: the scenes %s %s" % (
            arm, "/".join(names), "no longer show what they are for" if red else "STAY GREEN"), red))


SC_SPLIT = {"grammar": 4}      # a section run as N slices in the parallel run (its function takes part=(k, n))


def _sc_files(paths):
    """item 1's SECOND compile (its files and bzcourse.inc), beside the first"""
    _c, files, inc = compile_all(paths)
    return files, inc


def selfcheck(paths=None, only=None, jobs=None):
    """the course compiler's selfcheck (SPEC.md 130.10.4.6): the courses compiled, then every section
    (selfcheck_sections()), each a forked child when JOBS > 1 (the default: jobs_default(); _Sections
    says why the report is the sequential one).  ONLY: the sections to run, by name (--only)"""
    paths = paths or default_paths()
    res = []
    skipped = []
    S = _Sections(res, _jobs() if jobs is None else jobs, only)
    try:
        return _selfcheck(paths, res, skipped, S)
    finally:
        S.close()


def selfcheck_sections():
    """--selfcheck's section names, in the report's order"""
    return ["determinism"] + [n[4:] for n in _SC_ORDER]


_SC_ORDER = ("_sc_seeds", "_sc_crosscommit", "_sc_grammar", "_sc_w9", "_sc_wind", "_sc_palette", "_sc_tables", "_sc_courses",
             "_sc_split", "_sc_splitphys", "_sc_gaps", "_sc_physics", "_sc_props", "_sc_routes", "_sc_millroute",
             "_sc_camcheck", "_sc_play", "_sc_launch", "_sc_clockvis", "_sc_gap3", "_sc_w4", "_sc_flags",
             "_sc_y0moon", "_sc_hud", "_sc_demos4", "_sc_hopplan", "_sc_inc", "_sc_compact", "_sc_dither", "_sc_budget",
             "_sc_twoseg", "_sc_title", "_sc_clockrule", "_sc_path", "_sc_av", "_sc_guard", "_sc_kit", "_sc_cache",
             "_sc_magnet", "_sc_water", "_sc_boost", "_sc_spike", "_sc_arch", "_sc_hump", "_sc_gate", "_sc_tilt", "_sc_turn",
             "_sc_clockocc", "_sc_lift2", "_sc_width", "_sc_sheets")


def _selfcheck(paths, res, skipped, S):
    # 1. determinism: the second compile is a child's, beside the first - two compiles, two processes
    A = {}
    S.add("determinism", _sc_files, paths, now=True, post=lambda b: [(
        "1 two compiles byte-identical, file for file (%s, bzcourse.inc)" % ", ".join(sorted(A["a"][1])),
        all(A["a"][1][k] == b[0][k] for k in A["a"][1]) and A["a"][2] == b[1] and sorted(A["a"][1]) == sorted(b[0]))])
    a = A["a"] = compile_all(paths)
    courses = a[0]
    byname = {c.name: c for c in courses}
    for k, c in enumerate(courses):
        report(c, k)
    def _idok(c):                                   # (a TWO-PART course's is 130.30.4.3's, at its world part's
        if c.split:                                 # BZG1 +18: item 15 holds TWOSEG to the same)
            return struct.unpack_from("<H", c.wcga, c.part["gridoff"] + 18)[0] == ram_identity2(c.cga, c.wcga) \
                == c.ident
        return struct.unpack_from("<H", c.cga, c.part["gridoff"] + 18)[0] == ram_identity(c.cga) == c.ident \
            and _fletcher(_ident_bytes(identity_form(c))) == c.ident
    idok = all(_idok(c) for c in courses)
    res.append(("1 every course's identity at BZG1 +18 is 130.15.7's checksum of its RAM form's words as RECB 8 lays "
                "them out, that word and the directory's form bytes and stored lengths taken as 0 - a two-part "
                "course's 130.30.4.3's, over its two D parts (%s)"
                % ", ".join("%s %04Xh%s" % (c.name, c.ident, " (two parts)" if c.split else "") for c in courses),
                idok))
    st1 = all(expand(c.stored, c.name) == c.cga and (not c.split or expand(c.wstored, c.name) == c.wcga)
              for c in courses) and all(
        (a[1]["BZ%d.BIN" % k] == c.bstored and "BZ%dW.BIN" % k not in a[1]) if c.bstored else
        (a[1]["BZ%d.BIN" % k] == c.stored and (not c.split or a[1]["BZ%dW.BIN" % k] == c.wstored))
        for k, c in enumerate(courses))
    res.append(("1 every BZ<K>.BIN (and a two-part course's BZ<K>W.BIN) is the course's STORED form and expands to "
                "its RAM form - a SHEETED course's its ONE part, no BZ<K>W.BIN (both compiles' files compared "
                "above)", st1))
    import types
    X = types.SimpleNamespace(paths=paths, a=a, courses=courses, byname=byname, t=htab())
    for fn in _SC_ORDER:
        n = SC_SPLIT.get(fn[4:], 1) if S.par else 1
        for k in range(n):
            S.add(fn[4:], globals()[fn], X, res, *([(k, n)] if n > 1 else []))
    S.finish()
    ok = True
    for what, good in res:
        print("  %-4s %s" % ("ok" if good else "FAIL", what))
        ok = ok and good
    for what in skipped:
        print("  SKIP %s" % what)
    if S.left:                                  # (--only: what was left out is said, never a silent pass)
        print("  ONLY %d of %d sections ran (%s); left out: %s" % (
            len(selfcheck_sections()) - len(S.left), len(selfcheck_sections()),
            ", ".join(n for n in selfcheck_sections() if n not in S.left), ", ".join(S.left)))
    if os.environ.get("BB_TIMES"):              # (each section's seconds, for SC_COST and the policy's table)
        print("  times: " + ", ".join("%s %.1f" % kv for kv in sorted(S.times.items(), key=lambda kv: -kv[1])))
    print("bbcourse selfcheck: %s" % ("ok" if ok and not skipped else "FAILED" if not ok else
                                      "ok, but %d item%s SKIPPED (exit 77)" % (len(skipped), "s" if len(skipped) > 1
                                                                               else "")))
    return 1 if not ok else 77 if skipped else 0


# =============================================================================
# --sizes (SPEC.md 130.15.12.2): what each course and the package cost, both formats
# =============================================================================

def _ff(clk, nbytes):
    """an 8088 instruction's clocks with the fetch floor: max(clk, 4.34 x its bytes) (PERFORMANCE.md Part 2)"""
    return max(clk, 4.34 * nbytes)


# LZB's decode, PRICED from kernel/lz.inc's lz_lzb as kern_big assembles it (KHP_LZ), 8088 timings (the
# 8086's plus 4 a word access), each instruction at its fetch floor, all x 1.05 (ESTIMATED):
#   a literal:  cmp si,bp / jae / add dl,dl / jz / jc (each 2 bytes, 8.68) + sub bx,1 (3 bytes, 13.02)
#               + jb (8.68) + movsb (18) + jmp short .loop (15)                          = 98.1
#   a tag bit's refill, one bit in eight: the jz taken (+7.3), mov dl,[si] (13), inc si (4.34),
#               adc dl,dl (8.68), jmp short .bit (15) = 48.3, so 6.04 a bit
#   a match:    the head (four 8.68s, jc .match taken 16, its bit 6.04) = 56.8; two `call .gamma` (23)
#               and `ret` (20), two `mov ax,1` (13.02); mov cx,ax; the offset's dec ax x2, mov ah,al,
#               lodsb (12); dec ax, cmp ax,di, jae, sub bx,cx, jb; push ds (14), xchg, neg si, add si,di,
#               dec si, push es (14), pop ds (12), rep movsb's 9, pop ds (12), xchg, jmp short (15)
#   a gamma round (two bits: add/jz/adc/jc/add/jz and jc .g, two bit refills): 80.2 when it continues,
#               72.8 the last; a value v takes bit_length(v) - 1 rounds
#   a copied byte: rep movsb's 17 (a match's, and the tail's)
LZB_LIT = (5 * _ff(3, 2) + _ff(4, 3) + _ff(4, 2) + 18 + 15) + (16 - _ff(4, 2) + 13 + _ff(2, 1) + _ff(3, 2) + 15) / 8.0
_LZB_BIT = (16 - _ff(4, 2) + 13 + _ff(2, 1) + _ff(3, 2) + 15) / 8.0
LZB_MATCH0 = ((4 * _ff(3, 2) + 16 + _LZB_BIT) + 2 * 23 + 2 * 20 + 2 * _ff(4, 3) + _ff(2, 2)
              + 2 * _ff(2, 1) + _ff(2, 2) + 12 + _ff(2, 1) + 4 * _ff(3, 2) + 14 + _ff(3, 1) + 2 * _ff(3, 2)
              + _ff(2, 1) + 14 + 12 + 9 + 12 + _ff(3, 1) + 15)
LZB_ROUND = 6 * _ff(3, 2) + 2 * _LZB_BIT        # + the last jc: 16 taken, 8.68 not
LZB_COPY = 17
LZ4_BYTE = 63.8                                 # LZ4's clocks an output byte (SPEC.md 20.13.6, Calc)
SIZE_MARGIN = 1.05


def lzb_cost(stream, outlen):
    """-> (clocks, literals, matches, copied bytes): the decode's price from the
    real stream's symbols (ESTIMATED; the constants above)"""
    filt = os88lz.is_filtered(stream, outlen)
    buf = stream[2:] if filt else stream
    r = os88lz._BitIn(buf)
    r.p, end = os88lz._tail_bounds(buf)
    lits = matches = copied = 0
    clk = 0.0
    n = 0
    while r.p < end:
        if r.bit() == 0:
            r.byte()
            lits += 1
            n += 1
            continue
        ml = r.gamma()
        hi = r.gamma()
        r.byte()
        matches += 1
        copied += ml
        n += ml
        clk += LZB_MATCH0 + ml * LZB_COPY
        for v in (ml, hi):                      # bit_length - 1 rounds, every jc .g taken but the last
            rounds = v.bit_length() - 1
            clk += rounds * LZB_ROUND + (rounds - 1) * 16 + _ff(4, 2)
    tail = len(buf) - end
    clk += lits * LZB_LIT + tail * LZB_COPY
    return clk * SIZE_MARGIN, lits, matches, copied + tail


def _o88_arms(courses, demo_files):
    """BONANZA.O88 packed both ways (os88pkg, as the Makefile's rule runs it) from
    build/bonanza.bin, the built art's other parts and these courses' stored
    forms, and bonanza360.img's clusters with each: -> {fmt: (o88 bytes, clusters,
    of)} or None when the package is not built"""
    import subprocess
    import tempfile
    bdir = os.path.join(ROOT, "build")
    art = os.path.join(bdir, "bonanza-art")
    binf = os.path.join(bdir, "bonanza.bin")
    need = [os.path.join(art, n) for n in ("BZBALR.BIN", "BZBALS.BIN", "BZBALG.BIN", "BZSND.BIN")]
    if not os.path.exists(binf) or not all(os.path.exists(p) for p in need):
        return None
    songs = sorted((n for n in os.listdir(art) if re.match(r"^BZM\d+\.BIN$", n)), key=lambda n: int(n[3:-4]))
    readme = os.path.join(bdir, "zdata-lz4", "bonanza", "README.md")
    if not os.path.exists(readme):
        readme = os.path.join(ROOT, "apps", "bonanza", "README.md")
    out = {}
    with tempfile.TemporaryDirectory() as td:
        parts = []                      # (the balls ride the resident bundle since SPEC.md 130.25.5.2: added
        for k, c in enumerate(courses):
            p = os.path.join(td, "BZ%d.BIN" % k)
            with open(p, "wb") as f:
                f.write(c.bstored or c.stored)
            parts.append(p)
        for k, c in enumerate(courses):             # SPEC.md 130.30.4.4: the WORLD parts after the courses'
            if c.split and not c.bstored:
                p = os.path.join(td, "BZ%dW.BIN" % k)
                with open(p, "wb") as f:
                    f.write(c.wstored)
                parts.append(p)
        parts += [need[3]] + [os.path.join(art, n) for n in songs]
        for name in demo_files:                  # (the rows' order: named by course, SPEC.md 130.14.7.4)
            p = os.path.join(td, name)
            with open(p, "wb") as f:
                f.write(demo_files[name])
            parts.append(p)
        p = os.path.join(td, "BZKIT.BIN")       # SPEC.md 130.37: the kit's row, before the family rows
        with open(p, "wb") as f:
            f.write(kit_file(kit_load()))
        parts.append(p)
        bun = os.path.join(bdir, FBUN_FILE)     # ...last, as the family rows are, when it is built)
        if os.path.exists(bun):
            parts.append(bun)
        for fmt in ("lz4", "lzb"):
            o88 = os.path.join(td, "BONANZA.O88")
            r = subprocess.run([sys.executable, os.path.join(ROOT, "tools", "os88pkg.py"), "--compress-if=lz4", binf,
                                "-o", o88, "--part-compress", fmt] + [a for p in parts for a in ("--part", p)]
                               + [a for p in parts if p.startswith(td) for a in ("--part-data", p)],  # (the courses'
                                                    # and demos' data parts, as the Makefile's BZ_DATAPARTS: SPEC.md 20.3.3)
                               cwd=ROOT, capture_output=True, text=True)
            if r.returncode:
                return {"error": (r.stderr or r.stdout)[-300:]}
            img = os.path.join(td, "b360.img")
            r2 = subprocess.run([sys.executable, os.path.join(ROOT, "tools", "os88disk.py"), "-o", img, "--size", "360",
                                 o88, readme, "--folder", "SYSTEM/APPDATA"], cwd=ROOT, capture_output=True, text=True)
            m = re.search(r"(\d+)/(\d+) clusters", r2.stdout)
            out[fmt] = (os.path.getsize(o88), int(m.group(1)) if m else None, int(m.group(2)) if m else None)
    return out


def sizes(paths):
    """SPEC.md 130.15.12.2: every course's sections, its stored form packed
    both ways with its predicted decode, its RAM and its budget; then the
    package's.  Figures are MEASURED on the host (the packers are the
    shipped ones) except the decode times, which are PREDICTED"""
    fmts = (("lz4", "LZ4"), ("lzb", "LZB"))
    if "split:" in paths:                           # SPEC.md 130.24.10 (story D1.5): THE SPLIT COURSE's bytes,
        c = compile_course(_SPLIT, "<SPLIT>", _hack={"no_finish": True})    # and the same course with every
        cw = compile_course(re.sub(                 # half ROUNDED OUT to a whole cell (a zigzag band)
            r"(floor|wall|goal)(\s+)box (\S+) (\S+) (\S+) (\S+)",
                                   lambda m_: "%s%sband %d %d %d %d" % (m_.group(1), m_.group(2), int(m_.group(3)),
                                                                       int(m_.group(4)), int(m_.group(5)) - 1,
                                                                       int(m_.group(6))),
                                   "\n".join(ln for ln in _SPLIT.split("\n") if " half " not in ln and " quarter " not in ln)),
                            "<SPLIT, whole>", _hack={"no_finish": True})
        for nm, cc in (("SPLIT", c), ("the same boxes as whole-cell bands (every half rounded out)", cw)):
            pt = cc.part
            print("  %s: RAM %d, stored %d, LZ4 %d, LZB %d; %d split cells (%d quartered), D %d bytes; %d blocks, "
                  "%d records" % (nm, len(cc.cga), len(cc.stored), packed_len(cc.stored, "lz4"),
                                  packed_len(cc.stored, "lzb"), len(cc.pairs),
                                  sum(1 for v in cc.pairs.values() if len(v) == 4),
                                  sum(4 * len(v) for v in cc.pairs.values()), len(cc.blocks), len(cc.records)))
            for e in pt["dir"]:
                print("    %-3s %-22s %-10s %7d %7d" % (e["tag"], SEC_NAMES[e["tag"]], FORM_NAMES[e["form"]],
                                                        e["len"], e["dlen"]))
        paths = [q for q in paths if q != "split:"]
        if not paths:
            return 0
    courses, files, texts = compile_all(paths)
    tot = {"lz4": 0, "lzb": 0, "ram": 0}
    kitsave = [0]
    print("bbcourse --sizes: RECB %d (%s), the stored form of SPEC.md 130.15.4.3; packed as os88pkg packs a part "
          "(os88lz, the near-call filter tried); KiB = 1,024 bytes" % (REC, "D" if REC == 4 else "C"))
    for k, c in enumerate(courses):
        pt = c.part
        stores = [c.stored] + ([c.wstored] if c.split else [])     # (a two-part course's both, 130.30)
        pw = [{f: packed_len(st, f) for f, _ in fmts} for st in stores]
        more = list(c.sstored[1:]) if c.sstored else []   # (a SHEETED course's other sheets, 130.30.12)
        ps = [{f: packed_len(st, f) for f, _ in fmts} for st in more]
        whole = {f: sum(q[f] for q in pw + ps) for f, _ in fmts}
        if c.bstored:                                   # SPEC.md 130.30.12.5: ONE part on the disk, the sheets
            sep = dict(whole)                           # and the world part each from a paragraph
            whole = {f: packed_len(c.bstored, f) for f, _ in fmts}
            print("    ONE PART (SPEC.md 130.30.12.5): BZ%d.BIN %d bytes (OP_BIG), the sheets and the world part at "
                  "paragraphs %s: LZ4 %d, LZB %d - as separate parts they would pack to LZ4 %d, LZB %d" % (
                      k, len(c.bstored), c.plan["paras"], whole["lz4"], whole["lzb"], sep["lz4"], sep["lzb"]))
        print("\n  course %d %s (%s): RAM %d bytes, stored %d (%d of them holes), %d sections" % (
            k, c.name, os.path.basename(c.fname), sum(len(st) for st in stores + more),
            sum(len(st) for st in stores + more), sum(e["len"] - e["dlen"] for e in pt["dir"]), len(pt["dir"])))
        if c.split:
            print("    TWO PARTS (SPEC.md 130.30): the picture part %d bytes (%d of headroom under %d), LZ4 %d, LZB %d; "
                  "the world part %d (%d), LZ4 %d, LZB %d" % (
                      len(c.cga), PARTMAX - len(c.cga), PARTMAX, pw[0]["lz4"], pw[0]["lzb"], len(c.wcga),
                      PARTMAX - len(c.wcga), pw[1]["lz4"], pw[1]["lzb"]))
        if c.sstored:
            pl = c.plan
            print("    SHEETS (SPEC.md 130.30.12): the picture part as %d sheets of %d block rows (of %d; margins %d), "
                  "each %d bytes (%d of headroom): %s; one picture part would be %d" % (
                      pl["k"], pl["n"], c.brows, pl["H"], len(c.cga), PARTMAX - len(c.cga), "; ".join(
                          "sheet %d rows %d - %d, coverage %d - %d, window tops %d - %s, LZ4 %d, LZB %d" % (
                              i, x["m0"], x["m0"] + pl["n"] - 1, x["c0"], x["c1"] - 1, x["slo"],
                              "end" if x["shi"] is None else x["shi"], (pw[0] if not i else ps[i - 1])["lz4"],
                              (pw[0] if not i else ps[i - 1])["lzb"]) for i, x in enumerate(pl["sheets"])),
                      two_part_lens(c.model, REC)[0]))
        print("    %-3s %-18s %-10s %7s %7s %9s %9s" % ("tag", "section", "form", "RAM", "stored", "LZ4 share",
                                                       "LZB share"))
        for e in pt["dir"]:
            z = bytearray(stores[e["part"]])
            z[e["off"] + e["len"] - e["dlen"]:e["off"] + e["len"]] = bytes(e["dlen"])
            sh = {f: pw[e["part"]][f] - packed_len(bytes(z), f) if e["dlen"] else 0 for f, _ in fmts}
            print("    %-3s %-18s %-10s %7d %7d %9d %9d" % (e["tag"], SEC_NAMES[e["tag"]], FORM_NAMES[e["form"]],
                                                         e["len"], e["dlen"], sh["lz4"], sh["lzb"]))
        print("    header %d, directory %d x %d = %d" % (HDR, pt["nsec"], DIRENT, DIRENT * pt["nsec"]))
        z4 = _PACKED[(hashlib.sha256(bytes(c.stored)).digest(), "lz4")]
        zb = _PACKED[(hashlib.sha256(bytes(c.stored)).digest(), "lzb")]
        lzbclk, lits, mats, cop = lzb_cost(zb, len(c.stored))
        print("    the whole stored form: LZ4 %d (%d with its paragraph padding)%s, LZB %d (%d)%s" % (
            whole["lz4"], (whole["lz4"] + 15) & ~15, " +E8" if os88lz.is_filtered(z4, len(c.stored)) else "",
            whole["lzb"], (whole["lzb"] + 15) & ~15, " +E8" if os88lz.is_filtered(zb, len(c.stored)) else ""))
        if c.kit_use is not None:                   # SPEC.md 130.37: what the course takes from THE KIT
            src_ = c.fname if os.path.isabs(c.fname) else os.path.join(ROOT, c.fname)
            c0 = compile_course(src_, _hack={"nokit": True})
            z0 = sum(packed_len(st, "lzb") for st in [c0.stored] + ([c0.wstored] if c0.split else []))
            m_ = c.model
            nall = {"B": len(m_["blocks"]) // 16, "K": len(m_["masks"]), "F": len(m_["ftabs"]) // FTAB}
            kb = sum(KIT_SIZE[t] * len(c.kit_use[t]) for t in KIT_TAGS)
            ob = sum(KIT_SIZE[t] * (nall[t] - len(c.kit_use[t])) for t in KIT_TAGS)
            kitsave[0] += z0 - whole["lzb"]
            print("    THE KIT (SPEC.md 130.37): %s; its pieces from the kit %d bytes of RAM, its own %d; LZB %d "
                  "against %d without the kit: %+d" % (
                      ", ".join("%s %d of %d%s" % (t, len(c.kit_use[t]), nall[t], " (KITREF)" if t in m_["kit"]
                                                    else "") for t in KIT_TAGS), kb, ob, whole["lzb"], z0,
                      whole["lzb"] - z0))
        print("    its decode, PREDICTED: LZ4 %.0f ms (%d bytes at %.1f clk), LZB %.0f ms (%d literals, %d matches, "
              "%d bytes copied; %.0f clk a byte)" % (
                  len(c.stored) * LZ4_BYTE / 4770.0, len(c.stored), LZ4_BYTE, lzbclk / 4770.0, lits, mats, cop,
                  lzbclk / len(c.stored)))
        print("    RAM %d bytes against %d: %d of headroom; %.0f bytes a block row (%d rows)" % (
            len(c.cga), PARTMAX, PARTMAX - len(c.cga), len(c.cga) / float(c.brows), c.brows))
        if c.target is None:
            print("    no target (course 0, the benchmark's): no budget")
        else:
            bg, cap = budget(c.target), course_cap(c)
            pace = c.target / float(c.brows)
            rows = int((PARTMAX - HDR) / (len(c.cga) / float(c.brows)))
            print("    target %d s: %.3f s a block row; one part holds about %d rows at this density, about %.0f s at "
                  "this pace" % (c.target, pace, rows, rows * pace))
            if c.target == 90:
                print("    a 90 s course needs wave 11's levers (story 11.6) and a pace of at least 0.425 s a row")
            print("    budget %d bytes (ROOM %d x %d / %d), 1.5x %d (LZ4), REPORTED, never refused (SPEC.md "
                  "130.27.5): LZ4 %d, %s; LZB %d, %s" % (
                      bg, ROOM, c.target, PLAN_SECS, cap, whole["lz4"],
                      "OVER 1.5x" if whole["lz4"] > cap else "OVER" if whole["lz4"] > bg else "under",
                      whole["lzb"], "OVER" if whole["lzb"] > bg else "under"))
        tot["lz4"] += whole["lz4"]
        tot["lzb"] += whole["lzb"]
        tot["ram"] += sum(len(q) for q in sheet_rams(c))
    print("\n  the %d courses: LZ4 %d, LZB %d packed; RAM %d" % (len(courses), tot["lz4"], tot["lzb"], tot["ram"]))
    kp = kit_file(kit_load())
    print("  THE KIT (SPEC.md 130.37): BZKIT.BIN %d bytes of RAM, held; LZB %d (%s).  The play courses' LZB "
          "against their kit-less compiles: %d bytes less, %.2fx the kit's" % (
              len(kp), packed_len(kp, "lzb"), ", ".join("%s %d" % (t, len(kit_load()[t])) for t in KIT_TAGS),
              kitsave[0], kitsave[0] / float(max(1, packed_len(kp, "lzb")))))
    planned = 0
    have = {}
    for c in courses:
        if c.target:
            have[c.target] = have.get(c.target, 0) + 1
    for t, n in PLAN_SET:
        planned += max(0, n - have.get(t, 0)) * budget(t)
    shipped = sum(packed_len(c.stored, "lz4") for c in courses if c.target)
    shippedb = sum(packed_len(c.stored, "lzb") for c in courses if c.target)
    print("  the set: the shipped courses (%d LZ4, %d LZB) and the plan's courses still to come at their "
          "budgets (%d: %s) against ROOM %d (%.0f KiB): LZ4 %.1f KiB, LZB %.1f KiB" % (
              shipped, shippedb, planned, ", ".join("%d x %d s" % (max(0, n - have.get(t, 0)), t)
                                                    for t, n in PLAN_SET),
              ROOM, ROOM / 1024.0, (shipped + planned) / 1024.0, (shippedb + planned) / 1024.0))
    arms = _o88_arms(courses, {n: d for n, d in files.items() if n.startswith("BZD")})
    if arms is None:
        print("  the package: build/bonanza.bin or the built art's other parts are missing - `make bonanza` "
              "first for BONANZA.O88's figures")
    elif "error" in arms:
        print("  the package: os88pkg refused: %s" % arms["error"])
    else:
        for fmt, name in fmts:
            o, used, of = arms[fmt]
            print("  BONANZA.O88 with %s parts: %d bytes; bonanza360.img %s/%s clusters" % (name, o, used, of))
        o, used, of = arms["lzb"]
        crs = sum(packed_len(c.stored, "lzb") for c in courses)
        print("  the live derivation of ROOM: the 360KB disk's %d clusters, less what is not a course today (%d "
              "clusters with LZB parts, of which the courses are about %.0f KiB) leaves about %.0f KiB for courses "
              "before the plan's later items (the pathway, the front art, the family parts and 10%% slack) - "
              "ROOM is %.0f KiB" % (of, used, crs / 1024.0, of - used + crs / 1024.0, ROOM / 1024.0))
    return 0


def previews(paths, out):
    try:
        from PIL import Image
    except ImportError:
        print("bbcourse: --png needs Pillow; skipped", file=sys.stderr)
        return 1
    os.makedirs(out, exist_ok=True)
    items = []
    for path in paths:                              # `split:` - SPEC.md 130.24's SPLIT course and the owner's
        if path == "split:":                        # mock-up scenes, from their text (story D1.4)
            items += [(_SPLIT, "<SPLIT>")] + [(t, "<%s>" % n) for n, t in sorted(_split_mockups().items())]
        else:
            items.append((path, None))
    for path, nm in items:
        c = compile_course(path, nm, _hack={"no_finish": True}) if nm else compile_course(path)
        if nm:
            c.name = nm.strip("<>").upper() if nm != "<SPLIT>" else "SPLIT"
        img = Image.new("RGB", (c.width, c.lines))
        img.putdata([CGA1[v] for r in c.pic for v in r])
        px = img.load()
        for (bx, by) in c.route:
            for d in range(-3, 4):
                for (x, y) in ((bx + 8 + d, by + 13), (bx + 8, by + 13 + d)):
                    if 0 <= x < c.width and 0 <= y < c.lines:
                        px[x, y] = (255, 0, 0)
        base = os.path.join(out, c.name.lower())
        img.save(base + "-cga.png")
        occ = img.copy()
        op = occ.load()
        for r in c.records:
            for (x, y) in r["pix"]:
                rr, gg, bb = op[x, y]
                op[x, y] = (255, gg // 3, bb // 3) if (x + y) & 1 else (rr, gg, bb)
        occ.save(base + "-occ.png")
        h = Image.new("L", (c.width * 2, c.lines))
        data = []
        for y, row in enumerate(c.pic):
            for x, v in enumerate(row):
                pr = herc_pair(v, y, x)
                data += [255 * (pr >> 1), 255 * (pr & 1)]
        h.putdata(data)
        h.save(base + "-herc.png")
        ghost_previews(c, base, Image)
    print("bbcourse: previews in %s" % out)
    return 0


GHOST_ZOOM = 6                  # the ghost previews' zoom, in game pixels


def ghost_previews(c, base, Image, at=None):
    """the ghost dither (SPEC.md 130.15.10), side by side: the ball behind
    scenery BEFORE (every record laying its pixels, the undithered masks) and
    AFTER (the dithered masks out of the RAM part, laid as the guest lays
    them: card_composite), on the CGA's palette and through herc_pair, zoomed
    GHOST_ZOOM times.  AT: (px, py, sb, zb, air); default the autopilot
    route's step whose ball the rule hides most (its first such step).
    Writes BASE-ghost-cga.png and BASE-ghost-herc.png; -> the step, or None
    when no step of the route lays a record over the ball"""
    if at is None and not c.route:                  # (the pathway, 130.19.5: no route to ride)
        return None
    if at is None:
        best = (0, None)
        p = Physics(c, play=True)
        while p.nstep < DEMO_STEPS and not p.goal:
            p.step(p.auto())
            if p.tube or p.hid:
                continue
            laid = set()
            for r in laid_at(c, p.px, p.py, p.sb, p.zb, p.oair):
                laid |= r["pix"]
            k = sum(1 for q in ball_pixels(p.px, p.py) if q in laid)
            if k > best[0]:
                best = (k, (p.px, p.py, p.sb, p.zb, p.oair, p.nstep))
        if best[1] is None:
            return None
        at = best[1]
    px, py, sb, zb, air = at[:5]
    before = composite(c, px, py, sb, zb, air, "records", ghost=False)
    after = card_composite(c, px, py, sb, zb, air)
    x0, y0 = max(0, (px & ~3) - 16), max(0, py - 12)
    x1, y1 = min(c.width, (px & ~3) + 36), min(c.lines, py + 28)
    w, h = x1 - x0, y1 - y0
    gap = 2
    cga = Image.new("RGB", (2 * w + gap, h), (128, 128, 128))
    herc = Image.new("L", (2 * (2 * w + gap), h), 128)
    for i, comp in enumerate((before, after)):
        for y in range(y0, y1):
            for x in range(x0, x1):
                v = comp.get((x, y), c.pic[y][x])
                cga.putpixel((i * (w + gap) + x - x0, y - y0), CGA1[v])
                pr = herc_pair(v, y, x)
                hx = 2 * (i * (w + gap) + x - x0)
                herc.putpixel((hx, y - y0), 255 * (pr >> 1))
                herc.putpixel((hx + 1, y - y0), 255 * (pr & 1))
    cga.resize((cga.width * GHOST_ZOOM, h * GHOST_ZOOM), Image.NEAREST).save(base + "-ghost-cga.png")
    herc.resize((herc.width * GHOST_ZOOM // 2, h * GHOST_ZOOM), Image.NEAREST).save(base + "-ghost-herc.png")
    return at


def _mk_list(mk, var):
    """the files of the Makefile's first `VAR := ...` line (its continuation lines joined), or None"""
    m = re.search(r"^%s\s*:=\s*((?:.*\\\n)*.+)$" % var, mk, re.M)
    return m.group(1).replace("\\", " ").split() if m else None


def _makefile():
    with open(os.path.join(ROOT, "Makefile"), encoding="utf-8", errors="replace") as f:
        return f.read()


def default_paths():
    """the BZDEV=1 build's courses, read out of the Makefile - the one authority on the courses
    and their order (K): BZ_COURSES (its first line: the shipped courses) and then BZ_TESTCRS (the
    TEST courses, which only that build carries, AFTER every other: SPEC.md 130.54), as BZDEV's
    block puts them - so a course added to either is compiled and selfchecked by a bare
    `bbcourse.py --selfcheck` (the bonanzacourse row) too, the test courses included, never a hand
    copy of the list that can drift from it"""
    mk = _makefile()
    shipped = _mk_list(mk, "BZ_COURSES")
    if not shipped:
        raise SystemExit("bbcourse: the Makefile has no BZ_COURSES line")
    return [os.path.join(ROOT, p) for p in shipped + (_mk_list(mk, "BZ_TESTCRS") or [])]


def test_rule():
    """SPEC.md 130.54: -> the Makefile's files whose `test` statement is wrong - every file of BZ_TESTCRS says
    `test`, no file of the shipped BZ_COURSES (its first line) does; and the maps (130.54.6) likewise, the test
    map BZ_PATHDEV saying it and the shipped pathway BZ_PATH (its first line) not: [(file, why)]"""
    mk = _makefile()
    bad = []
    for var, want in (("BZ_COURSES", False), ("BZ_TESTCRS", True), ("BZ_PATH", False), ("BZ_PATHDEV", True)):
        for p in _mk_list(mk, var) or []:
            with open(os.path.join(ROOT, p), encoding="ascii") as f:
                has = bool(re.search(r"^\s*test\s*(#.*)?$", f.read(), re.M))
            if has != want:
                bad.append((p, "%s %s" % (var, "but no `test`" if want else "with `test`")))
    return bad


def _course_list(paths):
    """(NAME, path) of every course in BZ_COURSES's order, from the `course` lines alone"""
    out = []
    for p in paths:
        with open(p, encoding="ascii") as f:
            m = re.search(r"^\s*course\s+([A-Z0-9]{1,5})\b", f.read(), re.M)
        out.append((m.group(1) if m else None, p))
    return out


@functools.lru_cache(maxsize=None)
def _course_info_t(paths):
    out = []
    for p in paths:
        with open(p, encoding="ascii") as f:
            t = f.read()
        m = re.search(r'^\s*course\s+([A-Z0-9]{1,5})\s+"([^"]*)"', t, re.M)
        tst = bool(re.search(r"^\s*test\s*(#.*)?$", t, re.M))     # SPEC.md 130.54: a test course has no pad
        out.append((m.group(1), m.group(2), tst) if m else (None, None, False))
    return out


def _course_info(paths):
    """[(NAME, title, test)] of every course in BZ_COURSES's order, from the `course` and `test` lines alone
    (the pathway's pads' courses, SPEC.md 130.22.2; a test course plays on no pad, 130.54)"""
    return _course_info_t(tuple(paths))


# 130.16.5.4's figures (as built by wave 6, rule 4 exactly): --tune prints a trial against them
W6_SIZES = {"BENCH": (2747, 38732, 7223, 5770), "FIRST": (332, 8822, 2103, 1685), "TRIAL": (854, 15056, 3785, 3054),
            "MILL": (1324, 28690, 8801, 7153), "MOON": (2694, 42030, 9710, 7903),
            "PEAK": (3081, 45804, 11402, 9285)}
TUNE_FIELDS = ("ACC", "K", "EF", "EW", "BMIN", "HOP", "GRIP", "HTHR", "HSTEPS", "BOOST")


def apply_tune(assigns):
    """--tune's NAME=VALUE list onto MATERIALS (rubber, steel, glass in that
    order: NAME=a,b,c; BOOST=b alone sets rubber's), and the globals derived
    from it (HOPMAX, BOOSTMAX, BZ_PHYSV).  -> [what changed]"""
    global HOPMAX, BOOSTMAX, BADDMAX, PHYSV
    out = []
    for a in assigns:
        if "=" not in a:
            raise CourseError("--tune: %r is not NAME=VALUE" % a)
        name, val = a.split("=", 1)
        name = name.upper()
        if name not in TUNE_FIELDS:
            raise CourseError("--tune: %s is not a MATERIALS field (%s)" % (name, ", ".join(TUNE_FIELDS)))
        vals = [int(v) for v in val.split(",")]
        if len(vals) == 1 and name == "BOOST":
            vals = [vals[0], MATERIALS[MAT_STEEL]["BOOST"], MATERIALS[MAT_GLASS]["BOOST"]]
        if len(vals) != len(MATERIALS):
            raise CourseError("--tune: %s takes %d values (rubber, steel, glass)" % (name, len(MATERIALS)))
        for m, v in enumerate(vals):
            if MATERIALS[m][name] != v:
                out.append("%s's %s %d -> %d" % (MAT_NAMES[m], name, MATERIALS[m][name], v))
                MATERIALS[m][name] = v
    HOPMAX = max(m["HOP"] for m in MATERIALS)
    BOOSTMAX = max(m["BOOST"] for m in MATERIALS)
    BADDMAX = max(badd(m) for m in MATERIALS)
    PHYSV = phys_ident()
    return out


def main_tune(assigns, paths):
    """bbcourse.py --tune NAME=VALUE ... (SPEC.md 130.16.13): every course
    compiled under trial values of MATERIALS, NOTHING written; each course's
    verdict under the bounds, its records and sizes against 130.16.5.4's, the
    step ladder and the gap ladder, every route proof and every AUTHOR script"""
    import time
    t0 = time.time()
    ch = apply_tune(assigns)
    print("bbcourse --tune: %s; HOPMAX %d, BOOSTMAX %d, BZ_PHYSV %02Xh%s" % (
        "; ".join(ch) or "no change", HOPMAX, BOOSTMAX, PHYSV,
        " (an EARLIER physics' value: bump PHYS_REV)" if PHYSV in PHYSV_SHIPPED else ""))
    bad = []
    try:
        check_boosts()
    except CourseError as e:
        print("  REFUSED at import: %s" % e)
        bad.append("the boost's bound")
    courses = []
    for k, path in enumerate(paths):
        try:
            c = compile_course(path)
            c.packed4 = check_budget(c, k)
            was = W6_SIZES.get(c.name)
            print("  %-5s compiles: %d records, RAM %d, LZ4 %d, LZB %d%s" % (
                c.name, len(c.records), len(c.cga), packed_len(c.stored, "lz4"), packed_len(c.stored, "lzb"),
                "" if was is None else " (130.16.5.4: %d, %d, %d, %d)" % was))
            courses.append(c)
        except CourseError as e:
            print("  %-5s REFUSED: %s" % (os.path.basename(path), e))
            bad.append(os.path.basename(path))
            courses.append(None)
    st, gp = step_ladder(), gap_ladder()
    for line in ladder_text(st, gp).split("\n"):
        print("  " + line)
    for what, good in ladder_verdicts(st, gp):
        print("  %-4s the ladders: %s" % ("ok" if good else "FAIL", what))
        if not good:
            bad.append("the ladders")
    byname = {c.name: c for c in courses if c is not None}
    res = []
    if "BENCH" in byname:
        _route_checks(byname["BENCH"], res, byname.get("TRIAL"), byname.get("FIRST"))
    if "MILL" in byname:
        _mill_route(byname["MILL"], res)
    for c in courses:
        if c is not None and (any(p["kind"] >= PK_CHECKPOINT for p in c.props) or c.branches):
            _w4_route(c, res)
    for k, c in enumerate(courses):
        if c is None or c.test:
            continue
        if c.name in AUTHOR:
            try:
                _log, p = author_demo(c, k, AUTHOR[c.name])
                res.append(("AUTHOR %s: %d steps, %s" % (c.name, p.nstep, "to the goal" if p.goal else "NOT to the "
                                                                                                    "goal"), p.goal))
            except CourseError as e:
                res.append(("AUTHOR %s: %s" % (c.name, e), False))
        elif len(c.route) >= 2:
            p = Physics(c, play=True)
            while p.nstep < DEMO_STEPS and not p.goal:
                p.step_auto()
            res.append(("route demo %s: %d steps, %s" % (c.name, p.nstep, "to the goal" if p.goal else
                                                          "NOT to the goal"), p.goal))
    for what, good in res:
        print("  %-4s %s" % ("ok" if good else "FAIL", what))
        if not good:
            bad.append(what.split(":")[0])
    print("bbcourse --tune: %s (%.0f s; nothing written)" % ("every course, ladder, route and script passes" if not bad
                                                            else "REFUSED or FAILED: %s" % ", ".join(bad),
                                                            time.time() - t0))
    return 1 if bad else 0


def main_demo(argv):
    """bbcourse.py demo IN.BZR [-o OUT.bzd]: a log the owner saved (W, on a
    5150 or in 86Box) as a .bzd (SPEC.md 130.14.7.4).  The course is the log's
    K in BZ_COURSES; the file is checked as the guest's L checks it, except
    for its physics byte: a log under other physics converts, and the build
    then REFUSES it (SPEC.md 130.16.9) until it is recorded again."""
    ap = argparse.ArgumentParser(prog="bbcourse.py demo")
    ap.add_argument("log")
    ap.add_argument("-o", "--out")
    a = ap.parse_args(argv)
    with open(a.log, "rb") as f:
        log = f.read()
    paths = default_paths()
    names = _course_list(paths)
    if len(log) < RLOG_HDR or log[:4] != b"BZR1" or log[4] >= len(names) or log[4] == 0:
        print("bbcourse: %s is not a Bonanza demo of a course (K 1 ..)" % a.log, file=sys.stderr)
        return 1
    c = compile_course(paths[log[4]])
    idents = [0] * len(names)
    idents[log[4]] = c.ident
    bad = check_log(log, len(names), idents, physv=log[7])
    if bad:
        print("bbcourse: %s: check %d: %s" % (a.log, bad[0], bad[1]), file=sys.stderr)
        return 1
    text = demo_text(log, c.name, "%s's demo, converted from %s by `bbcourse.py demo` (SPEC.md 130.14.7.4)"
                     % (c.name, os.path.basename(a.log)))
    if a.out:
        with open(a.out, "w", newline="\n") as f:
            f.write(text)
    else:
        sys.stdout.write(text)
    return 0


# SPEC.md 130.30.7: THE TWO-PART TEST COURSE - the PLAYGROUND with its diagonal lane run on down the screen off the
# platform's foot (s 81 - 121), which takes its one-part form past 65,024 bytes (67,320 at the commit that made it,
# a picture part of 51,956 and a world part of 15,364).  Off every route: the route, the start and the goal are the
# PLAYGROUND's.  Not shipped: --selfcheck item 15 compiles it, `make bonanzatwoseg` adds it to a
# private build as course 7
TWOSEG_EXT = ("\n# SPEC.md 130.30.7: the lane run on down the screen off the platform's foot, until one part refuses "
              "the course\nfloor box 15 17 81 92 flat 2.5\n")      # (to 106, was 121, when PLAYGROUND's crack and
# group labs merged, 2026-11-17: its picture part 67,504 bytes at 121, over 130.30.4.1's 65,024; 63,202 at 106;
# to 92 when THE LOOK's wall tops landed, 2026-11-18 (130.47.3): 68,002 at 106, 64,868 at 95)


def twoseg_text():
    """the TWOSEG course's text (SPEC.md 130.30.7), from the PLAYGROUND's"""
    with open(os.path.join(COURSE_DIR, "playground.bbc"), "r", encoding="ascii") as f:
        t = f.read()
    t = _swap(t, 'course PLAY "Playground"', 'course TWOSG "Two segments"')
    return ("# TWOSG - GENERATED by `python3 tools/bbcourse.py twoseg` (SPEC.md 130.30.7): a test course, never "
            "shipped\n" + t + TWOSEG_EXT)


def main_twoseg(argv):
    """bbcourse.py twoseg [-o OUT.bbc]: the two-part test course's text (SPEC.md 130.30.7)"""
    ap = argparse.ArgumentParser(prog="bbcourse.py twoseg")
    ap.add_argument("-o", "--out")
    a = ap.parse_args(argv)
    t = twoseg_text()
    if a.out:
        with open(a.out, "w", newline="\n") as f:
            f.write(t)
    else:
        sys.stdout.write(t)
    return 0


def kit_pool_paths():
    """KIT_POOL's course files, in its order"""
    return [os.path.join(COURSE_DIR, n + ".bbc") for n in KIT_POOL]


def _kit_pieces(c):
    """a course's pieces by class, as compiled: {tag: [piece bytes]}"""
    m = c.model
    return {"B": [m["blocks"][i:i + 16] for i in range(0, len(m["blocks"]), 16)],
            "K": list(m["masks"]),
            "F": [m["ftabs"][i:i + FTAB] for i in range(0, len(m["ftabs"]), FTAB)]}


def kit_build(courses, kmin=KIT_MIN):
    """SPEC.md 130.37.2: the kit out of compiled courses (each compiled WITHOUT the kit, _hack nokit): every
    block and mask at least kmin of them hold, and every FIELD table any holds (the F library) - each class in
    first appearance over the courses in order, a course's own pieces in its order; the black block first"""
    kit, seen, uses = {t: [] for t in KIT_TAGS}, {t: set() for t in KIT_TAGS}, {t: {} for t in KIT_TAGS}
    pcs = [_kit_pieces(c) for c in courses]
    for pc in pcs:
        for t in KIT_TAGS:
            for q in set(pc[t]):
                uses[t][q] = uses[t].get(q, 0) + 1
    kit["B"].append(bytes(16))
    seen["B"].add(bytes(16))
    for pc in pcs:
        for t in KIT_TAGS:
            for q in pc[t]:
                if q not in seen[t] and (t == "F" or uses[t][q] >= kmin):
                    seen[t].add(q)
                    kit[t].append(q)
    return kit


def kit_text(kit, names, kmin=KIT_MIN):
    """the kit's source (KIT_FILE)"""
    out = ["# BONANZA's STANDARD KIT (SPEC.md 130.37): GENERATED by `python3 tools/bbcourse.py kit` from the",
           "# courses %s (bbcourse.KIT_POOL), each compiled without the kit." % ", ".join(names),
           "# B: a block a course draws, its 16 CGA bytes - every one at least %d of those courses hold, the black"
           % kmin,
           "#    block first.  K: an occluder mask, 16 bytes, on the same rule.  F: a FIELD cell's table, 289 bytes -",
           "#    every one any of them holds (the F library).  In kit order: a course names a piece by its place.",
           "# %d blocks, %d masks, %d tables: BZKIT.BIN %d bytes.  Every ship rebuilds every course, so this may"
           % (len(kit["B"]), len(kit["K"]), len(kit["F"]), len(kit_part(kit))),
           "# change freely (130.37.2); a course's identity and its demos follow it."]
    for t in KIT_TAGS:
        out += ["%s %s" % (t, q.hex().upper()) for q in kit[t]]
    return "\n".join(out) + "\n"


def main_kit(argv):
    """bbcourse.py kit [-o FILE] [--min N]: compile KIT_POOL's courses without the kit and write the kit's
    source (SPEC.md 130.37.2) - KIT_FILE unless -o says"""
    ap = argparse.ArgumentParser(prog="bbcourse.py kit")
    ap.add_argument("-o", "--out", default=KIT_FILE)
    ap.add_argument("--min", type=int, default=KIT_MIN)
    a = ap.parse_args(argv)
    paths = kit_pool_paths()
    got = par_map(_kit_compile, paths)
    for _c, e in got:
        if e is not None:
            raise e
    courses = [c for c, _e in got]
    kit = kit_build(courses, a.min)
    kit_check(kit, a.out)
    with open(a.out, "w", newline="\n") as f:
        f.write(kit_text(kit, [c.name for c in courses], a.min))
    print("bbcourse: %s: %d blocks, %d masks, %d tables, BZKIT.BIN %d bytes" % (
        os.path.relpath(a.out, ROOT), len(kit["B"]), len(kit["K"]), len(kit["F"]), len(kit_part(kit))))
    return 0


def _kit_compile(path):
    return compile_course(path, _hack={"nokit": True})


def main_author(argv):
    """bbcourse.py author COURSE.bbc [-o OUT.bzd]: play the course's AUTHOR
    script with the model and write its .bzd (MOON's and PEAK's demos until
    the owner records his, SPEC.md 130.14.7.4)"""
    ap = argparse.ArgumentParser(prog="bbcourse.py author")
    ap.add_argument("course")
    ap.add_argument("-o", "--out")
    a = ap.parse_args(argv)
    paths = default_paths()
    K = [os.path.abspath(p) for p in paths].index(os.path.abspath(a.course))
    c = compile_course(a.course)
    if c.name not in AUTHOR:
        print("bbcourse: %s has no AUTHOR script" % c.name, file=sys.stderr)
        return 1
    log, p = author_demo(c, K, AUTHOR[c.name])
    note = ("%s's AUTHORED demo (SPEC.md 130.14.7.4), written by `python3 tools/bbcourse.py author %s`\n"
            "from bbcourse.AUTHOR[%r] and the model: %d steps (%.2f s), %d fall, %d RETURN,\n"
            "%d pad swaps, %d spring launches, %s.  The build checks it against the course\n"
            "as built; replaced by the owner's recording the day one is committed."
            % (c.name, os.path.relpath(os.path.abspath(a.course), ROOT), c.name, p.nstep,
               p.nstep * STEP_PIT / float(PIT_HZ), p.nfall, p.nret, p.npad, p.nspr,
               "to the cup" if p.goal else "NOT to the goal"))
    text = demo_text(log, c.name, note)
    out = a.out or demo_path(a.course)
    with open(out, "w", newline="\n") as f:
        f.write(text)
    print("bbcourse: %s: %d runs, %d steps" % (out, struct.unpack_from("<H", log, 12)[0], p.nstep))
    return 0



def lock_across(c, ln):
    """SPEC.md 130.45.1: the horizontal LOCK's window per card -> (CGA c0, Hercules c0), the window centred on
    the course's PICTURE EXTENT across (every non-VOID cell, 16 px either side of its centre, and every clock's
    digit lane); REFUSED when the extent does not lie wholly inside the window on a card"""
    xs = []
    for k, t in rec_map(c.tiles).items():
        if t.kind != KIND_VOID:
            x = 16 * (k[0] - k[1]) + c.x0
            xs += [x - 16, x + 16]
    for rs in _clock_rects(c).values():
        for bx, _by, bw, _bh in rs:
            xs += [8 * bx, 8 * (bx + bw)]
    lo, hi = min(xs), max(xs)
    out = []
    for herc in (0, 1):
        W = CARDS[herc][0]
        cmax = c.cols - W
        c0 = max(0, min((lo + hi - 8 * W) // 16, cmax))
        if c0 >= 128:                               # (BZ_CRS_LOCKS holds c0 in a byte the guest's bz_vinit
            raise CourseError("%s:%d: lock across: the %s's window at column %d, past the 127 BZ_CRS_LOCKS' "
                              "byte holds (SPEC.md 130.45.1)" % (c.fname, ln, "Hercules" if herc else "CGA", c0))
        if lo < 8 * c0 or hi > 8 * (c0 + W):
            raise CourseError("%s:%d: lock across: the picture is %d px across (%d - %d), wider than the %s's "
                              "window of %d px: a lock never hides any of the course (SPEC.md 130.45.1)" % (
                                  c.fname, ln, hi - lo, lo, hi, "Hercules" if herc else "CGA", 8 * W))
        out.append(c0)
    return tuple(out)


def lock_bottom(c):
    """SPEC.md 130.45.4 (`stop down`): the BOTTOM LINE - the lowest front corner of any FINISH (every goal
    cell, every cup's cell) plus FACE8, three units of the face under it: once the finish is wholly in view
    the camera scrolls no further down"""
    rm = rec_map(c.tiles)
    out = 0
    cells = [k for k, t in rm.items() if t.kind == KIND_GOAL] + [tuple(p["at"]) for p in c.props
                                                                  if p["kind"] == PK_CUP]
    for k in cells:
        t = rm.get(tuple(k[:2]))
        if t is not None:
            out = max(out, 8 * (k[0] + k[1]) + 16 - _h4t(t, 16, 16) // 4 + c.y0 + FACE8)
    if not out:
        raise CourseError("%s: stop down needs a finish (a goal or a cup) to stop at" % c.fname)
    return out


def stopped_window(c, herc=0):
    """SPEC.md 130.45.4: the window a LOCKED and STOPPED course rests in at its finish - (x px, top line), its
    across the lock and its down the bottom stop - or None for any other course"""
    if not (getattr(c, "lockx", None) and getattr(c, "lockb", None)):
        return None
    W, H, rl, _lsh = CARDS[herc]
    rmax = min(c.brows * 8 // rl - H, max(0, -(-(c.lockb - WIN_LINES) // rl)))
    return 8 * c.lockx[herc], rmax * rl


# =============================================================================
# THE COURSE GUIDE's checks (wave 11, stories 11.11 and 11.13;
# docs/plans/bonanza-courses/README.md, G1, G3, G9 - G12): a course that says
# `guide` is a real course held to the owner's design rules.  Two halves:
#  - STATIC, at every compile of a `guide` course (no run, milliseconds):
#    G9's clock in view at the START, G10's never two clocks on one screen;
#  - over RUNS (--guide and the selfcheck's item): the length floor (G1), the
#    pans while airborne (G3), a clock beside the path (G11), the longest
#    stretch with no clock in view (G12).  A run is the autopilot's route
#    when it reaches a finish, and every demo log given; with none the
#    run-based half says so and refuses nothing (the pen-in-then-iterate
#    loop never waits on a run: the guide's section 3).
# =============================================================================

GUIDE_MIN_S = 25              # G1: a course's slowest finish at least this long, seconds
GUIDE_GAP_S = 15              # G12: at most this long with no clock's digits in the window, seconds


def _clock_rects(c):
    """{clock number: [lane rect (bx, by, w, h) in blocks]} of a compiled course"""
    out = {}
    for L in c.lanes:
        p = c.props[L["prop"]]
        if p["kind"] == PK_CLOCK:
            out.setdefault(p["num"], []).append(L["rect"])
    return out


def _clock_cells(c):
    """{clock number: (wx, wy)}"""
    return {p["num"]: tuple(p["at"]) for p in c.props if p["kind"] == PK_CLOCK}


def _rects_in(rs, xa, ya, w=VIEW_W, h=VIEW_H):
    return all(xa <= 8 * bx and 8 * (bx + bw) <= xa + w and ya <= 8 * by and 8 * (by + bh) <= ya + h
               for bx, by, bw, bh in rs)


def _rects_box(rs):
    return (min(8 * bx for bx, _by, _w, _h in rs), min(8 * by for _bx, by, _w, _h in rs),
            max(8 * (bx + w) for bx, _by, w, _h in rs), max(8 * (by + h) for _bx, by, _w, h in rs))


def guide_static_rule(c, _hack=None):
    """G9 (a clock's digits inside the CGA window centred on the start) and G10
    (no CGA window, ANYWHERE, holds two clocks' digits whole: checked pairwise,
    which is stricter than along a route and needs none) -> the verdict line;
    refused naming the clocks.  Only a `guide` course; the rest are exempt"""
    if not getattr(c, "guide", None):
        return "%s: not a guide course (exempt)" % c.name
    hk = _hack or ()
    clocks = _clock_rects(c)
    out = []
    if c.limit:
        rm = rec_map(c.tiles)
        wx, wy = c.src.start[0]
        t = rm.get((wx, wy))
        sx, sy = 16 * (wx - wy) + c.x0, 8 * (wx + wy) + 8 - (_h4t(t, 8, 8) // 4 if t else 0) + c.y0
        ok = [n for n, rs in sorted(clocks.items()) if _rects_in(rs, sx - VIEW_W // 2, sy - VIEW_H // 2)]
        if not ok and "g9" not in hk:
            raise CourseError("%s: GUIDE G9: no clock's digits lie inside the CGA window centred on the START "
                              "(px %d - %d, lines %d - %d): a clock face must be in view from the start "
                              "(docs/plans/bonanza-courses/README.md)" % (c.fname, sx - VIEW_W // 2,
                                                                          sx + VIEW_W // 2 - 1,
                                                                          sy - VIEW_H // 2, sy + VIEW_H // 2 - 1))
        out.append("G9 the start sees clock %s" % (ok[0] if ok else "NONE"))
    boxes = {n: _rects_box(rs) for n, rs in clocks.items()}
    ns = sorted(boxes)
    for i, a in enumerate(ns):
        for b in ns[i + 1:]:
            A, B = boxes[a], boxes[b]
            wspan = max(A[2], B[2]) - min(A[0], B[0])
            hspan = max(A[3], B[3]) - min(A[1], B[1])
            if wspan <= VIEW_W and hspan <= VIEW_H and "g10" not in hk:
                raise CourseError("%s: GUIDE G10: clocks %d and %d fit one CGA window together (%d x %d px of "
                                  "320 x 200): two clocks never share a screen" % (c.fname, a, b, wspan, hspan))
    out.append("G10 %d clocks, no two in one window" % len(ns))
    return "%s: %s" % (c.name, "; ".join(out))


def _guide_run(c, herc, keys):
    """one run through the model at a card's rate, the camera once a frame ->
    its CamRun, with .touch: every cell the ball's footprint met on the ground
    (its centre +- RAD gu), and .goal.  KEYS() -> (key, ball) or None (the run
    is over); None for the autopilot"""
    p = Physics(c, play=True)
    r = CamRun(c, herc, p)
    r.touch = set()
    n = [0]

    def st():
        n[0] += 1
        if n[0] > 8000 or p.goal or p.tout:
            return False
        try:
            if keys is None:
                p.step(p.auto())
            else:
                k = keys()
                if k is None:
                    return False
                p.step(*k)
        except IndexError:                          # the route ran out
            return False
        if not p.air:
            gx, gy = p.gx >> 8, p.gy >> 8
            for x in (gx - RAD, gx + RAD):
                for y in (gy - RAD, gy + RAD):
                    r.touch.add((x >> 4, y >> 4))
    while r.frame(st):
        pass
    r.goal = p.goal
    return r


def guide_runs(c, logs=()):
    """the runs the run-based checks read -> {herc: [(name, run)]}: the
    autopilot's route when it reaches a finish, and each (name, demo log)"""
    out = {0: [], 1: []}
    for herc in (0, 1):
        if c.route and c.has_finish:
            r = _guide_run(c, herc, None)
            if r.goal:
                out[herc].append(("the route", r))
        for name, log in logs:
            _k, _mat, kt, _fl = decode_log_t(log)
            it = iter(kt)
            r = _guide_run(c, herc, lambda it=it: next(it, None))
            if r.goal:
                out[herc].append((name, r))
    return out


def guide_run_checks(c, logs=(), _hack=None):
    """G1, G3, G11 and G12 over every run (guide_runs) on both cards -> the
    report lines; refused at the first breach.  A course with no complete run
    is reported and NOT refused (the playtest loop does not wait on a run)"""
    hk = _hack or ()
    runs = guide_runs(c, logs)
    if not runs[0]:
        return ["%s: no complete run yet (the autopilot's route does not reach a finish and no demo was given): "
                "G1, G3, G11 and G12 wait for one" % c.name]
    clocks, cells = _clock_rects(c), _clock_cells(c)
    lines = []
    for herc in (0, 1):
        W, _H, rl, _lsh = CARDS[herc]
        card = "Hercules" if herc else "CGA"
        for name, r in runs[herc]:
            secs = r.p.nstep / float(SEC_STEPS)
            # G1: the length floor (on the CGA's run: the step count is the card's nominal rate either way)
            if herc == 0 and secs < GUIDE_MIN_S and "g1" not in hk:
                raise CourseError("%s: GUIDE G1: %s finishes in %.1f s, under the floor of %d s"
                                  % (c.fname, name, secs, GUIDE_MIN_S))
            # G3: the columns panned while the ball is in the air, flight by flight
            # [first frame, columns, falls before, ended in a fall, thrown out of a tube].  A CANNON's throw is
            # exempt (the owner, 2026-11-18: the player is not steering it); a spring's is not
            flights, cur, intube = [], None, False
            for f in r.rows:
                if f["air"] and not f["tube"]:
                    if cur is None:
                        cur = [f["fr"], 0, f["resp"], False, intube]
                        flights.append(cur)
                    cur[1] += abs(f["dc"])
                else:
                    if cur is not None and f["resp"] != cur[2]:
                        cur[3] = True                       # a fall, not a jump: it ends in a respawn
                    cur = None
                intube = f["tube"]
            panned = [(fr, n) for fr, n, _r, fell, thrown in flights if n and not fell and not thrown]
            if panned and "g3" not in hk:
                raise CourseError("%s: GUIDE G3: on the %s, %s pans %s while the ball is in the air: a jump "
                                  "never needs a horizontal pan" % (
                                      c.fname, card, name,
                                      ", ".join("%d column(s) in the flight from frame %d" % (n, fr)
                                                for fr, n in panned)))
            # G11: a clock in the way - the ball's footprint met its (solid) cell
            hit = sorted(n for n, at in cells.items() if at in r.touch)
            if hit and "g11" not in hk:
                raise CourseError("%s: GUIDE G11: %s brushes clock(s) %s: a clock never obstructs a main "
                                  "pathway" % (c.fname, name, ", ".join(map(str, hit))))
            # G12: the longest stretch with no clock's digits in the window
            gap = worst = 0
            for f in r.rows:
                ya, xa = f["R0"] * rl, 8 * f["c0"]
                if any(_rects_in(rs, xa, ya, 8 * W, WIN_LINES) for rs in clocks.values()):
                    gap = 0
                else:
                    gap += 1
                    worst = max(worst, gap)
            gs = worst / float(CARD_HZ[herc])
            if gs > GUIDE_GAP_S and "g12" not in hk:
                raise CourseError("%s: GUIDE G12: on the %s, %s goes %.1f s with no clock in view, over %d s"
                                  % (c.fname, card, name, gs, GUIDE_GAP_S))
            lines.append("%s %s: %.1f s; %d flight(s), %d panned (%s); %s; longest with no clock in view %.1f s"
                         % (card, name, secs, len(flights), len(panned),
                            ", ".join("%d col from frame %d" % (n, fr) for fr, n in panned) or "none",
                            "clock(s) %s touched" % hit if hit else "no clock touched", gs))
    return lines


def main_guide(paths, logs):
    """--guide: the course guide's checks on each `guide` course - the static
    half again, then the run-based half over the route and LOGS (demo files)"""
    rc = 0
    lg = []
    for fn in logs:
        with open(fn, "rb") as f:
            lg.append((os.path.basename(fn), f.read()))
    for path in paths:
        c = compile_course(path)
        if not c.guide:
            print("%s: not a guide course (no `guide` statement): nothing to check" % c.name)
            continue
        print(c.guide_static)
        for line in guide_run_checks(c, lg):
            print("    " + line)
    return rc


def main():
    global OCC_MODE, FSHOW_ALL, SHADOW
    if len(sys.argv) > 1 and sys.argv[1] in ("fbundle", "famparts"):
        try:
            return main_fbundle(sys.argv[1:])
        except CourseError as e:
            print("bbcourse: %s" % e, file=sys.stderr)
            return 1
    if len(sys.argv) > 1 and sys.argv[1] in ("demo", "author", "tauthor", "twoseg", "kit"):
        try:
            return {"demo": main_demo, "author": main_author, "tauthor": main_tauthor,
                    "twoseg": main_twoseg, "kit": main_kit}[sys.argv[1]](sys.argv[2:])
        except CourseError as e:
            print("bbcourse: %s" % e, file=sys.stderr)
            return 1
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("courses", nargs="*", help="course files, in BZ_COURSES's order")
    ap.add_argument("-o", "--out", help="output directory")
    ap.add_argument("--path", metavar="BBC", help="THE PATHWAY's source (wave 8b, SPEC.md 130.19.5): compiled "
                    "beside the courses as BZPATH.BIN, its entry last in every BZ_CRS_ table")
    ap.add_argument("--title", metavar="BBC", help="THE TITLE's source (SPEC.md 130.23): compiled beside the "
                    "courses as BZTITLE.BIN, its entry after the pathway's in every BZ_CRS_ table")
    ap.add_argument("--selfcheck", action="store_true")
    ap.add_argument("--dev", action="store_true",
                    help="-o: the BZDEV=1 build's (make passes it): its TEST courses are written; without it a "
                         "`test` course is refused, so none ships (SPEC.md 130.54)")
    ap.add_argument("--only", metavar="SECTIONS",
                    help="--selfcheck: only these sections, comma-separated (`--only list` names them); the "
                         "courses are compiled whatever is named (docs/TESTING.md, *BONANZA's host checks*)")
    ap.add_argument("--jobs", "-j", type=int, metavar="N",
                    help="processes at once: the courses' compiles and --selfcheck's sections (default BB_JOBS, "
                         "else the cores, at most 4); 1 is the sequential run")
    ap.add_argument("--png", metavar="DIR", help="write preview PNGs (needs Pillow)")
    ap.add_argument("--tune", nargs="+", metavar="NAME=VALUE",
                    help="compile every course under trial values of MATERIALS (HOP=r,s,g BOOST=b ...), write "
                         "nothing, and print each course's verdict, the step and gap ladders, every route proof and "
                         "every AUTHOR script (SPEC.md 130.16.13)")
    ap.add_argument("--pans", action="store_true",
                    help="the camera's columns and rows panned over each demo on both cards, wave 6's policy and "
                         "LATTICE side by side, the host's prediction (SPEC.md 130.16.13, 130.17.9); writes nothing")
    ap.add_argument("--camcheck", action="store_true",
                    help="LATTICE over every demo and autopilot on both cards: the guarantees, the side, two-row, "
                         "ramp-bottom and dither checks, the reports and the controls (SPEC.md 130.17.9, item 8's); "
                         "writes nothing")
    ap.add_argument("--occ", choices=OCC_MODES, default=OCC_MODE,
                    help="the occluder records (SPEC.md 130.29): `void` (AV, the default and the shipped form: the "
                         "model computes the mask in the VOID cells and the part holds their residual) or `off` "
                         "(today's records everywhere, no GF_ANA: the A/B)")
    ap.add_argument("--fshow", action="store_true",
                    help="SPEC.md 130.28.6's SHOW rule on every course (make's BZFSHOW=1): a ball ON a shape drawn "
                         "whole - off by default, the owner's toggle; a course's own `fshow` turns it on for it")
    ap.add_argument("--shadow", action="store_true",
                    help="SPEC.md 130.47.5's CAST SHADOWS (make's BZSHADOW=1): light from -x+y, 1 gu of shadow a px "
                         "of height, a 50%% dither on the tops they fall on; off by default")
    ap.add_argument("--guide", action="store_true",
                    help="the course guide's checks (wave 11: G1, G3, G9 - G12) on each `guide` course, over its "
                         "route and any --log demos; writes nothing")
    ap.add_argument("--log", action="append", default=[], metavar="BZD",
                    help="with --guide: a demo log (.bzd) to check as a run; may repeat")
    ap.add_argument("--sizes", action="store_true",
                    help="every course's sections, stored and packed both ways, its decode time, RAM and budget, "
                         "then the package's (SPEC.md 130.15.12.2); about a minute a course")
    a = ap.parse_args()
    if not (a.out or a.selfcheck or a.png or a.sizes or a.tune or a.pans or a.camcheck or a.guide or a.only == "list"):
        ap.error("need -o OUT, --selfcheck, --sizes, --tune, --pans, --camcheck, --guide or --png DIR")
    OCC_MODE = a.occ
    FSHOW_ALL = a.fshow
    SHADOW = a.shadow
    JOBS[0] = a.jobs
    paths = a.courses or default_paths()
    only = None
    if a.only:
        if a.only == "list":
            print("\n".join(selfcheck_sections()))
            return 0
        only = [n.strip() for n in a.only.split(",") if n.strip()]
        bad = [n for n in only if n not in selfcheck_sections()]
        if bad or not a.selfcheck:
            ap.error("--only takes --selfcheck's sections (%s)%s" % (", ".join(selfcheck_sections()),
                                                                     ": not %s" % ", ".join(bad) if bad else ""))
    if a.camcheck:
        if a.out or a.selfcheck or a.png or a.sizes or a.tune or a.pans:
            ap.error("--camcheck writes nothing and runs alone")
        try:
            return main_camcheck(paths)
        except CourseError as e:
            print("bbcourse: %s" % e, file=sys.stderr)
            return 1
    if a.guide:
        if a.out or a.selfcheck or a.png or a.sizes or a.tune or a.pans:
            ap.error("--guide writes nothing and runs alone")
        try:
            return main_guide(paths, a.log)
        except CourseError as e:
            print("bbcourse: %s" % e, file=sys.stderr)
            return 1
    if a.pans:
        if a.out or a.selfcheck or a.png or a.sizes or a.tune:
            ap.error("--pans writes nothing and runs alone")
        try:
            return main_pans(paths)
        except CourseError as e:
            print("bbcourse: %s" % e, file=sys.stderr)
            return 1
    if a.tune:
        if a.out or a.selfcheck or a.png or a.sizes:
            ap.error("--tune writes nothing and runs alone")
        try:
            return main_tune(a.tune, paths)
        except CourseError as e:
            print("bbcourse: %s" % e, file=sys.stderr)
            return 1
    try:
        rc = 0
        if a.selfcheck:
            rc |= selfcheck(paths, only=only)
        if a.out:
            write_out(a.out, paths, a.path, a.title, dev=a.dev)
        if a.sizes:
            rc |= sizes(paths)
        if a.png:
            rc |= previews(paths, a.png)
        return rc
    except CourseError as e:
        print("bbcourse: %s" % e, file=sys.stderr)
        return 1


if __name__ == "__main__":
    import bbcourse                             # (run as the MODULE, so what this run pickles - the compile cache's
    sys.exit(bbcourse.main())                   # courses - names bbcourse.Course, as a test that imports it reads)
